	if (gcm.SYS_ID == 'IM10' || gcm.SYS_ID == 'ZI01') {
		var mainObj	= gcm.win.getMainWindow();

		if (com.util.isEmpty(id)) {
			return mainObj.gcm.session.info;
		} else {
			return mainObj.gcm.session.info[id];
		}
	} else {
		if (com.util.isEmpty(id)) {
			return gcm.session.info;
		} else {
			return gcm.session.info[id];
		}
	}
};


