 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.session.initSystem = function() {

	if (gcm.SYS_ID == 'IM10') {
		_send('Ic10');

		_send('Ib10');
		_send('Ic20');
		_send('Im20');
		_send('Im30');
		_send('Im50');
		_send('Im60');
		_send('Ir10');
		_send('Is10');
		_send('Sm60');

	} else if (gcm.SYS_ID == 'PM10') {
		_send('Pb10');
		_send('Pc10');
		_send('Pc20');
		_send('Pc30');
		_send('Pd10');
		_send('Pd20');
		_send('Pm10');
		_send('Pm30');
		_send('Pm40');
		_send('Pm50');
		_send('Pr10');
		_send('Pr20');
		_send('Ps10');
		_send('Ps20');

	} else {
		return;
	}

	function _send(wasId) {

		var action 	= gcm.session.getCrptedUrl('/biz/' + wasId + 'ComCodeIndvCtrl/touchSso.do');

		var ajaxOption = {
			action		: action,
	    	mode 		: 'asynchronous',
	    	mediatype  	: 'text/json',
	    	method		: 'POST',
	    	timeout		: 100,
	    };
		$p.ajax(ajaxOption);
	}
};


