/**
 * 함수명 	: com.page.setPageInfo
 * 함수설명	: wFrame 정보를 등록한다.
 * 파라미터	: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.page.setPageInfo = function() {

	try {
		if (com.util.isEmpty($p.getFrame())) return;

		//=======================================================
		// FloatingLayer 컴포넌트 모달 속성 추가
		//=======================================================
		com.comp.setFloating($p.getFrame());

		//=======================================================
		// onpageunoload 이벤트 비정상으로 blank 페이지를 추가
		//=======================================================
		com.page.setUnloadBlankPage($p.getFrame());

		var expr	= /popup[0-9]{10,30}/g;
		var frameId	= $p.getFrame().getID();

		if (frameId.indexOf('SYSTEM_ERROR_POPUP') != -1 || frameId.indexOf('message_popup') != -1 || expr.test(frameId)) {
	    	return;
	    }

	    // Frame 정보 지우기
		for (var i = gcm.WFRAME_INFO.length -1 ; i > -1 ; i -- ) {
			if (com.util.isEmpty(window[gcm.WFRAME_INFO[i].id])) {
				gcm.WFRAME_INFO.splice(i, 1);
			}
		}

		// 프레임 ID 취득
		var frameObj	= $p.getFrame();
		var id			= frameObj.id;
		var scopeId		= frameObj.scope_id;
		var orgId		= frameObj.org_id;
		var level		= 1;
		var path		= id;
		var parentObj	= frameObj.parentControl;
		var parent		= parentObj.scope_id;

		try {
			for (var i = 0 ; i < 100 ; i++) {
				if (parentObj.scope_id != 'mf') {
					if (path.indexOf(parentObj.scope_id + '@') == -1) {
						path 		= parentObj.scope_id + '@' + path;
						level++;
					}
					parentObj	= parentObj.parentControl;
				} else {
					break;
				}
			}
		} catch(ex) {
			console.log(ex);
		}

		if (gcm.WFRAME_INFO.filter(function(item) {return item.id == id}).length == 0) {
			gcm.WFRAME_INFO.push({id: id, orgId : orgId, scopeId : scopeId, level : level, parent : parent, path : path});
		}
	} catch(ex) {
		return;
	}
};


/**
 * 함수명 	: com.page.setMetaInfo
 * 함수설명	: 오케스트라 결함 등록을 위한 wFrame에 '결함등록' 버튼을 추가
 * 파라미터	: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.page.setMetaInfo = function() {

	try {
		if (window.name == '' && $p.getFrame().getID() == 'mf') {
			return;
		}

		var seq		= new Date();
		var id 		= 'btn_meta_info' + seq.getTime();
		var compObj	= null;
		var fileSrc	= ($p.getFrame().id == 'mf') ? WebSquare.net.getParameter('w2xPath') : $p.getFrame().options.src;
		var sysName	= '';

		if (com.util.isNotEmpty(fileSrc)) {		
			try {
				var fileNm = fileSrc.match(/[^\/](\w|[가-힣])+(?=\.)/)[0];

				sysName	= fileNm.substr(0, 4).toUpperCase();
			} catch(ex) {
				console.log(fileSrc);
			}
		}

		var paramData = {
			screenId 	: $p.getMetaValue('meta_screenId'),
			screenName	: $p.getMetaValue('meta_screenName'),
			screenDesc	: $p.getMetaValue('meta_desc'), 
			sysName		: sysName
		};

		if(paramData.screenId != "" && paramData.screenId != null && paramData.screenId != 'N/A'){
			console.log("## 통합테스트용 콘솔 로그 - GET_SCREEN_INFO :: SCREEN_ID:" + paramData.screenId + ", SCREEN_NAME:" + paramData.screenName);
		}

		if (paramData.screenId == 'N/A' || paramData.screenDesc == 'N') {
			return true;
		}

		var metaFlag	= gcm.win.getMainWindow().gcm.META_FLAG;
		var html		= $('<input type="button" tabindex="0" id="' + id + '" class="META_INFO" style="color:#ffffff; background:#000000; padding: 3px 10px; z-index:3999;width: 100px;position:absolute; display:' + metaFlag + ';" value="결함등록">');
		var messagePath = {
			IM10 : '/ui/im10/com/message/Im10SendOrchestra.xml',
			PM10 : '/ui/pm10/com/message/Pm10SendOrchestra.xml',
			PM20 : '/ui/pm20/com/message/Pm20SendOrchestra.xml',
			PM60 : '/ui/pm60/com/message/Pm60SendOrchestra.xml',
			EM40 : '/ui/em40/com/message/Em40SendOrchestra.xml',
			SM30 : '/ui/sm30/com/message/Sm30SendOrchestra.xml',
		};

		var url 	= messagePath[gcm.SYS_ID];

		html.click(function(e) {

			if (paramData.screenId == '') {
				alert('화면아이디가 메타정보에 없습니다.\n\n화면아이디 등록을 개발자에게 요청하여 주시기 바랍니다.');
				return false;
			}

			var popOptions = {
				popupName 	: '결함등록',
				width 		: 600,
				height 		: 240,
			};

			if (gcm.SYS_ID == 'IM10' || gcm.SYS_ID == 'ZI01') {
				popOptions.width = 600;
				popOptions.height = 210;

			} else if (gcm.SYS_ID == 'PM10') {
				popOptions.width = 700;
				popOptions.height = 400;

			} else if (gcm.SYS_ID == 'PM60') {
				popOptions.width = 700;
				popOptions.height = 400;

			} else if (gcm.SYS_ID == 'SM30') {
				popOptions.width = 600;
				popOptions.height = 240;

			} 

			com.win.openPopup(url, popOptions, paramData, true);
		});

		var render = (window.name != '' && $p.getFrame().getID() == 'mf')  ? $('body') : $($p.getFrame().render);
		render.prepend(html);

		return true;
	} catch(ex) {
		return false;
	}
};


/**
 * 함수명 	: com.page.setImeMode
 * 함수설명	: inputBox, textArea에 포커스가 있을때 IME모드 변경
 * 파라미터	: language : 언어
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.page.setImeMode = function(language) {

	if ((gcm.SYS_ID == 'IM10' || gcm.SYS_ID == 'SM30' || gcm.SYS_ID == 'EM40' || gcm.SYS_ID == 'ZI01') && window.wbrowser) {

		language = com.util.isEmpty(language) ? 'Korean' : language;

		$(document).on('focus', '[type=text], textarea, [pname=autoComplete]', function(e) {

			var compObj	= $p.getComponentById(e.target.id);
			var scope	= compObj.getScopeWindow();

			//========================================================
			// 화면에 컴포먼트별로 영문모드 설정된 경우 (IME_MODE_ENG)
			//	1. 화면전체 컴포넌트 : scwin.IME_MODE_ENG = true
			//	2. 일부 컴포넌트 : scwin.IME_MODE_ENG = 배열
			//========================================================
			if (scope.scwin.IME_MODE_ENG) {
				if (com.util.isBoolean(scope.scwin.IME_MODE_ENG) && scope.scwin.IME_MODE_ENG == true) {
					window.wbrowser.setIME('English', 100);

					return;
				} else {
					if (com.util.isArray(scope.scwin.IME_MODE_ENG)) {
						for (var i = 0 ; i < scope.scwin.IME_MODE_ENG.length ; i ++) {
							if (compObj.org_id == scope.scwin.IME_MODE_ENG[i]) {
								window.wbrowser.setIME('English', 100);
								return;
							}
						}
					}
				}
				window.wbrowser.setIME(language, 100);
			} else {
				//========================================================
				// 컴포넌트 INPUT MODE가 영문일 경우 영어 사용
				//========================================================
				var engInputMode	= ['UPPERCASEONLY', 'ENGU_DIGIT_ONLY', 'ENG_DIGIT1', 'ENG_DIGIT_ONLY'];
				var engUpper		= ['UPPERCASEONLY', 'ENGU_DIGIT_ONLY'];
				var inputMode		= com.util.isNotEmpty(compObj.mInputMode) ? compObj.mInputMode : '';

				// 영어 대/소문자 CapsLock 체크 (engUpper : CapsLock on, CapsLock : off)
				if (engInputMode.filter(function(item) {return item == inputMode}).length == 1) {

					window.wbrowser.setIME('English', 100);

					for (var i = 0 ; i < engUpper.length ; i ++) {

						if (engUpper[i] == inputMode) {
							window.wbrowser.setCapsLock(true);
							return false;
						}
					}
					window.wbrowser.setCapsLock(false);
					return false;
				}

				window.wbrowser.setIME(language, 100);
			}
		});
	}
};


/**
 * 함수명 	: com.page.setUnloadBlankPage
 * 함수설명	: 페이지 unload 시 endPageFn 함수가 있으면 endPageFn 함수 실행할 wFrame 추가
 * 				- onpageunload 시 dataList, dataMap 객체가 삭제되어 추가된 wFrame에서 endPageFn 함수 호출함.
 * 파라미터	: frameObj : wFrame 컴포넌트
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.page.setUnloadBlankPage = function(frameObj) {

	var scope 		= frameObj.scope;

	if (com.util.isNotEmpty(scope.scwin.endPageFn)) {
		console.log({endPageFn : frameObj.id});

		var ifrm = 'wfm_blank_' + com.num.random();
		try {
			if (frameObj.id == 'mf') {
				wbrowser.onbeforeunload = scope.scwin.endPageFn;

				//window.addEventListener('beforeunload', scope.scwin.endPageFn);
			} else {

				var fileName = '';

				if (gcm.SYS_ID == 'IM10') {
					fileName	= '/ui/im10/com/include/Im10ComIncludeBlank.xml';
				} else if (gcm.SYS_ID == 'EM40') {
					fileName	= '/ui/em40/com/include/Em10ComIncludeBlank.xml';
				} else if (gcm.SYS_ID == 'PM10') {
					fileName	= '/ui/pm10/com/include/Pm10ComIncludeBlank.xml';
				} else if (gcm.SYS_ID == 'PM20') {
					fileName	= '/ui/pm20/com/include/Pm20ComIncludeBlank.xml';
				} else if (gcm.SYS_ID == 'PM60') {
					fileName	= '/ui/pm60/com/include/Pm60ComIncludeBlank.xml';
				} else if (gcm.SYS_ID == 'SM30') {
					fileName	= '/ui/sm30/com/include/Sm30ComIncludeBlank.xml';
				}

				com.comp.createComponent(ifrm, 'wframe', {src : fileName},frameObj);
			}
		} catch(ex) {
			console.log(ex);
		}
    }
};


/**
 * 함수명 	: com.page.getParameter
 * 함수설명	: 팝업, 탭, WFrame 화면 호출 시 전달한 파라미터 데이터를 조회한다.
 * 파라미터	: paramKey : 파라미터 키 (없으면 파마미터 데이터 리턴)
 * 리턴		: paramKey 있는 경우 값
			  paramKey 없는 경우 paramData
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.page.getParameter
 */
com.page.getParameter = function (paramKey) {

	var paramData 	= "";
	var returnData	= null;

    try {
        paramData = $p.getParameter("paramData");

        if ((com.util.isEmpty(paramData) === false) && com.util.isJSON(paramData)) {
            if (com.util.isEmpty(paramKey) === false) {
            	returnData	= paramData[paramKey];
            } else {
            	returnData	= paramData;
            }
        } else {
            paramData = getUrlParameter("paramData");
            if (com.util.isEmpty(paramData) === false) {
                paramData = com.util.stringToJSON(WebSquare.text.BASE64Decode(paramData));
                if (com.util.isEmpty(paramKey) === false) {
                	returnData	= paramData[paramKey];
                } else {
                	returnData	= paramData;
                }
            } else if ($p.getFrame().getID() == 'mf' && com.util.isNotEmpty(window.name) && window.__popupParam__) {

            	paramData	= window.__popupParam__;

            	if (com.util.isEmpty(paramKey) === false) {
            		returnData	= paramData[paramKey];
                } else {
                	returnData	= paramData;
                }
            }
        }

        return returnData;
    } catch (ex) {
        return null;
    }


    /**
     * 함수명 	: getUrlParameter
     * 함수설명	: URL의 파라미터를 조회한다. (내부함수)
     * 파라미터	: paramKey : 파라미터 키
     * 작성일 	: 2022.05.16
     * 작성자 	: Inswave Systems
     * 예시	 	: API : com.page.getParameter
     */
    function getUrlParameter(paramKey) {
        var param = [];
        var paramArray = location.search.split(/[\&\?\#]/);
        for (var i = 0; i < paramArray.length; i++) {
            if (com.util.isEmpty(paramArray[i]) === false) {
                var valueIdx = paramArray[i].indexOf("=");
                if (valueIdx > 0) {
                    var key = paramArray[i].substring(0, valueIdx);
                    var value = paramArray[i].substring(valueIdx + 1);
                    if (key === paramKey) {
                        return value;
                    }
                }
            }
        }
    }
};


