/**
 * 함수명 	: com.page.movePage
 * 함수설명	: 현재 화면을 다른화면으로 이동한다.
 * 파라미터	: url : 이동할 페이지 URL
 *			  paramData : 페이지에 전송할 파라미터
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.page.movePage
 */
com.page.movePage = function(url, paramData) {

    // 화면 이동시 로그인 여부 체크
	if (com.session.isLogin(url)) {
		var frameObj	= com.win.getFrame();

		if (gcm.SYS_ID == 'PM10' || gcm.SYS_ID == 'ZI01') {
			if (frameObj.id == gcm.HISTORY_WFRAME) {
				com.win.addBrowserHistory('PAGE', {url : url, param : {dataObject : com.option.parameter(paramData)}});
			}
		}

		frameObj.setSrc(gcm.CONTEXT_PATH + url,  {dataObject : com.option.parameter(paramData)});

		if (gcm.SYS_ID == 'IM10') {
			setTimeout(function() {
	    		$p.top().wdc_main.selectWindow();
	    	}, 100);
		}
	} else {
		com.message.logout();
	}
};


