/**
 * 함수명 	: com.page._frameToPage
 * 함수설명	: WFrame의 Scope을 반환한다.
 * 파라미터	: frameObj : WFrame 컴포넌트
 * 리턴		: scope object
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.page._frameToPage = function(frameObj) {

	if (com.util.isEmpty(frameObj)) {
		return null;
	} 

	if (com.util.isArray(frameObj)) {
		var pageObj	= [];

		for (var i = 0 ; i < frameObj.length ; i ++) {
			 pageObj.push(frameObj[i].scope);
		}
		return pageObj;
	} else {
		return frameObj.scope;
	}
};



