/**
 * 함수명 	: com.session.isLogin
 * 함수설명	: 로그인 여부를 체크한다.
 * 파라미터	: url : 페이지 URL 주소
 * 리턴		: true / false
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.session.isLogin
 */
com.session.isLogin = function(url) {

	var reqParam = url || "";
	var result = false;
    gcm.session.isLogin(reqParam).done(function(res) {
    	// 응답 JSON객체가 없으면 함수 종료
        var resJson = res.responseJSON || null;
        if (com.util.isEmpty(resJson)) {
        	return;
        }
        if (com.util.isBoolean(resJson.isLogin) && resJson.isLogin === true) {
        	result = true;
        }
    }).fail(function(res) {
        // TODO 통신 오류일 때 예외처리
    	console.error("isLogin check error!");
    });

    return result;
};


