 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.sbm.executePms
 */
com.sbm.executePms = function(sbmObj, compObj, isNoMessage) {

	if (!(gcm.SYS_ID == 'IM10' || gcm.SYS_ID == 'ZI01')) {
		alert('내부시스템에서만 사용 가능합니다.(IM10)');
		return;
	}

	if (sbmObj) {
		sbmObj = (typeof sbmObj == 'object') ? sbmObj : (typeof sbmObj == 'string') ? $p.getSubmission(sbmObj) : sbmObj;

		// Promise 리턴
		return new Promise(function(resolve) {
			com.sbm.executeExtPms(sbmObj, null, compObj, isNoMessage).then(function(data) {
				resolve(data);
			});
		});
	} else {
		return false;
	}
};


