/**
 * 함수명 	: com.data.getCodeData
 * 함수설명	: 통합코드 데이터를 조회 후 dataList를 생성한다.
 *			   - codeInfo.cond_cls_cd 값이 없을 경우 모든 통합코드 조회
 *			   - codeInfo.intg_cd_id 는 중복 조회 불가 (동일한 그룹코드 사용 시 com.data.getCodeData를 추가로 조회함.
 * 파라미터	: codeInfo : 공통코드 조회 정보
 *			  codeInfo.dc_id : 생성할 dataList 아이디
 *			   - 아이디 : dtl_ + 통합코드그룹명 
 *			   - 동일 통합코드를 조회할 경우 아이디 +_01 을 붙임
 *			  codeInfo.intg_cd_id : 통합코드그룹코드
 *			  codeInfo.cond_cls_cd : 조건 유형
 *			   - IN : 포함 (IN)
 *			   - NOTIN : 미포함 (NOT IN)
 *			  codeInfo.property_cd : 통합코드 IN, NOT IN 조건 프로퍼티 코드
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.data.getCodeData
 */
com.data.getCodeData = function(codeInfo) {

	for (var i = 0 ; i < codeInfo.length ; i ++) {

		var propertyVal	= '';
		if (com.util.isNotEmpty(codeInfo[i].property_cd)) {
			propertyVal = com.util.getPropertyStringValue(codeInfo[i].property_cd);
		}

		codeInfo[i]['efect_val'] 	= propertyVal;
		codeInfo[i]['cond_cls_cd'] = (codeInfo[i]['cond_cls_cd']) ? codeInfo[i]['cond_cls_cd'] : '';
	}

	//=============================================================================
	// 공통코드 조회한 데이터를 dataList로 생성한다.
	//	- promise 함수
	//=============================================================================
	gcm.data.getCommCodeListForMulti({intg_cd_srch_info : codeInfo}).done(function(resData) {

		// 서비스 조회 결과 데이터
		var data		= resData.responseJSON.egovNrsIntgCdOfEfectValList;

		// 코드목록을 그룹코드로 그룹핑.
		for (var i = 0 ; i < codeInfo.length ; i ++) {
			var codeData	= [];

			for (var j = 0 ; j < data.length ; j ++) {

				if (data[j].intg_cd_id == codeInfo[i].intg_cd_id) {
					codeData.push(data[j]);
				}
			}

			// 데이터 order 설정
			if (com.util.isNotEmpty(codeInfo[i].sort)) {

				var sortInfo = codeInfo[i].sort;
				codeData.sort(function(a, b) {

					if (sortInfo[1] == 'ASC') {
						if (a[sortInfo[0]] >= b[sortInfo[0]]) {
							return 1;
						} else {
							return -1;
						}
					} else {
						if (a[sortInfo[0]] >= b[sortInfo[0]]) {
							return -1;
						} else {
							return 1;
						}
					}
				});
			}

			// dataList를 생성
			com.data.createDataListSimple(codeInfo[i].dc_id, codeData);
		}
	});
};


/**
 * 함수명 	: com.data.bindCodeDataAll
 * 함수설명	: 통합코드 컴포넌트 바인딩 (전체) - 컴포넌트 속성 이용
 *			   - class 속성 : COMM_CODE
 *			   - userData1 : 바인딩 dataList 아이디
 * 파라미터	: N/A
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.data.bindCodeDataAll
 */
com.data.bindCodeDataAll = function(codeCols) {

	var scopeId	= $p.getFrame().getID();
	var obj		= (scopeId == 'mf') ? $('.COMM_CODE') : $('#' + scopeId).find('.COMM_CODE');
	var codeCol	= [];

	if (com.util.isEmpty(codeCols)) {
		codeCol = ['efect_val', 'efect_val_name']; 
	} else {
		codeCol = codeCols; 
	}

	for (var i = 0 ; i < obj.length ; i ++) {

		var compObj 	= $p.getComponentById(obj[i].id);
		var userData	= '';

		if (compObj.options.pluginName == 'gridView') {

			var colInfo	= compObj.cellInfoHash;

			for (var item in colInfo) {
				var userData	= colInfo[item].options.userData1;

				if (com.util.isNotEmpty(userData)) {

					compObj.getCellInfo(item).setColumnNodeSet('data:' + userData, codeCol[1], codeCol[0]);
					compObj.refreshColumnItemset(item);
				}
			}
		} else {
			var userData	= compObj.getUserData('userData1');

			if (userData) {
				com.data.bindCodeData(compObj, userData, codeCol);
			}
		}
	}
};


