/**
 * 함수명 	: com.data.getXmlData
 * 함수설명	: XML데이터를 조회 후 dataList를 생성한다.
 *			   - addkey, addvalue 값을 입력하면 dataList 생성 시 추가된다.
 * 파라미터	: xmlInfo : XML 데이터 조회 정보
 *			  xmlInfo.dcId : 생성할 dataList 아이디 - 아이디 : dtl_ + 통합코드그룹명 - 동일 통합코드를 조회할 경우 아이디 +_01 을 붙임
 *			  xmlInfo.datakey : XML 데이터 키
 *			  xmlInfo.listkey : XML 데이터 List 키
 *			  xmlInfo.addkey : 추가 데이터 키
 *			  xmlInfo.addvalue : 추가 데이터 값
 *			  xmlInfo.sort : 정렬정보 (배열) [컬럼명, 정렬기준]
 *			   - 컬럼명 :  key, value 
 *			   - 정렬기준 : ASC : DESC
 *			  ex) ['key', 'DESC']
 *			  
 *			  * 문자열로 정렬
 *			  * 생략 시 조회한 순서로 나옴.
 *			  * 추가 데이터는 항상 마지막에 추가됨.
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.data.getXmlData
 */
com.data.getXmlData = function(xmlInfo) {

	if (xmlInfo.length == 0) return;

	var url		= '';
	var sysCode = '';
	var param	= {};

	_setSysCode(xmlInfo);

	if (xmlInfo.length == 1) {
		_setSingleXmlDataParam(xmlInfo);
	} else {
		_setMultiXmlDataParam(xmlInfo);
	}

	//=============================================================================
	// XML 조회한 데이터를 dataList로 생성한다.
	//	- promise 함수
	//=============================================================================
	gcm.data.getCommXmlDataListForMulti(param, url).done(function(resData) {

		var data		= resData.responseJSON.xmlDataList;

		// 코드목록을 그룹코드로 그룹핑.
		for (var i = 0 ; i < xmlInfo.length ; i ++) {
			var xmlData	= [];

			for (var j = 0 ; j < data.length ; j ++) {

				if (data[j].datakey == xmlInfo[i].datakey && data[j].listkey == xmlInfo[i].listkey) {
					xmlData.push({key : data[j].key, value : data[j].value});
				}
			}

			// 데이터 order 설정
			if (com.util.isNotEmpty(xmlInfo[i].sort)) {

				var sortInfo = xmlInfo[i].sort;
				xmlData.sort(function(a, b) {

					if (sortInfo[1] == 'ASC') {
						if (a[sortInfo[0]] >= b[sortInfo[0]]) {
							return 1;
						} else {
							return -1;
						}
					} else {
						if (a[sortInfo[0]] >= b[sortInfo[0]]) {
							return -1;
						} else {
							return 1;
						}
					}
				});
			}

			// 추가 데이터가의 키, 값을 xmlData에 추가한다.
			if (com.util.isNotEmpty(xmlInfo[i].addvalue) || com.util.isNotEmpty(xmlInfo[i].addkey)) {

				var addData = {};

				if (com.util.isNotEmpty(xmlInfo[i].addkey)) {
					addData.key = xmlInfo[i].addkey;
				}

				if (com.util.isNotEmpty(xmlInfo[i].addvalue)) {
					addData.value = xmlInfo[i].addvalue;
				}

				xmlData.push(addData);
			}

			// dataList를 생성한다.
			com.data.createDataListSimple(xmlInfo[i].dcId, xmlData);
		}
	});

	/**
	 * 함수명 	: _setSingleXmlDataParam
	 * 함수설명	: 시스템별 싱글 XML 데이터 조회 URL 및 파라미터 설정 (내부함수)
	 * 파라미터	: xmlInfo : XML 데이터 조회 정보
	 * 리턴		: N/A
	 * 작성일 	: 2022.05.16
	 * 작성자 	: Inswave Systems
	 */
	function _setSingleXmlDataParam(xmlInfo) {
		url = '/biz/' + sysCode + 'ComXmlDataCtrl/retrieveXmlDataList.do'
		param = {datakey : xmlInfo[0].datakey, listkey : xmlInfo[0].listkey};
	}


	/**
	 * 함수명 	: _setMultiXmlDataParam
	 * 함수설명	: 시스템별 멀티 XML 데이터 조회 URL 및 파라미터 설정 (내부함수)
	 * 파라미터	: xmlInfo : XML 데이터 조회 정보
	 * 리턴		: N/A
	 * 작성일 	: 2022.05.16
	 * 작성자 	: Inswave Systems
	 */
	function _setMultiXmlDataParam(xmlInfo) {

		var xmlKey 	= [];

		for (var i = 0 ; i < xmlInfo.length ; i ++) {
			xmlKey.push(xmlInfo[i].datakey + '|' + xmlInfo[i].listkey);
			sysCode = (sysCode == '') ? xmlInfo[i].datakey.substr(0,4) : sysCode;
		}

		url = '/biz/' + sysCode + 'ComXmlDataCtrl/retrieveXmlDataListForMulti.do'

		param	=  {xml_data_multi_key : xmlKey.join('^')};
	}


	/**
	 * 함수명 	: _setSysCode
	 * 함수설명	: datakey에서 시스템 코드 조회 (내부함수)
	 * 파라미터	: xmlInfo : XML 데이터 조회 정보
	 * 리턴		: N/A
	 * 작성일 	: 2022.05.16
	 * 작성자 	: Inswave Systems
	 */
	function _setSysCode(xmlInfo) {
		sysCode = xmlInfo[0].datakey.substr(0,4);
		sysCode = sysCode.substr(0,1).toUpperCase() + sysCode.substr(1,4);
	}
};


