/**
 * 함수명 	: com.data.createDataMap
 * 함수설명	: dataMap을 생성한다.
 *			  dcId가 동일할 경우 삭제 후 생성함.
 * 파라미터	: dcId : dataMap 아이디
 *			  colInfo : 컬럼정보
 *			  initData : 초기 데이터
 * 리턴		: dataMap
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.data.createDataMap
 */
com.data.createDataMap = function(dcId, colInfo, initData) {

	try{
        // dataMap 있을 경우 삭제
    	if (!com.util.isNotEmpty(com.comp.getComponent(dcId))) {
            $p.data.remove( dcId );
        }

    	// 컬럼 정보 정리
    	for (var i = 0 ; i < colInfo.length ; i ++) {
    		colInfo[i].name	= colInfo[i].name || colInfo[i].id,
    		colInfo[i].type	= colInfo[i].type || 'text'
    	}

    	// dataMap 생성 옵션
        var dataOption = {
            "id" 		: dcId,
            "type" 		: "dataMap",
            "option" 	: {
                "baseNode" : "map",
            },
            "keyInfo" : colInfo
        };

        // dataMap 생성
        $p.data.create(dataOption);
        var dataMap	= com.comp.getComponent(dcId);

        // dataMap 초기 데이터 설정
        if (initData) {
        	dataMap.setJSON(initData);
        	dataMap.initRowStatus();
        }

        return dataMap;
    } catch (ex) {
        console.error(ex);
        return;
    }
};


