 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.data.createDataMapBind
 */
com.data.createDataMapBind = function(dcId, initData) {

	var colInfo	= [];
	var mapData	= {};

	// dataMap 생성 
	for (var item in initData) {
		colInfo.push({id : item});
		mapData[item]	= initData[item][0];
	}
	var dataMap	= com.data.createDataMap(dcId, colInfo, mapData);

	// 컴포넌트 바인딩.
	for (var item in initData) {
		if (initData[item].length == 2) {
