/**
 * 함수명 	: com.data.createDataList
 * 함수설명	: dataList을 생성한다.
 * 파라미터	: dcId : dataList 아이디
 *			  colInfo : 컬럼정보
 *			  initData : 초기 데이터
 * 리턴		: dataList
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.data.createDataList
 */
com.data.createDataList = function(dcId, colInfo, initData) {

    try {
    	var compObj		= com.comp.getComponent(dcId);
    	var isCreate	= true;
    	var colOld		= '';
    	var colNew		= '';

    	for (var i = 0 ; i < colInfo.length ; i ++) {
        	colInfo[i].name	= colInfo[i].name || colInfo[i].id;
    		colInfo[i].type	= colInfo[i].type || 'text';

    		colNew	+= (i == 0) ? colInfo[i].id : ',' + colInfo[i].id;
        }

    	if (com.util.isNotEmpty(compObj)) {
    		colOld	= compObj.cellIdList.join(',');

    		if (colOld == colNew) {
    			isCreate	= false;
    		} else {
    			$p.data.remove(dcId);
    		}
    	}

    	if (isCreate) {
	    	var dataListInfo = {
	            id 		: dcId,
	            type 	: "dataList",
	            option 	: {
	                "baseNode" 			: "list",
	                "repeatNode"		: "map",
	                "saveRemovedData" 	: "true",
	            },
	            columnInfo : colInfo
	        };

	        $p.data.create(dataListInfo);
    	} else {
        	compObj.removeAll();
       }

        compObj	= com.comp.getComponent(dcId);

        // dataMap 초기 데이터 설정
        if (initData) {
        	compObj.insertJSON(0, initData);
        	compObj.initRowStatus();
        }

        return compObj;
    } catch (ex) {
        console.log(ex);
        return;
    }
};


/**
 * 함수명 	: com.data.createDataListSimple
 * 함수설명	: dataList을 생성한다. (간편버전)
