	if (com.util.isArray(initData)) {
		isData	= true;
		colData	= initData[0];
	} else {
		colData	= initData;
	}

	for (var item in colData) {
		colInfo.push({id : item});
	}

	if (isData) {
		return com.data.createDataList (dcId, colInfo, initData);
	} else {
		return com.data.createDataList (dcId, colInfo);
	}
