/**
 * 함수명 	: com.data.getBindDataObject
 * 함수설명	: 컴포넌트에 바인딩된 dataMap, dataList를 조회한다.
 * 파라미터	: compObj : 컴포넌트
 * 리턴		: dataList, dataMap
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.data.getBindDataObject
 */
com.data.getBindDataObject = function (compObj) {

	var bindComp	= null;

	if (compObj.options.pluginName == 'gridView') {
		dataId = compObj.getDataList();

		if (com.util.isNotEmpty(dataId)) {

			bindComp	= $p.getComponentById(dataId);
		} else {
			console.log('바인딩 정보가 없습니다.');
			return null;
		}
	} else {
		var compRef	= compObj.modelControl.ref;

		if (com.util.isNotEmpty(compRef)) {
			var tempRef	= compRef.split('.')[0].replace('data:', '');
			bindComp	= $p.getComponentById(tempRef);
		} else {
			console.log('바인딩 정보가 없습니다.');
			return null;
		}
	}

	if (com.util.isNotEmpty(bindComp)) {
		return bindComp;
	} else {
		console.log('데이터 컬렉션이 없습니다.');
		return null;
	}
};


