/**
 * 함수명 	: com.data.getMatchData
 * 함수설명	: dataList에 조건식에 맞는 데이터를 조회한다. (OR 연산함)
 * 파라미터	: dcObj : dataList
 *			  opInfo : 
 *			  opInfo.col : 매칭 대상 컬럼
 *			  opInfo.op : 연산자 (==, >, <, >=, <=)
 *			  opInfo.value : 비교 값
 *			  userMatchFn : 사용자 매칭 함수 (true / false 리턴 필요)
 *			   - true : 매칭 데이터 추가
 *			   - false : 매칭 데이터 추가 되지 않음
 * 리턴		: 매칭 데이터
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.data.getMatchData
 */
com.data.getMatchData = function(dcObj, opInfo, userMatchFn) {

	var data 		= dcObj.getAllJSON();
	var filterData	= [];

	filterData	= data.filter(function(item) {
		try {
			for (var i = 0 ; i < opInfo.length ; i ++) {

				var value	= opInfo[i].value;
				var colVal	= item[opInfo[i].col];

				if (com.util.isString(value)) {
					value	= "'" + value + "'"
					colVal	= "'" + colVal + "'";
				} 

				if (eval(colVal + opInfo[i].op + value)) return true;
			}

			if (userMatchFn) {
				return userMatchFn(item);
			}
		} catch(ex) {
			return false;
		}
		return false;
	});
	return filterData;
};


/**
 * 함수명 	: com.data.validate
 * 함수설명	: dataMap 컬럼값의 유효성을 체크한다.
 * 파라미터	: dcObj : dataMap
 *			  validInfo : 유효성 체크 정보
 *			  validInfo.id : 컬럼 아이디
 *			   - validInfo.type이 range일 경우 배열
 *			  validInfo.name : 이름 (메시지 창 띄울 시 이름 사용 : XXX를 입력해 주세요)
 *			   -  - validInfo.type이 range일 경우 배열
 *			  validInfo.type : 유효성 체크 유형
 *			     - mandatory : 필수값 (length == 0)
 *			     - minLength : 최소길이 (length > 길이)
 *			     - minByteLength : 최소길이 바이트체크 (byteLength > 길이)
 *			     - maxLength : 최대길이 (length < 길이)
 *			     - maxByteLength : 최대길이 바이트체크 (byteLength < 길이)
 *			     - minCnt : 최소 선택 수
 *			     - maxCnt : 최대 선택 수
 *			     - range : 범위 체크 (From ~ To)
 *			     - duplication : 중복체크 (dataList에만 사용됨)
 *			     - custom : 사용자함수 체크 (true / false 반드시 return)
 *			  validInfo.count : 체크 수
 *			  validInfo.type이 minCnt, maxCnt 일때 필수
 *			  validInfo.length : 체크길이
 *			  validInfo.type이 minLength, minByteLength, maxLength, maxByteLength 일때 필수
 *			  options : 옵션정보
 *			  options.checkAll : 전체체크 여부 (true : 전체, false : 실패시 리턴)
 * 리턴		: options.chkeckAll 이 true : 전체 유효성 체크 결과 배열로 리턴
 *			  options.chkeckAll 이 false : 전체 유효성 체크 결과 true / false 리턴
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.data.validate
 */
com.data.validate	= function(dcObj, validInfo, options) {

	for (var i = 0 ; i < validInfo.length ; i ++) {

		var item	= validInfo[i];

		if (com.util.isEmpty(item.focus)) {
			if (com.util.isArray(item.id)) {
				item.focus	= _findRefComp(item.id[0]);
			} else {
				item.focus	= _findRefComp(item.id);
			}
		}
	}

	/**
	 * 함수명 	: _findRefComp
	 * 함수설명	: dataList와 바인딩된 컴포먼트 조회 (내부함수)
	 * 파라미터	: id : 컴포넌트 ID
	 * 리턴		: N/A
	 * 작성일 	: 2022.05.16
	 * 작성자 	: Inswave Systems
	 */
	function _findRefComp(id) {

		var refComp	= dcObj.refCompHash;

		for (var item in refComp) {

			var ref	= refComp[item].modelControl.ref;

			if (com.util.isEmpty(ref)) {
				return null;
			} else {
				var chkKey	= com.util.isArray(id) ? id[0] : id;
				var refTemp	= ref.split('.')[1];

				if (chkKey == refTemp) {
					return refComp[item];
				}
			}
		}
		return null;
	};

	var jsonData = dcObj.getJSON();

	return com.data.validateJson(jsonData, validInfo, options);
};


/**
 * 함수명 	: com.data.validateJson
 * 함수설명	: Json 데이터 키값의 유효성을 체크한다.
 *			   - 유효성 유형별로 메시지 출력 후 메시지 창을 닫으면 설정된 컴포넌트로 포커스를 이동한다.
 *			  
 *			  [공통메시지 정보]
 *			  mandatory : {0} 입력해 주십시오.
 *			  mandatorySelect : {0} 선택해 주십시오.
 *			  minLength, minByteLength : {0} 최소 글자수가 {1} 입니다.
 *			  maxLength, maxByteLength : {0} 최대 글자수가 {1} 입니다.
 *			  minCnt : {0} 최소 갯수가 {1} 입니다.
 *			  maxCnt : {0} 최대 갯수가 {1} 입니다.
 *			  range : {0} {1}보다 큽니다.
 * 파라미터	: jsonData : 유효성체크 대상 jsonData
 *			  validInfo : 유효성 체크 정보
 *			  validInfo.id : 컬럼 아이디
 *			   - validInfo.type이 range일 경우 배열
 *			  validInfo.type : 유효성 체크 유형
 *			     - mandatory : 필수값 (length == 0)
 *			     - mandatorySelect : 필수선택 (length == 0)
 *			     - minLength : 최소길이 (length > 길이)
 *			     - minByteLength : 최소길이 바이트체크 (byteLength > 길이)
 *			     - maxLength : 최대길이 (length < 길이)
 *			     - maxByteLength : 최대길이 바이트체크 (byteLength < 길이)
 *			     - minCnt : 최소 선택 수
 *			     - maxCnt : 최대 선택 수
 *			     - range : 범위 체크 (From ~ To)
 *			     - custom : 사용자함수 체크 (true / false 반드시 return)
 *			  validInfo.count : 체크 수
 *			  validInfo.type이 minCnt, maxCnt 일때 필수
 *			  validInfo.length : 체크길이
 *			  validInfo.type이 minLength, minByteLength, maxLength, maxByteLength 일때 필수
 *			  validInfo.customFunc : 유효성 체크 사용자 함수
 *			  - validInfo.type이 ‘custom’ 일 경우 필수
 *			  - customFunc는 반드시 유효성 체크결과를 true / false로 반환해야함.
 *			  validInfo.msgCd : 메시지 프로퍼티 CD
 *			   - 유형별 공통 메시지 사용하지 않고 개별 메시지 사용시 옵션 추가함.
 *			   - validateInfo.type 이 custom 일 경우 필수 (없을 경우 메시지 미노출)
 *			  validInfo.msgArg : 메시지 파라미터
 *			   - {0}, {1} 메시지 파라미터
 *			  
 *			  [공통메시지 정보]
 *			  mandatory : {0} 입력해 주십시오.
 *			  mandatorySelect : {0} 선택해 주십시오.
 *			  minLength, minByteLength : {0} 최소 글자수가 {1} 입니다.
 *			  maxLength, maxByteLength : {0} 최대 글자수가 {1} 입니다.
 *			  minCnt : {0} 최소 갯수가 {1} 입니다.
 *			  maxCnt : {0} 최대 갯수가 {1} 입니다.
 *			  range : {0} {1}보다 큽니다.
 *			  validInfo.focus : 메시지 출력 후 닫기 시 이동할 포커스 컴포넌트
 *			  options : 옵션정보
 *			  options.checkAll : 전체체크 여부 (true : 전체, false : 실패시 리턴)
 * 리턴		: options.chkeckAll 이 true : 전체 유효성 체크 결과 배열로 리턴
 *			  options.chkeckAll 이 false : 전체 유효성 체크 결과 true / false 리턴
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.data.validateJson
 */
com.data.validateJson	= function(jsonData, validInfo, options) {

	var result	= [];
	var options = $.extend({checkAll : false}, options);

	for (var i = 0 ; i < validInfo.length ; i ++) {
		var item		= validInfo[i];
		var chkResult	= null;

		if (item.type == 'mandatory' || item.type == 'mandatorySelect') {
			chkResult	= com.data._validateCheck(item.type, jsonData[item.id]);

		} else if (item.type == 'minLength' || item.type == 'minByteLength' || item.type == 'maxLength' || item.type == 'maxByteLength') {
			chkResult  = (com.util.isEmpty(jsonData[item.id].trim())) ? false : true;

			if (chkResult) {
				chkResult	= com.data._validateCheck(item.type, jsonData[item.id], item);
			}

		} else if (item.type == 'minCnt' || item.type == 'maxCnt') {

			chkResult  = (com.util.isEmpty(jsonData[item.id].trim())) ? false : true;

			if (chkResult) {
				chkResult	= com.data._validateCheck(item.type, jsonData[item.id], item);
			}

		} else if (item.type == 'range') {

			var value1 	= jsonData[item.id[0]];
			var value2 	= jsonData[item.id[1]];

			chkResult	= com.data._validateCheck(item.type, [value1, value2]);

		} else if (item.type == 'custom') {
			chkResult	= item.customFunc(jsonData);
		} else {
			chkResult = false;
		}

		if (options && options.checkAll) {
			result.push($.extend(item, {check : chkResult}));
		} else {
			if (!chkResult) {
				result.push($.extend(item, {check : false}));
				break;
			}
		}
	}

	if (result.length == 0) {
		return true;
	} else {
		if (options && options.checkAll) {
			return result;
		} else {
			com.data._validateMessage(result[0]);
			return false;
		}
	}
};


/**
 * 함수명 	: com.data._validateMessage
 * 함수설명	: 유효성 체크 메시지 창을 호출한다.
 * 파라미터	: info : 메시지 정보
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.data._validateMessage = function(info) {

	 if (com.util.isEmpty(info.msgCd)) {

		 if (info.type == 'mandatory') {
			 info.msgCd 	= 'egov.message.info.web.com.0005';
		 } else if (info.type == 'mandatorySelect') {
			 info.msgCd 	= 'egov.message.info.web.com.0006';
		 } else if (info.type == 'minLength' || info.type == 'minByteLength') {
			 info.msgCd 	= 'egov.message.info.web.com.0007';
		 } else if (info.type == 'maxLength' || info.type == 'maxByteLength') {
			 info.msgCd 	= 'egov.message.info.web.com.0008';
		 } else if (info.type == 'minCnt') {
			 info.msgCd 	= 'egov.message.info.web.com.0009';
		 } else if (info.type == 'maxCnt') {
			 info.msgCd 	= 'egov.message.info.web.com.0010';
		 } else if (info.type == 'range') {
			 info.msgCd 	= 'egov.message.info.web.com.0011';
		 }
	 }

	 if (com.util.isNotEmpty(info.msgCd)) {

		 var msgOption = {
	         msgType    	: 'info',
	         msgCode    	: info.msgCd,
	         msgArg     	: info.msgArg,
	         closeFocusID 	: (com.util.isNotEmpty(info.focus)) ? info.focus.getID() : ''
	     };

		 com.message.openMessage(msgOption);
	 }

};


/**
 * 함수명 	: com.data.validateList
 * 함수설명	: dataList 컬럼값의 유효성을 체크한다.
 * 파라미터	: dcObj : dataList
 *			  validInfo : 유효성 체크 정보
 *			  validInfo.id : 컬럼 아이디
 *			   - validInfo.type이 range일 경우 배열
 *			  validInfo.name : 이름 (메시지 창 띄울 시 이름 사용 : XXX를 입력해 주세요)
 *			   -  - validInfo.type이 range일 경우 배열
 *			  validInfo.type : 유효성 체크 유형
 *			     - mandatory : 필수값 (length == 0)
 *			     - minLength : 최소길이 (length > 길이)
 *			     - minByteLength : 최소길이 바이트체크 (byteLength > 길이)
 *			     - maxLength : 최대길이 (length < 길이)
 *			     - maxByteLength : 최대길이 바이트체크 (byteLength < 길이)
 *			     - minCnt : 최소 선택 수
 *			     - maxCnt : 최대 선택 수
 *			     - range : 범위 체크 (From ~ To)
 *			     - duplication : 중복체크 (dataList에만 사용됨)
 *			     - custom : 사용자함수 체크 (true / false 반드시 return)
 *			  validInfo.count : 체크수
 *			  validInfo.type이 minCnt, maxCnt 일때 필수
 *			  validInfo.length : 체크길이
 *			  validInfo.type이 minLength, minByteLength, maxLength, maxByteLength 일때 필수
 *			  options : 옵션정보
 *			  options.grid : GridView 컴포넌트
 *			  options.checkAll : 옵션정보
 * 리턴		: options.chkeckAll 이 true : 전체 유효성 체크 결과 배열로 리턴
 *			  options.chkeckAll 이 false : 전체 유효성 체크 결과 true / false 리턴 (GridView cell 이동)
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.data.validateList
 */
com.data.validateList	= function(dcObj, validInfo, options) {

	var orgData		= dcObj.getAllJSON();
	var modiData	= dcObj.getModifiedJSON();
	var modiIdx		= dcObj.getModifiedIndex();
	var result		= [];

	for (var i = 0 ; i < modiData.length ; i ++) {

		var rowData	= modiData[i];
		var rowIdx	= modiIdx[i];
		var isValid	= true;

		if (rowData.rowStatus == 'C' || rowData.rowStatus == 'U') {

			for (var j = 0 ; j < validInfo.length ; j ++) {
				var item 	= validInfo[j];

				if (item.type == 'mandatory') {
					if (_addResult(i, item, com.data._validateCheck(item.type, rowData[item.id]))) {
						isValid	= false;
						break;
					}
				} else if (item.type == 'minLength' || item.type == 'minByteLength' || item.type == 'maxLength' || item.type == 'maxByteLength') {
					var mandatory	= com.data._validateCheck('mandatory', rowData[item.id]);

					if (mandatory) {
						if (_addResult(rowIdx, item, com.data._validateCheck(item.type, rowData[item.id], item))) {
							isValid	= false;
							break;
						}
					} else {
						if (_addResult(rowIdx, item, mandatory)) {
							isValid	= false;
							break;
						}
					}

				} else if (item.type == 'minCnt' || item.type == 'maxCnt') {
					var mandatory	= com.data._validateCheck('mandatory', rowData[item.id]);

					if (mandatory) {
						if (_addResult(rowIdx, item, com.data._validateCheck(item.type, rowData[item.id], item))) {
							isValid	= false;
							break;
						}
					} else {
						if (_addResult(rowIdx, item, mandatory)) {
							isValid	= false;
							break;
						}
					}

				} else if (item.type == 'range') {

					var value1 	= rowData[item.id[0]];
					var value2 	= rowData[item.id[1]];

					var mandatory1	= com.data._validateCheck('mandatory', value1);
					var mandatory2	= com.data._validateCheck('mandatory', value2);

					if (mandatory1 && mandatory2) {
						if (_addResult(rowIdx, item, com.data._validateCheck(item.type, [value1, value2]))) {
							isValid	= false;
							break;
						}
					} else {
						if (!mandatory1) {
							if (_addResult(rowIdx, item, mandatory1)) {
								isValid	= false;
								break;
							}
						} else {
							if (_addResult(rowIdx, item, mandatory2)) {
								isValid	= false;
								break;
							}
						}
					}
				} else if (item.type == 'duplicate') {

					if (rowData[item.id] != '') {
						if (_addResult(rowIdx, item, com.data._validateCheck(item.type, rowData[item.id], {id : item.id, data : orgData}))) {
							isValid	= false;
							break;
						}
					}

				} else if (item.type == 'custom') {
					if (_addResult(rowIdx, item, item.customFunc(rowData))) {
						isValid	= false;
						break;
					}
				} 
			}

			if (!options.checkAll && !isValid) {
				break;
			}
		}
	}

	if (result.length == 0) {
		return true;
	} else {

		if (options.checkAll) {
			return result;
		} else {

			if (result[0].type == 'mandatory') {
				alert(result[0].name + ' ' + result[0].type);
			} else if (result[0].type == 'minLength' || result[0].type == 'minByteLength') {
				alert(result[0].name + ' ' + result[0].type + '(' + result[0].length +')');
			} else if (result[0].type == 'maxLength' || result[0].type == 'maxByteLength') {
				alert(result[0].name + ' ' + result[0].type + '(' + result[0].length +')');
			} else if (result[0].type == 'minCnt') {
				alert(result[0].name + ' ' + result[0].type + '(' + result[0].count +')');
			} else if (result[0].type == 'maxCnt') {
				alert(result[0].name + ' ' + result[0].type + '(' + result[0].count +')');
			} else if (result[0].type == 'range') {
				alert(result[0].name + ' ' + result[0].type);
			} else if (result[0].type == 'duplicate') {
				alert(result[0].name + ' ' + result[0].type);
			}

			if (options.grid) {
				var rowIdx	= result[0].rowIdx;
				var colId	= (com.util.isArray(result[0].id)) ? result[0].id[0] : result[0].id;
				options.grid.setFocusedCell(rowIdx, colId);
			}

			return false;
		}
	}

	/**
	 * 함수명 	: _addResult
	 * 함수설명	: 유효성 체크 결과를 추가한다. (내부함수)
	 * 파라미터	: rowIdx : row index
	 * 			  info : 유효성 체크 정보
	 * 			  data : 유효성 체크 결과
	 * 리턴		: N/A
	 * 작성일 	: 2022.05.16
	 * 작성자 	: Inswave Systems
	 */
	function _addResult(rowIdx, info, data) {

		var addData	= $.extend(info, {check : data}, {rowIdx : rowIdx});

		if (options.checkAll) {
			result.push(addData);

			return false;
		} else {
			if (data) {
				return false;
			} else {
				result.push(addData);
				return true;
			}
		}
	}
};


/**
 * 함수명 	: com.data._validateCheck
 * 함수설명	: 값의 유효성을 체크한다. (내부함수)
 * 파라미터	: type : 체크 유형
 *			  value : 체크 대상 값
 *			  option : 체크 옵션
 *			  option.length : 체크 길이
 *			  option.count : 체크 개수
 * 리턴		: true / false
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.data.validateList
 */
com.data._validateCheck	= function(type, value, option) {

	if (type == 'mandatory' && value.trim() == '') {
		return false;
	} else if (type == 'mandatorySelect' && value.trim() == '') {
		return false;
	} else if (type == 'minLength' && value.trim().length < option.length) {
		return false;
	} else if (type == 'minByteLength' && com.str.getByteLength(value.trim()) < option.length) {
		return false;
	} else if (type == 'maxLength' && value.trim().length > option.length) {
		return false;
	} else if (type == 'maxByteLength' && com.str.getByteLength(value.trim().length) > option.length) {
		return false;
	} else if (type == 'minCnt') {
		var tempCnt	= value.split(',');
		return (tempCnt.length >= option.count)
	} else if (type == 'maxCnt') {
		var tempCnt	= value.split(',');
		return (tempCnt.length <= option.count);
	} else if (type == 'range') {
		if (value[0] > value[1]) {
			return false;
		}
	} else if (type == 'duplicate') {

		var filterData	= option.data.filter(function(item) {
			return item[option.id] == value;
		});

		if (filterData.length > 1) {
			return false;
		}
	}

	return true;	
};


/**
 * key, value를 json obj에 저장한다.
 *
 * @memberOf com.data
 * @param {Json} jsonObj 변환된 Json결과 
 * @param {String} key 변환할 키
 * @param {String} value 변환할 값
 * @date 2021.11.01
 * @author Inswave Systems
 * @return {Json} jsonObj 변환된 Json결과 : 첫번째 파라미터값
 * @example
 * com.data.setJsonValue(jsonObj, "key1", "value1");
 * jsonObj : {key1:value1}
 */
com.data.setJsonValue = function (jsonObj, key, value) {
	var keys = Object.getOwnPropertyNames(jsonObj);
	var flag = false;
	for (var i = 0; i < keys.length; i++) {
		if (keys[i] === key) {
			jsonObj[key] = value;
			flag = true;
			break;
		}
	}
	if (flag === false) {
		jsonObj[key] = value;
	}
};

/**
 * json obj에서 해당 key값에 대한 value값을 가져온다.
 *
 * @memberOf com.data
 * @param {Json} jsonObj 조회할 Json데이타 
 * @param {String} key 조회할 키
 * @date 2021.11.01
 * @author Inswave Systems
 * @return {String} key 값에 대한 value값
 * @example
 * var value = com.data.getJsonValue(jsonObj, "key1");
 * value : value1
 */
com.data.getJsonValue = function (jsonObj, key) {
	if(jsonObj===null) {
		jsonObj = new Object();
	}
	var keys = Object.getOwnPropertyNames(jsonObj);
	var result = "";

	for (var i = 0; i < keys.length; i++) {
		if (keys[i] === key) {
			result = jsonObj[key];
			break;
		}
	}

	return result;
};

