/**
 * LocalStorage에서 INI 정보를 가져온다.
 *
 * @param {String} grp 그룹구분 코드
 * @param {String} key 키 값
 * @param {String} sysJob 시스템업무코드
 * @memberOf com.data
 * @date 2021.10.29
 * @author Inswave Systems
 * @return {String} key 값에 해당하는 value 값
 * @example
 * com.data.getIni("menu", "menu_gubun", "pc10_muin_comm");
 */
com.data.getIni = function (grp, key, sysJob) {
	//console.log("com.data.getIni - grp:"+grp+", key:"+key+", sysJob:"+sysJob);
	var strObj = gcm.data.getLocalStorage(sysJob);
	if(strObj===null) {
		return "";
	}
	//console.log("com.data.getIni - strObj:"+strObj);
	var jsonObj = JSON.parse(strObj);
	if(jsonObj===null) {
		return "";
	}
	//console.log("com.data.getIni - jsonObj:"+jsonObj);
	var grpObj = com.data.getJsonValue(jsonObj, grp);
	//console.log("com.data.getIni - grpObj:"+grpObj);
	var value = com.data.getJsonValue(grpObj, key);
	//console.log("com.data.getIni - value:"+value);

	return value;
};

/**
 * LocalStorage에 INI 정보를 저장한다.
 *
 * @param {String} grp 그룹코드
 * @param {String} key 키 값
 * @param {String} value 저장할 값
 * @param {String} sysJob 시스템업무코드
 * @memberOf com.data
 * @date 2021.10.29
 * @author Inswave Systems
 * @example
 * com.data.setIni("menu", "menu_gubun", "1", "pc10_muin_comm");
 */
com.data.setIni = function (grp, key, value, sysJob) {
	//console.log("com.data.setIni - Start key="+key+", value="+value);
	var strObj = gcm.data.getLocalStorage(sysJob);
	var jsonObj = JSON.parse(strObj);
	//console.log("com.data.setIni - jsonObj="+jsonObj);
	if (com.util.isEmpty(jsonObj)) {
		//해당 시스템업무코드가 없는 경우(신규생성) -----------------
		var _newValue = new Object();
		_newValue[key] = value;

		var _newValue2 = new Object();
		_newValue2[grp] = _newValue;

		var str = JSON.stringify(_newValue2);
		gcm.data.setLocalStorage(sysJob, str);
		//console.log("com.data.setIni - sysJob Null key="+key+", value="+value);
		return;
	}

	var grpObj = com.data.getJsonValue(jsonObj, grp);
	if (com.util.isEmpty(grpObj)) {
		//해당 그룹이 없는 경우(신규생성) -----------------
		var _newValue = new Object();
		_newValue[key] = value;

		//새로 만들어진 그룹(jsonObj)을 jsonObj에 넣어준다.(다른 그룹정보 유지해야 함)
		com.data.setJsonValue(jsonObj, grp, _newValue);
		var str = JSON.stringify(jsonObj);
		gcm.data.setLocalStorage(sysJob, str);
		//console.log("com.data.setIni - grpObj Null key="+key+", value="+value);
		return;
	}

	//Value 생성하기 -----------------
	com.data.setJsonValue(grpObj, key, value);
	com.data.setJsonValue(jsonObj, grp, grpObj);
	var str = JSON.stringify(jsonObj);
	gcm.data.setLocalStorage(sysJob, str);
	return;
};



