/**
 * 함수명 	: com.win.getPopupOrgId
 * 함수설명	: 팝업창 원본 id를 조회한다. (팝업창에서 사용)
 * 파라미터	: targetId : 대상 ID
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.win.getPopupOrgId = function(targetId) {

	var popId	= null;

	if (targetId) {
		popId	= _popupMatch(targetId);
	} else {
		var id	= ($p.getFrame()) ? $p.getFrame().getID() : null;

		if (id == null) return null;

		popId	= _popupMatch(id);
	}

	if (popId == null) {
		return _popupMatch(window.name);
	} else {
		return popId;
	}


	/**
	 * 함수명 	: _popupMatch
	 * 함수설명	: 팝업 ID 패턴을 검사하여 팝업 원본 ID 리턴
	 * 파라미터	: id : 대상 ID
	 * 리턴		: N/A
	 * 작성일 	: 2022.05.16
	 * 작성자 	: Inswave Systems
	 */
	function _popupMatch(id) {

		var expr	= /popup[0-9]{10,30}/g;
		var temp	= id.match(expr);

		if (temp) {
			return temp[temp.length-1];
		} else {
			null;
		}
	}   
};


/**
 * 함수명 	: com.win.getPopup
 * 함수설명	: 팝업창을 조회한다.
 * 파라미터	: id : 팝업 아이디
 *			  - 아이디가 없을 경우 자신의 팝업창 조회
 *			  resultType : 리턴 유형
 *			  - POPUP : 팝업 Window (닫기용) 
 *			  - FRAME : 팝업 Frame (화면 이동용)
 *			  - PAGE : 팝업 Scope (페이지 제어용)
 *			  - INFO : 팝업 정보
 * 리턴		: id 가 있으면 해당 팝업창 리턴
 *			  id 가 없으면 자신의 팝업 리턴
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.win.getPopup
 */
com.win.getPopup	= function(id, resultType) {

	var popInfo	= null;
	if (com.util.isEmpty(id)) {
		id	= com.win.getPopupOrgId();
	} else {
		id 	+= '_wframe';
	}

	popInfo	= gcm.popup.getPopupInfo(id);

	if (com.util.isEmpty(popInfo)) {
		popInfo	= _getPopupWin();
	}

	if (popInfo) {
		if (resultType == 'POPUP') {
			return popInfo.popWin;
		} else if (resultType == 'FRAME') {
			if (popInfo.popType == 'wframePopup') {
				return popInfo.popWin.frame;
			} else {
				return null;
			}
		} else if (resultType == 'PAGE') {
			if (popInfo.popType == 'wframePopup') {
				return popInfo.popWin.frame.scope;
			} else {
				return popInfo.popWin.mf.scope;
			}
		} else if (resultType == 'INFO') {
			return popInfo;
		} else {
			return popInfo.popWin;
		}
	}


	/**
	 * 함수명 	: _getPopupWin
	 * 함수설명	: 팝업창을 찾지 못했을 경우 팝업창을 조회한다.
	 * 파라미터	: N/A
	 * 리턴		: 팝업창 정보
	 * 작성일 	: 2022.05.16
	 * 작성자 	: Inswave Systems
	 */
	function _getPopupWin() {

		if ($p.isWFramePopup()) {
			var popObj =  $p.getPopup($p.getPopupId());

			return {popWin : popObj.popupWin};
		} else {
			return {popWin : window};
		}
	}
};


/**
 * 함수명 	: com.win.getPopupCaller
 * 함수설명	: 팝업창을 호출한 페이지를 조회한다.
 * 파라미터	: resultType : 리턴 유형
 *			  - FRAME : wFrame 컴포넌트 (화면 이동용)
 *			  - 없으면 : 페이지 scope
* 리턴		: resultType 이 FRAME : wFrame 컴포넌트
 * 			  resultType 이 없으면 : scope
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.win.getPopupCaller
 */
com.win.getPopupCaller	= function(resultType) {

	var callerId	= '';
	var popType		= '';
	var winObj		= null;

	try {
		var popId		= com.win.getPopupOrgId();
		var popInfo		= gcm.popup.getPopupInfo(popId);

		// 팝업 onpageload 이벤트 발생 후 팝업 정보가 추가되어 팝업 객체로 직접 조회. 
		if (com.util.isEmpty(popInfo)) {
			callerId	= com.page.getParameter('__callerId__');
			popType		= com.page.getParameter('__popType__');
		} else {
			callerId	= popInfo.callerId;
			popType		= popInfo.popType;
		}

		winObj = (popType == 'wframePopup') ? window : opener;

		if (resultType == 'FRAME') {
			return winObj[callerId];
		} else {
			return winObj[callerId].scope;
		}
	} catch(ex) {
		return null;
	}
};


