/**
 * 함수명 	: com.win.setPopupResizeTo
 * 함수설명	: 한개의 팝업창 크기를 변경한다.
 *			   - browserPopup 창은 현재창 보다 클 수 없다.
 * 파라미터	: popupObj : 공통함수에서 리턴한 팝업 정보 (resultType : ‘POPUP’)
 *			   - com.win.getPopup, com.win.searchPopup, com.win.searchPathPopup 함수를 이용해 popupObj 조회
 *			  width : 팝업 창 넒이
 *			  height : 팝업 창 높이
 *			  resizeType : 사이즈 변경 기준 정보
 *			  resizeType.vertical : 높이 변경 기준 
 *			   - top    : top을 기준으로 높이 변경
 *			   - middle : 가운데를 기준으로 높이 변경
 *			   - bottom : bottom을 기준으로 높이 변경  (기본값)
 *			  resizeType.horizontal : 넓이 변경 기준 
 *			   - left : 왼쪽을 기준으로 넓이 변경
 *			   - center : 가운데를 기준으로 넓이 변경
 *			   - right : 오른쪽을 기준으로 넓이 변경 (기본값)
 *            isDirect : 즉시변경여부 (0.1초 delay 여부)
 *            callbackFn : 콜백함수
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.win.setPopupResizeTo
 */
com.win.setPopupResizeTo = function(popupObj, width, height, resizeType, isDirect, callbackFn) {

	console.log({method : 'setPopupResizeTo', isDirect : isDirect, callbackFn : callbackFn});

	var resizeType	= $.extend({
		vertical 	: 'bottom',		// top : 위 , middle : 중심, bottom : 아래 
		horizontal 	: 'right'		// left : 왼쪽, center : 가운데, right : 오른쪽
	}, resizeType);

	var popPos		= {};
	var movePos		= {};
	var gapInfo		= {};
	var isMove		= false;

	width			= parseInt(width);
	height			= parseInt(height);

	//===================================================================
	// 브라우져 팝업창의 경우 비동기로 timer를 이용해야 정확한 위치로 이동함.
	//===================================================================
	if (isDirect) {
		_resize();
	} else {
		setTimeout(_resize, 100);
	}

	/**
	 * 함수명 	: _resize
	 * 함수설명	: 팝업창 사이즈를 변경한다. (내부함수)
	 *			   	- 사이즈 변경 시 resizeType에 따라 팝업 창 위치도 함께 조정
	 *				- wFrame팝업, 브라우져 팝업은 리사이즈 및 위치 조정 계산도 틀림
	 * 파라미터	: N/A
	 * 리턴		: N/A
	 * 작성일 	: 2022.05.16
	 * 작성자 	: Inswave Systems
	 * 예시	 	: API : com.win.setPopupResizeTo
	 */
	function _resize() {
		if (com.win.isPopupWFrame(popupObj)) {
			// 팝업 이동 위치 및 크기 정보
			var $popup		= $(popupObj.render);

			if (isNaN(width)) width = $popup.width();
			if (isNaN(height)) width = $popup.height();

			popPos		= $popup.position();
			gapInfo	= {
				width 	: (width - $popup.width()),
				height	: (height - $popup.height())
			}

			// 팝업 리사이즈
			popupObj.show();
			popupObj.setSize(width, height);
		} else {
			// 팝업 이동 위치 및 크기 정보
			// 팝업 사이즈 조절시 innerWidth, outerWidth 차이가 있고, resizeTo는 outerWidth로 변경됨.
			popPos	= {
				top 	: popupObj.screenTop,
				left	: popupObj.screenLeft
			};

			if (isNaN(width)) width = popupObj.innerWidth;
			if (isNaN(height)) width = popupObj.innerHeight;


			gapInfo	= {
				width 	: (width - popupObj.innerWidth),
				height	: (height - popupObj.innerHeight)
			}


			var resizeGap	= {
				width	: 16,
				height	: 39,
			};

			width 	= width + resizeGap.width;
			height	= height + resizeGap.height;

			// 팝업 리사이즈
			popupObj.resizeTo(width, height);
		}

		//===================================================================
		// 옵션별 팝업 이동 정보 설정 및 팝업 창 이동
		//===================================================================
		// 수직 이동
		if (resizeType.vertical == 'top') {
			isMove	= true;

			movePos.top	= popPos.top - gapInfo.height;
		} else if (resizeType.vertical == 'middle'){
			isMove	= true;

			movePos.top	= popPos.top - (gapInfo.height/2);
		} 

		// 수평 이동
		if (resizeType.horizontal == 'left') {
			isMove	= true;

			movePos.left	= popPos.left - gapInfo.width;
		} else if (resizeType.horizontal == 'center'){
			isMove	= true;

			movePos.left	= popPos.left - (gapInfo.width/2);
		} 

		// 이동 대상이면 com.win.setPopupMoveTo로 함수로 이동함.
		if (isMove) {
			console.log({method : 'resizeTo', move : movePos});
			com.win.setPopupMoveTo(popupObj, movePos.top, movePos.left);
		}

		if (callbackFn) {			
		    callbackFn();
		}
	}
};


/**
 * 함수명 	: com.win.setPopupMaximize
 * 함수설명	: 팝업창을 최대화 한다
 * 파라미터	: popupObj : 공통함수에서 리턴한 팝업 정보 (resultType : ‘POPUP’)
 *			   - com.win.getPopup, com.win.searchPopup, com.win.searchPathPopup 함수를 이용해 popupObj 조회
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.win.setPopupMaximize
 */
com.win.setPopupMaximize = function(popupObj) {

	if (gcm.win.isWbrowser()) {
		if (com.win.isPopupWFrame(popupObj)) {
			com.win.setPopupResizeTo(popupObj, window.screen.availWidth, window.screen.availHeight);
			com.win.setPopupMoveTo(popupObj, 0, 0);
		} else {
			popupObj.maximize();
			popupObj.show();
		}
	} else {
		com.win.setPopupResizeTo(popupObj, window.screen.availWidth, window.screen.availHeight);
		com.win.setPopupMoveTo(popupObj, 0, 0);
	}
};


/**
 * 함수명 	: com.win.setPopupMinimize
