/**
 * 함수명 	: com.win.searchPopup
 * 함수설명	: 팝업창을 검색한다.
 * 파라미터	: searchOptions : 공통함수에서 리턴한 팝업 정보 (resultType : ‘POPUP’)
 *			   - com.win.getPopup
 *			   - com.win.searchPopup
 *			   - com.win.searchPathPopup
 *			   - 배열 아님
 *			  searchOptions.popId : 팝업 ID
 *			   - 값이 없을 경우
 *			     : PARENT, PARENT_ALL, BROTHER : 현재 창 ID
 *			     : CHILD, CHILD_ALL : 현재 페이지 ID
 *			  searchOptions.type : 검색 유형
 *			   - PARENT : 상위 팝업 창
 *			   - PARENT_ALL : 상위 팝업 창 모두
 *			   - BROTHER : 형제 팝업 창
 *			   - CHILD : 자식 팝업 창
 *			   - CHILD_ALL : 자식 팝업 창 모두
 *			  searchOptions.searchInfo : 팝업 오픈 시 등록한 popOptions.searchInfo의 값 검색 정보
 *			  resultType : 리턴 유형
 *			  - POPUP : 팝업 Window (닫기용) 
 *			  - FRAME : 팝업 Frame (화면 이동용)
 *			  - PAGE : 팝업 Scope (페이지 제어용)
 * 리턴		: 팝업정보 목록
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.win.searchPopup
 */
com.win.searchPopup = function(searchOptions, resultType) {

	var resultData	= [];
	var popOptions = {
		id		: searchOptions.id,
		type 	: searchOptions.type,
	};

	if (com.util.isEmpty(popOptions.id)) {
		try {
			popOptions.id = ((window.name != '') ? window.name + '_wframe_' : '') + $p.getFrame().getID();

			if (popOptions.type == 'BROTHER' || popOptions.type == 'PARENT' || popOptions.type == 'PARENT_ALL') {

				var expr	= /popup[0-9]{10,30}/g;
				var temp	= popOptions.id.match(expr);

			    popOptions.id = temp[temp.length-1];
			}
		} catch(ex) {
			popOptions.id = '';
		}
	}

	// 검색정보로만 찾기
	if (popOptions.type == 'FULL') {
		popOptions.id 	= 'mf';
		popOptions.type = 'CHILD_ALL';
	}

	var popInfo	= gcm.popup.searchPopup(popOptions, searchOptions.searchInfo);

	for (var i = 0 ; i < popInfo.length ; i ++) {
		if (resultType == 'POPUP') {
			resultData.push(popInfo[i].popWin);			
		} else if (resultType == 'FRAME') {
			if (popInfo[i].popType == 'wframePopup') {
				resultData.push(popInfo[i].popWin.frame);
			}
		} else if (resultType == 'PAGE') {
			if (popInfo[i].popType == 'wframePopup') {
				resultData.push(popInfo[i].popWin.frame.scope);
			} else {
				resultData.push(popInfo[i].popWin.mf.scope);
			}
		} else {
			resultData.push(popInfo[i]);
		}
	}

	return resultData;
};


/**
 * 함수명 	: com.win.searchPopupPath
 * 함수설명	: 경로로 팝업창을 검색한다.
 * 파라미터	: pathInfo : 팝업 검색 정보
 *			  pathInfo.searchInfo : 팝업 오픈시 popOptions.searchInfo의 값 검색 정보
 *			  resultInfo : searchOptions 으로 검색한 팝업창을 기준으로 리턴할 정보
 *			  resultInfo.type : 검색 유형
 *			   - PARENT : 상위 팝업 창
 *			   - PARENT_ALL : 상위 팝업 창 모두
 *			   - BROTHER : 형제 팝업 창
 *			   - CHILD : 자식 팝업 창
 *			   - CHILD_ALL : 자식 팝업 창 모두
 *			  * 없으면 searchOptions 으로 검색한 팝업 창의 첫번째
 *			  resultInfo.resultType : 검색 결과 유형
 *			  - POPUP : 팝업 Window (닫기용) 
 *			  - FRAME : 팝업 Frame (화면 이동용)
 *			  - PAGE : 팝업 Scope (페이지 제어용)
 * 리턴		: 팝업 정보 목록
 *			   - resultInfo.type 이 없을 경우 마지막 경로의 팝업창
 *			   - resultInfo.type 이 있을 경우 resultInfo로 조회한 팝업창 목록 (배열)
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.win.searchPopupPath
 */
com.win.searchPopupPath = function(pathInfo, resultInfo) {

	var resultData	= [];
	var popId		= '';
	var popInfo		= [];

	for (var i = 0 ; i < pathInfo.length ; i ++) {

		if (pathInfo[i].type == 'PARANT' || pathInfo[i].type == 'CHILD' || pathInfo[i].type == 'BROTHER') {

			var popOptions 		= {id : '', type : pathInfo[i].type};
			var searchOptions	= pathInfo[i].searchInfo;

			if (popId == '' ) {

				popOptions.id = ((window.name != '') ? window.name + '_wframe_' : '') + $p.getFrame().getID();

				if (popOptions.type == 'BROTHER' || popOptions.type == 'PARENT') {
					if (window.name != '') {
						popOptions.id = window.name;
					} else {
						var parent	= gcm.popup.searchPopup({id : popOptions.id, type : 'PARENT'})[0];
						popOptions.id = parent.id;
					}
				}
			} else {
				popOptions.id = popId;
			}

			popInfo	= gcm.popup.searchPopup(popOptions, searchOptions);

			if (!popInfo || popInfo.length == 0) {
				return null;
			} else {
				popId = popInfo[0].id;
			}

		} else {
			console.log('팝업 찾기 경로 type이 잘못되었습니다.');
			return null;
		}
	}

	if (com.util.isEmpty(resultInfo.type)) {
		if (resultType == 'POPUP') {
			return popInfo[0].popWin;			
		} else if (resultType == 'FRAME') {
			if (popInfo[i].popType == 'wframePopup') {
				popInfo[0].popWin.frame;
			} else {
				return null;
			}
		} else if (resultType == 'PAGE') {
			if (popInfo[i].popType == 'wframePopup') {
				return popInfo[0].popWin.frame.scope;
			} else {
				return popInfo[0].popWin.mf.scope;
			}
		} else {
			return popInfo[0].popWin;
		}
	} else {
		var resultOptions	= {
			id 		: popInfo[0].id,
			type 	: resultInfo.type
		};
		return com.win.searchPopup(resultOptions, resultInfo.resultType);
	}
};

/**
 * 함수명 	: com.win.isPopup
