};


/**
 * 함수명 	: com.win.openPopup
 * 함수설명	: 팝업창을 오픈한다.
 * 파라미터	: url : 페이지 URL
 *			  opt : 팝업 옵션 정보
 *			  opt.id : 팝업 아이디 (없으면 랜덤생성)
 *			  opt.popupName : 팝업창 이름
 *			  opt.type : 팝업 종류
 *			   wframePopup : 레이어팝업
 *			   browserPopup : 윈도우 팝업
 *			  opt.width : 팝업 넓이
 *			  opt.height : 팝업 높이
 *			  opt.top : 팝업 상단 위치
 *			  opt.left : 팝업 좌측 위치
 *			  opt.modal : 모달 / 모달리스 창
 *			  opt.alwaysOnTop : 기존 팝업이 항상 위에 떠있게 함
 *			  opt.useModalStack : 여러 개의 팝업을 생성할 경우, 제일 마지막에 표시되는 팝엄만 활성화
 *			  opt.resizable : size 조절 유무 
 *			   - opt.type 이 wframePopup 인 경우 해당
 *			  opt.override : 동일 아이디가 있을 때 처리
 *			   - true : 기존팝업 종료 후 생성
 *			   - false : 아이디 랜덤생성
 *			  data : 팝업 전달 데이터
 *			  {
 *			   팝업데이터 : {...}
 *			    callbackFn : scwin.popOpenCallbackFn - 콜백함수
 *			  }
 *			  data.callbackFn : 팝업창 닫기 시 호출할 콜백 함수 
 *			   - com.win.closePopup에서 전송할 데이터를 넘길 수 있음
 * 리턴		: 팝업 아이디
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.win.openPopup
 */
com.win.openPopup = function(url, popOptions, data, passLoginCheck) {

	var isLogin	= com.session.isLogin(url);

	//=======================================================================
	// 팝업 오픈시 로그인 여부 체크
	//=======================================================================
	if (isLogin || passLoginCheck) {

		// popupKey가 있을 경우 중복 팝업 창 띄우는 걸 방지
		if (com.win._checkOpenPopup(popOptions) == false) return;

		try {
			console.log("## 통합테스트용 콘솔 로그 - OPEN_POPUP :: POPUP_URL:" + url);

			var mainWin	= gcm.win.getMainWindow();

			// 시스템별 옵션 설정
			if (gcm.SYS_ID == 'PM10' || gcm.SYS_ID == 'PM20' || gcm.SYS_ID == 'PM60') {
				popOptions.useATagBtn = true;
			} else if (gcm.SYS_ID == 'IM10') {
				if (com.util.isEmpty(popOptions.className)) {
					popOptions.className = "no_header";
				}
			}

			//=======================================================================
			// 팝업 기본값 설정 및 위치 지정
			//=======================================================================
			popOptions.id			= 'popup' + com.num.random();
			popOptions.type			= popOptions.type || "wframePopup";
			popOptions.modal		= com.util.isEmpty(popOptions.modal) ? true : popOptions.modal;
			popOptions.width		= popOptions.width || 500;
			popOptions.height		= popOptions.height || 500;
			popOptions.posScreen 	= (popOptions.type == 'wframePopup') ? '' : popOptions.posScreen || 'WIN';
			popOptions.orgLeft		= popOptions.left;
			popOptions.orgTop		= popOptions.top;

			if (popOptions.type == 'wframePopup') {
				_getPopupPosition(popOptions);
			} else {
				_getPopupPositionWB(popOptions);
			}

	        //=======================================================================
			// 팝업 콜백 설정 & Caller 설정 (공통 파라미터 설정)
			//=======================================================================
			var popData = null;

			if (com.util.isArray(data)) {
				popData	= data;
			} else {
				popData	= $.extend({}, data);
			}

			popData.__callerId__ 	= ($p.getFrame() && $p.getFrame().id) ? $p.getFrame().id : 'mf';
			popData.__popName__		= (popOptions.popupName) ? popOptions.popupName : '';
			popData.__popType__		= popOptions.type;

			if (com.util.isNotEmpty(popData) && com.util.isNotEmpty(popData.callbackFn)) {
		    	if (com.util.isFunction(popData.callbackFn)) {
		    		var callbackId 		= $p.id +  "__close_callback_Func__" + new Date().getTime();

		            gcm.CB_FUNCTION_MANAGER["cbFuncSave"][callbackId] = popData.callbackFn;
		            popData.callbackId = callbackId;

		            delete popData.callbackFn;
		       } else {
		    		console.log('콜백함수가 함수형이 아닙니다. 함수형으로 설정해 주세요.');
		       }
		    } 

		    //=======================================================================
			// 팝업 옵션 설정
			//=======================================================================
			var options 		= {
		        id 				: popOptions.id,
		        popupName 		: popOptions.popupName || "",
		        type 			: popOptions.type,
		        width 			: popOptions.width,
		        height 			: popOptions.height,
		        top 			: popOptions.top,
		        left 			: popOptions.left,
		        modal 			: com.util.isEmpty(popOptions.modal) ? true : popOptions.modal,
		        className 		: popOptions.className || '',
		        useATagBtn 		: com.util.isEmpty(popOptions.useATagBtn) ? false : popOptions.useATagBtn,
		        alwaysOnTop 	: com.util.isEmpty(popOptions.alwaysOnTop) ? false : popOptions.alwaysOnTop,
		        resizable 		: com.util.isEmpty(popOptions.resizable) ? false : popOptions.resizable,
		        scrollbars		: true,
		        useMaximize		: false,
		        useModalStack 	: com.util.isEmpty(popOptions.modal) ? true : popOptions.modal,
		        dataObject 		: com.win.frameParamOption(popData).dataObject,
		    };

		    console.info({method : 'openPopup', options : options});

		    //=======================================================================
			// 팝업 오픈 && 팝업 정보 저장
			//=======================================================================
		    popOptions.postParam	= true;

		    // 프로세스메시지 중지
		    WebSquare.layer.hideProcessMessage();

		    if (options.type == 'wframePopup') {		

		    	// PM10, PM20의 프레임 팝업화면은 윈도우 내부창의 크기를 벗어날수 없도록 조정한다.
		    	if ( gcm.SYS_ID == 'PM10' || gcm.SYS_ID == 'PM20' ) {
					var innerWidth = window.innerWidth;
			        var innerHeight = window.innerHeight;

			        if(innerHeight < popOptions.height){
			        	options.height = innerHeight;
			        }
			        if(innerWidth < popOptions.width ){
			        	options.width = innerWidth;
			        }
				}

		    	$p.openPopup(url, options);
		    } else {

		    	if (gcm.SYS_ID == 'IM10') options.popupUrl = 'popup.jsp';

		    	var paramUrl = '';
//		    	console.log("popupe log url ===> " + url);
//		    	console.log("popupe log options ===> " + JSON.stringify(options));
		    	//var paramUrl = ((com.util.isNotEmpty(data))) ? '&paramData=' + WebSquare.text.BASE64Encode(com.str.serialize(data)) : '';

		    	// 브라우져 팝업 창의 파라미터는 window에 __popupParam__를 추가하여 파라미터를 조회함
		    	//	- 큰 파라미터의 경우 414오류가 발생하여 window에 __popupParam__을 이용함.
		    	$p.openPopup(url + paramUrl, options);
		    }

		    var searchInfo	= $.extend({
		    	__popType__ : popOptions.type
		    }, (popOptions.searchInfo) ? popOptions.searchInfo : {});

		    // 팝업 키 추가 (중복 팝업 방지)
		    if (com.util.isNotEmpty(popOptions.popupKey)) searchInfo.__popupKey__ = popOptions.popupKey;

		    var parentId	= com.util.isNotEmpty($p.getFrame()) ? $p.getFrame().getID() : 'mf';
		    var popInfo		= {
		    	id 			: options.id + '_wframe',
		    	orgId		: popOptions.id, 								// 오픈한 팝업창 아이디
		    	popName		: popOptions.popupName,
		    	parentId	: (window.name == '') ? parentId : window.name + '_wframe_' + parentId,								// 호출한 팝업 아이디 (메인 : mf, 팝업 : 팝업 아이디)
		    	scopeId		: parentId,
		    	searchInfo	: searchInfo,
		    	sub			: [],
		    	popWin		: _getPopupWindow(options.id, popOptions),
		    	callerId	: popData.__callerId__,
		    	popType		: popOptions.type,								// 팝업창 종류
		    	popModal	: options.modal,								// 팝업창 종류
		    };

		    // 팝업정보 저장
		    setTimeout(function() {
		    	gcm.popup.setPopupInfo(popInfo);
		    }, 0);

		    // 팝업창 닫기 이벤트 정의
		    if ( popInfo.popType == 'wframePopup' ) {
		        if ( gcm.SYS_ID == 'PM20' ) {
                    var closeObj    = $(popInfo.popWin.render).find('.w2window_close');

                    closeObj.bind('touchstart click', {id : options.id}, function(e) {
                        try {
                            var popId   = e.data.id;
                            var popObj  = com.win.getPopup(popId, 'PAGE');

                            // 팝업 닫기 시 콜백 함수에 리턴할 데이터 처리 함수
                            // 해당 팝업에 scwin.closeCallBackDataFn() 함수가 있는 경우에 한해 해당 함수의 결과를 return 
                    		if (popObj.scwin.closeCallBackDataFn) {
                    			var result = popObj.scwin.closeCallBackDataFn();
                    			popObj.com.win.closePopup(result);
                    		} else {
                    			popObj.com.win.closePopup('close');
                    		}

                        } catch (ex) {
                            return;
                        }
                    }, true);
		        }else if ( gcm.SYS_ID != 'IM10' ) {
                    var closeObj    = $(popInfo.popWin.render).find('.w2window_close');

                    closeObj.bind('click', {id : options.id}, function(e) {
                        try {
                            var popId   = e.data.id;
                            var popObj  = com.win.getPopup(popId, 'PAGE');

                            // 팝업 닫기 시 콜백 함수에 리턴할 데이터 처리 함수
                            // 해당 팝업에 scwin.closeCallBackDataFn() 함수가 있는 경우에 한해 해당 함수의 결과를 return 
                            if (popObj.scwin.closeCallBackDataFn) {
                    			var result = popObj.scwin.closeCallBackDataFn();
                    			popObj.com.win.closePopup(result);
                    		} else {
                    			popObj.com.win.closePopup('close');
                    		}

                        } catch (ex) {
                            return;
                        }
                    }, true);
		        }
		    }

		    // 팝업 ID 리턴.
		    return options.id;
		} catch (ex) {
			console.error({method : 'com.win.openPopup', error : ex});
		}
	} else {
		com.message.logout();
	}

	/**
	 * 함수명 	: _getPopupPosition
	 * 함수설명	: 팝업창의 위치를 설정한다. (내부함수 : wframePopup)
	 * 파라미터	: options : 팝업 옵션
	 * 리턴		: N/A
	 * 작성일 	: 2022.09.01
	 * 작성자 	: Inswave Systems
	 */
	function _getPopupPosition(options) {

		if (com.util.isEmpty(options.left)) {
			options.left	= (document.body.offsetWidth - options.width) / 2 + $(document).scrollLeft();
		}

		if (com.util.isEmpty(options.top)) {
			options.top		= (window.innerHeight - options.height) / 2 + $(document).scrollTop();
		}

		if (options.left < 0) options.left = 5;
		if (options.top < 0) options.top = 5;
	}


	/**
	 * 함수명 	: _getPopupPositionWB
	 * 함수설명	: 팝업창의 위치를 설정한다. (내부함수 : browserPopup)
	 * 파라미터	: options : 팝업 옵션
	 * 리턴		: N/A
	 * 작성일 	: 2022.09.01
	 * 작성자 	: Inswave Systems
	 */
	function _getPopupPositionWB(options) {

		var screen	= {};

		// 절대 좌표 일경우
		if (options.type == 'browserPopup' && options.posScreen == 'ABSOLUTE') {
			options.top		= options.top + 'px';
			options.left	= options.left + 'px';
			options.width	= options.width + 'px';
			options.height	= options.height + 'px';
		} else {
			// 상대 좌표일 경우
			if (options.type == 'browserPopup' && gcm.SCREEN_INFO.screen) {

				screen.top		= window.screen.availTop;
				screen.left		= window.screen.availLeft;
				screen.width	= window.screen.availWidth;
				screen.height	= window.screen.availHeight;

				if (options.posScreen == 'OWIN' && gcm.SCREEN_INFO.count == 2) {
					var otherScreen		= {};

					if (window.screen.availLeft == gcm.SCREEN_INFO.screen[0].left) {
						otherScreen	= gcm.SCREEN_INFO.screen[1];
					} else {
						otherScreen	= gcm.SCREEN_INFO.screen[0];
					}

					screen.top		= otherScreen.top;
					screen.left		= otherScreen.left;
					screen.width	= otherScreen.width;
					screen.height	= otherScreen.height;
				}
			} else {
				screen.top		= window.screen.availTop;
				screen.left		= window.screen.availLeft;
				screen.width	= window.screen.availWidth;
				screen.height	= window.screen.availHeight;
			}

			// 팝업 위치 결정
			options.top		= ((com.util.isNotEmpty(popOptions.top)) ? options.top : (screen.height- options.height) / 2);
			options.left	= ((com.util.isNotEmpty(popOptions.left)) ? options.left : (screen.width- options.width) / 2);

			options.top		= parseInt(options.top) + screen.top + 'px';
			options.left	= parseInt(options.left) + screen.left + 'px';
			options.width	= options.width + 'px';
			options.height	= options.height + 'px';
		}
	}

