	/**
	 * 함수명 	: _getPopupWindow
	 * 함수설명	: 팝업창 정보를 조회한다. (내부함수)
	 * 파라미터	: id : 팝업창 ID
	 * 			  type : 팝업종류
	 * 리턴		: 팝업객체 (popupWin)
	 * 작성일 	: 2022.09.01
	 * 작성자 	: Inswave Systems
	 */
	function _getPopupWindow(id, popOptions) {

		var popList	= w2popup_singleton.popupList;

		for (var i = 0 ; i < popList.length ; i ++) {

			if (popList[i].id == id) {
				popList[i].popupWin.popType = popOptions.type;

				// 브라우져 팝업 & 포스트 방식으로 파라미터 전달 시 open한 window객체에 __popupParam__를 추가.
				//  - 파라미터가 클 경우 오류 발생 하여 오픈한 window객체 사용
				if (popOptions.type == 'browserPopup') {
					popList[i].popupWin.__popupParam__ = popData;
				}

				return popList[i].popupWin;
			}
		}
		return null;
	}
};


/**
 * 함수명 	: com.win.openPopupPms
 * 함수설명	: 동기식 팝업창을 오픈한다. (콜백함수 없음)
 * 파라미터	: url : 페이지 URL
 *			  opt : 팝업 옵션 정보
 *			  opt.id : 팝업 아이디 (없으면 랜덤생성)
 *			  opt.popupName : 팝업창 이름
 *			  opt.type : 팝업 종류
 *			   wframePopup : 레이어팝업
 *			   browserPopup : 윈도우 팝업
 *			  opt.width : 팝업 넓이
 *			  opt.height : 팝업 높이
 *			  opt.top : 팝업 상단 위치
 *			  opt.left : 팝업 좌측 위치
 *			  opt.modal : true : 모달 
 *			  false : 모달리스 창
 *			  opt.alwaysOnTop : 기존 팝업이 항상 위에 떠있게 함
 *			  opt.useModalStack : 여러 개의 팝업을 생성할 경우, 제일 마지막에 표시되는 팝엄만 활성화
 *			  opt.resizable : size 조절 유무 
 *			   - opt.type 이 wframePopup 인 경우 해당
 *			  opt.override : 동일 아이디가 있을 때 처리
 *			   - true : 기존팝업 종료 후 생성
 *			   - false : 아이디 랜덤생성
 *			  data : 팝업 전달 데이터
 *			  {
 *			   ...
 *			  }
 * 리턴		: 팝업 닫기 con.win.closePopup 함수에 사용한 파라미터
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.win.openPopupPms
 */
com.win.openPopupPms = function(url, opt, data) {

	if (gcm.SYS_ID != 'IM10') {
		alert('전용브라우져에서만 사용 가능합니다.(IM10)');
		return;
	}

	if (com.util.isEmpty(data)) {
		data	= {};
	}

	// 비동기 처리를 위해 Promise를 이용하여 콜백 처리.
	return new Promise(function(resolve) {

		if (com.util.isEmpty(opt)) opt = {};

		// 동일 팝업창 유무 체크
		// - 동일 팝업 창 있음 : false 리턴
		// - 동일 팝업 창 없음 : callback 함수 리턴
		if (com.win._checkOpenPopup(opt) == false) {
			setTimeout(function(){
				resolve(false);
			}, 10);

			return;
		} else {
			opt.modal	= true;
			opt.disableCloseButton = true;
			data.callbackFn = function(data) {
				setTimeout(function(){
					resolve(data);
				}, 200);
			};
		}

		com.win.openPopup(url, opt, data);
	});
};


/**
 * 함수명 	: com.win._checkOpenPopup
 * 함수설명	: 팝업창 오픈 여부
 * 				- options.popupKey와 동일한 팝업창이 오픈되어 있는지 체크
 * 				- 동일 팝업 창이 있는 경우 포커스 이동 시킴
 * 파라미터	: options : 팝업 옵션
 * 리턴		: true / false
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
com.win._checkOpenPopup = function(options) {

	console.log('checkOpenPopup');

	var w2PopupList	= window.w2popup_singleton.popupList;
	for (var i = 0 ; i < w2PopupList.length ; i ++) {
		if (w2PopupList[i].popupWin._zIndex) {
			w2PopupList[i].popupWin.setStyle('z-index', w2PopupList[i].popupWin._zIndex);
		}
	}

	if (com.util.isNotEmpty(options.popupKey)) {
		var searchOptions   = {
            type         : 'FULL',
            searchInfo   : {__popupKey__ : options.popupKey}
        };

		var popList = com.win.searchPopup(searchOptions, 'POPUP');

		if (popList.length == 0) {
			return true;
		} else {
			// wframePopup : z-index를 조정하여 포커스 이동
			// browserPopup : 팝업객체(window)에 focus를 줌
			if (popList[0].popType && popList[0].popType == 'wframePopup') {

				var zIndex	= popList[0].getStyle('z-index');

				popList[0]._zIndex = zIndex;

				popList[0].setStyle('z-index', (zIndex+1));

				if (gcm.SYS_ID == 'IM10') $('#' + window.focusInfo[popList[0].org_id].last).focus();
			} else {
				popList[0].focus();
			}
			return false;
		}
	} else {
		return true;
	}
}

