 */
com.win.closePopup = function(resultData) {

	console.log({method : 'closePopup', data : resultData});

	var popWin		= com.win.getPopup();
	var popCom		= ((popWin.popType == 'wframePopup') ? popWin.frame.scope : popWin.mf.scope).com;
	var callbackId	= popCom.page.getParameter('callbackId');
	var callerId	= popCom.page.getParameter('__callerId__');
	var popType		= popCom.page.getParameter('__popType__');
	var callbackFn	= null;
	var win			= (popType == 'wframePopup') ? window : opener;

	// Callback 함수 실행
	if (com.util.isNotEmpty(callbackId)) {
    	callbackFn = win.gcm.CB_FUNCTION_MANAGER["cbFuncSave"][callbackId];

        if (callbackFn) {
        	callbackFn(resultData);
        	delete win.gcm.CB_FUNCTION_MANAGER["cbFuncSave"][callbackId];
        }
    }

	// 팝업 닫기 시 처리할 함수
	try {
		if ($p.getFrame && $p.getFrame().scope && $p.getFrame().scope.scwin.endPageFn) {
			$p.getFrame().scope.scwin.endPageFn();
		}
	} catch(ex) {
		console.log(ex);
	}

	// 팝업창을 닫는다.
	com.win.closePopupList(popWin);
};

