/**
 * 함수명 	: com.win.closePopupList
 * 함수설명	: 팝업창을 닫는다. (com.win.closePopup 함수에서 실제 팝업창을 닫는 처리)	
 * 파라미터	: N/A
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.win.closePopup
 */
com.win.closePopupList = function(popInfo) {

	var closePopId	= [];
	var popList		= (com.util.isArray(popInfo)) ? popInfo : [popInfo];

	for (var i = popList.length -1 ; i > -1  ; i --) {
		try {
			if (com.util.isNotEmpty(popList[i])) {
				var popId		= ((com.util.isEmpty(popList[i].name)) ? popList[i].id : popList[i].name ) + '_wframe';
				var closeData	= closePopId.filter(function(item) {return item == popId;});

				if (closeData.length == 0) {
					var childList	= gcm.popup.searchPopup({id : popId, type : 'CHILD_ALL'});

					for (var j = 0 ; j < childList.length ; j ++) {

						var closeId	= childList[j].id;
						closePopId.push(closeId);
						childList[j].popWin.close();
					}
				}

				// 포커스 이동
				_setFocus();

				// 팝업창 닫기
				popList[i].close();

				try {
					var thisData	= gcm.popup.getPopupInfo(popId);
					var parentData	= gcm.popup.getPopupInfo(thisData.parentId);

					for (var j = parentData.sub.length -1 ; j > -1 ; j --) {
						if (parentData.sub[j] == thisData) {
							parentData.sub.splice(j, 1);
							break;
						}
					}
				} catch(ex) {
					console.log(ex);
				}
			}
			gcm.popup.clearPopupInfo();
		} catch(ex) {
			console.log(ex);
		}
	}

	function _setFocus() {

		// 포커스 이동
		if (gcm.SYS_ID == 'IM10' || gcm.SYS_ID == 'ZI01') {

			// 브라우져 팝업 창의 경우 호출자를 찾아야 함.
			var callerPage	= com.win.getPopupCaller();

			// 호출자가 없는 경우 (메인에서 닫을 시) 포커스 이동을 하지 않음.
			if (!callerPage) return;

			var focusTarget	= 'main';

			if (callerPage.com.win.isPopup()) {

				var popObj	= callerPage.com.win.getPopup();

				if (popObj.popType == 'wframePopup') {

					callerPage.im10.focus.setFocusFrame(popObj.org_id);

					//websquare 측에서 불필요한 부분으로 해당 부분이 인풋박스 타이핑시 한글자동완성에 영향을 미친다고 하여 주석처리함
					//callerPage.im10.getWindow().focus();
				} else {
					focusTarget	= com.str.replaceAll(popObj.name, 'mf_', '');

					popObj.im10.focus.setFocusFrame(focusTarget);

					//websquare 측에서 불필요한 부분으로 해당 부분이 인풋박스 타이핑시 한글자동완성에 영향을 미친다고 하여 주석처리함
					//popObj.focus();
				}
			} else {
				callerPage.im10.focus.setFocusFrame(focusTarget);
			}
		}
	}

};


