 * 파라미터	: menuInfo : 메뉴정보 (각 포탈 담당자에게 데이터 확인)
 *			  param : 메뉴오픈 시 전달할 파라미터
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.win.openMenu
 */
com.win.openMenu = function(menuInfo, param, beforeCallback) {

	var sysId	= gcm.SYS_ID;

	if (sysId == 'IM10') {
		if (com.util.isNotEmpty(menuInfo.file_path)) { 
			if (com.session.isLogin(menuInfo.file_path)) {
				gcm.win.openMenu($p, menuInfo, param, beforeCallback);
			} else {
				com.message.logout();
			}
		}
	} else if (sysId == 'PM10'){
		if (com.util.isNotEmpty(menuInfo.menu_url)) { 
				gcm.win.openMenu($p, menuInfo, param);
		} else {
			com.message.logout();
		}
	} else if (sysId == 'PM20'){
		if (com.util.isNotEmpty(menuInfo.menu_url)) { 
				gcm.win.openMenu($p, menuInfo, param);
		} else {
			com.message.logout();
		}
	} else if (sysId == 'SM30') {
		if (com.util.isNotEmpty(menuInfo.url)) { 
			if (com.session.isLogin(menuInfo.url)) {
				gcm.win.openMenu($p, menuInfo, param);
			} else {
				com.message.logout();
			}
		}
	} else if (sysId == 'PM60'){
		if (com.util.isNotEmpty(menuInfo.menu_link)) { 
			gcm.win.openMenu($p, menuInfo, param);
		} else {
			com.message.logout();
		}
	}
};


