/**
 * 함수명 	: com.win.saerchFrame
 * 함수설명	: Frame을 검색한다.
 * 파라미터	: options : 옵션정보
 *			  options.sch_type : 검색방법 
 *			   - PARENT : 상위
 *			   - CHILD : 하위
 *			   - BROTHER : 형제
 *			  options.sch_all : 검색 결과 
 *			   true : 동일 아이디 모두  (배열 Frame)
 *			   false : 가장 가까운 Frame 1개만
 *			  id : Frame 아이디
 *			   - WFrame : WFrame 아이디
 *			   - Tab Content : content 아이디
 * 리턴		: options.sch_all
 *			   true : 동일 아이디 모두(배열 Frame)
 *			   false : 가장 가까운 Frame 1개만
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.win.saerchFrame
 */
com.win.searchFrame = function(options, id) {

	var options = $.extend({
		sch_scope	: $p.getFrame().getID(),
		sch_type 	: 'PARENT',
		sch_all 	: false
	}, options);

	var thisId		= options.sch_scope;
	var thisInfo 	= gcm.WFRAME_INFO.filter(function(item) {return item.id == thisId})[0];
	var thisLevel	= thisInfo.level;
	var thisPath	= thisInfo.path;
	var result		= [];

	if (options.sch_type  == 'PARENT' || options.sch_type == 'CHILD') {
		for (var i = 0 ; i < gcm.WFRAME_INFO.length ; i ++) {

			var isFind	= false;
			var pathCnt	= 0;

			if (thisId != gcm.WFRAME_INFO[i].id ) {
				if (options.sch_type == 'PARENT') {
					if (thisPath.indexOf(gcm.WFRAME_INFO[i].id) !=-1) {
						pathCnt	= 1;
						isFind	= true;
					} 
				} else if (options.sch_type == 'CHILD') {
					if (gcm.WFRAME_INFO[i].path.indexOf(thisPath) !=-1) {
						pathCnt	= 2;
						isFind	= true;
					} 
				}
			}

			if (isFind) {
				if (gcm.WFRAME_INFO[i].orgId == id || gcm.WFRAME_INFO[i].orgId.indexOf('contents_' + id + '_body') != -1) {
					var addObj	= gcm.WFRAME_INFO[i];
					addObj.gap	= (Math.abs(thisLevel - gcm.WFRAME_INFO[i].level)) * 100 + pathCnt;
					result.push(addObj);
				} 
			}
		}
	} else if (options.sch_type == 'BROTHER') {
		result	= gcm.WFRAME_INFO.filter(function(item) {
			return (thisInfo.parent == item.parent) && (item.orgId == id || item.orgId.indexOf('contents_' + id + '_body') != -1)
		});
	}

	if (result.length == 0) {
		return null;
	} else {

		if (result.length > 1) {
			result.sort(function(a, b) {
				return a.gap - b.gap;
			});
		}

		if (options.sch_all) {

			var resultFrame	= [];
			for (var i = 0 ; i < result.length ; i ++) {
				var frameObj	= $p.getComponentById(result[i].id);
				resultFrame.push(frameObj);
			}

			return resultFrame;
		} else {
			var frameObj	= $p.getComponentById(result[0].id);
			return frameObj;
		}
	}
};


/**
 * 함수명 	: com.win.searchFramePath
 * 함수설명	: Frame을 검색한다.
 * 파라미터	: N/A
 * 리턴		: resultInfo 없을 경우
 *			   - pathInfo로 조회한 Frame (Object)
 *			  resultInfo 가 있을 경우
 *			   - resultInfo.type, resultInfo.id에 맞는 Frame (배열)
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.win.searchFramePath
 */
com.win.searchFramePath = function(pathInfo, resultInfo) {

	var wFrame		= $p.getFrame();
	var sch_scope	= wFrame.getID();
	var thisInfo 	= gcm.WFRAME_INFO.filter(function(item) {return item.id == sch_scope})[0];
	var tabInfo;
	var isTab		= false;

	for (var i = 0 ; i < pathInfo.length ; i ++) {
		var options = {
			sch_scope	: sch_scope,
			sch_type 	: pathInfo[i].sch_type,
		};

		// WFrame 찾기
		wFrame	= com.win.searchFrame(options, pathInfo[i].id);

		if (com.util.isEmpty(wFrame)) {
			return null;
		} else {
			// Next WFrame 찾기
			sch_scope	= wFrame.id;
		}
	}

	// 결과 리턴방식 (형제, 탭)
	var resultFrame = [];

	if (resultInfo) {

		var resultObj;

		if (resultInfo.type == 'CHILD') {
			resultObj	= gcm.WFRAME_INFO.filter(function(item) {
				return item.parent == wFrame.id;
			});
		} else if (resultInfo.type == 'BROTHER') {
			var tempObj	= gcm.WFRAME_INFO.filter(function(item) {
				return item.id == wFrame.id;
			});

			resultObj	= gcm.WFRAME_INFO.filter(function(item) {
				return item.parent == tempObj[0].parent;
			});
		} 

		if (resultInfo.id) {
			for (var i = 0 ; i <  resultObj.length ; i ++ ) {
				for (var j = 0 ; j < resultInfo.id.length ; j++) {
					if (resultObj[i].orgId == resultInfo.id[j] || resultObj[i].orgId.indexOf('contents_' + resultInfo.id[j] + '_body') !=-1) {
						var frameObj	= $p.getComponentById(resultObj[i].id)

						resultFrame.push(frameObj);
						break;
					}
				}
			}
		} else {
			for (var i = 0 ; i <  resultObj.length ; i ++ ) {
				var frameObj	= $p.getComponentById(resultObj[i].id)

				resultFrame.push(frameObj);
			}
		}
		return resultFrame;
	} else {
		return wFrame;
	}
};


