 * 파라미터	: sbmObj : Submission 컴포넌트
 *			   - target 속성 설정 않함.
 *			  dcObj : 검색 파라미터 dataMap
 *			  paramData : 보고서 파리미터
 *			  paramData.oz_title : 보고서 타이틀
 *			  paramData.oz_ozr_path : 보고서 OZR 경로
 *			  paramData.oz_param1 : 보고서 추가 파라미터 1
 *			  paramData.oz_param2 : 보고서 추가 파라미터 2
 *			  paramData.oz_param3 : 보고서 추가 파라미터 3
 *			  paramData.oz_param4 : 보고서 추가 파라미터 4
 *			  paramData.oz_param5 : 보고서 추가 파라미터 5
 *			  paramData.oz_param6 : 보고서 추가 파라미터 6
 *			  paramData.oz_param7 : 보고서 추가 파라미터 7
 *			  paramData.oz_param8 : 보고서 추가 파라미터 8
 *			  paramData.oz_param9 : 보고서 추가 파라미터 9
 *			  paramData.oz_param10 : 보고서 추가 파라미터 10
 *			  popOptions : 팝업 옵션
 *			  popOptions.type : 팝업 유형
 *			  -	wframePopup, browserPopup
 *			  popOptions.modal : 팝업 모달 유무
 *			   - true, false
 *			  popOptions.width : 팝업 넓이
 *			  popOptions.height : 팝업 높이
 *			  popOptions.posScreen : 팝업 창 위치
 *			   - WIN, OWIN (전용브라우져)
 *			  viewOptions : 뷰어 옵션 정보
 *			  viewOptions.viewer_usetoolbar : 툴바 사용 여부
 *			  viewOptions.toolbar_save : 저장 아이콘 표시 여부 
 *			  viewOptions.toolbar_print : 인쇄 아이콘의 표시 여부
 *			  viewOptions.toolbar_zoomin : 확대 아이콘의 표시 여부 
 *			  viewOptions.toolbar_zoomout : 축소 아이콘의 표시 여부
 *			  viewOptions.toolbar_zoomlist : 줌 선택 콤보 박스의 리스트에 표시할 비율 (쉼표로분리)
 *			  viewOptions.script_movepage : 지정된 페이지 번호로 이동
 *			  viewOptions.viewer_useprogressbar : 보고서를 바인딩할 때 표시되는 프로그레스바 표시
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.win.openReportPopJson
 */
com.win.openReportPopJson = function(sbmObj, dcObj, paramData, popOptions, viewOptions, callbackFn) {

	console.log({method : 'com.win.openReportPopJson', paramData : paramData, popOptions : popOptions, viewOptions : viewOptions});

	var info	 	= com.win._getOpenReportInfo('SINGLE', 'ComReportPop.xml');

	if (com.util.isEmpty(popOptions)) popOptions = {};

	popOptions.popupName 	= paramData.oz_title;
	popOptions.type 		= popOptions.type || 'wframePopup';
	popOptions.modal		= popOptions.modal ? true : popOptions.modal;
	popOptions.width		= popOptions.width || 1024;
	popOptions.height		= popOptions.height || (window.screen.availHeight * 0.8);
	popOptions.posScreen	= (popOptions.type == 'wframePopup') ? '' : popOptions.posScreen || 'WIN';

	viewOptions	= (viewOptions) ? viewOptions : {};

	var reportParam	= {
		action 		: info.action,
		submtType	: 'SUBMISSION',
		sbmId		: sbmObj.id,
		dcId		: dcObj.getID(),
		popHeight 	: popOptions.height,
		popType		: popOptions.type,
		messageKey	: info.messageKey,
		pageType	: ((popOptions.type == 'wframePopup') ? 'iframe' : 'popup'),
		ozParam 	: [],
	};

	reportParam.viewOptions = com.win._getOpenReportViewOptions(viewOptions);
	reportParam.ozParam.push(com.win._getOpenReportParam(paramData, ''));

	var popupId	= com.win.openPopup(info.url, popOptions, reportParam);

	// 콜백함수 등록
	if (callbackFn) {
		// info.messageKey  : OZ 뷰어 이벤트 콜백 처리 메시지 키
		// viewerType		: OZ 뷰어 형태 (wframe, popup, oz-exe)
		// viewerId			: OZ 뷰어 인베디드 컴포넌트 ID (wFrame : wFrame ID, pupup : 팝업 ID, oz_exe : messageKey)
		// callbacnkFn		: 콜백 함수
		gcm.postmessage.callbackInfo('oz', 'INSERT', info.messageKey, {viewerId : popupId, viewerType : 'popup', callbackFn : callbackFn});
	}
};


