/**
 * 함수명 	: com.win.convReport2PDF
 * 함수설명	: 조회한 데이터를 오즈 리포트에서 wFrame으로 조회한다.
 * 파라미터	: paramData.oz_ozr_path : 보고서 OZR 경로 (필수)
 *            paramData.export_file_name : export 파일명 (필수)
 *			  paramData.oz_param : 보고서 데이터 (필수)
 *			  paramData.oz_odi_name : ODI 명 (필수)
 * 리턴		: result.retCode (000:생성성공, 999:생성실패)
 *            result.retMsg  (성공/실패 메시지)
 *            result.retData (export 결과내역)
 *            result.retData.pageCount (결과물 총페이지)
 *            result.retData.taskexportFileListID (결과물 위치)...이하생략
 * 작성일 	: 2023.12.08
 * 작성자 	: Inswave Systems
 * 예시	 	: N/A
 */
com.win.convReport2PDF = function(paramData) {

	console.log({method : 'com.win.convReport2PDF', paramData : paramData});

	var sbmParam = {};

	sbmParam.cmd = "schDirectExport";

	var ozSchInfo = com.win._getConvReport2PDFSchInfo();
	sbmParam.serverUrl     = ozSchInfo.servlet;
	sbmParam.schedulerIp   = ozSchInfo.schIp;
	sbmParam.schedulerPort = ozSchInfo.schPort;

	sbmParam.schedulerWorkList = [];

	var paramData	= (com.util.isArray(paramData)) ? paramData : [paramData];

	//multi ozr 포맷을 위해 
	//for문 schedulereWorkList 에 work를 추가함
	for(var i = 0; i < paramData.length ; i++){

		var work = {};

		//paramData.ozr_path 예시 : "/zi01/z1/form/Zi01Z1Calendar.ozr"
		//post 방식으로 보내므로 특수문자(이미지Base64나 파일경로)에 대한 encodeURI 필요없음
		work.ozrName = (paramData[i].oz_ozr_path==null) ? "" : paramData[i].oz_ozr_path;	
		work.odiName = (paramData[i].oz_odi_name==null) ? "" : paramData[i].oz_odi_name;

		//oz_param 예시 : [jsondata={}, title=, param1=, param2=, ...]  
		var ozrParamList = (com.util.isArray(paramData[i].oz_param)) ? paramData[i].oz_param : [paramData[i].oz_param];
		work.ozrParamVal = [];
		work.odiParamVal = [];		
		for(var j = 0; j < ozrParamList.length; j++){
			work.ozrParamVal.push(ozrParamList[j]);
		}

		//odi_name이 존재할때만 odi 파라미터를 세팅한다.
		if(work.odiName==""){

			var odiParamList = (com.util.isArray(paramData[i].oz_param)) ? paramData[i].oz_param : [paramData[i].oz_param];
			//oz_param 예시 : [param1=, param2=, ...]
			for(var j = 0; j < odiParamList.length; j++){
				work.odiParamVal.push(odiParamList[j]);
			}

		}

		//exportFileName 예시 : /SLDKGS07/ir10/sample
		work.exportFileName = com.win._getConvReport2PDFPath(paramData[i].export_file_name);

		sbmParam.schedulerWorkList.push(work);

	}

	// sbm return datamap 생성
	var colInfo	= [
		{id : 'retCode'},
		{id : 'retMsg'},
		{id : 'retData'}
	];
	com.data.createDataMap('_com_dma_convreport2pdf_result_', colInfo, {});

	//===========================================================================
	// Submission 생성
	//===========================================================================
	var sbmOptions = {
    	"id" 			: 'sbm_convReport2PDF',
    	"action" 		: "/ozweb/api/action.do",
    	"method" 		: 'post',
    	"mediatype" 	: 'application/json',
    	"mode" 			: 'synchronous',
    	"encoding" 		: "UTF-8", // [default: utf-8, euc-kr, utf-16] 서버 측 encoding 타입 설정 (euc-kr/utf-16/utf-8) - OZ서버 MS949
    	"processMsg" 	: '$blank',
    	"target"        : 'data:json,{"id":"_com_dma_convreport2pdf_result_","key":"nrs_return"}',
    };

	var sbmObj	= com.sbm.create(sbmOptions);

	//com.sbm.executeExt(sbmObj, sbmParam, callbackFnInfo.submitError);
	com.sbm.executeExt(sbmObj, sbmParam);

	var result = _com_dma_convreport2pdf_result_.getJSON();

	// sbm return datamap 삭제
	$p.data.remove( '_com_dma_convreport2pdf_result_' );

	return result;

};

/**
 * 함수명 	: com.win._getConvReport2PDFPath
 * 함수설명	: 오즈리포트 PDF전환 경로조회
 * 파라미터	: exportFileName : 변환 파일명 
 * 리턴		: N/A
 * 작성일 	: 2023.12.08
 * 작성자 	: Inswave Systems
 */
com.win._getConvReport2PDFPath = function(exportFileName) {

	var path = "";

	if (gcm.SYS_ID == 'IM10' ) {
		path = com.util.getPropertyStringValue('im10.system.nas.etc.report2pdf.path');
	} else if (gcm.SYS_ID == 'PM10') {
		path = com.util.getPropertyStringValue('pm10.system.nas.etc.report2pdf.path');
	} else if (gcm.SYS_ID == 'PM20') {
		path = com.util.getPropertyStringValue('pm20.system.nas.etc.report2pdf.path');
	} else if (gcm.SYS_ID == 'PM60') {
		path = com.util.getPropertyStringValue('pm60.system.nas.etc.report2pdf.path');
	} else if (gcm.SYS_ID == 'SM30') {
		path = com.util.getPropertyStringValue('sm30.system.nas.etc.report2pdf.path');
	} else if (gcm.SYS_ID == 'EM40') {
		path = com.util.getPropertyStringValue('em40.system.nas.etc.report2pdf.path');
	} else if (gcm.SYS_ID == 'ZI01') {
		path = com.util.getPropertyStringValue('zi01.system.nas.etc.report2pdf.path');
	}				

	path = path  + exportFileName;

	return path;
}

