 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.win._getOpenReportInfo = function(type, viewName) {

	var info = {};

	if (gcm.SYS_ID == 'IM10' ) {
		info.url		= '/ui/im10/com/report/Im10' + viewName;
		info.action		= (type == 'SINGLE') ? com.util.getPropertyStringValue('im10.system.oz.viewer.url') : com.util.getPropertyStringValue('im10.system.oz.viewer.multi.url');
	} else if (gcm.SYS_ID == 'PM10') {
		info.url		= '/ui/pm10/com/report/Pm10' + viewName;
		info.action		= (type == 'SINGLE') ? com.util.getPropertyStringValue('pm10.system.oz.viewer.url') : com.util.getPropertyStringValue('pm10.system.oz.viewer.multi.url');
	} else if (gcm.SYS_ID == 'PM20') {
		info.url		= '/ui/pm20/com/report/Pm20' + viewName;
		info.action		= (type == 'SINGLE') ? com.util.getPropertyStringValue('pm20.system.oz.viewer.url') : com.util.getPropertyStringValue('pm20.system.oz.viewer.multi.url');
	} else if (gcm.SYS_ID == 'PM60') {
		info.url		= '/ui/pm60/com/report/Pm60' + viewName;
		info.action		= (type == 'SINGLE') ? com.util.getPropertyStringValue('pm60.system.oz.viewer.url') : com.util.getPropertyStringValue('pm60.system.oz.viewer.multi.url');
	} else if (gcm.SYS_ID == 'SM30') {
		info.url		= '/ui/sm30/com/report/Sm30' + viewName;
		info.action		= (type == 'SINGLE') ? com.util.getPropertyStringValue('sm30.system.oz.viewer.url') : com.util.getPropertyStringValue('sm30.system.oz.viewer.multi.url');
	} else if (gcm.SYS_ID == 'EM40') {
		info.url		= '/ui/em40/com/report/Em40' + viewName;
		info.action		= (type == 'SINGLE') ? com.util.getPropertyStringValue('em40.system.oz.viewer.url') : com.util.getPropertyStringValue('em40.system.oz.viewer.multi.url');
	} else if (gcm.SYS_ID == 'ZI01') {
		info.url		= '/ui/zi01/com/report/Zi01' + viewName;
		info.action		= (type == 'SINGLE') ? com.util.getPropertyStringValue('zi01.system.oz.viewer.url') : com.util.getPropertyStringValue('zi01.system.oz.viewer.multi.url');
	}

	// OZ 뷰어 이벤트 발생 시 콜백 처리를 위해 참조하는 키  
	info.messageKey	= 'oz_' + com.num.random();								

	return info;
};


