/**
 * 함수명 	: com.win._openReportExeSubmit
 * 함수설명	: 오즈리포트 미리보기 (EXE) 창으로 조회한다.
 * 파라미터	: type 			: 구분 (SINGLE : 단일, MULTI : 복수 리포트)
 *			  paramData 	: 보고서 파리미터 (배열)
 *		      viewOptions	: 뷰어 옵션 정보
 *			  callbackFn	: 콜백 함수
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.win._openReportExeSubmiti
 */
com.win._openReportExeSubmit = function(type, paramData, viewOptions, callbackFn) {

	//===============================================================================
	// 오즈 뷰어 URL 설정 
	//===============================================================================
	var action	= '';

	if (gcm.SYS_ID == 'IM10' ) {
		action		= (type == 'SINGLE') ? com.util.getPropertyStringValue('im10.system.oz.exeviewer.url') : com.util.getPropertyStringValue('im10.system.oz.exeviewer.multi.url');
	} else if (gcm.SYS_ID == 'PM10') {
		action		= (type == 'SINGLE') ? com.util.getPropertyStringValue('pm10.system.oz.exeviewer.url') : com.util.getPropertyStringValue('pm10.system.oz.exeviewer.multi.url');
	} else if (gcm.SYS_ID == 'PM20') {
		action		= (type == 'SINGLE') ? com.util.getPropertyStringValue('pm20.system.oz.exeviewer.url') : com.util.getPropertyStringValue('pm20.system.oz.exeviewer.multi.url');
	} else if (gcm.SYS_ID == 'PM60') {
		action		= (type == 'SINGLE') ? com.util.getPropertyStringValue('pm60.system.oz.exeviewer.url') : com.util.getPropertyStringValue('pm60.system.oz.exeviewer.multi.url');
	} else if (gcm.SYS_ID == 'SM30') {
		action		= (type == 'SINGLE') ? com.util.getPropertyStringValue('sm30.system.oz.exeviewer.url') : com.util.getPropertyStringValue('sm30.system.oz.exeviewer.multi.url');
	} else if (gcm.SYS_ID == 'EM40') {
		action		= (type == 'SINGLE') ? com.util.getPropertyStringValue('em40.system.oz.exeviewer.url') : com.util.getPropertyStringValue('em40.system.oz.exeviewer.multi.url');
	} else if (gcm.SYS_ID == 'ZI01') {
		action		= (type == 'SINGLE') ? com.util.getPropertyStringValue('zi01.system.oz.exeviewer.url') : com.util.getPropertyStringValue('zi01.system.oz.exeviewer.multi.url');
	}

	//===============================================================================
	// 리포트 파라미터 설정
	//===============================================================================
	// 뷰 옵션 파라미터 설정
	viewOptions	= (viewOptions) ? viewOptions : {};

	var viewParam		= $.extend({
		viewer_frametitle 		: paramData[0].oz_title,
		toolbar_save 			: true, 
		global_concatpage		: true,
		print_mode 				: false,
		print_printername 		: '',
		viewer_mode 			: 'preview',
		viewer_framewidth 		: 1200,
		viewer_frameheight 		: 800,
		viewer_framex 			: 300,
		viewer_framey 			: 100,
		viewer_usetoolbar		: true,
		viewer_showtree			: false,
		viewer_showtab			: true,
		viewer_treeviewtitle	: '보고서',
		viewer_useprogressbar	: false,
		viewer_viewmode			: 'normal',
		toolbar_print			: true,
		toolbar_zoomin			: true,
		toolbar_zoomout			: true,
		toolbar_zoomlist		: '',
		script_movepage			: '1',
		screen					: 'WIN',
		pos						: 'CENTER',
		modal					: true,
		export_mode				: 'silent',
		export_path				: 'c:\\temp',
		export_filename			: 'excel',
		export_format			: 'xlsx',
		export_confirmsave		: false,
		export_executefile		: true,
		xlsx_removeblank		: true,
		xlsx_numberformat		: '#,##0.00',	
	}, viewOptions);


	viewParam.export_path = com.str.replaceAll(viewParam.export_path, '\\', '\\\\');

	// 리포트 파라미터 설정
	var reportParam 	= [];

	for (var i = 0 ; i < paramData.length ; i ++) {
		reportParam.push($.extend({
			oz_title			: '',
			oz_ozr_path			: '',
			oz_odi_name			: '',
			oz_json_data		: '',	
			oz_param1			: '',
			oz_param2			: '',
			oz_param3			: '',
			oz_param4			: '',
			oz_param5			: '',
			oz_param6			: '',
			oz_param7			: '',
			oz_param8			: '',
			oz_param9			: '',
			oz_param10			: '',
		}, paramData[i]));
	}

	//===============================================================================
	// 오즈 뷰어 창 위치 설정
	//===============================================================================
	var screen 	= (viewParam.screen == 'OWIN' && gcm.SCREEN_INFO.screen && gcm.SCREEN_INFO.count == 2) ? 'OWIN' : 'WIN';
	var posX	= viewParam.viewer_framex;
	var posY	= viewParam.viewer_framey;

	// 좌표 위치
	if (viewParam.pos == 'CENTER') {
		posX	= (window.screen.availWidth - parseInt(viewParam.viewer_framewidth)) / 2;
		posY	= (window.screen.availHeight - parseInt(viewParam.viewer_frameheight)) / 2;
	}

	// 스크린 위치
	if (screen == 'OWIN') {
		viewParam.viewer_framex = window.screen.availWidth + parseInt(posX);
		viewParam.viewer_framey = posY;
	} else {
		viewParam.viewer_framex = posX;
		viewParam.viewer_framey = posY;
	}

	//===============================================================================
	// form data 생성
	//===============================================================================
	var form	= $('[name=ozReportForm__]');

	form.empty();

	// 뷰 옵션 hidden 생성
	for ( var item in viewParam) {
		var val	= (com.util.isBoolean(viewParam[item])) ? viewParam[item] + '' : encodeURIComponent(viewParam[item]);
		form.append('<input type="hidden" id="hdn_oz_option_' + item  + '" name="hdn_oz_option_' + item + '" value="' + val + '"/>');
	}

	// 리포트 데이터 생성
	for (var i = 0 ; i < reportParam.length ; i ++) {

		for (var item in reportParam[i]) {
			var val	=  encodeURIComponent((item == 'oz_json_data') ? EgovNrsStringBase.gfn_jSONStringifyForEnterLine(reportParam[i][item]) : reportParam[i][item]); 

			form.append('<input type="hidden" id="hdn_' + item  + '" name="hdn_' + item + '" value="' + val + '"/>');
		}
	}

	// 화면 모달 처리.
	if (viewParam.viewer_mode == 'preview') {
		if (com.util.isEmpty(viewParam.modal) || viewParam.modal == true || viewParam.modal == 'true') {
			WebSquare.layer.showModal();
		}
	}

	// 메시지 키
	var messageKey	= 'postMessage_' + com.num.random();
	form.append('<input type="hidden" id="hdn_message_key" name="hdn_message_key" value="' + messageKey + '"/>');


	form.attr('method', 'post');
	form.attr('action', action);
	form.attr('target', 'ozReportFrame__');  

	form[0].submit();

	// 콜백함수 등록
	if (callbackFn) {
		// messageKey   : OZ 뷰어 이벤트 콜백 처리 메시지 키
		// viewerType	: OZ 뷰어 형태 (wframe, popup, oz-exe)
		// viewerId		: OZ 뷰어 ID (wFrame : wFrame ID, pupup : 팝업 ID, oz-exe : messageKey)
		// callbacnkFn	: 콜백 함수
		gcm.postmessage.callbackInfo('oz', 'INSERT', messageKey, {viewerId : messageKey, viewerType : 'oz-exe', callbackFn : callbackFn});
	}
};



/**
