 *			  pdfOptions.result_pdf_file_path : PDF 결과 저장 FULL경로
 *			  - 음영, 서명 PDF 용
 *			  pdfOptions.scale : PDF 비율
 *			  - 최소~최대 : 0.3 ~ 4
 *			  - 피팅 : auto(자동), page-fit(높이), page-width(넓이)
 *			  pdfOptions.oam : 오픈후 변경사항으로 이동여부 true/false
 *			  - 검색 PDF용
 *			  popOptions : 팝업 옵션
 *			  popOptions.type : 팝업 유형
 *			  wframePopup, browserPopup
 *			  popOptions.modal : 팝업 모달 유무
 *			   - true, false
 *			  popOptions.width : 팝업 넓이
 *			  popOptions.height : 팝업 높이
 *			  popOptions.posScreen : 팝업 창 위치
 *			   - WIN, OWIN (전용브라우져)
 *			  callbackFn : 콜백함수
 *			  callbackFn.sign : 서명 성공 후 콜백함수
 *			  callbackFn.bm : 음영 성공 후 콜백 함수
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.win.openPdfViewerPop
 */
com.win.openPdfViewerPop = function(pdfOptions, popOptions, callbackFn) {

	console.log({method : 'com.win.openPdfViewerPop', pdfOptions : pdfOptions, popOptions : popOptions});

	var info	 	= com.win._getOpenPdfViewerInfo(pdfOptions, 'ComPdfViewerPop.xml');

	if (com.util.isEmpty(popOptions)) popOptions = {};

	popOptions.popupName 	= pdfOptions.title;
	popOptions.type 		= popOptions.type || 'wframePopup';
	popOptions.modal		= popOptions.modal ? true : popOptions.modal;
	popOptions.width		= popOptions.width || 1024;
	popOptions.height		= popOptions.height || (window.screen.availHeight * 0.8);
	popOptions.posScreen	= (popOptions.type == 'wframePopup') ? '' : popOptions.posScreen || 'WIN';

	var messageKey	= 'ezpdf_' + com.num.random();
	var pdfParam	= {
		action		: info.action,
		popTitle	: pdfOptions.title,
		popHeight	: popOptions.height,
		popType		: popOptions.type,
		messageKey	: messageKey,
		pageType	: ((popOptions.type == 'wframePopup') ? 'iframe' : 'popup'),
		addParam	: {
			initScale 	: (pdfOptions.scale) ? pdfOptions.scale : 'auto',
			oam			: (pdfOptions.oam == true) ? 'true' : 'false',
			//is_page_change_callback	:	(com.util.isEmpty(pdfOptions.is_page_change_callback)) ? true :  pdfOptions.is_page_change_callback
		}
	};

	// encdata 파라미터
	pdfParam.encParam	= com.win._getOpenPdfViewerEncParam(pdfOptions);

	var popupId	= com.win.openPopup(info.url, popOptions, pdfParam);

	// 콜백함수 등록
	if (callbackFn) {
		// compObj.id		: OZ 뷰어 이벤트 콜백 처리 메시지 키
		// viewerType		: OZ 뷰어 형태 (wframe, popup, oz-exe)
		// viewerId			: OZ 뷰어 인베디드 컴포넌트 ID (wFrame : wFrame ID, pupup : 팝업 ID, oz-exe : messageKey)
		// callbacnkFn		: 콜백 함수
		gcm.postmessage.callbackInfo('ezpdf', 'INSERT', messageKey, {viewerId : popupId, viewerType : 'popup', callbackFn : callbackFn});
	}
};



