		info.url		= '/ui/pm10/com/pdf/Pm10' + xmlType;
		info.action	= com.util.getPropertyStringValue('pm10.system.pdf.viewer.' + pdfOptions.pdf_type + '.apm4.url');
	} else if (gcm.SYS_ID == 'PM20') {
		pdfOptions.pdf_type	= (pdfOptions.pdf_type) ? pdfOptions.pdf_type : 'searchpdf';
		info.url		= '/ui/pm20/com/pdf/Pm20' + xmlType;
