	} else if (gcm.SYS_ID == 'PM60') {
		pdfOptions.pdf_type	= (pdfOptions.pdf_type) ? pdfOptions.pdf_type : 'ezpdf';
		info.url		= '/ui/pm60/com/pdf/Pm60' + xmlType;
		info.action		= com.util.getPropertyStringValue('pm60.system.pdf.viewer.' + pdfOptions.pdf_type + '.apm4.url');
	} else if (gcm.SYS_ID == 'SM30') {
		pdfOptions.pdf_type	= (pdfOptions.pdf_type) ? pdfOptions.pdf_type : 'ezpdf';
		info.url		= '/ui/sm30/com/pdf/Sm30' + xmlType;
		info.action		= com.util.getPropertyStringValue('sm30.system.pdf.viewer.' + pdfOptions.pdf_type + '.aim6.url');
	} else if (gcm.SYS_ID == 'EM40') {
		pdfOptions.pdf_type	= (pdfOptions.pdf_type) ? pdfOptions.pdf_type : 'ezpdf';
		info.url		= '/ui/em40/com/pdf/Em40' + xmlType;
		info.action		= com.util.getPropertyStringValue('em40.system.pdf.viewer.' + pdfOptions.pdf_type + '.aim6.url');
