/**
 * 함수명 	: com.win._getOpenPdfViewerEncParam
 * 함수설명	: PDF 뷰어 유형별 파라미터 (encParam)를 리턴한다.
 * 파라미터	: options : PDF 뷰어 옵션
 * 리턴		: encParam : PDF 뷰어 파라미터
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.win._getOpenPdfViewerEncParam = function(options) {

	var newOptions = $.extend({
		is_download : true,
		is_print	: true,
		is_annot 	: true,
		is_sign		: true,
		is_search	: true,
	}, options);

	var encParam	= [];

	if (newOptions.pdf_type == 'ezpdf') {
		encParam.push(newOptions.pdf_file_path);
		encParam.push((newOptions.is_download == true) ? 'true' : 'false');
		encParam.push((newOptions.is_print == true) ? 'true' : 'false');
		encParam.push((newOptions.is_annot == true) ? 'true' : 'false');

	} else if (newOptions.pdf_type == 'searchpdf') {
		encParam.push(newOptions.pdf_file_path);

	} else if (newOptions.pdf_type == 'signpdf') {
		encParam.push(newOptions.pdf_file_path);
		encParam.push(newOptions.result_pdf_file_path);
		encParam.push((newOptions.is_sign == true) ? 'true' : 'false');
		encParam.push((newOptions.is_print == true) ? 'true' : 'false');

	} else if (newOptions.pdf_type == 'bmpdf') {
		encParam.push(newOptions.pdf_file_path);
		encParam.push(newOptions.result_pdf_file_path);
		encParam.push((newOptions.is_search == true) ? 'Y' : 'N');

	} else if (newOptions.pdf_type == 'annotpdf') {
		encParam.push(newOptions.pdf_file_path);
		encParam.push(newOptions.doc_id);
		encParam.push(newOptions.user_id);
	}

	return encParam;

};

/**
 * 함수명 	: com.win.openPdfViewerPostMessage
 * 함수설명	: PDF 뷰어 화면에 메시지를 전송한다.
 * 파라미터	: target : PDF뷰어 window
 *			  type : 메시지 구분
 *			  param : 메시지 파라미터
 *			  callbackFn : 메시지 전송 후 호출할 콜백함수
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.win.print
 */
com.win.openPdfViewerPostMessage = function(target, type, param, callbackFn) {

	console.log({method : 'com.win.openPdfViewerPostMessage', type : type, param : param, callbackFn : callbackFn});

	try {
		var winObj		= $(target.render).find('iframe')[0].contentWindow;
		var message 	= {name : type, param : param, wframe : target.id};

		gcm.postmessage.send(winObj, JSON.stringify(message));

		// 콜백함수 등록
		if (callbackFn) {
			// compObj.id		: OZ 뷰어 이벤트 콜백 처리 메시지 키
			// viewerType		: OZ 뷰어 형태 (wframe, popup, oz-exe)
			// viewerId			: OZ 뷰어 인베디드 컴포넌트 ID (wFrame : wFrame ID, pupup : 팝업 ID, oz-exe : messageKey)
			// callbacnkFn		: 콜백 함수

			if ( type == 'setScale' || type == 'getScale' || type == 'getScaleR' || type == 'getCPage' 
				|| type == 'getTPage' || type == 'bmLength' || type == 'setkeyCallback') {
				gcm.postmessage.callbackInfo('ezpdf', 'INSERT', 'ezpdf_' + type, {callbackFn : callbackFn});
			}else if( type == "setScaleChangedCallback" || type == 'setPageChangedCallback' ) { //프레임 구별이 필요한 CallBack
				gcm.postmessage.callbackInfo('ezpdf', 'INSERT', 'ezpdf_' + target.id + '_' + type, {callbackFn : callbackFn});				
			}

		} else{ // 콜백함수 등록을 안한 경우만 가능 -- 검색 PDF뷰어에서 응용 메시지를 사용하기 위함 
			if ( type == 'changedTextPrev' || type == 'searchNumberPrev' || type == 'searchTextPrev' 
				|| type == 'changedTextNext' || type == 'searchNumberNext' || type == 'searchTextNext'
			    || type == 'searchNumber' || type == 'searchText' ){
				gcm.postmessage.callbackInfo('ezpdf', 'INSERT', 'ezpdf_callMsgcd', {callbackFn : com.win.showEzpdfCallMsgcd});
			}
		}
	} catch(ex) {
		console.log(ex);
	}
}

/**
 * 함수명 	: com.win.showEzpdfCallMsgcd
 * 함수설명	: PDF 뷰어 솔루션에서 제공하는 메시지를 화면에 보여준다.
 * 파라미터	: data : 뷰어솔루션 제공 메시지코드
 * 리턴		: N/A
 * 작성일 	: 2023.11.10
 * 작성자 	: Inswave Systems
 */
com.win.showEzpdfCallMsgcd = function(data) {

	try {

		var msgCode;

		if(data == 'msg001'){
			msgCode = 'egov.message.info.web.ezpdf.0001';
		}else if(data == 'msg002'){
			msgCode = 'egov.message.info.web.ezpdf.0002';
		}else if(data == 'msg003'){
			msgCode = 'egov.message.info.web.ezpdf.0003';
		}else if(data == 'msg004'){
			msgCode = 'egov.message.info.web.ezpdf.0004';
		}else if(data == 'msg005'){
			msgCode = 'egov.message.info.web.ezpdf.0005';
		}else if(data == 'msg006'){
			msgCode = 'egov.message.info.web.ezpdf.0006';
		}else if(data == 'msg007'){
			msgCode = 'egov.message.info.web.ezpdf.0007';
		}else{
			msgCode = 'egov.message.info.web.ezpdf.9999';
		}

		var msgOption = {
            msgType     : 'info',
