 *			    - 입력 시 : wFrame, Group ID (컴포넌트.getID() 로 ID 추출)
 *			  options.printClass : 인쇄 스타일 class name
 *			   - css로 추가하여 사용
 *			  options.bottomComp : 마지막에 출력할 컴포넌트로 팝업화면의 경우 팝업 높이를 조절하는 용도로 사용
 *			  * 메인화면
 *			  - 옵션 생략
 *			  * 팝업화면
 *			    - 옵션 필수
 *			  options.bottomMargin : 인쇄 bottom 여백으로 생략 시 0가 적용됨 (숫자형 – 정수)
 *			  options.allDataGrid : 전체 데이터 출력 GridView 컴포넌트
 *			  options.printCallBackFn : 인쇄 전/후 화면에서 별도 처리용 콜백 함수로 특정 컴포넌트를 인쇄에서 제외시킬 수 있음
 *			  -	인쇄 전 : 컴포넌트 숨기기
 *			  -	인쇄 후 : 숨긴 컴포넌트 노출
 *			  * 호출 시 파라미터 : type
 *			  - 인쇄 전 : BEFORE
 *			  - 인쇄 후 : AFTER
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.win.print
 */
com.win.print = function(options) {

	console.log({method : 'print'});

	//=========================================================
    // 인쇄 정보 조회
	//=========================================================
	var printInfo	= com.win._printCommon(options);

	//=========================================================
	// GridView visibleRowNum 'All' 처리
	//=========================================================
	com.win._printBefore(printInfo.targetObj, printInfo);
	com.win._printGridBefore(options, printInfo);


	/**
	 * 함수명 	: window.onbeforeprint
	 * 함수설명	: 인쇄 전 이벤트 처리
	 * 				- 인쇄 대상에 미디어쿼리(css)를 적용
	 * 파라미터	: N/A
	 * 리턴		: N/A
	 * 작성일 	: 2022.05.16
	 * 작성자 	: Inswave Systems
	 */
	window.onbeforeprint  = function() {		
		if (gcm.SYS_ID == 'IM10' || gcm.SYS_ID == 'SM30' || gcm.SYS_ID == 'ZI01') {
			com.win.printIm10('BEFORE', options, printInfo);
		} else if (gcm.SYS_ID == 'PM10') {
			com.win.printPm10('BEFORE', options, printInfo);
		} else {
			com.win.printEtc('BEFORE', options, printInfo);
		}
	};


	/**
	 * 함수명 	: window.onafterprint
	 * 함수설명	: 인쇄 종료 이벤트 처리
	 * 				- GridView, 팝업창 높이 이전 상태로 변경
	 * 				- 인쇄 대상에 미디어쿼리(css)를 제거
	 * 파라미터	: N/A
	 * 리턴		: N/A
	 * 작성일 	: 2022.05.16
	 * 작성자 	: Inswave Systems
	 */
    window.onafterprint   = function() {
    	com.win._printAfter(options, printInfo);
    	com.win._printGridAfter(options, printInfo);

    	if (gcm.SYS_ID == 'IM10' || gcm.SYS_ID == 'SM30' || gcm.SYS_ID == 'ZI01') {
			com.win.printIm10('AFTER', options, printInfo);
		} else if (gcm.SYS_ID == 'PM10') {
			com.win.printPm10('AFTER', options, printInfo);
		} else {
			com.win.printEtc('AFTER', options, printInfo);
		}

    	if (options.gridViewComp) {
    		setTimeout(function() {
    			options.gridViewComp.mStopObserver = false;
    		}, 100);
		}
    };

    setTimeout(function() {
    	window.print();
	}, 400);

};


/**
 * 함수명 	: com.win.printIm10
 * 함수설명	: IM10용 window 인쇄 이벤트 전후 처리 (버튼 숨김/노출 , GridView 인쇄높이 설정/복원)
 * 				- 인쇄 전 이벤트 : window.onbeforeprint
 * 				- 인쇄 후 이벤트 : window.onafterprint
 *	 			- 인쇄 전/후 처리 후 콜백함수 호출
 * 파라미터	: type : 인쇄 전 / 후
 * 				- BEFOER : 인쇄 전
 * 				- AFTER : 인쇄 후
 * 			  options : 인쇄 옵션
 * 			  printInfo : 인쇄 정보
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.win.printIm10 = function(type, options, printInfo) {

	// 출력 전/후 화면에서 처리할 함수 호출
	if (options.callbackPrint) options.callbackPrint(type);

	if (printInfo.isPopup) {

		var popupHtml		= $(printInfo.popupObj.render);

		if (type == 'BEFORE') {
			// 창 닫기 버튼 숨기기
			popupHtml.find('.w2window_close').hide();

			$(printInfo.popupObj.render).css({height : 'auto', overflow : 'initial'});

		} else {
			// 창 닫기 버튼 원복
			popupHtml.find('.w2window_close').show();

			// 팝업 스타일 원복
			$(printInfo.popupObj.render).attr('style', printInfo.popupStyle);
    	}
	} else {
		// BEFORE : body 스크롤이 있으면 높이 증가
		// AFTER  : body 스크롤이 있으면 높이 원복
		if (type == 'BEFORE') {
			var scrollHeight	= mf_wdc_main_subWindow1_wframe.render.scrollHeight + 150;

			mf_wdc_main_subWindow1_wframe.render.style.height = scrollHeight + 'px !important';
			document.body.style.height  = scrollHeight + 'px';
		} else {
			mf_wdc_main_subWindow1_wframe.render.style.height = null;
			document.body.style.height = null;
		}
	}
};


/**
 * 함수명 	: com.win.printPm10
 * 함수설명	: PM10용 window 인쇄 이벤트 전후 처리  (버튼 숨김/노출 , GridView 인쇄높이 설정/복원)
 * 				- 인쇄 전 이벤트 : window.onbeforeprint
 * 				- 인쇄 후 이벤트 : window.onafterprint
 * 				- 인쇄 전/후 처리 후 콜백함수 호출
 * 파라미터	: type : 인쇄 전 / 후
 * 				- BEFOER : 인쇄 전
 * 				- AFTER : 인쇄 후
 * 			  options : 인쇄 옵션
 * 			  printInfo : 인쇄 정보
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.win.printPm10 = function(type, options, printInfo) {

	// 출력 전/후 화면에서 처리할 함수 호출
	if (options.callbackPrint) options.callbackPrint(type);

	if (printInfo.isPopup) {
		var popupHtml		= $(printInfo.popupObj.render);

		if (type == 'BEFORE') {

			popupHtml.find('.popup-wrap').css({'display' : 'table'});
			popupHtml.find('.content-wrap').css({'display' : 'block'});
			popupHtml.find('.popup-body').css({'overflow' : 'hidden'});

			// 창 닫기 버튼 숨기기
			popupHtml.find('.w2window_close').hide();

			$(printInfo.popupObj.render).css({height : 'auto', overflow : 'initial'});
		} else {
			// body 원복
			popupHtml.find('.popup-wrap').removeAttr('style');
			popupHtml.find('.content-wrap').removeAttr('style');
			popupHtml.find('.popup-body').removeAttr('style');

			// 창 닫기 버튼 원복
			popupHtml.find('.w2window_close').show();

			// 팝업 스타일 원복
			$(printInfo.popupObj.render).attr('style', printInfo.popupStyle);
    	}
	}
};


/**
 * 함수명 	: com.win.printEtc
 * 함수설명	: 기타 시스템 window 인쇄 이벤트 전후 처리
 * 				- 인쇄 전 이벤트 : window.onbeforeprint
 * 				- 인쇄 후 이벤트 : window.onafterprint
 * 				- 인쇄 전/후 처리 후 콜백함수 호출
 * 파라미터	: type : 인쇄 전 / 후
 * 				- BEFOER : 인쇄 전
 * 				- AFTER : 인쇄 후
 * 			  options : 인쇄 옵션
 * 			  printInfo : 인쇄 정보
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
