/**
 * 함수명 	: com.win._printCommon
 * 함수설명	: 인쇄 대상 미디어 css 설정 (noprint, print)
 * 파라미터	: options : 인쇄 옵션
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.win._printCommon = function(options) {

	var result	= {};

	if (options.gridViewComp) {
		options.gridViewComp.mStopObserver = true;
	}

	// 인쇄 대상이 없을 경우 전체 인쇄 (팝업창은 팝업창만)
    if (com.util.isEmpty(options.targetId)) {
	    if (com.win.isPopup()) {
	    	result.popupObj		= com.win.getPopup();
	    	result.isPopup		= true;
	    	result.targetId		= result.popupObj.id;
	    	result.popOption	= com.win._printPopupSize();
	    	result.popupStyle	= $(result.popupObj.render).attr('style');
		} else {
			result.targetId	= 'main';
		}
	} else {
		result.targetId    = options.targetId;
	}

    result.noPrintClass	= (gcm.SYS_ID == 'IM10' || gcm.SYS_ID == 'ZI01')  ? 'noprint' : 'no-print';
    result.printClass	= (com.util.isEmpty(options.printClass)) ? 'print' : options.printClass;
    result.targetObj 	= (com.util.isEmpty(result.targetId) || result.targetId == 'main') ? $('body') : $('#' + result.targetId);
    result.scroll		= {x : window.scrollX, y : window.scrollY};

    return result;

};

/**
 * 함수명 	: com.win._printGridBefore
 * 함수설명	: GridView 전체 데이터 및 팝업창 사이즈를 변경
 * 				- GridView의 테이블 HTML을 복제하여 인쇄 시 사용
 * 				- visibleRowNum = 'all'로 하여 전체 데이터 노출
 * 				- GridView 높이 변경 분 만큼 팝업창 사이즈 변경
 * 파라미터	: options : 인쇄 옵션
 * 			  printInfo : 인쇄 정보
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.win._printGridBefore = function(options, printInfo) {

	printInfo.gridOption	= {
		visibleRowNum : [],
		cloneGrid : [],
		height : [],
	};

	if (options.gridViewComp) {

		var gridComp	= (com.util.isArray(options.gridViewComp)) ? options.gridViewComp : [options.gridViewComp];

		for (var i = 0 ; i < gridComp.length ; i ++) {

			if (gridComp[i].options.drawType == 'virtual' && gridComp[i].options.visibleRowNum != 'all') {

				//=================================================================
				// GridView 전체데이터 노출
				//=================================================================
				var dcObj	 = $p.getComponentById(gridComp[i].getDataList());

				printInfo.gridOption.visibleRowNum.push(gridComp[i].options.visibleRowNum);
				printInfo.gridOption.height.push(gridComp[i].resizeObj.height);

				gridComp[i].setTopRowIndex(0);
				gridComp[i].setVisibleRowNum(dcObj.getTotalRow());
			} 
		}

		// 전체 데이터 노출 할 경우 시간이 필요함. (300 초 뒤에 복제 시작)
		setTimeout(function() {
			for (var i = 0 ; i < gridComp.length ; i ++) {
				_cloneGrid(gridComp[i]);
			}
		}, 300);
	}



	/**
	 * 함수명 	: _cloneGrid
	 * 함수설명	: GridView 테이블 HTML 복제 후 GridView 컴포넌트를 숨김 처리 (복제한 테이블을 인쇄에서 사용함) (내부함수)
	 * 파라미터	: gridComp : GridView 컴포넌트
	 * 리턴		: N/A
	 * 작성일 	: 2022.05.16
	 * 작성자 	: Inswave Systems
	 */
	function _cloneGrid(gridComp) {

		var domGrid			= $(gridComp.render);
		var domGridClass	= domGrid.attr('class');
		var domParent		= domGrid.parent();
		var cloneGrid		= $('<div class="' + domGridClass + '"></div>');
		var cloneTable		= $(gridComp.dom[gridComp.id + '_body_table']).clone();
		var cloneFooter		= $(gridComp.dom[gridComp.id + '_foot_table']).clone();

		cloneTable.attr('id', '__clone__');
		cloneTable.css({'position' : 'initial', 'width' : '100%'});
		cloneTable.find('[id]').attr('id', '__clone__');
		cloneTable.find('thead').css({'display' : 'table-header-group'});
		cloneTable.find('td').css({'background-color' : '#ffffff'});

		// footer 추가
		if (cloneFooter.length != 0) {
			cloneTable.find('tbody').append(cloneFooter.find('tr'));
		}
		cloneGrid.append(cloneTable);

		// 복제 GridView 추가
		domParent.append(cloneGrid);

		// 원본 GridView 숨기기
		gridComp.hide();
		printInfo.gridOption.cloneGrid.push(cloneGrid);
	}
};


/**
 * 함수명 	: com.win._printGridAfter
 * 함수설명	: GridView, 팝업창 원본상태 복원
 * 파라미터	: options : 인쇄 옵션
 * 			  printInfo : 인쇄 정보
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.win._printGridAfter = function(options, printInfo) {

	if (options.gridViewComp) {

		var gridComp	= (com.util.isArray(options.gridViewComp)) ? options.gridViewComp : [options.gridViewComp];

		for (var i = 0 ; i < gridComp.length ; i ++) {

			printInfo.gridOption.cloneGrid[i].remove();
			gridComp[i].show('');

			if (gridComp[i].options.drawType == 'virtual' && gridComp[i].visibleRowNum != 'all') {

				if (printInfo.gridOption.visibleRowNum[i] == '') {
					gridComp[i].options.visibleRowNum = '';
					gridComp[i]._dynamicVisibleRowNum = -1;

					gridComp[i].setGridHeight(printInfo.gridOption.height[i]);
				} else {
					gridComp[i].setVisibleRowNum(printInfo.gridOption.visibleRowNum[i]);
				}
			}
		}
	}
};


/**
 * 함수명 	: com.win._printBefore
 * 함수설명	: 인쇄대상 HTML에 미디어쿼리(css)적용
 * 파라미터	: N/A
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.win._printBefore = function(obj, printInfo) {

	var parentObj = obj.parent();

    // 형제 엘리먼트 숨기기
    var childObj  = parentObj.children();

    for (var i = 0 ; i < childObj.length ; i ++) {
	     if (childObj[i] == obj[0]) {
		     $(childObj[i]).addClass(printInfo.printClass);
		 } else {
		     $(childObj[i]).addClass(printInfo.noPrintClass);
		 }
	}

    if (com.util.isEmpty(parentObj[0].tagName) || parentObj[0].tagName == 'BODY') {
	    return;
    } else {
    	com.win._printBefore(parentObj, printInfo);
	}
};


/**
 * 함수명 	: com.win._printAfter
 * 함수설명	: 인쇄대상 엘리먼트에 미디어쿼리(css)제거 및 window 스크롤 위치 복원
 * 파라미터	: N/A
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.win._printAfter = function(options, printInfo) {

	$('.' + printInfo.noPrintClass).removeClass(printInfo.noPrintClass);
	$('.' + printInfo.printClass).removeClass(printInfo.printClass);

    window.onbeforeprint   = null;
    window.onafterprint    = null;

    window.scrollTo(printInfo.scroll.x, printInfo.scroll.y);
};



/**
 * 함수명 	: com.win._printPopupSize
 * 함수설명	: 인쇄대상 팝업 사이즈 설정
 * 파라미터	: N/A
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.win._printPopupSize = function() {

	var orgOption	= {};
	var popupObj	= com.win.getPopup();

	if (com.win.isPopupWFrame(popupObj)) {
		var $popup		= $(popupObj.render);

		orgOption.popHeight	= $popup.height();
		orgOption.popWidth	= $popup.width();
	} else {
		orgOption.popHeight	= popupObj.outerHeight;
		orgOption.popWidth	= popupObj.outerWidth;
	}

	return orgOption;
}



/**
 * 함수명 	: com.win.addistory
 * 함수설명	: window history를 정보를 추가한다. (브라우져 back, forward 용)
 * 				- back, forward 시 window.popstate 이벤트에서 이력 정보 조회하여 wFrame에 페이지 로드
 * 파라미터	: type : 유형 (MENU, PAGE)
 * 			  info : 이력 정보
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
com.win.addBrowserHistory = function(type, info, targetFrameObj) {
	window.history.pushState( {type: type, info : info} , '', window.location.href);

	if (com.util.isNotEmpty(targetFrameObj)) {
		gcm.HISTORY_WFRAME = targetFrameObj.id;
	}
};



