/**
 * 함수명 	: com.comp.createComponent
 * 함수설명	: 컴포넌트를 동적으로 생성한다.
 *			   - GridView 동적생성은 /ui/zi01/z2/sample/grid/grid.createComp.xml 참조
 * 파라미터	: compNm : 컴포넌트 이름 (내부이름)
 *			  option : 컴포넌트 옵션 정보 (속성 참조)
 *			  parent : 컴포넌트 생성 위치
 * 리턴		: 컴포넌트
 *			   - Selectbox, radio, checkbox itemSetting은 compObj.setNodeSet 메소드를 이용하여 바인딩함
 *			   - compObj.setNodeSet('data:dlt_dataList1', 'col2', 'col1');
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.comp.createComponent
 */
com.comp.createComponent = function(compId, compNm, option, parent) {
	try {

		var asComp	= $p.getComponentById(compId);

		if (com.util.isNotEmpty(asComp)) {
			asComp.destroy();
		}

		if (com.util.isNotEmpty(compId) && com.util.isNotEmpty(compNm)) {
			option	= option || {}
			parent	= parent || ''

			return $p.dynamicCreate(compId, compNm, option, parent);
        } else {
