/**
 * 함수명 	: com.comp.textAreaMaxByteLength
 * 함수설명	: textArea 엔터 입력 값 2바이트 체크하여 입력 제한
 * 				- keydown 이벤트 : 입력전 바이트 체크 
 * 				- oninput 이벤트 : 입력값 바이트 체크
 * 파라미터	: compObj : 컴포넌트
			  maxByteLength : 최대입력바이트수
			  callbackFn : 콜백함수 (파라미터 : 바이트수)
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.comp.textAreaMaxByteLength
 */
com.comp.textAreaMaxByteLength	= function(compObj, maxByteLength, callbackFn) {

	console.log({method : 'textAreaMaxByte', maxByteLength : maxByteLength});

	// oninput 이벤트 발생 시킴 (중복발생 금지)
	if (com.util.isEmpty(compObj.mInputEvent)) {
		//com.comp.addHtmlEvent(compObj.render, 'keydown', _checkPosition);		// 입력전 바이트 체크 
		compObj.event.addListener(compObj.render, 'oninput', _checkByte);		// 입력값 바이트 체크
		compObj.mInputEvent = true;

		_checkByte.apply(compObj.render, [{inputType : 'insertFromPaste'}]);
	}


	/**
	 * 함수명 	: _checkPosition
	 * 함수설명	: 입력 값 maxByteLenght vs 입력된 글자 바이트 수
	 * 				- Ctrl + V 
	 * 				  - byteLength == maxByteLength : 추가 없음
	 * 				  - byteLength != maxByteLength : 추가 체크 필요(현재글자수 설정 >> oninput에서 체크)
	 * 파라미터	: e : 이벤트객체
	 * 리턴		: N/A
	 * 작성일 	: 2022.05.16
	 * 작성자 	: Inswave Systems
	 * 예시	 	: API : com.comp.textAreaMaxByteLength
	 */
	function _checkPosition(e) {

		var byteLength  = com.str.getByteLength(this.value, null, true);

		if (e.ctrlKey && e.keyCode == 86) {
			this.mBytePosition	= 0;
			if (byteLength == maxByteLength) {
				gcm.win.stopEvent(e);
			} else if (byteLength > maxByteLength) {
				this.mBytePosition	= Math.floor((maxByteLength / 2));
			} else {
				this.mBytePosition = this.value.length;
			}
		} else {

		}
	};


	/**
	 * 함수명 	: _checkByte
	 * 함수설명	: 입력 후 maxByteLenght vs 입력된 글자 바이트 수
	 * 				- Ctrl + V : 현재글자수(mBytePosition) 부터 1씩 증가 시키면서 maxByteLength 체크
	 * 				- 현재글자수 maxByteLength 체크
	 * 			  입력된 바이트 수 콜백함수로 리턴
	 * 파라미터	: e : 이벤트객체
	 * 리턴		: N/A
	 * 작성일 	: 2022.05.16
	 * 작성자 	: Inswave Systems
	 * 예시	 	: API : com.comp.textAreaMaxByteLength
	 */
	function _checkByte(e) {

		//console.log(e);

		var value		= this.value;
		var byteLength  = com.str.getByteLength(value, null, true);

		if (byteLength > maxByteLength) {

			var bytePosition	= Math.floor((maxByteLength / 2));

			var checkVal	= value;

			for (var i = bytePosition + 1 ; i <= value.length ; i ++) {
				checkVal	= value.substring(0, i);
				byteLength  = com.str.getByteLength(checkVal, null, true);

				if (byteLength > maxByteLength) {

					this.value	= checkVal.substring(0, checkVal.length -1);

					_setInputApply();
					break;
				}
			}
		}

		if (callbackFn) {
			byteLength  = com.str.getByteLength(this.value, null, true);
			callbackFn(byteLength);
		}
	}

	function _checkByteOld(e) {

		console.log(e);

		var value		= this.value;
		var byteLength  = com.str.getByteLength(value, null, true);

		if (byteLength > maxByteLength) {

			var bytePosition	= Math.floor((maxByteLength / 2));

			if (e.inputType == 'insertFromPaste') {

				var checkVal	= value;

				for (var i = bytePosition + 1 ; i <= value.length ; i ++) {
					checkVal	= value.substring(0, i);
					byteLength  = com.str.getByteLength(checkVal, null, true);

					if (byteLength > maxByteLength) {

						this.value	= checkVal.substring(0, checkVal.length -1);

						_setInputApply();
						break;
					}
				}
				this.mBytePosition	= 0;
			} else {
				var pos     = WebSquare.text.getCaretPos(this);
		        this.value 	= value.substr(0, pos-1) + value.substr(pos, value.length-1);;

		        WebSquare.text.setCaretPos(this, pos-1);
		        _setInputApply();
			}
		}

		if (callbackFn) {
			byteLength  = com.str.getByteLength(this.value, null, true);
			callbackFn(byteLength);
		}
	}

	function _setInputApply() {
		$('#__IME_HIDDEN__').focus();

    	setTimeout(function() {
    		compObj.focus();
    	}, 1);
	}
};


