 * 파라미터	: compObj : 컴포넌트 (dataMap, inputType, inputCalendar)
 *			   - dataMap : dataMap 컴포넌트
 *			   - inputType, inputCalendar : 컴포넌트 (배열)
 *			  info : 설정정보
 *			   - compObj가 dataMap
 *			      info.colIds : 컬럼아이디 (배열)
 *			      info.foramt : 날짜 포맷 (yyyy, yyyy-MM, yyyy-MM-dd)
 *			   - compObj가 inputBox, inputCalendar
 *			      info.format : 날짜 포맷 (yyyy, yyyy-MM, yyyy-MM-dd)
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.comp.setCurrDate
 */
com.comp.setCurrDate = function(compObj, info) {

	var dateVal	= com.date.getServerDateTime(info.format || 'yyyy-MM-dd');
	var compObj	= (com.util.isArray(compObj)) ? compObj : [compObj];

	for (var i = 0 ; i < compObj.length ; i ++) {
		var pluginName	= compObj[i].options.pluginName;

		if (pluginName == 'dataMap') {
			for (var j = 0 ; j < info.colIds.length ; j ++) {
				compObj[i].set(info.colIds[j], dateVal);
			}
		} else {
			compObj[i].setValue(dateVal);
		}
	}
};


