/**
 * 함수명 	: com.comp.setInputModeAll
 * 함수설명	: input mode를 일괄 적용한다.
 *			   - UI 표준가이드 11.InputMode 참조
 * 파라미터	: N/A
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.comp.setInputModeAll
 */
com.comp.setInputModeAll = function() {

	var scopeId	= com.win.getFrame().getID();
	var obj		= (scopeId == 'mf') ? $('.INPUT_MODE') : $('#' + scopeId).find('.INPUT_MODE');

	for (var i = 0 ; i < obj.length ; i ++) {
		var compId	= $(obj[i]).attr('id');
		var compObj	= $p.getComponentById(compId);

		var inputCompObj	= [];

		if (compObj.options.pluginName == 'gridView') {

			var colInfo	= compObj.cellInfoHash;

			for (var item in colInfo) {
				var allowChar	= colInfo[item].options.userData1;

				if (com.util.isNotEmpty(allowChar)) {

					// 웹접근성 그리드는 컬럼 객체 
					// 일반 그리드는 생성한 컴포넌트 객채
					if (compObj.options.senseReader == true) {
						inputCompObj.push({compObj : colInfo[item], char : allowChar});
					} else {
						var colComp	= colInfo[item].mainGrid.getInput(colInfo[item]);
						colInfo[item].comp	= colComp;

						inputCompObj.push({compObj : colInfo[item].comp, char : allowChar});
					}
				}
			}
		} else {
			var allowChar 	= com.comp.getCompUseData('INPUT_MODE', compObj);
			inputCompObj.push({compObj : compObj, char : allowChar})
		}

		for (var j = 0 ; j < inputCompObj.length ; j ++) {
			if (compObj.options.senseReader == true) {
				// 웹접근성 그리드는 컬럼 옵션에 allowChar 설정
				// 일반 그리드는 컬럼의 생성된 컴포넌트에 allowChar 설정
				inputCompObj[j].compObj.options.allowChar		= com.comp._getAllowChar(inputCompObj[j].char);
				inputCompObj[j].compObj.options.validateOnInput	= true;
			} else {
				com.comp.setInputMode(inputCompObj[j].compObj, inputCompObj[j].char);
			}
		}
	}
};


