com.comp._getAllowChar = function(allowChar) {

	var regExp	= '';
	var hanja	= com.util.unicodeToString('0x4e00') + '-' + com.util.unicodeToString('0x9fa5');

	if (allowChar == 'HANGULONLY2') {
		regExp = 'ㄱ-ㅎㅏ-ㅣ가-힣\\s';

	} else if (allowChar == 'HANGULDIGITONLY') {
		regExp = 'ㄱ-ㅎㅏ-ㅣ가-힣0-9\\s\\-㎡';

	} else if (allowChar == 'DIGITONLY') {
		regExp = '0-9,';

	} else if (allowChar == 'UPPERCASEONLY') {
		regExp = 'A-Z\\s';

	} else if (allowChar == 'NUMBER') {
		regExp = '0-9\\-_.';

	} else if (allowChar == 'NUMBER2') {
		regExp = '0-9\\-.';

	} else if (allowChar == 'NUMBER3') {
		regExp = '0-9.';

	} else if (allowChar == 'DIGITS') {
		regExp = '0-9';

	} else if (allowChar == 'DIGIT_SPEC1') {
		regExp = "0-9\\-.,()~/=";

	} else if (allowChar == 'HANGUL_DIGIT') {
		regExp = 'ㄱ-ㅎㅏ-ㅣ가-힣0-9\\s';

	} else if (allowChar == 'KOREAN_ONLY') {
		regExp = "^a-zA-Z";

	} else if (allowChar == 'HANGULDIGITSPEC1') {
		regExp = "ㄱ-ㅎㅏ-ㅣ가-힣0-9\\s\\-.,()";

	} else if (allowChar == 'HANGULDIGITSPEC2') {
		regExp = "ㄱ-ㅎㅏ-ㅣ가-힣0-9\\s\\-.,()" + hanja;

	} else if (allowChar == 'HANGULDIGITSPEC3') {
		regExp = "ㄱ-ㅎㅏ-ㅣ가-힣0-9\\s\\-.,():㎡";

	} else if (allowChar == 'HANGULDIGITSPEC4') {
		regExp = "ㄱ-ㅎㅏ-ㅣ가-힣0-9\\s\\-.,():=_+*\\/";

	} else if (allowChar == 'HANGUL_DIGIT1') {
		regExp = "ㄱ-ㅎㅏ-ㅣ가-힣0-9\\-.,()";

	} else if (allowChar == 'HANGUL_DIGIT_SPEC1') {
		regExp = "ㄱ-ㅎㅏ-ㅣ가-힣0-9\\s\\-.,()/:";

	} else if (allowChar == 'ENG_DIGIT_ONLY') {
		regExp = "0-9a-zA-Z";

	} else if (allowChar == 'ENGU_DIGIT_ONLY') {
		regExp = "0-9A-Z";

	} else if (allowChar == 'ENG_DIGIT1') {
		regExp = "a-zA-Z0-9\\s(),.\\-";

	} else if (allowChar == 'HANGUL_DIGIT_SPEC2') {
		regExp = "^a-be-zA-Z";

	} else if (allowChar == 'HANGUL_DIGIT_SPEC3') {
		regExp = "ㄱ-ㅎㅏ-ㅣ가-힣0-9m\\s\\-.,()㎡";
	}
	return regExp;
};


