/**
 * 함수명 	: com.comp.setPreTabOrder
 * 함수설명	: Shift + Tab 입력 시 이동할 컴포넌트를 설정한다.
 * 파라미터	: compObj : 현재 컴포먼트
 *			  preCompObj : 이동할 컴포넌트
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.comp.setPreTabOrder
 */
com.comp.setPreTabOrder = function(compObj, preCompObj) {

	if (com.util.isEmpty(WebSquare.tabOrder[compObj.getID()])) {
		WebSquare.tabOrder[compObj.getID()] = {preTabID : preCompObj.getID()};
	} else {
		WebSquare.tabOrder[compObj.getID()].preTabID = preCompObj.getID();
	}
};


com.comp.setFloating = function(frameObj) {

	var scope 			= frameObj.scope;

	// FloatingLayer 컴포넌트 이벤트 정의 및 초기 숨기기
	for (var item in scope) {
		if (com.util.isNotEmpty(scope[item].options) && scope[item].options.pluginName == 'floatingLayer') {

			var func = com.comp.getUserEventFunc(scope[item], 'onclose', 'com');

			if (!func) {
				com.comp.addUserEvent(scope[item], 'onclose', com.comp.hideFloating);
				com.comp.hideFloating(scope[item]);
			}
		}
	}
};

com.comp.showFloating = function(compObj, options) {

	if ($(compObj.render).is(':visible')) return;

	console.log({method : 'showFloating', options : options});

	// 오픈 시 속성 설정
	compObj.options.frameModal 		= '';
	compObj.modalStack				= 0;
	compObj.show();
	//compObj.render.style.zIndex 	= 9000;
	//compObj.render.setAttribute('mzindex', 9000);

	//===========================================================
	// 오픈 위치 결정 (메인 / 팝업)
	//===========================================================
	var floatingBox	= compObj.render.getBoundingClientRect();
	var pos			= {};
	var popTop		= 0;
	//포커스이동여부 추가
	var setFocus = (options?.setFocus != false) ? true : false;  

	if (com.win.isPopup()) {
		var popupObj	= com.win.getPopup();
		var popLayer	= {};

		if (com.win.isPopupWFrame(popupObj)) {
			popLayer  = popupObj.render.getBoundingClientRect();

			// 팝업창에 모달 복사
			if (compObj.options.useModal && ($('.w2modal_popup').length == 1 || $('.w2modal_floatingLayer').length == 1)) {
				var modalObj	= ($('.w2modal_popup').length == 1) ? $('.w2modal_popup').clone() : $('.w2modal_floatingLayer').clone();

				modalObj.css({position : 'absolute'});
				modalObj.attr('mfloatmodal', 'yes');

				$(popupObj.render).append(modalObj);
			}	

			popTop	= popLayer.top;
		} else {
			popLayer	= {
				left	: 0,
				top 	: 0,
				width	: popupObj.innerWidth,
				height	: popupObj.innerHeight
			};
		}
		pos.left	= popLayer.left + (popLayer.width - floatingBox.width) / 2;
		pos.top 	= popLayer.top + (popLayer.height - floatingBox.height) / 2;
	} else {
		var splitObj	= $(compObj.render).closest('.split_wrap');

		if (splitObj && splitObj.length == 1) {
			splitObj.find('.ly_column').css({overflow : 'initial'});
		}

		pos	= {
			left : (document.body.offsetWidth - floatingBox.width) / 2 + $(document).scrollLeft(),
			top	 : (window.innerHeight - floatingBox.height) / 2 + $(document).scrollTop(),
		};
	}

	var left	= (options && options.left) ? options.left : pos.left;
	var top		= (options && options.top) ? options.top : pos.top;

	setTimeout(function() {
		//===========================================================
		// 포커스 정보 설정 및 이동
		//	1. FloatingLayer ID를 window.mfloat에 설정 (im10.focus._lastFocus 에서 사용)
		//	2. 첫번째 컴포넌트로 포커스 이동 (im10.focus._moveNextFoucs 함수 이용)
		//===========================================================\
		$(compObj.render).offset({top : top, left : left});

		//포커스이동여부 추가
		if (gcm.SYS_ID == 'IM10' && setFocus) {
			// floating 정보 추가.
			if (com.util.isEmpty(window.mfloat)) window.mfloat = [];
			window.mfloat.push(compObj.id);

			var target	= $(compObj.render).find('[posindex]').first();

			// 포커스 이동 대상 없을 경우 리턴
			if (target.length == 0) return;

			var pName	= target.attr('pname');
			var compId  = target.attr('compid');


			im10.focus._moveNextFoucs(compObj.id, compId, null, null, true);
		}
	}, 10);
};

com.comp.hideFloating = function(compObj) {

	compObj	= (com.util.isEmpty(compObj)) ? this : compObj;

	//===========================================================
	// 포커스 정보 삭제 및 이동
	//	1. FloatingLayer ID를 window.mfloat에 삭제
	//	2. 상위 엘리먼트 클릭 하여 포커스 이동
	//===========================================================
	if (gcm.SYS_ID == 'IM10' && window.mfloat) {
		for (var i = 0 ; i < window.mfloat.length ; i ++) {
			if (window.mfloat[i] == compObj.id) {
				window.mfloat.splice(i, 1);
				break;
			}
		}
		// 오픈한 페이지에 포커스 이동 (상위 엘리먼트 클릭 => im10.focus._lastFocus 호출됨)

		$(compObj.render).parent().click();		
	}

	// 닫기 시 속성 설정
	compObj.options.frameModal 		= 'false';

	// 모달 스톡 정리
	if (com.util.isEmpty(WebSquare.getBody().stackComponents)) return;

	var modalStack = WebSquare.getBody().stackComponents.floatingLayer;

	for (var i = 0 ; i < modalStack.length ; i ++) {
		if (compObj.uuid == modalStack[i]) {
			modalStack[i] = {id : compObj.uuid, modal : true};
		}
	}

	compObj.hide('');

	// IM10 split 된 화면 복원
	var splitObj	= $(compObj.render).closest('.split_wrap');

	if (splitObj && splitObj.length == 1) {
		splitObj.find('.ly_column').css({overflow : ''});
	}

	// 팝업에 추가한 모달 삭제
	setTimeout(function() {
		var modalObj	= $('[mfloatmodal]');

		if (modalObj.length  != 0) {
			var floatObj	= modalObj.parent().find('.w2floatingLayer');
			var isRemove	= true;
			for (var i = 0 ; i < floatObj.length ; i ++) {
				if ($(floatObj[i]).is(':visible')) {
					isRemove = false;
				}
			}

			if (isRemove) {
				$('[mfloatmodal]').remove();
			}
		}
	}, 10);
};


/**
 * 함수명 	: com.comp.setOpenFloating
 * 함수설명	: FloatingLayer 옵션을 조정한다.
 * 파라미터	: obj : HTML 엘리먼트
 *			  type : 이벤트 유형
 *			  callUserFn : 이벤트 함수
 *			  isOrder : 이벤트 전파유형 (true : 캡처링, false : 버블링)
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.comp.setPreTabOrder
 */
com.comp.setOpenFloating = function(type, options) {

	var floatingObj	= $('.w2floatingLayer').filter(':visible');

	if (type == 'Z-INDEX') {
		for (var i = 0 ; i < floatingObj.length ; i ++) {
			if (options == 'BEFORE') {
				floatingObj[i].style.old_zIndex = floatingObj[i].style.zIndex;
				floatingObj[i].style.zIndex		= 'auto';

				$('.w2modal_floatingLayer').hide();

			} else {
				floatingObj[i].style.zIndex = floatingObj[i].style.old_zIndex;

				$('.w2modal_floatingLayer').show();
				delete floatingObj[i].style.old_zIndex;
			}	
		}	
	}
};


/**
 * 함수명 	: com.comp.addHtmlEvent
 * 함수설명	: HTML 이벤트를 추가한다.
 * 파라미터	: obj : HTML 엘리먼트
 *			  type : 이벤트 유형
 *			  callUserFn : 이벤트 함수
 *			  isOrder : 이벤트 전파유형 (true : 캡처링, false : 버블링)
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.comp.setPreTabOrder
 */
com.comp.addHtmlEvent = function(obj, type, callUserFn, isOrder) {
	if (com.util.isNotEmpty(obj)) {
		obj.addEventListener(type, callUserFn, isOrder);
	} else {
		console.log({error_method : 'addHtmlEvent' , desc : 'empty object'});
	}
};


/**
 * 함수명 	: com.comp.addUserEvent
 * 함수설명	: 웹스퀘어 컴포넌트 이벤트를 추가한다.
 * 파라미터	: compObj : 컴포넌트
 *			  eventName : 이벤트명
 *			  callUserFn : 이벤트 함수
 *			  isFirst : 우선 이벤트 발생 여부 (true : 우선발생, false : 기존이벤트 발생 후 발생)
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.comp.setPreTabOrder
 */
com.comp.addUserEvent = function(compObj, eventName, callUserFn, isFirst) {

	if (com.util.isNotEmpty(compObj) && com.util.isNotEmpty(compObj.userEventList)) {

		isFirst = (com.util.isNotEmpty(isFirst)) ? isFirst : false;

		var event = {
			action 	: 'script',
			name 	: eventName,
			type	: 'com',
			param 	: {handler : callUserFn},
		};

		if (isFirst) {
			compObj.userEventList.unshift(event);
		} else {
			compObj.userEventList.push(event);
		}
	}
};


/**
 * 함수명 	: com.comp.getUserEventFunc
 * 함수설명	: 웹스퀘어 사용자 이벤트를 함수 조회한다.
 * 파라미터	: compObj : 컴포넌트
 *			  eventName : 이벤트명
 * 리턴		: 이벤트 함수
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.comp.setPreTabOrder
 */
com.comp.getUserEventFunc = function(compObj, eventName, type) {

	var scope		= compObj.getScopeWindow();
	var resultFunc	= [];
	var eventNames	= (com.util.isArray(eventName)) ? eventName : [eventName];

	for (var i = 0 ; i < compObj.userEventList.length ; i ++) {

		var userEvent	= compObj.userEventList[i];

		for (var j = 0 ; j < eventNames.length ; j ++) {

			if (userEvent.name == eventNames[j] && userEvent.param && com.util.isNotEmpty(userEvent.param.handler) && userEvent.type == type) {

				var func	= null;
				if ('function' == typeof userEvent.param.handler) {
					func	= userEvent.param.handler;
				} else {
					try {
						func			= scope;
						var funcInfo	= userEvent.param.handler.split('.');
						for (var cnt = 0 ; cnt < funcInfo.length ; cnt ++) {

							func	= func[funcInfo[cnt]];
						}

						if ('function' != typeof func) {
							func	= null;
						}
					} catch (ex) {
						console.log(ex);
					}
				}	

				if (com.util.isNotEmpty(func)) resultFunc.push(func);

				if (resultFunc.length == eventNames.length) {
					if (eventNames.length == 1) {
						return resultFunc[0];
					} else {
						return resultFunc;
					}
				}
			}
		}
	}

	if (com.util.isArray(eventName)) {
		return resultFunc;
	} else {
		return null;
	}
};

com.comp.imeComplete = function(compObj) {

	compObj.setEventPause(null, true);
	$('#__IME_HIDDEN__').focus();

	setTimeout(function() {
		compObj.options.pluginName
		compObj.focus();
		compObj.setEventPause(null, false);	
	}, 1);
};

com.comp.getCompUseData = function(type, compObj, userData) {

	var userData	= compObj.getUserData('userData1');

	if (com.util.isNotEmpty(userData)) {
		var bizData	= userData.split(',');

		// INPUT_MODE , HOT_KEY 구분
		for (var i = 0 ; i < bizData.length ; i ++) {

			if (com.util.isNotEmpty(bizData[i].trim())) {
				var bizKey	= com.comp._getAllowChar(bizData[i]);

				if (type == 'INPUT_MODE') {
					if (com.util.isNotEmpty(bizKey)) return bizData[i];
				} else {
					if (com.util.isEmpty(bizKey)) return bizData[i];
				}
			}
		}
	}
}


com.comp.editCallFn = function(obj, fnName, param) {
	try {
		var parentObj	= $(obj).closest('.w2textbox');

		if (parentObj.length == 0) return;

		var parentComp	= $p.getComponentById(parentObj[0].id);
		var scopeId		= parentComp.getScope().id;
		var callFn		= WebSquare.util.getGlobalFunction(fnName, scopeId);
		var fParam		= (param) ? param : null;

		if (callFn) callFn(fParam);
	} catch (ex) {
		console.log(ex);
	}
};


