com.grid	= {};


/**
 * 함수명 	: com.grid.setRemoveAutofit
 * 함수설명	: GridView 컬럼 넓이 정보 설정 및 이벤트 제어
 * 				- 이벤트 : oncolumnwidthchange, oncontextclick
 * 파라미터	: compObj : 컴포넌트
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.comp.setPreTabOrder
 */
com.grid.setRemoveAutofit = function (compObj) {

	console.log({method : 'setRemoveAutofit', gridId : compObj.id});

	if (compObj.mRemoveAutofit) {
		try {
			// natvie의 경우 기본컬럼이 있을 경우 autofit 제어를 할 수 없어 autofit을 제거 후 _scroll 함수에서 넓이 계산하여 지정함.
			if (compObj.options.drawType == 'native') {

				var defaultCnt		= 0;
				var colWidth		= compObj.colWidthList.concat();

				if (compObj.options.rowStatusVisible == true) defaultCnt++;
				if (compObj.options.rowNumVisible == true) defaultCnt++;

				compObj.mDefaultCnt			= defaultCnt;	// 기본 컬럼 수 저장

				compObj.clearAutoFit();

				for (var i = defaultCnt ; i < colWidth.length ; i ++) {
					compObj.setColumnWidth(i - defaultCnt, colWidth[i]);
				}
			}

			compObj.mOrgColWidth	= compObj.initialColWidthList.concat();
			com.grid.getColumnWidthInfo(compObj, false);

			com.comp.addUserEvent(compObj, 'oncolumnwidthchange', com.grid._oncolumnwidthchange, true);
			com.comp.addUserEvent(compObj, 'oncontextclick', com.grid._oncontextclick, true);
		} catch (ex) {
			console.log(ex)
			//debugger;
		}
	}
};


/**
 * 함수명 	: com.grid._oncontextclick
 * 함수설명	: GridView 컨텍스트 메뉴에서 컬럼 숨기기, 숨기기 해제 메뉴를 클릭 이벤트 함수 (내부함수)
 * 				- 숨김, 숨김해제로 전체 컬럼 넓이 변경 발생하여 넓이 재계산 (_oncolumnwidthchange 함수 호출)
 * 파라미터	: row : row index
 * 			  col : column index
 * 			  userMenuId : 사용자 메뉴 ID
 * 			  isSystemMenu : 시스템 메뉴 여부
 *  		  systemMenu : 시스템 메뉴 ID
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
com.grid._oncontextclick = function(row, col, useMenuId, isSystemMenu, systemMenu) {

	console.log({method : '_oncontextclick', row : row, col : col, useMenuId : useMenuId, isSystemMenu : isSystemMenu, systemMenu : systemMenu});

	//=============================================================================
	// 시스템 메뉴
	// 	- ColumnHide           - 선택 컬럼 숨기기
	// 	- ColumnShowAll        - 전체 컬럼 숨기기 해제
	// 	- ColumnFix            - 선택 컬럼 틀고정
	// 	- ColumnUnfixAll       - 전체 컬럼 틀고정 취소
	// 	- ColumnAdjustWidth    - 전체 컬럼 크기 자동 맞추기
	// 	- ColumnAdjustAuto     - 전체 컬럼 크기 자동 맞추기
	// 	- ColumnAdjustAutoNone - 전체 컬럼 자동 맞추기 취소		
	//=============================================================================
	if (isSystemMenu && (systemMenu == 'ColumnHide' || systemMenu == 'ColumnShowAll')) {
		// 컬럼 넓이 재계산 함수 호출
		_oncolumnwidthchange.apply(this, [{columnIndex : -999}]);
	}
};

/**
 * 함수명 	: com.grid._oncolumnwidthchange
 * 함수설명	: GridView 컬럼 넓이 정보 설정 및 BlankRow 생성
 * 파라미터	: info : 컬럼넓이 변경 정보 & BlankRow 생성 유형
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
com.grid._oncolumnwidthchange = function (info) {

	console.log({method : '_oncolumnwidthchange', gridId : this.id, autofit : this.mRemoveAutofit});

	if (this.mRemoveAutofit) {
		com.grid.getColumnWidthInfo(this, false);
	}

	if ($(this.render).is(':visible')) {
		if (this.options.autoFit == 'lastColumn' && com.util.isString(info) == false) this.setAutoFit({type : 'lastColumn'});

		if (com.util.isString(info)) {
	    	im10.grid.setBlankDrawRow(this, info);
	    } else {
	    	im10.grid.setBlankDrawRow(this, 'COL_RESIZE');
	    }
	}
}


/**
 * 함수명 	: com.grid.setColumnWidthInit
 * 함수설명	: 컬럼의 초기 넓이로 변경한다.
 * 				- 마지막 컬럼을 10으로 하여 넓이 변경 처리.
 * 파라미터	: compObj : 컴포넌트
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
com.grid.setColumnWidthInit = function (compObj) {

	for (var i = 0; i < compObj.length ; i ++) {
		compObj[i].setColumnWidth(compObj[i].mLastColInfo.idx - compObj[i].mDefaultCnt, 10);
	}
}


/**
 * 함수명 	: com.grid.getColumnWidthInfo
 * 함수설명	: 컬럼 전체 넓이를 조회한다.
 * 파라미터	: compObj : 컴포넌트
 * 리턴		: 컬럼 넓이 정보
 * 				- totWidth : 전체 넓이 (숨김컬럼 제외)
 * 				- lastColId : 마지막 컬럼 index
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
com.grid.getColumnWidthInfo = function (compObj, isSystem) {

	var orgColWidth	= (isSystem && compObj.mOrgColWidth) ? compObj.mOrgColWidth : compObj.colWidthList.concat();
	var totWidth	= 0;
	var lastIdx		= 0;
	var lastWidth	= 0;

	for (var i = 0 ; i < orgColWidth.length ; i ++) {
		if (compObj.hiddenList[i] == false) {
			totWidth 	+= parseInt(orgColWidth[i]);
			lastWidth	= parseInt(orgColWidth[i]);
			lastIdx		= i;
    	}
	}

	compObj.mLastColInfo = {idx : lastIdx};

	return {totWidth : totWidth, lastIdx : lastIdx, lastWidth : lastWidth};
}


/**
 * 함수명 	: com.grid.getColumnLastInfo
 * 함수설명	: 마지막 컬럼 넓이 정보를 저장 및 조회한다.
 * 				- 마지막 컬럼 넓이 정보를 mLastColInfo 에 저장한다.
 * 파라미터	: compObj : 컴포넌트
 * 리턴		: 컬럼 넓이 정보
 * 				- width : 마지막 컬럼 넓이
 * 				- idx : 마지막 컬럼 index
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
com.grid.getColumnLastInfo = function (compObj) {

	for (var i = compObj.hiddenList.length -1 ; i > -1  ; i --) {
		if (compObj.hiddenList[i] == false) {
			compObj.mLastColInfo 	= {
				idx 	: i,
				width 	: compObj.colWidthList[i]
			};

			break;
		}
	}
	return compObj.mLastColInfo;
};


/**
