 *			  {id : scwin.columnFormatBlue}, 	// key : 컬럼아이디, 값 : 사용자포맷팅 함수
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.grid.setColumnFormatCustom
 */
com.grid.setColumnFormatCustom = function(compObj, options) {

	var dcObj	= com.data.getBindDataObject(compObj);

	dcObj.setBroadcast(false);

	for (var i = 0 ; i < options.length ; i ++) {

		for (var item in options[i]) {
			compObj.cellInfoHash[item].options.displayFormatter = options[i][item];
