/**
 * 함수명 	: com.grid.setColumnFormatCustomCell
 * 함수설명	: GridView Cell의 text의 사용자가 포맷을 설정한다. (사용자함수)
 *			   - GridView Readonly에서만 사용
 *			   - 교합처리 화면 사용
 * 파라미터	: compObj : GridView 컴포넌트
 *			  options : 사용자함수 이름쌍
 *			   {desc : scwin.cellFormat}  (키 : 컬럼아이디, 값 : 포맷팅함수)
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.grid.setColumnFormatCustomCell
 */
com.grid.setColumnFormatCustomCell = function(compObj, options) {

	var dcObj	= com.data.getBindDataObject(compObj);

	dcObj.setBroadcast(false);

	for (var i = 0 ; i < dcObj.getTotalRow() ; i ++) {

		for (var j = 0 ; j < options.length ; j ++) {

			for (var item in options[j]) {
				var func		= options[j][item];
				var customData	= func(item, dcObj.getRowJSON(i));

				dcObj.setCellData(i, item, customData);
			}
		}
	}
	dcObj.setBroadcast(true, true);
};


/**
 * 함수명 	: com.grid.setTopRowIndex
 * 함수설명	: row를 top으로 이동시킨다. (세로스크롤)
 * 				- virtual 모드 : GridVidw의 setTopRowIndex 메소드 동일하게 사용
 * 				- native 모드 
 * 					- autoFocus == true : 포커스 이동 (setFocusedCell) 후 포커스된 cell의 offsetTop를 scrollTop로 설정
 * 					- autoFocus != true : GridView의 테이블에서 이동할 tr 조회 후 tr의 offsetTop를 scrollTop로 설정
 * 파라미터	: compObj : GridView 컴포넌트
 *			  topRowIndex : Top으로 이동할 row index
 *			  noEvent : 스크롤이 맨 끝으로 도달할 경우 onscrollend 이벤트를 발생시키지 않을 때 true인자를 추가로 넘김.
 *			  autoFocus : 포커스도 이동 여부 (true : 포커스 이동 , false : 포커스 이동없음 (스크롤만 이동))
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.grid.setTopRowIndex = function (compObj, topRowIndex, noEvent, autoFocus) {

	if (compObj.options.drawType == 'virtual') {
		compObj.setTopRowIndex(topRowIndex, noEvent, autoFocus);
	} else {

		var dataLayer 		= document.getElementById(compObj.id + '_dataLayer');
		var headerHeight	= compObj.dom[compObj.id + '_head_table'].offsetHeight;		// 해더 높이

		if (dataLayer.offsetHeight == dataLayer.scrollHeight) return;

		var topElement		= null;

		if (autoFocus == true) {
			compObj.setFocusedCell(topRowIndex, 0);
			topElement		= compObj.focusedCell[0].focusedTd;
		} else {
			var tableLayer	= compObj.body_table;
			var tr			= $(tableLayer).find('tbody').find('tr');

			if (tr.length > topRowIndex) {
				topElement	= tr[topRowIndex];
			}
		} 

		if (topElement) {
			var cellTop       	= topElement.offsetTop - headerHeight;

			dataLayer.scrollTop	= cellTop;
			compObj.mScrollTop  = dataLayer.scrollTop;
		}
	}
};


