/**
 * 함수명 	: com.grid.setPagingList
 * 함수설명	: GridView Combo 형태의 페이징을 처리한다.
 *			   - 검색버튼 클릭 시 조회는 화면에서 처리함.
 * 파라미터	: compObj : GridView 컴포넌트
 *			  compObjInfo : 컴포넌트 정보
 *			  compObjInfo.sbm : Submission 컴포넌트
 *			  compObjInfo.dataMap : 검색조건 dataMap
 *			  compObjInfo.page : 검색조건 pageList 컴포넌트
 *			  compObjInfo.totalCnt : 총 건수 표시 컴포넌트
 *			  compObjInfo.dataList : GridView 바인딩된 dataList
 *			  compObjInfo.checkDataList : 체크한 데이터 저장하는 dataList
 *			  compObjInfo.checkKeyColId : 체크한 데이터와 GridView 데이터와 비교하기 위한 key 컬럼 ID
 *			  compObjInfo.checkColId : dataList, checkDataList의 체크 컬럼 ID
 *			  options : 옵션정보
 *			  options.visibleRowNum : GridView 노출 Row 수
 *			   - all 일 경우 dataList 건 수에 맞게 노출됨
 *			  options.pageUnit : 페이지당 조회 건수
 *			  callbackFnInfo : 콜백함수 정보
 *			  callbackFnInfo.searchParam : 검색조건 설절 콜백함수
 *			  callbackFnInfo.submitDone : Submission 수행 후 호출하는 콜백함수
 *			   - 파라미터 : 서비스에서 조회한 결과 데이터 (Submission의 submitdone 이벤트 참조)
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.grid.setPagingList
 */
com.grid.setPagingList = function(compObj, compObjInfo, options, callbackFnInfo) {

	var options = $.extend({
		visibleRowNum 	: gcm.GRID_VISIBLE_ROWNUM,
		pageUnit		: gcm.PAGE_LIST_SIZE,
		isVisibleRowNum	: true
	}, options);

	// grid, page 기본 값 설정
	compObjInfo.dataMap.set('pageUnit', options.pageUnit);

	if (options.isVisibleRowNum != false) {
		compObj.options.visibleRowNum 	= options.visibleRowNum;
	}

	// submission 처리완료 후 callback 처리.
	compObjInfo.sbm.submitDoneHandler	= function(resData) {

		// 페이징 정보 처리 (페이징, 총건수)
		var paginationInfo = resData.responseJSON.paginationInfo;
	    if (com.util.isNotEmpty(paginationInfo)) {
	    	compObjInfo.page.setCount(paginationInfo.totalPageCount, true);
	    	compObjInfo.page.setValue(paginationInfo.currentPageNo);

	    	// 총 건수
	    	if (compObjInfo.totalCnt) {
	    		compObjInfo.totalCnt.setValue(com.num.formatNumber(paginationInfo.totalRecordCount));
	    	}
	    }

	    // 체크 데이터와 조회한 데이터를 비교하여 조회한 데이터에 체크 처리한다.
	    // 체크 데이터(compObjInfo.checkDataList)의 checkKeyColId의 컬럼값으로 조회한 데이터(compObjInfo.dataList)가 같으면 compObjInfo.checkColId에 값 설정
	    if (compObjInfo.dataList && compObjInfo.checkDataList && compObjInfo.checkKeyColId && compObjInfo.checkColId) {

	    	compObjInfo.dataList.setBroadcast(false, false);

	    	for (var i = 0 ; i < compObjInfo.checkDataList.getTotalRow() ; i ++) {

	    		var checkKeyVal = compObjInfo.checkDataList.getCellData(i, compObjInfo.checkKeyColId);
	    		var checkVal	= compObjInfo.checkDataList.getCellData(i, compObjInfo.checkColId);

	    		for (var j = 0 ; j < compObjInfo.dataList.getTotalRow() ; j ++) {

	    			var keyVal = compObjInfo.dataList.getCellData(j, compObjInfo.checkKeyColId);

	    			if (checkKeyVal == keyVal) {
	    				compObjInfo.dataList.setCellData(j, compObjInfo.checkColId, checkVal);
	    				break;
	    			}
	    		}
	    	}

	    	compObjInfo.dataList.setBroadcast(true, true);
	    }

	    // 콜백이 있을 경우 페이징 처리 후 콜백
	    if (callbackFnInfo && callbackFnInfo.submitDone) {
			callbackFnInfo.submitDone(resData);
		}
	};

	compObjInfo.sbm.userEventList	= [];
	compObjInfo.sbm.userEventList.push(new WebSquare.Events.XmlEvent('xforms-submit-done', 'script', {handler : compObjInfo.sbm.submitDoneHandler}));

	//==============================================================================
	// page 클릭 이벤트 처리
	//==============================================================================
	compObjInfo.page.unbind('onclick');
	compObjInfo.page.bind('onclick', function(idx) {

		if (callbackFnInfo && callbackFnInfo.searchParam) {
			callbackFnInfo.searchParam();
		} 

		compObjInfo.dataMap.set('pageIndex', idx);
		com.sbm.execute(compObjInfo.sbm);
	});
};


/**
 * 함수명 	: com.grid.setPagingCombo
 * 함수설명	: GridView List 형태의 페이징을 처리한다.
 *			   - 검색버튼 클릭 시 조회는 화면에서 처리함.
 * 파라미터	: compObj : GridView 컴포넌트
 *			  compObjInfo : 컴포넌트 정보
 *			  compObjInfo.sbm : Submission 컴포넌트 
 *			   - sumitdone 이벤트로 후 처리가 필요할 경우 callbackFn으로 사용
 *			  compObjInfo.dataMap : 검색조건 dataMap 컴포넌트 
 *			  - pageIndex, pageUnit 컬럼이 반드시 있어야 함.
 *			  compObjInfo.page : 페이징 목록 selectbox
 *			  compObjInfo.totalPage : totalPage 표시 컴포넌트 (textbox, span..)
 *			  compObjInfo.totalCnt : 전체 검수 표시 컴포넌트
 *			  compObjInfo.dataList : GridView 바인딩된 dataList
 *			  compObjInfo.checkDataList : 체크한 데이터 저장하는 dataList
 *			  compObjInfo.checkKeyColId : 체크한 데이터와 GridView 데이터와 비교하기 위한 key 컬럼 ID
 *			  compObjInfo.checkColId : dataList, checkDataList의 체크 컬럼 ID
 *			  options : 옵션정보
 *			  options.pageUnit : 페이징 사이즈
 *			  options.visibleRowNum : GridView 표시할 row 수 (GridView.visibleRowNum 속성 값)
 *			   - all : 데이터 모두 표시, 숫자 : 숫자만큼 표시
 *			   - options.visibleRowNum
 *			  callbackFnInfo : 콜백함수 정보
 *			  callbackFnInfo.searchParam : 검색조건 설정 콜백함수
 *			  callbackFnInfo.submitDone : 페이징 조회 후 콜백함수를 호출함
 *			   - submission의 submitdone 이벤트 대신 callbackFn 함수 이용함.
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.grid.setPagingCombo
 */
com.grid.setPagingCombo = function(compObj, compObjInfo, options, callbackFnInfo) {

	var options = $.extend({
		visibleRowNum 	: gcm.GRID_VISIBLE_ROWNUM,
		pageUnit		: gcm.PAGE_LIST_SIZE
	}, options);

	// grid, page 기본 값 설정
	compObjInfo.dataMap.set('pageUnit', options.pageUnit);
	compObj.options.visibleRowNum 	= options.visibleRowNum;

	// submission 처리완료 후 callback 처리.
	compObjInfo.sbm.submitDoneHandler	= function(resData) {

		var paginationInfo = resData.responseJSON.paginationInfo;
	    if (com.util.isNotEmpty(paginationInfo)) {

	    	compObjInfo.page.setEventPause('onviewchange', true);

	    	// 전체 페이지와 콤보박스의 페이징 설정
	    	compObjInfo.page.removeAll();
	    	for (var i = 1 ; i <= paginationInfo.totalPageCount ; i ++) {
	    		compObjInfo.page.addItem( i + "" , i + "");
	    	}
	    	compObjInfo.page.setValue(paginationInfo.currentPageNo);
	    	compObjInfo.totalPage.setValue(paginationInfo.totalPageCount);

	    	// 총 건수 표기
	    	if (compObjInfo.totalCnt) {
	    		compObjInfo.totalCnt.setValue(com.num.formatNumber(paginationInfo.totalRecordCount));
	    	}

	    	compObjInfo.page.setEventPause('onviewchange', false);
	    }

	    // 체크 데이터와 조회한 데이터를 비교하여 조회한 데이터에 체크 처리한다.
	    // 체크 데이터(compObjInfo.checkDataList)의 checkKeyColId의 컬럼값으로 조회한 데이터(compObjInfo.dataList)가 같으면 compObjInfo.checkColId에 값 설정
	    if (compObjInfo.dataList && compObjInfo.checkDataList && compObjInfo.checkKeyColId && compObjInfo.checkColId) {

	    	compObjInfo.dataList.setBroadcast(false, false);

	    	for (var i = 0 ; i < compObjInfo.checkDataList.getTotalRow() ; i ++) {

	    		var checkKeyVal = compObjInfo.checkDataList.getCellData(i, compObjInfo.checkKeyColId);
	    		var checkVal	= compObjInfo.checkDataList.getCellData(i, compObjInfo.checkColId);

	    		for (var j = 0 ; j < compObjInfo.dataList.getTotalRow() ; j ++) {

	    			var keyVal = compObjInfo.dataList.getCellData(j, compObjInfo.checkKeyColId);

	    			if (checkKeyVal == keyVal) {
	    				compObjInfo.dataList.setCellData(j, compObjInfo.checkColId, checkVal);
	    				break;
	    			}
	    		}
	    	}

	    	compObjInfo.dataList.setBroadcast(true, true);
	    }

	    // 콜백이 있을 경우 페이징 처리 후 콜백
		if (callbackFnInfo && callbackFnInfo.submitDone) {
			callbackFnInfo.submitDone(resData);
		}
	};

	compObjInfo.sbm.userEventList	= [];
	compObjInfo.sbm.userEventList.push(new WebSquare.Events.XmlEvent('xforms-submit-done', 'script', {handler : compObjInfo.sbm.submitDoneHandler}));

	//==============================================================================
	// page 클릭 이벤트 처리
	//==============================================================================
	compObjInfo.page.unbind('onviewchange');
	compObjInfo.page.bind('onviewchange', function(info) {

		if (callbackFnInfo && callbackFnInfo.searchParam) {
			callbackFnInfo.searchParam();
		}

		compObjInfo.dataMap.set('pageIndex', info.newValue);
		com.sbm.execute(compObjInfo.sbm);
	});
};


/**
 * 함수명 	: com.grid.setPagingMobile
 * 함수설명	: GridView Mobile 형태의 페이징을 처리한다.
 *			   - 검색버튼 클릭 시 조회는 화면에서 처리함.
 * 파라미터	: compObj : GridView 컴포넌트
 *			  compObjInfo : 페이징 관련 컴포넌트 정보
 *			  compObjInfo.sbm : Submission 컴포넌트 
 *			   - target 정보가 반드시 있어야 함
 *			  compObjInfo.dataMap : 검색조건 dataMap
 *			  compObjInfo.page : 더보기 버튼 컴포넌드
 *			   - 초기 설정 시 화면에서 hide 처리
 *			  compObjInfo.totalCnt : 총 건수 컴포넌트
 *			  options : 옵션정보
 *			  options.pageUnit : 페이징 단위
 *			  callbackFnInfo : 콜백함수
 *			  callbackFnInfo.searchParam : Submission  수행 전 검색조건 설정 콜백
 *			  callbackFnInfo.submitDone : Submission 수행 후 호출될 콜백함수
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.grid.setPagingMobile
 */
com.grid.setPagingMobile = function(compObj, compObjInfo, options, callbackFnInfo) {

	var options = $.extend({
		visibleRowNum 	: 'all',
		pageUnit		: gcm.PAGE_LIST_SIZE
	}, options);

	// grid, page 기본 값 설정
	compObjInfo.dataMap.set('pageUnit', options.pageUnit);
	compObj.options.visibleRowNum 	= options.visibleRowNum;



	// Submission의 target를 '' 처리
	if (com.util.isEmpty(compObjInfo.sbm.target)) {
		alert('submission의 target 정보가 없습니다.');
		return;
	}
	var targetTemp	= compObjInfo.sbm.target.replace('data:json,', '');
	var targetInfo	= JSON.parse(targetTemp);
	compObjInfo.sbm.target	= '';

	// submission 처리완료 후 callback 처리.
	compObjInfo.sbm.submitDoneHandler	= function(resData) {

		var paginationInfo 	= resData.responseJSON.paginationInfo;
		var listData		= resData.responseJSON[targetInfo.key];
		var dataList		= $p.getComponentById(targetInfo.id);
		var rowPos			= dataList.getRowCount();

		dataList.setJSON( listData , true);

		if (com.util.isNotEmpty(paginationInfo)) {
	    	if (paginationInfo.totalPageCount == paginationInfo.currentPageNo) {
	    		compObjInfo.page.show('none');
	    	} else {
	    		compObjInfo.page.setValue(options.pageUnit + '개의 결과 더보기 +');
	    	}
	    	compObjInfo.totalCnt.setValue(com.num.formatNumber(paginationInfo.totalRecordCount));
	    }

		compObj.setFocusedCell(rowPos, 0);


	    // 콜백이 있을 경우 페이징 처리 후 콜백
		if (callbackFnInfo && callbackFnInfo.submitDone) {
			callbackFnInfo.submitDone(resData);
		}
	};

	compObjInfo.sbm.userEventList	= [];
	compObjInfo.sbm.userEventList.push(new WebSquare.Events.XmlEvent('xforms-submit-done', 'script', {handler : compObjInfo.sbm.submitDoneHandler}));

	//==============================================================================
	// page 클릭 이벤트 처리
	//==============================================================================
	compObjInfo.page.unbind('click');
	compObjInfo.page.bind('click', function(e) {

		if (callbackFnInfo && callbackFnInfo.searchParam) {
			callbackFnInfo.searchParam();
		}

		var pageIndex	= parseInt(compObjInfo.dataMap.get('pageIndex')) + 1;

		compObjInfo.dataMap.set('pageIndex', pageIndex);
		com.sbm.execute(compObjInfo.sbm);
	});
};


/**
 * 함수명 	: com.grid.setPagingScrollBtn
 * 함수설명	: GridView Combo 형태의 페이징을 처리한다.
 *			   - 검색버튼 클릭 시 조회는 화면에서 처리함.
 * 파라미터	: compObj : GridView 컴포넌트
 *			  compObjInfo : 컴포넌트 정보
 *			  compObjInfo.sbm : Submission 컴포넌트 
 *			   - sumitdone 이벤트로 후 처리가 필요할 경우 callbackFn으로 사용
 *			  compObjInfo.dataMap : 검색조건 dataMap
 *			  compObjInfo.dataList : GridView에 바인딩된 dataList
 *			  compObjInfo.btnUp : 이전 조회 버튼
 *			  compObjInfo.btnUpVal : 이전 조회 버튼 값
 *			  compObjInfo.btnDown : 다음 조회 버튼
 *			  compObjInfo.btnDownVal : 다음 조회 버튼 값
 *			  options : 옵션 정보
 *			  options.dataKey : 조회한 dataList의 key 
 *			  options.pageUnit : 페이징 사이즈
 *			  options.visibleRowNum : GridView 표시할 row 수 (GridView.visibleRowNum 속성 값)
 *			   - all : 데이터 모두 표시, 숫자 : 숫자만큼 표시
 *			   - options.visibleRowNum
 *			  callbackFnInfo : 콜백함수 정보
 *			  callbackFnInfo.submitDone : 페이징 조회 후 콜백함수를 호출함
 *			   - submission의 submitdone 이벤트 대신 callbackFn 함수 이용함.
 *			  callbackFnInfo.searchParam : 검색조건 설정 콜백 함수
 *			  callbackFnInfo.sortData : 데이터 조회한 결과 정렬을 처리할 콜백 함수
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.grid.setPagingScrollBtn
 */
com.grid.setPagingScrollBtn = function(compObj, compObjInfo, options, callbackFnInfo) {

	var btnUpVal	= (compObjInfo.btnUpVal) ? compObjInfo.btnUpVal : 'T';
	var btnDownVal	= (compObjInfo.btnDownVal) ? compObjInfo.btnDownVal : 'B';

	if (com.util.isEmpty(options.isFocus)) {
		options.isFocus = true;
	}

	compObj.options.overflowY 	= 'scroll';					// 스크롤 Y는 항상 나와야 함.
	compObj.options.alwaysTriggerScrollStart 	= true;		// 스크롤TOP일때 매번 이벤트 발생
	compObj.mPagingScrollBtn					= true;		// 스크롤 페이징 버튼형 GridView

	compObjInfo.btnUp.searchYn	 	= true;
	compObjInfo.btnDown.searchYn 	= true;

	//=============================================================
	// Submission done 이벤트 처리 (데이터 적재 및 버튼 컨트롤 관리)
	//=============================================================
	compObjInfo.sbm.submitDoneHandler	= function(resData) {

		var data		= resData.responseJSON[options.returnDataKey];
		var scrollTask	= _getSearchData(options.scropllTaskColID);

		console.log({method : 'setPagingScrollBtn_submitDoneHandler', data : data});

		// 스크롤 유형별 데이터 적재
		if (this.searchInit) {
			compObjInfo.btnUp.searchYn	 	= true;
			compObjInfo.btnDown.searchYn 	= true;

			scrollTask	= 'INIT';
			_addData('INIT', data);
		} else {
			if (scrollTask == btnUpVal) {
				_addData('ADD_UP', data);
			} else if (scrollTask == btnDownVal) {
				_addData('ADD_DOWN', data);
			}
		}

		this.searchInit	 = false;

		// Submission 처리 후 콜백함수 호출
		if (callbackFnInfo && callbackFnInfo.submitDone) callbackFnInfo.submitDone(resData, data, scrollTask);

		// 버튼 제어
		setTimeout(function() {
			_btnControl(scrollTask);
		}, 100);
	};

	//=============================================================
	// 등록된 submissiondone 이벤트 삭제 후 추가
	//	- submissiondone 이벤트 발생 시 조회한 데이터를 dataList에 추가 작업을 위해 이벤트 공통에서 재정의
	//=============================================================
	compObjInfo.sbm.userEventList	= [];
	compObjInfo.sbm.userEventList.push(new WebSquare.Events.XmlEvent('xforms-submit-done', 'script', {handler : compObjInfo.sbm.submitDoneHandler}));

	//=============================================================
	// GridView 이벤트 처리 (버튼 컨트롤 제어)
	//=============================================================
	// 스크롤 상단 이벤트
	compObj.bind('onscrollstart', function() {
		_btnControl('UP');
	});
	// 스크롤 하단 이벤트
	compObj.bind('onscrollend', function() {
		_btnControl('DOWN');
	});
	// GridView 스크롤 이동 시 버튼 제어
	compObj.bind('onscrolly', function() {
		_btnControl('NONE');
	});

	//=============================================================
	// 버튼 클릭 이벤트 (submission)
	//=============================================================
	// 버튼 UP 이벤트 처리 (Submission 호출)
	compObjInfo.btnUp.bind('onclick', function() {

		if (this.searchYn == true) {
			_setSearchData(options.scropllTaskColID, btnUpVal);
			_submission();
		}
		this.searchYn	= true;
	});
	compObjInfo.btnDown.bind('onclick', function() {

		if (this.searchYn == true) {
			_setSearchData(options.scropllTaskColID, btnDownVal);
			_submission();
		}
		this.searchYn	= true;
	});


	/**
	 * 함수명 	: _submission
	 * 함수설명	: Submission을 실행한다. (내부함수)
	 * 파라미터	: N/A
	 * 리턴		: N/A
	 * 작성일 	: 2022.05.16
	 * 작성자 	: Inswave Systems
	 */
	function _submission() {

		var dataList	= compObjInfo.dataList;
		var keyData 	= (_getSearchData(options.scropllTaskColID) == btnUpVal) ? dataList.getCellData(0, options.scropllKeyColID) : dataList.getCellData(dataList.getTotalRow()-1, options.scropllKeyColID);

		_setSearchData(options.scropllKeyColID, keyData);

		var searchParam	= _getSearchParam();
		com.sbm.executeExt(compObjInfo.sbm, {nrs_param : [searchParam]}, callbackFnInfo.submitError);

		console.log({nrs_param : [searchParam]});
	}


	/**
	 * 함수명 	: _btnControl
	 * 함수설명	: UP / DOWN 버튼을 제어 한다.(SHOW / HIDE) (내부함수)
	 * 			   - 세로 스크롤 높이와 UP / DOWN 버튼을 제어 
	 * 파라미터	: type : 버튼유형 (UP / DOWN / NONE)
	 * 리턴		: N/A
	 * 작성일 	: 2022.05.16
	 * 작성자 	: Inswave Systems
	 */
	function _btnControl(type) {

		// 스크롤 높이에 따라 버튼 제어
		var isUpBtn		= false;
		var isDownBtn	= false;
		var scrollObj	= (compObj.options.drawType == 'virtual') ? compObj.dom[compObj.getID() + '_scrollY_div'] : compObj.dom[compObj.getID() + '_dataLayer'];

		if (scrollObj.offsetHeight == scrollObj.scrollHeight) {
			isUpBtn		= true;
			isDownBtn	= true;
		} else if (scrollObj.scrollTop == 0) {
			isUpBtn		= true;
		} else if ((scrollObj.offsetHeight + scrollObj.scrollTop) == scrollObj.scrollHeight) {
			isDownBtn	= true;
		}

		compObjInfo.btnUp.setDisabled(true);
		compObjInfo.btnDown.setDisabled(true);

		if (isUpBtn) {
			compObjInfo.btnUp.setDisabled(false);
		} 
		if (isDownBtn) {
			compObjInfo.btnDown.setDisabled(false);
		}
	}


	/**
	 * 함수명 	: _getSearchData
	 * 함수설명	: 검색 dataMap에서 컬럼의 값 조회 (내부함수)
	 * 파라미터	: colId : 컬럼명
	 * 리턴		: N/A
	 * 작성일 	: 2022.05.16
	 * 작성자 	: Inswave Systems
	 */
	function _getSearchData(colId) {
		return compObjInfo.searchDcObj.getCellData(0, colId);
	}


	/**
	 * 함수명 	: _setSearchData
	 * 함수설명	: 검색 dataMap에서 컬럼의 값 설정 (내부함수)
	 * 파라미터	: colId : 컬럼명
	 * 			  value : 컬럼값
	 * 리턴		: N/A
	 * 작성일 	: 2022.05.16
	 * 작성자 	: Inswave Systems
	 */
	function _setSearchData(colId, value) {
		compObjInfo.searchDcObj.setCellData(0, colId, value);
	}


	/**
	 * 함수명 	: _getSearchParam
	 * 함수설명	: 검색조건을 JSON으로 조회한다. (내부함수)
	 * 파라미터	: N/A
	 * 리턴		: N/A
	 * 작성일 	: 2022.05.16
	 * 작성자 	: Inswave Systems
	 */
	function _getSearchParam() {
		return compObjInfo.searchDcObj.getRowJSON(0);
	}


	/**
	 * 함수명 	: _addData
	 * 함수설명	: 조회한 데이터를 GridView의 dataList에 추가한다. (내부함수)
	 * 				- INIT : 기존 데이터를 삭제하고 추가
	 * 				- ADD_UP : 기존 데이터 위에 추가
	 * 				- ADD_DOWN : 기존 데이터 아래 추가
	 * 파라미터	: N/A
	 * 리턴		: N/A
	 * 작성일 	: 2022.05.16
	 * 작성자 	: Inswave Systems
	 */
	function _addData(task, data) {

		var rowIdx	= 0;

		if (task == 'INIT') {
			compObjInfo.dataList.removeAll();

			compObjInfo.dataList.insertJSON(0, data);

		} else if (task == 'ADD_UP') {
			compObjInfo.dataList.insertJSON(0, data);
			rowIdx	= data.length;
		} else {
			compObjInfo.dataList.insertJSON(compObjInfo.dataList.getTotalRow(), data);

			rowIdx	= compObjInfo.dataList.getTotalRow() - data.length -1;
		}

		compObjInfo.dataList.setBroadcast(true, true);

		//=============================================================
		// GridView Position 유지.
		//=============================================================
		if (options.isFocus) {
			compObj.setFocusedCell(rowIdx, 0);
		}

	}
};


/**
 * 함수명 	: com.grid.getTotalValue
 * 함수설명	: GridView Total, subTotal 항목 값을 조회한다.
 *			   - 포맷팅이 적용되지 않은 원형 값
 * 파라미터	: compObj : GridView 컴포넌트
 *			  totalColId : Total, SubTotal의  아이디
 * 리턴		: Total 값
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.grid.getTotalValue
 */
com.grid.getTotalValue = function (compObj, totalColId) {

	var dispVal	= '';
	var orgVal	= '';

	try {
		var dcObj		= $p.getComponentById(compObj.getDataList());
		var rowCnt		= dcObj.getTotalRow()-1

		var subTotal	= compObj.getSubtotalData(compObj.tempTr, '', '', rowCnt);
		var val			= subTotal[totalColId];

		 return val;
	} catch(ex) {
		return '';
	}
};


