/**
 * 엑셀 다운로드 / 업로드 관련 모듈
 *
 * @author Inswave Systems
 * @class excel
 * @namespace com.excel
 */
// =============================================================================
com.excel	= {};


/**
 * 함수명 	: com.excel.uploadGridView
 * 함수설명	: 엑셀 데이터 GridView로 Import
 * 파라미터	: compObj : GridView 컴포넌트
 *			  excelOptions : 엑셀 옵션 정보
 *			  excelOptions.sheetNo : 엑셀 시트 번호
 *			  (0 ~ n)
 *			  excelOptions.startRowIndex : 엑셀 데이터 시작 row index
 *			  - 엑셀 해더가 2줄이상일 경우 조정필요
 *			  excelOptions.append : 기존 GridView 데이터에 추가 적재 여부
 *			   - 추가 : 1, 신규 : 0
 *			  excelOptions.skipSpace : 공백 제거 여부
 *			   - 포함 : 0, 무시 : 1
 *			  excelOptions.columnMap : 컬럼 맵핑정보 (배열)
 *			   - 엑셀 컬럼 IDX     : 배열 IDX
 *			   - GridView 컬럼 IDX : 배열 값
 *			  excelOptions.columnVal : 엑셀 컬럼의 값을 설정 (배열)
 *			   - idx : GridView 컬럼 IDX or ID
 *			   - val : 값
 *			  
 *			  excelOptions.callbackUpload : 콜백 호출 함수
 *			  - 엑셀 데이터 IMPORT 후
 *			  - 팝업 창 닫을 때
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.excel.uploadGridView
 */
com.excel.uploadGridView = function(compObj, excelOptions) {

	var columnIds		= null;
	var poppuUrl		= {
		IM10 : '/ui/im10/com/popup/im10ComExcelUploadIndi.xml',
		PM10 : '/ui/pm10/com/popup/pm10ComExcelUploadIndi.xml',
		PM20 : '/ui/pm20/com/popup/pm20ComExcelUploadIndi.xml',
		PM60 : '/ui/pm60/com/popup/pm60ComExcelUploadIndi.xml',
		SM30 : '/ui/sm30/com/popup/sm30ComExcelUploadIndi.xml',
		EM40 : '/ui/em40/com/popup/em40ComExcelUploadIndi.xml',
		ZI01 : '/ui/zi01/com/popup/zi01ComExcelUploadIndi.xml',
	};

	var options = $.extend({
		popupUrl		: poppuUrl[gcm.SYS_ID],
		wframe			: true, 
		useModalDisable : true,
	}, com.excel.uploadGridViewOptions('POPUP', compObj, excelOptions));


	compObj.advancedExcelUpload(options);

	var popObj	= _getPopObj();

	// 엑셀 IMPORT 팝업 창에 추가 파라미터 설정
	if (com.util.isNotEmpty(popObj)) {
		// 업로드 완료 후 콜백 추가
		if (com.util.isNotEmpty(excelOptions.callbackUpload)) {
			popObj.options.dataObject.data.callbackUpload = options.callbackUpload;
		}

		// 닫기 시 콜백 추가
		if (com.util.isNotEmpty(excelOptions.callbackUploadClose)) {
			popObj.options.dataObject.data.callbackUploadClose = options.callbackUploadClose;
		}

		// 컬럼 기본 값 설정
		if (com.util.isNotEmpty(excelOptions.columnVal)) {
			popObj.options.dataObject.data.columnVal = options.columnVal;
		}

		// 숨김컬럼 적재
		if (excelOptions.hiddenColumns != undefined) {
			popObj.options.dataObject.data.hiddenColumns = excelOptions.hiddenColumns;
		}

		// 컬럼 맵핑 정보 
		if (com.util.isNotEmpty(options.columnIds)) {
			popObj.options.dataObject.data.columnIds = options.columnIds;
		}
	}


	/**
	 * 함수명 	: _getPopObj
	 * 함수설명	: 엑셀 업로드 팝업 정보 조회
	 * 				- 팝업 창에 추가 파라미터 전달하기 위해 엑셀 업로드 팝업 창 조회함.
	 * 파라미터	: N/A
	 * 리턴		: N/A
	 * 작성일 	: 2022.05.16
	 * 작성자 	: Inswave Systems
	 */
	function _getPopObj() {
		var compId	= compObj.id;
		var popList	= w2popup_singleton.popupList;
		var popObj	= null;

		for (var i = 0 ; i < popList.length ; i ++) {
			if (compId + '_excelPop' == popList[i].id) {
				return popObj	= popList[i];
			}
		}
	}
};


/**
 * 함수명 	: com.excel.uploadGridViewOptions
 * 함수설명	: 엑셀 업로드 옵션 설정
 * 파라미터	: type : 엑셀 업로드 형식 (PUPUP : 팝업형식, UDC : UDC 형식)
 * 			  compObj : GridView 컴포넌트
 *			  excelOptions : 엑셀 옵션 정보
 *			  excelOptions.sheetNo : 엑셀 시트 번호
 *			  (0 ~ n)
 *			  excelOptions.startRowIndex : 엑셀 데이터 시작 row index
 *			  - 엑셀 해더가 2줄이상일 경우 조정필요
 *			  excelOptions.append : 기존 GridView 데이터에 추가 적재 여부
 *			   - 추가 : 1, 신규 : 0
 *			  excelOptions.skipSpace : 공백 제거 여부
 *			   - 포함 : 0, 무시 : 1
 *			  excelOptions.columnMap : 컬럼 맵핑정보 (배열)
 *			   - 엑셀 컬럼 IDX     : 배열 IDX
 *			   - GridView 컬럼 IDX : 배열 값
 *			  excelOptions.columnVal : 엑셀 컬럼의 값을 설정 (배열)
 *			   - idx : GridView 컬럼 IDX or ID
 *			   - val : 값
 *			  excelOptions.callbackUpload : 엑셀 업로드 완료 시 호출 함수
 *			  excelOptions.callbackUploadClose : 닫기 시 호출 함수
 *			  - 엑셀 데이터 IMPORT 후
 *			  - 팝업 창 닫을 때
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.excel.uploadGridViewOptions = function(type, compObj, excelOptions) {

	// 엑셀 옵션 기본값 설정
	var options = $.extend({
		startRowIndex   : '1',			// 시작 row index
		skip_space	 	: 'false',		// 공백문자 제거하지 않음
		bodyRows	 	: '1',			// Body의  row
	}, excelOptions);

	//=========================================================
	// 컬럼 맵핑 및 기본 값 설정 (columnMap, excelColumnVal)
	//=========================================================
	if (com.util.isNotEmpty(excelOptions.columnMap)) {
		var colInfo		= [];

		var cellList	= compObj.cellIdList;

		for (var i = 0 ; i < cellList.length ; i ++) {
			var isAdd	= true;
			for (var j = 0 ; j < excelOptions.columnMap.length ; j ++) {
				if (excelOptions.columnMap[j] == i) {
					isAdd	= false;
					break;
				}
			}
			if (isAdd) {
				excelOptions.columnMap.push(i);
			}
		}

		for (var i = 0 ; i < excelOptions.columnMap.length ; i ++) {
			colInfo.push(cellList[excelOptions.columnMap[i]]);
		}
		options.columnIds	= colInfo.join(',');
	}

	//=========================================================
	// UDC인 경우 옵션을 추가함.
	//=========================================================
	if (type == 'POPUP') {
		return options;
	} else {
		return $.extend(compObj.getExcelUploadInfo(options), options);
	}
} 


