 *			  excelOptions.excelInfo.rowNumVisible : 행 번호 표시 컬럼의 유무
 *			  excelOptions.excelInfo.service.websquare_url : 서비스 URL
 *			  excelOptions.excelInfo.headerAutoFilter : Header에 filter를 적용할지 여부
 *			  excelOptions.excelInfo.service.websquare_param : 서비스 파라미터
 *			  excelOptions.excelInfo.rowNumVisible : 행 번호 표시 컬럼의 유무
 *			  excelOptions.excelInfo.service : 데이터 다운로드 시 사용할 서비스 - 전체 데이터 다운로드 시 설정
 *			  excelOptions.excelInfo.service.rep_col : 다운로드 할 컬럼을 변경한다.
 *			   - 코드 컬러의 경우 코드명을 다운로드할 경우 사용함
 *			  excelOptions.excelInfo.addInfo : 추가 정보 (배열)
 *			  excelOptions.excelInfo.service.websquare_url : 서비스 URL
 *			  excelOptions.excelInfo.addInfo.rowIndex : 내용을 표시할 행번호
 *			  excelOptions.excelInfo.addInfo.colIndex : 내용을 표시할 열번호
 *			  excelOptions.excelInfo.addInfo.rowSpan : 병합할 행의 수
 *			  excelOptions.excelInfo.addInfo.colSpan : 병합할 열의 수
 *			  excelOptions.excelInfo.addInfo.text : 표시할 내용
 *			  excelOptions.excelInfo.addInfo.textAlign : 표시할 내용의 정렬 방법 (left, center, right)
 *			  excelOptions.excelInfo.addInfo.fontSize : font size 설정 (예: "20px")
 *			  excelOptions.excelInfo.addInfo.fontName : font name 설정
 *			  excelOptions.excelInfo.addInfo.color : font color 설정 (예: "red")
 *			  excelOptions.excelInfo.addInfo.fontWeight : font weight 설정 (예: "bold")
 *			  excelOptions.excelInfo.addInfo.drawBorder : cell의 border 지정 (예: true)
 *			  excelOptions.excelInfo.addInfo.borderColor : cell의 border color를 지정 (예: "#FF0000", "red")
 *			  excelOptions.excelInfo.addInfo.borderWidth : cell의 border width 지정 ( "thin", "medium", "thick")
 *			  excelOptions.excelInfo.addInfo.wordWrap : cell의 줄 바꿈 기능 (예: "true")
 *			  excelOptions.excelInfo.addInfo.bgColor : cell의 배경 color 설정 (예: "red")
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.excel.downloadGridView
 */
com.excel.downloadGridView = function(compObj, excelOptions) {

	var options = com.excel._setCommon(excelOptions.common);

	//=========================================================
	// Excel Options 설정 (엑셀옵션, 스타일옵션)
	//=========================================================
	var excelInfo	= com.excel._setExcelInfo(excelOptions.excelInfo, excelOptions.style)

	//=========================================================
	// Excel Provider 설정 (dataList)
	//=========================================================
	var colList		= compObj.cellIdList;
	var dataProvider= com.excel._setDataProvider(colList, excelOptions.excelInfo);

	//=========================================================
	// 엑셀 추가 데이터 설정
	//=========================================================
	var addInfo		= com.excel._setAddInfo(excelOptions.excelInfo, colList, excelOptions.excelInfo.addInfo);

	//=========================================================
	// 컬럼 넓이와 해더 넓이가 틀릴 경우 보정
	//=========================================================
	com.excel._setGridHeadWidth(compObj);

	//=========================================================
	// Excel download 옵션 머지
	//=========================================================
	options = $.extend(
		options,
		excelInfo, 
		dataProvider
	);

	console.log({method : 'com.excel.downloadGridView', options : options});

	// 엑셀 다운로드 
	compObj.advancedExcelDownload(options, addInfo.infoArr);

};


