 *			  excelOptions.excelInfo.title : 제목
 *			  excelOptions.excelInfo.gridId : GridView 아이디
 *			  excelOptions.excelInfo.wframeId : GridView Frame ID
 *			   - 동일한 페이지에 있는 GridView의 경우 wframeid를 생략할 수 있다.
 *			  excelOptions.excelInfo.removeColumns : 다운로드 시 제거할 컬럼 (0,1,2)
 *			  excelOptions.excelInfo.columnOrder : 다운로드 컬럼 순서 설정(0,1,2,3 ... n) - - GridView 모든 컬럼에 대해 순서를 설정해야함
 *			  excelOptions.excelInfo.columnMove : 컬럼이동시 이동된 상태로 다운로드 유무
 *			  excelOptions.excelInfo.useSubTotal : SubTotal 출력 여부
 *			  excelOptions.excelInfo.service.websquare_param : 서비스 파라미터
 *			  excelOptions.excelInfo.service.rep_col : 다운로드 할 컬럼을 변경한다. - 코드 컬러의 경우 코드명을 다운로드할 경우 사용함
 *			  excelOptions.excelInfo.addInfo : 추가 정보 (배열)
 *			  excelOptions.excelInfo.addInfo.rowIndex : 내용을 표시할 행번호
 *			  excelOptions.excelInfo.addInfo.colIndex : 내용을 표시할 열번호
 *			  excelOptions.excelInfo.addInfo.rowSpan : 병합할 행의 수
 *			  excelOptions.excelInfo.addInfo.colSpan : 병합할 열의 수
 *			  excelOptions.excelInfo.addInfo.text : 표시할 내용
 *			  excelOptions.excelInfo.addInfo.textAlign : 표시할 내용의 정렬 방법 (left, center, right)
 *			  excelOptions.excelInfo.addInfo.fontSize : font size 설정 (예: "20px")
 *			  excelOptions.excelInfo.addInfo.fontName : font name 설정
 *			  excelOptions.excelInfo.addInfo.color : font color 설정 (예: "red")
 *			  excelOptions.excelInfo.addInfo.fontWeight : font weight 설정 (예: "bold")
 *			  excelOptions.excelInfo.addInfo.drawBorder : cell의 border 지정 (예: true)
 *			  excelOptions.excelInfo.addInfo.borderColor : cell의 border color를 지정 (예: "#FF0000", "red")
 *			  excelOptions.excelInfo.addInfo.borderWidth : cell의 border width 지정 ( "thin", "medium", "thick")
 *			  excelOptions.excelInfo.addInfo.wordWrap : cell의 줄 바꿈 기능 (예: "true")
 *			  excelOptions.excelInfo.addInfo.bgColor : cell의 배경 color 설정 (예: "red")
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.excel.downloadGridViewMulti
 */
com.excel.downloadGridViewMulti = function(excelOptions) {

	var frameID	= $p.getFrameId();
	var options = {
		common : com.excel._setCommon(excelOptions.common)
	};

	options.multipleSheet = true;
	options.excelInfo = [];

	//=========================================================
	// Excel Sheet 옵션 만들기
	//	- 멀티 다운로드는 GridView 갯수만큼 엑셀 Sheet가 생성됨.
	//=========================================================
	for (var i = 0 ; i < excelOptions.excelInfo.length ; i ++) {

		//=========================================================
		// grid ID는 Full id 찾기 (wframeId + gridId)
		//=========================================================
		if (com.util.isEmpty(excelOptions.excelInfo[i].wframeId)) {
			excelOptions.excelInfo[i].wframeId  = frameID;
		} else {
			excelOptions.excelInfo[i].wframeId  = frameID + '_' + excelOptions.excelInfo[i].wframeId;
		}

		var gridId 		= excelOptions.excelInfo[i].wframeId + '_' + excelOptions.excelInfo[i].gridId;
		var grdObj		= $p.getComponentById(gridId);

		//=========================================================
		// Excel Options
		//=========================================================
		var excelInfo	= com.excel._setExcelInfo(excelOptions.excelInfo[i], excelOptions.style)

		//=========================================================
		// Excel Provider (dataList)
		//=========================================================
		var dataProvider= com.excel._setDataProvider(grdObj.cellIdList, excelOptions.excelInfo[i]);

		//=========================================================
		// 추가 데이터 
		//=========================================================
		var addInfo		= com.excel._setAddInfo(excelOptions.excelInfo[i], grdObj.cellIdList, excelOptions.excelInfo[i].addInfo);

		//=========================================================
		// 컬럼 넓이와 해더 넓이가 틀릴 경우 보정
		//=========================================================
		com.excel._setGridHeadWidth(grdObj);

		//=========================================================
		// Excel 옵션 머지
		//=========================================================
		options.excelInfo.push($.extend(
			excelInfo, 
			dataProvider,
			addInfo
		));
	}

	// 엑셀 다운로드
	WebSquare.util.multipleExcelDownload( options );

};


/**
 * 함수명 	: com.excel._setCommon
 * 함수설명	: 엑셀 공통 옵션 설정
 * 				- 파일명, 공통옵션, 출력옵션
 * 파라미터	: common : 공통옵션 정보
 * 리턴		: 공통옵션
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.excel._setCommon = function(common) {

	var fileName	= ((com.util.isNotEmpty(common.fileName)) ? common.fileName : 'excel') + '_' + com.date.getServerDateTime('yyyyMMddHHmmss') + '.xlsx';
	var options		= $.extend(
		com.excel._getOptions('comm'),
		com.excel._getOptions('print'),
		common
	);

	options.onSuccessCallback = function() {
		if (common.callbackSuccess) {
			common.callbackSuccess();
		}
	};

	options.onFailureCallback = function() {

		// 메시지 출력
		var msgOption = {
			msgType		: 'error',
			msgTitle	: 'egov.message.title.web.com.error',
		    msgCode		: 'egov.message.error.web.com.error',
		};

		// 콜백 메시지
		com.message.openMessage(msgOption, common.callbackFail);
	};

	options.fileName = fileName;
	return options;
};


/**
 * 함수명 	: com.excel._setExcelInfo
 * 함수설명	: 엑셀 옵션 설정
 * 				- 파일명, 공통옵션, 출력옵션
 * 				- excelInfo.checkColId이 있을 경우 GridView의 체크한 데이터만 다운로드 함.
 * 파라미터	: excelInfo : 엑셀옵션
 * 			  style : 엑셀 다운로드 스타일
 * 리턴		: 엑셀옵션
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.excel._setExcelInfo = function(excelInfo, style) {

	// 엑셀 스타일 적용
	excelInfo.useStyle = com.util.isEmpty(excelInfo.useStyle) ? true : excelInfo.useStyle;

	// GridView의 체크한 데이터만 1차원 배열로 추출하여 dataHandler 옵션에 추가
	if (excelInfo.checkColId) {
		excelInfo.dataHandler = _getCheckData;
	}

	// 기본 옵션과 사용자 스타일 머지
	var options = $.extend(
		com.excel._getOptions('excel'),
		(excelInfo.useStyle && WebSquare.util.getBoolean(excelInfo.useStyle)) ? {} : com.excel._getOptions('style'),
		excelInfo,
		style
	);

	//=================================================================================
	// 시트명 규칙
	//	- 특수문자 제거 : / \ ? * : [ ]
	//	- 31자 문자 자름
	//=================================================================================
	var reg 			= /[\[\]\/?:*]/gi;
	var sheetName		= excelInfo.title.replace(reg, '');
	options.sheetName 	= sheetName.substr(0, 31);

	return options;


	/**
	 * 함수명 	: _getCheckData
	 * 함수설명	: GridView의 체크한 데이터만 배열로 조회한다. (내부함수)
	 * 				- displayFormat이 되어있는 text를 추가하기 위해 getCellDisplayData 함수를 이용함.
	 * 파라미터	: N/A
	 * 리턴		: 체크데이터 (1차원 배열)
	 * 작성일 	: 2022.05.16
	 * 작성자 	: Inswave Systems
	 */
	function _getCheckData() {

		var retData		= [];
		var chkIdx		= this.getCheckedIndex(excelInfo.checkColId);

		for (var i = 0 ; i < chkIdx.length ; i ++) {
			for (var j = 0 ; j < this.cellIdList.length ; j ++) {
				retData.push(this.getCellDisplayData(chkIdx[i], j));
			}
		}

		return retData;
	}
};


/**
 * 함수명 	: com.excel._setDataProvider
 * 함수설명	: Excel 데이터를 서버로 부터 다운로드하기 위해 Provider 옵션을 설정한다.
 * 파라미터	: colList : 컬럼 목록
 * 			  excelInfo : 엑셀  옵션 (excelInfo.service 사용)
 * 리턴		: 엑셀 Provider 정보
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.excel._setDataProvider = function(colList, excelInfo) {

	var options = {};

	//=========================================================
	// dataProvider를 이용하여 엑셀다운로 설정
	//=========================================================
	if (com.util.isNotEmpty(excelInfo.service)) {

		if (com.util.isNotEmpty(excelInfo.service.rep_col)) {
			for (var i = 0 ; i < colList.length ; i ++) {

				for (var j = 0 ; j < excelInfo.service.rep_col.length ; j ++) {

					var colTemp	= excelInfo.service.rep_col[j].split(':');

					if (colList[i] == colTemp[0]) {
						colList[i] = colTemp[1];
						break;
					}
				}
			}
		}

		//=========================================================
		// SSO 처리를 위해 Privider 서비스 URL에 SSO 정보 추가
		//=========================================================
		var crpId = gcm.data.getLocalStorage("CRYPTED_ID__");
		var userId = gcm.data.getLocalStorage("USER_ID__");
		if(excelInfo.service.websquare_url.indexOf("CRYPTED_ID__") == -1) {
			if (!com.util.isEmpty(crpId)) {
				excelInfo.service.websquare_url = excelInfo.service.websquare_url + "?CRYPTED_ID__=" + crpId + "&USER_ID__=" + userId;
			}
		}

		//=========================================================
		// dataProvider에 전송할 Parameter Data
		//	- websquare_url : 서비스 URL
		//	- websquare_param : 검색조건 파라미터
		//	- col_list : 컬럼 목록 (문자열)
		//=========================================================
		var excelParam	= {
			websquare_url 		: excelInfo.service.websquare_url,
			websquare_param		: excelInfo.service.websquare_param,
			col_list			: colList.join(',')
		};

		// Provider 옵션 추가
		options.providerRequestXml	= '<info><excelParam><![CDATA[' + JSON.stringify(excelParam) + ']]></excelParam></info>'
		options.dataProvider		= 'egov.nrs.file.provider.EgovNrsFileExcelWebsquareProvider';	
	}

	return options;

};


/**
 * 함수명 	: com.excel._setAddInfo
 * 함수설명	: 추가정보를 조회한다.
 * 파라미터	: excelInfo : 추가데이터 옵션 
 * 			  colList : 컬럼목록
 * 			  addInfo : 추가 정보
 * 리턴		: 추가정보 (배열)
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.excel._setAddInfo = function(excelInfo, colList, addInfo) {

	// 추가 정보 (제목은 기본)
	var infoArr 		= [];

	// 제목 추가
	var removeColCnt	= 0;
	if (com.util.isNotEmpty(excelInfo.removeColumns)) {
		removeColCnt	= excelInfo.removeColumns.split(',').length;
	}

	var colCnt 	= colList.length - removeColCnt;

	if (excelInfo.rowNumVisible) {
		colCnt++;
	}
	infoArr.push($.extend({
		colSpan 	: colCnt,
		text 		: excelInfo.title,
	}, 	com.excel._getOptions('title')));

	// 추가 컬럼
	if (com.util.isNotEmpty(addInfo)) {
		for (var i = 0 ; i < addInfo.length ; i ++) {
			infoArr.push(
				$.extend(
					com.excel._getOptions('addInfo'), 
					addInfo[i]
				)
			);
		}
	}

	return {infoArr : infoArr};
};


/**
 * 함수명 	: com.excel._setGridHeadWidth
 * 함수설명	: GridView의 해더의 넓이와 컬럼 넓이를 동일하게 변경한다.
 * 				- 2단 해더일 경우 해더 넓이와 컬럼 넓이가 틀릴 수 있다.
 * 파라미터	: gridComp : GridView 컴포넌트
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.excel._setGridHeadWidth = function(gridComp) {

	for (var item in gridComp.headerToBodyRelation) {
		var headId		= item;
		var headWidth	= gridComp.headerInfoHash2[headId].getAttribute('width');
		var colId		= gridComp.headerToBodyRelation[item];
		var colWidth	= gridComp.colWidthList[gridComp.bodyIdColIndexMap[colId]] + '';

		if (com.util.isNotEmpty(headWidth) && headWidth != colWidth) {

			console.log({head : headId, headWidth : headWidth, col : colId, colWidth : colWidth});
			gridComp.headerInfoHash2[headId].setAttribute('width', colWidth);
		}
	}
};

