/**
 * 파일 업로드 / 다운로드 관련 모듈
 *
 * @author Inswave Systems
 * @class file
 * @namespace com.file
 */
// =============================================================================

com.file = {};


/**
 * 함수명 	: com.file.getFileList
 * 함수설명	: 파일 객체를 FileList로 조회한다.
 *			  - 파일 업로드 할 수 있는 객체로 조회
 *			   - 사용 시 공통 개발에 문의 바람.
 * 파라미터	: file : 파일 데이터
 * 리턴		: FileList 객체
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.file.getFileList
 */
com.file.getFileList = function(file) {

    var dataTranster = new DataTransfer();

    dataTranster.items.add(file);
    return dataTranster.files;
};


/**
 * 함수명 	: com.file.getFileData
 * 함수설명	: UDC, dataList에서 파일 정보를 조회한다.
 *			  - UDC : udc_fileUpload_single
 *			  - dataList : udc_fileUpload_multi와 연동한 dataList
 * 파라미터	: dcObj : dataList 컴포넌트
 *			  compObjs : UDC 컴포넌트
 *			  - udc_fileUpload_single
 * 리턴		: 업로드 용 파일 데이터 (배열)
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.file.getFileData
 */
com.file.getFileData = function(dcObj, compObjs) {

	console.log({method : 'getFileData', dataObj : dcObj, compObj : compObjs});

	var fileData = [];

	if (com.util.isNotEmpty(dcObj)) {
		for (var i = 0 ; i < dcObj.getTotalRow() ; i ++) {
			if (com.util.isNotEmpty(dcObj.getCellData(i, '__file_data__'))) {
				fileData.push(dcObj.getCellData(i, '__file_data__'));
			}
		}
	}

	if (com.util.isNotEmpty(compObjs)) {
		for (var i = 0 ; i < compObjs.length ; i++) {
			var fileInfo = compObjs[i].getFile();

			if (com.util.isNotEmpty(fileInfo)) fileData.push(fileInfo);
		}
	}

	return fileData;
};



/**
 * 함수명 	: com.file.open
 * 함수설명	: 파일을 오픈한다.
 *			  - 파일 선택 후 콜백함수를 이용하여 바로 파일 업로드를 할 수 있다.
 * 파라미터	: options : 옵션정보
 *			  options.paramID : 서비스에서 받을 파라미터 ID
 *			  options.propCdExt
 *			  options.propCdMaxSize
 *			  - udc_fileUpload_single
 * 리턴		: 업로드 용 파일 데이터 (배열)
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.file.getFileData
 */
com.file.open = function(options, callbackFn) {

	console.log({method : 'com.file.open', options : options, callbackFn : callbackFn});

	var multiple = (options.isMulti == true) ? 'multiple' : '';

	//================================================================
	// 파일 엘리먼트 생성
	//================================================================
	var fileObj		= $('#__file__');
	var newFileObj 	= $('<input type="file" id="__file__" style="display: none;" ' + multiple + '>');

	if (fileObj.length != 0) fileObj.remove();

	$('body').append(newFileObj);

	newFileObj.click();


	//================================================================
	// 파일 선택 시 이벤트 발생 (change)
	//================================================================
	com.comp.addHtmlEvent(newFileObj[0], 'change', function() {

		if (this.files.length != 0) {

			var ext         = (options.propCdExt) ? com.util.getPropertyStringValue(options.propCdExt) : '';
			var maxSize     = (options.propCdMaxSize) ? parseInt(com.util.getPropertyStringValue(options.propCdMaxSize)) : 0;

			for (var i = 0 ; i < this.files.length ; i ++) {

				// 파일 확장자 체크
	            if (com.util.isNotEmpty(ext)) {
	            	var tExt    = this.files[0].name.split('.');
		            var fileExt	= (tExt.length > 1) ? tExt[tExt.length -1] : '';

	            	ext		= ext.toUpperCase();
	            	fileExt	= fileExt.toUpperCase();

	            	if (ext.indexOf(fileExt) == -1) {
	            		var msgOption = {
                            msgType     : 'info',
                            msgCode     : 'egov.message.info.web.udc.0004',
                            msgArg      : '(확장자 : ' + ext.toLowerCase() + ')',
                        };
	            		com.message.openMessage(msgOption);
	            		return;
	            	}
	            }

				// 파일 사이즈 체크
	            if (maxSize != 0) {
	            	if (maxSize < this.files[i].size) {
						var msgOption = {
							msgType     : 'info',
							msgCode     : 'egov.message.info.web.udc.0005',
							msgArg      : '(파일 사이즈 : ' + com.num.sizeUnit(maxSize) + ')',
						};
						com.message.openMessage(msgOption);
						return;
					}
	            }

			}

			var fileData = [{
	            name          : options.paramID, 
	            files         : this.files,
	            propCdExt     : ext,
	            propCdMaxSize : maxSize,
	        }];

			// 콜백함수로 전달.
			if (callbackFn) callbackFn(fileData);
		} 
	});
};



/**
 * 함수명 	: com.file.upload
 * 함수설명	: 파일 업로드 한다.
 *			  - 정보(JSON) + 파일
 * 파라미터	: url : 서비스 URL
 *			  paramData : 서비스에 전송할 데이터
 *			  fileData : 서비스에 전송할 파일 데이터
 *			  options : 파일 업로드 옵션
 *			  options.isProcessMsg : 파일 업로드 ‘진행바’ 노출 여부
 *			  callbackFn : 콜백 함수
 *			  callbackFn.success : 파일 업로드 성공 시 호출할 콜백 함수
 *			  callbackFn.fail : 파일 업로드 실패 시 호출할 콜백 함수
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.file.upload
 */
com.file.upload = function(url, paramData, fileData, options, callbackFn) {

	console.log({method : 'upload', paramData : paramData, fileData : fileData, options : options});

	var sendData	= paramData;
	var sendFile	= [];

	url = gcm.session.getCrptedUrl(url);

	// 파일객체에서 추출
	var fileSize	= 0;
	for (var i = 0 ; i < fileData.length ; i++) {

		var fileInfo	= fileData[i];
		var fileName	= fileInfo.name;

		sendFile.push({name : fileName, value : fileInfo.files});

		sendData[fileName + '_ext'] = fileInfo.propExt;
		sendData[fileName + '_size'] = fileInfo.propSize;

		for (var j = 0 ; j < fileInfo.files.length ; j ++) {
			fileSize	+= fileInfo.files[j].size;
		}
	}

	// 전체 사이즈 체크
	if (options && options.propCdMaxSize) {
		var totSize = parseInt(com.util.getPropertyStringValue(options.propCdTotMaxSize));

		if (fileSize > totSize) {
			var msgOption = {
	            msgType     : type,
	            msgCode     : 'egov.message.inf.web.udc.0005',
	            msgArg		: '파일 사이즈 : ' + com.num.sizeUnit(totSize)
	        };
	        com.message.openMessage(msgOption);
		}
	}

	if (options && options.propCdMaxCount) {
		var totCount = parseInt(com.util.getPropertyStringValue(options.propCdTotMaxCount));

		if (totCount < fileData.length) {
			var msgOption = {
	            msgType     : type,
	            msgCode     : 'egov.message.inf.web.udc.0005',
	            msgArg		: '파일 갯수 : ' + totCount
	        };
	        com.message.openMessage(msgOption);
		}

	}

	// 메세지 
	if (options && com.util.isNotEmpty(options.isProcessMsg)) {
		WebSquare.layer.showProcessMessage('처리 중입니다.');
	}

	// FILE UPLOAD FORM APPEND
	var form	= $(document.uploadFileForm__);
	form[0].action = url;

	form.empty();

	// 일반 데이터 적재
	for (var item in sendData) {
		form.append("<input type='hidden' name='" + item + "' value='" + sendData[item] + "'>");
	}

	// 파일데이터 생성
	for (var i = 0 ; i < sendFile.length ; i ++) {
		var fileObj	= $("<input type='file' name='" + sendFile[i].name + "'>");
		form.append(fileObj);
		fileObj[0].files = sendFile[i].value;
	}

	// 콜백 핸들러 처리
	gcm.CB_FUNCTION_FILEUPLOAD = callbackFn;

	form[0].submit();
};


/**
 * 함수명 	: com.file.download
 * 함수설명	: 파일을 다운로드 한다.
 * 파라미터	: url : 서비스 URL
 *			  paramData : 서비스에 전송할 데이터
 *			  fileName : 다운로드 파일명
 *			  options : 옵션 정보
 *			  options.isProcessMsg : 파일 다운로드 ‘진행바’ 노출 여부
 *			  callbackFn : 콜백 함수
 *			  callbackFn.success : 파일 다운로드 성공 시 호출할 콜백 함수
 *			  callbackFn.fail : 파일 다운로드 실패 시 호출할 콜백 함수
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.file.download
 */
com.file.download = function(url, paramData, fileName, options, callbackFn) {

	console.log({method : 'download', paramData : paramData, fileName : fileName, options : options});

	url = gcm.session.getCrptedUrl(url);

	var xhr = new XMLHttpRequest();

	xhr.onreadystatechange = function() {
		if (this.readyState == 4) {
			WebSquare.layer.hideProcessMessage();

			if (this.status == 200) {

				var link        = document.createElement('a');
                var url         = URL.createObjectURL(this.response);
                link.href       = url
                link.download   = fileName;

                link.click();

                window.URL.revokeObjectURL(url);

                $(link).remove();

				if (callbackFn && callbackFn.success) callbackFn.success(this.response, this);
			} else {
				var resData = {responseStatusCode 	: '500'};
				var tempObj	= {execptionCallbackFn 	: (callbackFn && callbackFn.fail) ? callbackFn.fail : null};

				gcm.sbm._callbackSubmitFunction (resData, tempObj);
			}
		}

	}

	if (options && options.isProcssMsg) WebSquare.layer.showProcessMessage('처리 중입니다.');

	xhr.open('POST', url, true);
	xhr.setRequestHeader('Content-Type', 'application/json;charset=UTF-8');
	xhr.responseType = 'blob';
	xhr.send(JSON.stringify(paramData));
};


/**
 * 함수명 	: com.file.remove
 * 함수설명	: 파일을 삭제 한다.
 * 파라미터	: url : 서비스 URL
 *			  paramData : 서비스에 전송할 데이터
 *			  options : 옵션 정보
 *			  options.isProcessMsg : 파일 삭제 ‘진행바’ 노출 여부
 *			  callbackFn : 콜백 함수
 *			  callbackFn.success : 파일 삭제 성공 시 호출할 콜백 함수
 *			  callbackFn.fail : 파일 삭제 실패 시 호출할 콜백 함수
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.file.remove
 */
com.file.remove = function(url, paramData, options, callbackFn) {

	console.log({method : 'remove', paramData : paramData, options : options});

	url = gcm.session.getCrptedUrl(url);

	if (options && options.isProcssMsg) WebSquare.layer.showProcessMessage('처리 중입니다.');

	$.ajax({
