				if (callbackFn && callbackFn.success) callbackFn.success(data, xhr);
			}
		}, 
		error : function(xhr, status) {
			WebSquare.layer.hideProcessMessage();

			var resData = {responseStatusCode : '500'};
			var tempObj	= {execptionCallbackFn : (callbackFn && callbackFn.fail) ? callbackFn.fail : null};

			gcm.sbm._callbackSubmitFunction(resData, tempObj);
		}
	});
};



