com.history = {};

/**
 * 함수명 	: com.history.getHistoryIndex
 * 함수설명	: 현재 History 위치를 리턴한다. 
 * 파라미터	: frameComp : frame 컴포넌트
 * 리턴     : History index
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.history.getHistoryIndex
 */
com.history.getHistoryIndex = function(frameComp) {

	var id		= frameComp.getID();
	var history	= gcm.HISTORY[id];

	for (var i = 0 ; i < history.length ; i ++) {
		if (history[i].pos) {
			return i;
		}
	}
	return null;
};


/**
 * 함수명 	: com.history.getHistory
 * 함수설명	: History 정보를 리턴한다. 
 * 파라미터	: frameComp : frame 컴포넌트
 * 			  idx : History index
 * 리턴     : History 정보
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.history.getHistory
 */
com.history.getHistory = function(frameComp, idx) {

	var id		= frameComp.getID();
	var history	= gcm.HISTORY[id];

	if (history.length == 0 || (history.length -1 < idx)) return;

	return history[idx];
};


/**
 * 함수명 	: com.history.add
 * 함수설명	: History 정보를 추가한다. 
 * 파라미터	: frameComp : frame 컴포넌트
 * 			  url : URL
 * 			  param : 파라미터
 * 리턴     : History index 
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.history.getHistory
 */
com.history.add = function(frameComp, url, param) {

	var id		= frameComp.getID();
	var history	= [];

	if (!gcm.HISTORY[id]) {
		gcm.HISTORY[id] = [];
	} 

	history	= gcm.HISTORY[id];

	history.push({
		url 	: url,
		param	: param,
	});

	for (var i = 0 ; i < history.length ; i ++) {
		if (i == history.length -1) {
			history[i].pos	= true;
		} else {
			history[i].pos	= false;
		}
	}

	frameComp.setSrc(url, com.win.frameParamOption(param));
	$(document).scrollTop(0);

	return history.length -1;
};


