/**
 * 함수명 	: com.history.move
 * 함수설명	: History 이동한다.
 * 파라미터	: frameComp : frame 컴포넌트
 * 			  idx : History index
 * 			  isRemove : 이동 index 이후 이력 삭제 여부 (true / false)
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.history.getHistory
 */
com.history.move = function(frameComp, idx, isRemove) {
	var id		= frameComp.getID();
	var history	= gcm.HISTORY[id];

	if (history.length == 0 || (history.length -1 < idx)) return;

	if (history[idx].pos) {
		return;
	} else {
		frameComp.setSrc(history[idx].url, com.win.frameParamOption(history[idx].param));

		// 이력 현재 위치 설정
		for (var i = 0 ; i < history.length ; i ++) {
			history[i].pos = false;
		}
		history[idx].pos = true;

		// 이후 이력 삭제 처리
		if (isRemove) {
			history.splice(idx+1, (history.length - (idx+1)))
		}
	}
};


/**
 * 함수명 	: com.history.back
 * 함수설명	: History 이전 이력 이동.
 * 파라미터	: frameComp : frame 컴포넌트
 * 			  isRemove : 이동 index 이후 이력 삭제 여부 (true / false)
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.history.getHistory
 */
com.history.back = function(frameComp, isRemove) {
	var id			= frameComp.getID();
	var history		= gcm.HISTORY[id];
	var historyPos	= -1;

	if (history.length == 0 ) return;

	for (var i = history.length -1 ; i > -1 ; i --) {
		if (history[i].pos) {
			if (i == 0) {
				return;
			} else {
				historyPos	= i-1;
			}
			break;
		}
	}

	if(gcm.SYS_ID == 'PM20') {
		$(document).scrollTop(0);
	}
	frameComp.setSrc(history[historyPos].url, com.win.frameParamOption(history[historyPos].param));

	// 이력 현재 위치 설정
	for (var i = 0 ; i < history.length ; i ++) {
		history[i].pos = false;
	}
	history[historyPos].pos = true;

	// 이후 이력 삭제 처리
	if (isRemove) {
		history.splice(historyPos + 1, (history.length - (historyPos+1)))
	}
};


/**
 * 함수명 	: com.history.forward
 * 함수설명	: History 이후 이력 이동.
 * 파라미터	: frameComp : frame 컴포넌트
 * 			  isRemove : 이동 index 이후 이력 삭제 여부 (true / false)
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.history.getHistory
 */
com.history.forward = function(frameComp, isRemove) {

	var id			= frameComp.getID();
	var history		= gcm.HISTORY[id];
	var historyBack	= {};
	var historyPos	= -1;

	if (history.length == 0 ) return;

	for (var i = 0 ; i < history.length ; i++) {
		if (history[i].pos) {

			if (i == history.length -1) {
				return;
			} else {
				historyPos	= i+1;
			}
			break;
		}
	}

	frameComp.setSrc(history[historyPos].url, com.win.frameParamOption(history[historyPos].param));

	// 이력 현재 위치 설정
	for (var i = 0 ; i < history.length ; i ++) {
		history[i].pos = false;
	}
	history[historyPos].pos = true;


	// 이후 이력 삭제 처리
	if (isRemove) {
		history.splice(historyPos + 1, (history.length - (historyPos+1)))
	}
};


