/**
 * 함수명 	: com.anySign._splitSignFileInit
 * 함수설명	: 분리서명 초기 설정
 * 파라미터	: signFileType : 분리서명 유형 (SINGLE, MULTI)
 * 			  fileData : 서명대상 파일 데이터
 * 			  signOptions : 서명 정보
 * 			  callbackFn : 서명 완료 후 호출할 콜백함수
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.anySign._splitSignFileInit = function(signFileType, fileData, signOptions, callbackFn) {

	console.log('_splitSignFileInit');

	//===========================================================================
	// 유효성 체크
	//===========================================================================
	var fileTemp	= fileData.nas_target_file_sub_path.split('.');

	if (fileTemp.length == 1) {
		console.error('파일확장자가 없습니다.');
		return false;
	}

	//===========================================================================
	// 옵션 설정 
	//===========================================================================
	var options	= $.extend({
		    signFileType			 : signFileType
		  , tmpIsCacheCert           : false       //캐시인증서사용여부     : 사용자입력금지 (대내:true, 대민-다중파일-혼합(비서명,서명)-서명파일전자서명시:true, 그외:false)
	      , tmpIsIdnForVid			 : false	   //본인인증 여부			: 사용자입력금지
		  , tmpSignedData            : ""          //SIGN데이타             : 사용자입력금지
	      , tmpVidData               : ""          //VID데이타              : 사용자입력금지
	      , tmpMultiSignID           : 0           //다중서명ID             : 사용자입력금지
	      , tmpFileCnt               : 0           //파일건수               : 사용자입력금지
	      , tmpFileDelimite          : "&"         //파일구분자             : 사용자입력금지
	      , tmpIsMixType             : false       //혼합유형여부           : 사용자입력금지 (true:혼합유형, false:단일유형)
	      , tmpMixSignSeq            : 0           //혼합서명회차           : 사용자입력금지
	      , tmpMixHashInfoMapNomal   : null        //혼합서명요청정보(일반) : 사용자입력금지
	      , tmpMixHashInfoMapSigned  : null        //혼합서명요청정보(서명) : 사용자입력금지
	      , tmpSaveDataNomal         : null        //저장결과(일반유형)     : 사용자입력금지
	      , tmpSaveDataSigned        : null        //저장결과(전자서명유형) : 사용자입력금지
	 }, signOptions);


	// 1차 ~ N차 서명 유형
	if (fileTemp[fileTemp.length -1] == 'sig') {
		options.signGubun = 2;
	} else {
		options.signGubun = 1;
	}

	// 캐시 여부 (대내:true, 대민-다중파일-혼합(비서명,서명)-서명파일전자서명시:true, 그외:false)
	if (com.util.isEmpty(options.isCache)) {
		options.tmpIsCacheCert = (gcm.SYS_ID == 'IM10') ? true : false;
	} else {
		options.tmpIsCacheCert = options.isCache;
	}

	// 본인인증 여부
	options.tmpIsIdnForVid	= (com.util.isEmpty(options.idnForVid)) ? false : true;

	// 인증서 기본값 설정
	if (!options.certGubun) {
		if (gcm.SYS_ID == 'IM10' || gcm.SYS_ID == 'ZI01') {
			options.certGubun = 'GPKI';
		} else if (gcm.SYS_ID == 'PM10' || gcm.SYS_ID == 'PM20' || gcm.SYS_ID == 'PM60') {
			options.certGubun = 'NPKI';
		}
	}

	//===========================================================================
	// 사인 취소 시 호출할 함수 등록 
	//===========================================================================
	if (com.util.isNotEmpty(options.cancelFuncName)) {
		gcm.ANYSIGN_CANCEL_FUNC_INFO = {
			scopeId 	: ($p.getFrame() && $p.getFrame().id) ? $p.getFrame().id : 'mf',
			funcName 	: options.cancelFuncName
		};
	} else {
		gcm.ANYSIGN_CANCEL_FUNC_INFO = {};
	}

	//===========================================================================
	// Submission 생성
	//===========================================================================
	var sbmOptions = {
    	"id" 			: '__SBM_COMMON__',
    	"action" 		: '',
    	"method" 		: 'post',
    	"mediatype" 	: 'application/json',
    	"mode" 			: 'synchronous',
    	"processMsg" 	: '$blank',
    };

	var sbmObj	= com.sbm.create(sbmOptions);

	var sysId	= gcm.SYS_ID.toLowerCase();
	var wasId	= fileData.nas_prop_key.split('.')[0];
	var singleUrl		= {
		hash 	: com.util.getPropertyStringValue(sysId + '.websquare.Property.anysign.split.file.hash.' + wasId + '.url'),
		merge 	: com.util.getPropertyStringValue(sysId + '.websquare.Property.anysign.split.file.merge.' + wasId + '.url'),
	};
	var multiUrl		= {
		hash 	: com.util.getPropertyStringValue(sysId + '.websquare.Property.anysign.split.file.multi.hash.' + wasId + '.url'),
		merge 	: com.util.getPropertyStringValue(sysId + '.websquare.Property.anysign.split.file.multi.merge.' + wasId + '.url'),
	};

	//===========================================================================
	// 분리서명 정보 리턴
	//===========================================================================
	return $.extend(options, {
		fileData		: fileData,						// 서명파일 데이터
		sbm				: {								// submission 정보 (파일해시, 파일머지)
			sbmObj : sbmObj, 
			url : ((signFileType == 'SINGLE') ? singleUrl : multiUrl)
		},	
		userCallbackFn 	: callbackFn,					// 사용자 콜백함수
		signCallbackFn	: {								// 분리서명 처리 시 콜백함수
			hash 		: (signFileType == 'SINGLE') ? com.anySign._splitSignSingle : com.anySign._splitSignHashSplit,
			hashSplit	: com.anySign._splitSignMulti,
			sign 		: com.anySign._splitSignMerge,
			merge 		: com.anySign._splitSignComplete
		}
	});
};


/**
 * 함수명 	: com.anySign._splitSignHash
 * 함수설명	: 분리서명 파일의 해시 정보 조회
 * 파라미터	: options : 분리서명 옵션
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.anySign._splitSignHash = function(options) {

	console.log('_splitSignHash');

	// 서비스 설정
	options.sbm.sbmObj.action 			= options.sbm.url.hash;
	options.sbm.sbmObj.userEventList	= [];
	options.sbm.sbmObj.userEventList.push(new WebSquare.Events.XmlEvent('xforms-submit-done', 'script', {handler : function(resData) {

		// 파일 해시 정보 hashInfoMap 설정
		options.hashInfoMap 			= resData.responseJSON.hashInfoMap;
		options.nasPropKey 				= options.fileData.nas_prop_key; 				//NAS경로프로퍼티키
		options.nasTargetFileSubPath 	= options.fileData.nas_target_file_sub_path; 	//대상파일의 NAS Sub경로(파일명포함)
		options.orgFileDelYn			= options.fileData.org_file_del_yn; 

		// 콜백함수 호출
		if (options.signFileType == 'SINGLE') {
			com.anySign._splitSignSingle(options);
		} else {
			com.anySign._splitSignHashSplit(options);
		}
	}}));

	// 서비스 실행
	com.sbm.executeExt(options.sbm.sbmObj, {websquare_param : options.fileData});
};


/**
 * 함수명 	: com.anySign._splitSignHashSplit
 * 함수설명	: 분리서명 서명 대상 분리(1차서명, N차 서명) 
 * 				- com.anySign.splitSignFileMulti 인 경우 사용
 * 파라미터	: options : 분리서명 옵션
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.anySign._splitSignHashSplit = function(options) {

	console.log('_splitSignHashSplit');

	//===========================================================================
	// 1. 멀티파일 혼합파일 분류 작업
    //===========================================================================
    //파일구분자
	options.tmpFileDelimite 	= options.hashInfoMap.delimite;

	//일반 파일
    var hashInfoMapNomal = {
		  delimite 		: options.hashInfoMap.delimite
		, nas_prop_key 	: options.hashInfoMap.nas_prop_key
		, total 		: 0
		, file_info 	: ''
		, file_hash 	: ''
		, nas_target_file_sub_path 	: ''
		, before_file_signed_data 	: ''
	};

	//서명 파일
	var hashInfoMapSigned = {
		  delimite 		: options.hashInfoMap.delimite
		, nas_prop_key 	: options.hashInfoMap.nas_prop_key
		, total 		: 0
		, file_info 	: ''
		, file_hash 	: ''
		, nas_target_file_sub_path 	: ''
		, before_file_signed_data 	: options.hashInfoMap.before_file_signed_data
	};  

    //대상파일하위경로, 파일해쉬정보, 파일기본정보 split
    var nasTargetFileSubPath	= options.hashInfoMap.nas_target_file_sub_path.split(options.tmpFileDelimite);
    var fileHash	 			= options.hashInfoMap.file_hash.split(options.tmpFileDelimite);
    var fileInfo	 			= options.hashInfoMap.file_info.split(options.tmpFileDelimite);

	//===========================================================================
	// 1차 서명, N차 서명 해시 정보 분리
	//	- 1차 서명 : hashInfoMapNomal
	//	- N차 서명 : hashInfoMapSigned
    //===========================================================================
    for (var i = 0 ; i < nasTargetFileSubPath.length ; i ++) {

    	var tempExt = nasTargetFileSubPath[i].split('.');

 	   if (tempExt[tempExt.length -1] == 'sig') { 
 		  //hashInfoMapSigned
 		  hashInfoMapSigned.nas_target_file_sub_path	+= nasTargetFileSubPath[i] + options.tmpFileDelimite;
 		  hashInfoMapSigned.file_info					+= fileInfo[i] + options.tmpFileDelimite;
 		  hashInfoMapSigned.file_hash					+= fileHash[i] + options.tmpFileDelimite;

 		  hashInfoMapSigned.total 						+= 1; 			//건수 업데이트
 	   } else {
 		  hashInfoMapNomal.nas_target_file_sub_path		+= nasTargetFileSubPath[i] + options.tmpFileDelimite;
 		  hashInfoMapNomal.file_info					+= fileInfo[i] + options.tmpFileDelimite;
 		  hashInfoMapNomal.file_hash					+= fileHash[i] + options.tmpFileDelimite;

 		  hashInfoMapNomal.total 						+= 1; 			//건수 업데이트
 	   }
    }

    //===========================================================================
    // 분리서명 대상 해시 정보 설정 및 실행
    //	- 혼합 : hashInfoMapNomal and hashInfoMapSigned
    //	- 단일 : hashInfoMapNomal or hashInfoMapSigned
    //===========================================================================
    if (hashInfoMapNomal.total > 0 && hashInfoMapSigned.total > 0) {

    	options.tmpIsMixType = true;

    	options.tmpMixSignSeq = 1; 								//혼합전자서명 1회
    	options.tmpMixHashInfoMapNomal  = hashInfoMapNomal;  	//혼합서명요청정보(일반)
    	options.tmpMixHashInfoMapSigned = hashInfoMapSigned; 	//혼합서명요청정보(서명)

    	options.signGubun 		= 1; 	
    	options.hashInfoMap		= hashInfoMapNomal;
    } else if (hashInfoMapNomal.total > 0) {
    	options.signGubun 		= 1; 	
    	options.hashInfoMap		= hashInfoMapNomal;

    } else if (hashInfoMapSigned.total > 0)  {
    	options.signGubun 		= 2; 	
    	options.hashInfoMap		= hashInfoMapSigned;

    } else {
    	return;
    }

    // 분리서명 실행
    com.anySign._splitSignMulti(options);
};

/**
 * 함수명 	: com.anySign._sortTargetFile
 * 함수설명	: 혼합파일인 경우 파일순서를 재 정리함
 *            - 일반,서명,일반,서명 : 이처럼 순서가 뒤섞이면 서명오류 발생함
 *            - 일반,일반,서명,서명 : 서명 파일들을 맨 뒤로 정렬토록 해야 서명 오류 해결됨
 * 파라미터	: pTargetFile : 파일정보
 * 작성일 	: 2024.02.19
 * 작성자 	: 오성식
 */
com.anySign._sortTargetFile = function (pTargetFile) {

	console.log('_sortTargetFile');

	var rNewTargetFile = "";

	var tmpTargetArr = pTargetFile.split("&");
	var tmpSignFile = "";

	for(i=0; i<tmpTargetArr.length; i++) {
		if(tmpTargetArr[i].split('.').pop()=='sig') {
			//서명파일인 경우
			if(com.util.isEmpty(tmpSignFile)) {
				tmpSignFile = tmpTargetArr[i];
			} else {
				tmpSignFile = tmpSignFile + "&" + tmpTargetArr[i];
			}
		} else {
			//일반파일인 경우
			if(com.util.isEmpty(rNewTargetFile)) {
				rNewTargetFile = tmpTargetArr[i];
			} else {
				rNewTargetFile = rNewTargetFile + "&" + tmpTargetArr[i];
			}
		}
	}

	//서명파일 정보 추가
	if(com.util.isEmpty(rNewTargetFile)) {
	    rNewTargetFile = tmpSignFile;
	} else {
		if(com.util.isNotEmpty(tmpSignFile)) {
		    rNewTargetFile = rNewTargetFile + "&" + tmpSignFile;
		}
	}

	return rNewTargetFile;
};


