/**
 * 함수명 	: com.anySign._splitSignMerge
 * 함수설명	: 분리서명 파일 머지 처리
 * 				- 콜백함수 : options.signCallback.complete
 * 파라미터	: options : 분리서명 옵션
 * 			  resData : 서명결과
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.anySign._splitSignMerge = function(options, resData) {

	console.log('_splitSignMerge');

	// fn_mergeSplitFileSign_callback
	// fn_mergeSplitMultiFileSign_callback

	//===========================================================================
    // 파일 머지 데이터 설정
    //===========================================================================
	var sendData				= options.fileData;

	sendData.file_signed_data 	= resData;												// 서명값
	sendData.vid_data			= (options.tmpIsIdnForVid) ? options.tmpVidData : '';	//VID정보
	sendData.idn 				= (options.tmpIsIdnForVid) ? options.idnForVid : '';	//idn : 신원확인정보 (주민등록번호 또는 사업자등록번호)
	sendData.nas_prop_key		= options.nasPropKey;									//NAS경로프로퍼티키
	sendData.org_file_del_yn	= options.orgFileDelYn;     							//서명 후 원본파일 삭제 여부

	// 대상파일의 NAS Sub경로(파일명포함)
	if (options.tmpIsMixType == true) {
		//혼합유형인 경우
        if(options.tmpMixSignSeq == 1) {
            //1회차 병합 요청인 경우
        	sendData.nas_target_file_sub_path = options.tmpMixHashInfoMapNomal.nas_target_file_sub_path		//대상파일의 NAS Sub경로(파일명포함)
        } else {
            //2회차 병합 요청인 경우
        	sendData.nas_target_file_sub_path = options.tmpMixHashInfoMapSigned.nas_target_file_sub_path		//대상파일의 NAS Sub경로(파일명포함)
        }
	} else {
		sendData.nas_target_file_sub_path = options.nasTargetFileSubPath; 	//대상파일의 NAS Sub경로(파일명포함)
	}

	options.sbm.sbmObj.action 			= options.sbm.url.merge;
	options.sbm.sbmObj.userEventList	= [];
	options.sbm.sbmObj.userEventList.push(new WebSquare.Events.XmlEvent('xforms-submit-done', 'script', {handler : function(resData) {

		// 콜백함수 호출
		com.anySign._splitSignComplete(options, resData.responseJSON);

	}}));

	//===========================================================================
    // 파일 머지 서비스 호출
    //===========================================================================
	com.sbm.executeExt(options.sbm.sbmObj, {websquare_param : sendData});
};


/**
 * 함수명 	: com.anySign._splitSignComplete
 * 함수설명	: 분리서명 파일 머지 완료
 * 				- 혼합서명
 * 					- 1차 서명완료 후 N차 서명 호출
 * 					- N차 서명완료 후 1차 + N차 서명결과 머지 후 사용자 콜백함수 호출
 * 				- 단일서명
 * 					- 콜백함수 호출
 * 				- 콜백함수 
 * 					- 혼합서명 : com.anySign._splitSignMulti, options.userCallback
 * 					- 단일서명 : options.userCallback
 * 파라미터	: options : 분리서명 옵션
 * 			  resData : 파일 머지 결과
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.anySign._splitSignComplete = function(options, resData) {

	console.log('_splitSignComplete');

	 if(options.tmpIsMixType) {
		 //혼합유형인 경우
		 if(options.tmpMixSignSeq == 1) {
			 //1회차 병합 완료인 경우
			 options.signGubun			= 2;
			 options.tmpSaveDataNomal 	= resData; 	//1차 저장정보 업데이트
			 options.tmpMixSignSeq 		+= 1; 		//혼합서명회차 업데이트

			 options.hashInfoMap	= options.tmpMixHashInfoMapSigned	// 인증대상 파일해시 정보
			 options.tmpIsCacheCert = true; 							// 2회차는 캐시 인증서 서명으로 진행함(2번 인증서창 호출 방지)

			 // N차 서명 실행
			 com.anySign._splitSignMulti(options);

		 } else {

			 //debugger;

			 //통합 저장정보
			 //var dataForFinal 	= options.tmpSaveDataNomal.signFileInfoMap.concat(resData.signFileInfoMap)
			 //if (com.util.isNotEmpty(options.userCallbackFn)) options.userCallbackFn({signFileInfoMap : dataForFinal}); 
			 //2회차 병합 완료인 경우
			 options.tmpSaveDataSigned = resData; //2차 저장정보 업데이트

			 //-----------------------------------------------------------
			 //처리결과 통합하기
			 //-----------------------------------------------------------
			 var dataForNomal = options.tmpSaveDataNomal; //일반파일 저장정보
			 var dataForSigned = options.tmpSaveDataSigned; //서명파일 저장정보

			 var iMapSize = dataForNomal.signFileInfoListMap.length + dataForSigned.signFileInfoListMap.length;
			 var dataForFinal = {
			         signFileInfoListMap : [
			             iMapSize
			         ]
			 };

			 dataForFinal.signFileInfoListMap = dataForNomal.signFileInfoListMap.concat(dataForSigned.signFileInfoListMap); //통합 저장정보

			 //-----------------------------------------------------------
			 //저장 CallBack함수 실행하기
			 //-----------------------------------------------------------
			 //options.saveCallBackFn(dataForFinal);
			 if (com.util.isNotEmpty(options.userCallbackFn)) options.userCallbackFn({signFileInfoMap : dataForFinal}); 


		 }
	 } else {
		 if (com.util.isNotEmpty(options.userCallbackFn)) options.userCallbackFn(resData); 
	 }
};


