/**
 * 함수명 	: com.anySign.fcmsFileSelectUpload
 * 함수설명	: 파일 선택 업로드
 * 파라미터	: folderPath : 폴더 경로
 * 		  	  options : 자동 업로드 옵션
 * 			  options.uploadSubPath : 업로드 서브 폴더 (서버)
 * 			  options.isSign : 서명여부
 * 			  options.certGubun : 인증서 구분 (NPKI2:(NPKI + RPKI)인증서목록, RPKI:RPKI인증서목록, GPKI:GPKI인증서목록, ALL:전체인증서목록)
 *			  callbackFn : 콜백함수
 *			  callbackFn.succ : 성공 콜백함수
 *			  callbackFn.fail : 실패 콜백함수
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.anySign.fcmsFileSelectUpload = function(folderPath, options, callbackFn) {

	console.log({method : 'fcmsFileSelectUpload', folderPath : folderPath, options : options});

	var fcmsOptions 	= com.anySign.getFcmsFileUploadOptions(options);	

	//=======================================================================
	// 서명 여부에 따른 파일 업로드 실행
	//=======================================================================
	if(fcmsOptions.isSign == true) {
        //PKI타입에 따른 인증서 선택창 표시 대상 목록 지정
		//NPKI:NPKI인증서목록, NPKI2:(NPKI + RPKI)인증서목록, RPKI:RPKI인증서목록, GPKI:GPKI인증서목록, ALL:전체인증서목록
        AnySign.setPkiType4Sign(fcmsOptions.certGubun);         
    }

	AnySign.SelectFile (folderPath, fcmsOptions.filterString, fcmsOptions.selectOptions, _uploadCallback);


	/**
	 * 함수명 	: _uploadCallback
	 * 함수설명	: 서명 후 파일 업로드 함수 (내부함수)
	 * 				anySign에서 서명완료 후 콜백하는 함수
	 * 파라미터	: filePath : 파일 경로
	 * 리턴		: N/A
	 * 작성일 	: 2022.05.16
	 * 작성자 	: Inswave Systems
	 */
	function _uploadCallback(filePath) {

		// 선택한 파일이 없는 경우 upload 를 시도하지 않는다. (취소 버튼 포함)
		if(filePath == null || filePath == "") {
	        return;
	    }

		if (options.isSign == true) {
			com.anySign._fcmsFileSignUpload(filePath, fcmsOptions, callbackFn);
		} else {
			com.anySign._fcmsFileUpload(filePath, fcmsOptions, callbackFn);
		}
	};
};


com.anySign.getFcmsFileUploadOptions = function (options) {

	var fcmsOptions	= $.extend({
		delimiter 		: '|',
		filterString	: '',
		selectOptions	: 2
	}, options);

	//=======================================================================
	// 인증서 기본값 설정
	// 	- IM10 : GPKI
	//	- PM10, PM20, PM60 : NPKI
	//=======================================================================
	if (gcm.SYS_ID == 'IM10' || gcm.SYS_ID == 'ZI01') {
		fcmsOptions.certGubun 	= 'GPKI';
		fcmsOptions.isCache		= (com.util.isNotEmpty(fcmsOptions.isCache) ? fcmsOptions.isCache : true);
	} else if (gcm.SYS_ID == 'PM10' || gcm.SYS_ID == 'PM20' || gcm.SYS_ID == 'PM60') {
		fcmsOptions.certGubun 	= 'NPKI';
		fcmsOptions.isCache		= false;
	}

	return fcmsOptions;
};


/**
 * 함수명 	: com.anySign._fcmsFileUpload
 * 함수설명	: 파일 업로드
 * 파라미터	: sysCd : 시스템(WAS) 코드
 * 			  filePath : 파일 경로 (멀티파일 '|' 구문자로 구분)
 * 			  fcmsAquery : 업로드 서브 폴더 (서버)
 * 			  callbackFn : 콜백함수
 * 			  callbackFn.succ : 성공 콜백함수
 *			  callbackFn.fail : 실패 콜백함수
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.anySign._fcmsFileUpload = function(filePath, fcmsOptions, callbackFn) {

	//=======================================================================
	// 업로드 성공 콜백 함수 재정의 (없을 경우 오류 발생)
	//=======================================================================
	var callbackSucc = function(data) {
		var file		= filePath.split('|');
		var result		= data.split('|');
		var sendData	= [];

		for (var i = 0 ; i < file.length ; i ++) {
			sendData.push({file : file[i], result : result[i]});
		}

		if (com.util.isFunction(callbackFn.succ)) {
			callbackFn.succ.apply(null, [sendData]);
		}
	};

	//=======================================================================
	// 업로드 실패 콜백 함수 재정의 (없을 경우 오류 발생)
	//=======================================================================
	var callbackFail = function(data) {
		if (com.util.isFunction(callbackFn.fail)) {
			callbackFn.fail.apply(null, [data]);
		}
	};

	//=======================================================================
	// anySign 파일 업로드 실행
	//=======================================================================
	var uploadUrl	= '/solution/AnySign/fcms/' + fcmsOptions.sysCd + 'AnySign4PCFileUpload.jsp';

	console.log(uploadUrl);

	AnySign.UploadFile (
		AnySign.mXgateAddress,
		uploadUrl,
		fcmsOptions.uploadSubPath, 		//서버업로드Sub경로
        AnySignProp.aHostNameForFcms,  	//aHostName
        AnySignProp.aPortForFcms,   	//aPort
        filePath, 						//업로드대상경로
        1048576, 						//1048576:성공 시 진행창을 닫는다.(오류 시는 닫지 않는다), 0:기본 옵션(완료후 진행창 유지함), 524288:진행창을 보이지 않는다.
        '', 							//aDescription
        callbackSucc, 					//업로드 성공시 수행할 CallBack함수
        callbackFail					//업로드 실패시 수행할 CallBack함수
	); 
};




/**
 * 함수명 	: com.anySign._fcmsFileSignUpload
 * 함수설명	: 서명 파일 업로드
 * 파라미터	: filePath : 파일 경로 (멀티파일 '|' 구문자로 구분)
 * 			  fcmsAquery : 업로드 서브 폴더 (서버)
 * 			  callbackFn : 콜백함수
 * 			  callbackFn.succ : 성공 콜백함수
 *			  callbackFn.fail : 실패 콜백함수
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.anySign._fcmsFileSignUpload = function(filePath, fcmsOptions, callbackFn) {

	/**
     * 함수명 	: sleep
     * 함수설명	: 지연처리를 위한 함수
     * 				- 단위 : 밀리세컨드 (1000:1초, 3000:3초)
     *        - 사유 : 부동산 스캔시 첨부파일 등록 > 삭제 > 재등록시 오류발생하는 문제 해결을 위한 스크립트 추가
     * 파라미터	: 지연처리하기 위한 시간
     * 리턴		: N/A
     * 작성일 	: 2023.12.14
     * 작성자 	: 오성식
     */
    function sleep(ms) {
      const wakeUpTime = Date.now() + ms;
      while (Date.now() < wakeUpTime) {}
    }

    sleep(1000); //부동산 스캔시 첨부파일 등록 > 삭제 > 재등록시 오류발생하는 문제 해결을 위한 스크립트 추가

	/**
     * 함수명 	: _selectSignCallback
     * 함수설명	: 서명 완료 후 콜백함수
     * 				- 결과코드가 '0' 일때 파일 업로드 실행
     * 파라미터	: result : 결과코드
     * 리턴		: N/A
     * 작성일 	: 2022.05.16
     * 작성자 	: Inswave Systems
     */
    function _selectSignCallback(result) {

    	if(com.util.isEmpty(result)) {
    		if (com.util.isFunction(callbackFn.fail)) {
        		callbackFn.fail.apply(this);
        	}
        } else {
        	com.anySign._fcmsFileUpload(filePathSigned.join(fcmsOptions.delimiter), fcmsOptions, callbackFn);
        }
    }

	//===========================================================================
    // 2. 서명대상파일 추가 및 서명파일명 만들기
    //===========================================================================
    var filePathSign 			= filePath.split("|"); 	//서명대상파일
    var filePathSigned 			= []; 					//서명파일용

    for(var i = 0; i < filePathSign.length; i ++) {

    	//서명파일명 만들기 (업로드대상 서명파일경로 생성하기)
    	if (filePathSign[i].indexOf('.sig') == -1) {
	    	filePathSigned.push(filePathSign[i] + '.sig');
    	} else {
    		filePathSigned.push(filePathSign[i]);
    	}
    }

    fcmsOptions.fileCount 	= filePathSign.length;

    //===========================================================================
    // 3. 서명실행하기
    //===========================================================================
    if (fcmsOptions.isCache) {
		//<SPLIT-SIGN-VER5>------------------------------
        if(AnySignProp.lastSignLocation==5010) {
            //금융인증서인 경우
            console.log("금융인증서[사용할 수 없는 유형인 경우] 입니다.");
            //alert("금융인증서로 이용 불가한 접근 입니다.\n\n사용자지원센터에 문의 바랍니다.");
            var msgOption = {
                    msgType     : 'complete',
                    msgCode     : 'egov.message.info.web.com.0017',
                };
            com.message.openMessage(msgOption);
            return;
        } else {
   		//</SPLIT-SIGN-VER5>------------------------------
            console.log("[★★SplitFileSignAPI★★] MultiFileSign_CacheCert");
        	MultiFileSign_CacheCert(
            		fcmsOptions.fileCount,              //aTotal        : 서명대상 파일건수
            		filePath + fcmsOptions.delimiter,  	//aSignFilePath : 서명대상파일정보(마지막에 Delimiter 붙여야함)
            		fcmsOptions.delimiter,              //aDelimiter    : 파일구분값
            		_selectSignCallback
            	);
   		//<SPLIT-SIGN-VER5>------------------------------
        }
		//</SPLIT-SIGN-VER5>------------------------------
    } else {
        console.log("[★★SplitFileSignAPI★★] MultiFileSign");
    	MultiFileSign(
    		fcmsOptions.fileCount,              //aTotal        : 서명대상 파일건수
    		filePath + fcmsOptions.delimiter,  	//aSignFilePath : 서명대상파일정보(마지막에 Delimiter 붙여야함)
			fcmsOptions.delimiter,              //aDelimiter    : 파일구분값
			_selectSignCallback
		);
    }

    //===========================================================================-
    // 4. 서명결과 파일업로드 실행하기(CallBack)
    //===========================================================================-
};


/**
 * 함수명 	: com.anySign.fcmsFileDownload
 * 함수설명	: 파일 다운로드
 * 파라미터	: fileInfo : 파일 정보
 * 			  fileInfo.inputFile			// test1.txt|test2.txt
 * 			  fileInfo.outputFilePath		// C:\\SCAN\\IROSTMP\\TEMP
 * 			  fileInfo.inputFileSubPath	    // downloadSubPath=/tmp2/
 * 		  	  options : 자동 업로드 옵션
 * 			  options.sysCd : 시스템 (WAS) 코드
 * 			  options.message : 다운로드 메시지
 * 			  options.opCd : 옵션코드
 *                - (65536)  : 저장할 파일 선택창을 띄우지 않는다. (기본값)(입력불가)
 *                - (524288) : 진행창을 보이지 않는다.
 *                - 그외의 옵션 값은 아직 사용 계획 없음
 *			  callbackFn : 콜백함수
 *			  callbackFn.succ : 성공 콜백함수
 *			  callbackFn.fail : 실패 콜백함수
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.anySign.fcmsFileDownload = function(fileInfo, options, callbackFn) {

	console.log({method : 'com.anySign.fcmsFileDownload', fileInfo : fileInfo, options : options});

	//============================================================================
	// 옵션 기본값 설정
	//============================================================================
	var downOptions	= $.extend({
		message : '파일을 다운로드 합니다.',
		downJsp : '/solution/AnySign/fcms/' + options.sysCd + 'AnySign4PCFileDownload.jsp',
		aOption : (options.opCd) ? (65536 + options.opCd) : 65536
	}, options);

	//debugger;
	console.log({method : 'com.anySign.fcmsFileDownload', downOptions : downOptions});

	//============================================================================
	// 유효성 체크
	//============================================================================
	if(com.util.isEmpty(fileInfo.inputFile)) {
		callbackFn.fail('NO_FILE');
		return;
	}

	if(com.util.isEmpty(fileInfo.outputFilePath)) {
		callbackFn.fail('NO_FILE');
		return;
	}

	//============================================================================
	// fcms 다운로드 함수 실행
	//============================================================================
	AnySign.DownloadFile (
		AnySign.mXgateAddress,                                   	//aXgateAddress   : Xgate 주소 정보
		downOptions.downJsp, 										//aPath           : 접속하려는 페이지의 URI
		fileInfo.inputFileSubPath,                                  //aQueryString    : 접속하려는 페이지에 전달할 Query String
		AnySignProp.aHostNameForFcms,                            	//aHostName       : 연결할 웹 서버 HostName
		AnySignProp.aPortForFcms,                                	//aPort           : 연결할 웹 서버 Port
		fileInfo.inputFile,                                         //aInputFilePath  : 다운로드 받을 서버의 파일 경로 또는 파일명 (다중 파일 입력 시 “|” 구분자를 사용한다.)
		fileInfo.outputFilePath,                                    //aOutputFilePath : 다운로드 받은 파일을 저장할 폴더 또는 파일 경로 (파일명 입력 시 입력한 파일명으로 저장하고, 다중 파일 입력 시 “|” 구분자를 사용한다.) (0x00020000 옵션인 경우 해당 파라미터 입력은 무시된다.)
		downOptions.aOption,                                        //aOption         : 옵션 설정 (조합하여 사용가능하며 사용하고자 하는 옵션 값을 더해 준다.) (저장할 파일 선택창을 띄우지 않고[65536] + 저장할 파일을 임시 폴더에 저장[131072] = 65536 + 131072 = 196608)
																	//		                      0x00000000 (0) : 기본 옵션
																	//		                      0x00010000 (65536) : 저장할 파일 선택창을 띄우지 않는다.
																	//		                      0x00020000 (131072) : 저장할 파일을 임시 폴더에 저장한다.
																	//		                      0x00040000 (262144) : 동일한 이름의 저장 파일이 있는 경우, 오류 처리 한다. (기본값은 덮어씀)
																	//		                      0x00080000 (524288) : 진행창을 보이지 않는다.
																	//		                      0x00100000 (1048576) : 성공 시 진행창을 닫는다. (오류 시는 닫지 않음)
																	//		                      0x00200000 (2097152) : 완료 시 진행창을 닫는다. (오류 발생 시도 닫음)
																	//		                      0x00400000 (4194304) : 오류 시 다음 파일 계속 진행한다.(기본값은 종료)
																	//		                      0x00800000 (8388608) : 오류 시 다음 파일 계속 진행할지 확인창을 띄운다.
		downOptions.message,                               			//aDescription    : 다운로드 진행창에 보일 설명문을 입력한다. (기본메시지 : “Download File”)
		callbackFn.succ,                                           	//aUserCallback   : 성공 시 처리할 유저 콜백 함수를 등록한다.
		callbackFn.fail                                             //aErrCallback    : 실패 시 처리할 에러 콜백 함수를 등록한다.
	);

};





