/**
 * 함수명 	: com.nppfs._addNppfs
 * 함수설명	: 컴포넌트에 가상키패드 속성을 설정한다.
 * 파라미터	: nppfsTheme : 가상키패드 종류
 *			   - default : PC 용
 *			   - mobile : 모바일
 *			  nppfsInfo : 가상키패드 대상 정보
 *			  nppfsInfo.keypadType : 가상키패드 유형
 *			   - alpha : 문자키패드
 *			   - num : 숫자키패드
 *			  nppfsInfo.compObj : 가상키패드 대상 컴포넌트
 *			  nppfsInfo.maxLength : 최대 자리수
 *		      nppfsInfo.keypadAction : 숫자형 전용 마우스입력기 동작방식
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.nppfs.setNppfsKeypad
 */
com.keyboard._setNppfsAttribute = function(nppfsTheme, nppfsInfo) {

	var nppfsComp	= nppfsInfo.compObj;
	var compOInfo	= {};

	if (nppfsInfo.compObj.options.pluginName == 'searchbox') {
		nppfsComp	= nppfsInfo.compObj.input;
	}

	if (nppfsComp.modelControl.dataCollectionRefInfo.dataComp != undefined) {
		compOInfo		= {
			compName 	: nppfsComp.modelControl.dataCollectionRefInfo.dataComp.org_id + '_' + nppfsComp.modelControl.dataCollectionRefInfo.key,
			dataMapId	: nppfsComp.modelControl.dataCollectionRefInfo.dataComp.org_id
		};
	} else {
		compOInfo		= {
			compName 	: nppfsComp.id,
			dataMapId	: null
		};
	}

	// 응용단의 변경로직을 최소화 하기위해 keypadAction 을 option으로 주지 않았을때는 기존과 동일하게 처리함
	if( nppfsInfo.keypadAction ){
		nppfsComp.render.setAttribute('data-keypad-action', nppfsInfo.keypadAction);
	}else{
		// 비밀번호일 경우 '1' 로 키패드가 설정되는데 키패드에서 선택한 숫자로 노출 시킴
		if (nppfsInfo.keypadType == 'num') {
			nppfsComp.render.setAttribute('data-keypad-action', 'number');
		}
	}

	// 컴포넌트 keydown 이벤트 발생 여부 (gcm >>> npPfsExtension의 formatter를 이용)
	if (nppfsInfo.keydownevent) {
		nppfsComp.render.setAttribute('nppfs-formatter-type', 'keydown');
	}

	nppfsComp.render.setAttribute('name', compOInfo.compName);
	nppfsComp.render.setAttribute('npkencrypt', 'on');
	nppfsComp.render.setAttribute('maxLength', nppfsInfo.maxLength);
	nppfsComp.render.setAttribute('data-keypad-type', nppfsInfo.keypadType);
	nppfsComp.render.setAttribute('data-keypad-theme', nppfsTheme);

	return compOInfo;
}


