com.util = {};


/**
 * 함수명 	: com.util.isJSON
 * 함수설명	: JSON 객체 여부를 판단한다.
 * 파라미터	: json : JSON 판단 값
 * 리턴		: Object형 : JSON 형식 true / false
 *			  String형 :  JSON.parse true / false
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.util.isJSON
 */
com.util.isJSON = function(json) {
    try {
        if (typeof json === "object") {
            try {
                if (com.util.isArray(json)) {
                    if (com.util.isPlainObject(json[0])) {
                        return true;
                    } else {
                        return false;
                    }
                } else {
                    if (com.util.isPlainObject(json)) {
                        return true;
                    } else {
                        return false;
                    }
                }
            } catch (ex) {
                return false;
            }
        } else if (typeof json === "string") {
            try {
                var jsonObj = JSON.parse(json);
                if (com.util.isArray(jsonObj)) {
                    if (com.util.isPlainObject(jsonObj[0])) {
                        return true;
                    } else {
                        return false;
                    }
                } else {
                    return true;
                }
            } catch (ex) {
                return false;
            }
        }
        return false;
    } catch (ex) {
        return false;
    }
};


/**
 * 함수명 	: com.util.isArray
 * 함수설명	: 배열 여부를 판단한다.
 * 파라미터	: array : 배열판단 값
 * 리턴		: true / false
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.util.isArray
 */
com.util.isArray = function(array) {
    try {
        if ((typeof array !== "undefined") && (array !== null) && (typeof array == "object")) {
            if (array.constructor.name && array.constructor.name.toLowerCase() == "array")
                return true;
            if (array.constructor && array.constructor == Array)
                return true;
        }
        return false;
    } catch (ex) {
        return false;
    }
};


