/**
 * 함수명 	: com.util.isXmlDoc
 * 함수설명	: XML Document 객체인지 여부를 검사한다.
 * 파라미터	: data : 판단 데이터
 * 리턴		: true / false
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.util.isXmlDoc
 */
com.util.isXmlDoc = function(data) {
    if (typeof data != 'object')
        return false;
    if ((typeof data.documentElement != 'undefined' && data.nodeType == 9)
            || (typeof data.documentElement == 'undefined' && data.nodeType == 1)) {
        return true;
    }
    return false;
};


/**
 * 함수명 	: com.util.getObjectType
 * 함수설명	: 객체의 typeof 값을 반환하며 typeof의 값이 object인 경우 array, json, xml, null로 체크하여 반환한다.
 * 파라미터	: obj : 판단 데이터
 * 리턴		: object : 객체
 * 			  array : 배열
 * 			  json : JSON 데이터
 * 			  null : 빈값
 * 			  xml : XML
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.util.getObjectType
 */
 com.util.getObjectType = function (obj) {
     var objType = typeof obj;

     if (objType !== "object") {
        return objType;
     } else if (com.util.isArray(obj)) {
        return "array";
     } else if (objType === "object" && (com.util.isJSON(obj) === false)) {
        return "object";
     } else if (com.util.isJSON(obj)) {
        return "json";
     } else if (obj === null) {
        return "null";
     } else {
        var tmpDoc = WebSquare.xml.parse("<data></data>");
        if (obj.constructor === tmpDoc.constructor || obj.constructor === tmpDoc.childNodes[0].constructor) {
            return "xml";
        } else {
            return objType;
        }
     }
 };


