/**
 * 함수명 	: com.util.jsonToQueryString
 * 함수설명	: json 데이터를 QueryString으로 변환한다.
 * 파라미터	: data : JSON 데이터
 * 			  chr : 연결문자열 (기본값 : &)
 * 리턴		: 연결문자열
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.util.jsonToQueryString
 */
com.util.jsonToQueryString = function(data, chr, isEncode) {

	var chr	= chr || '&';
	var isEncode = isEncode || false;

	// 인코딩은 추가해야 함.
	var temp	= [];
	for (var item in data) {

		if (isEncode) {
			temp.push(item + '=' + encodeURIComponent(data[item]));
		} else {
			temp.push(item + '=' + data[item]);
		}
	}


	return temp.join(chr);
};


