com.message	= {};


/**
 * 함수명 	: com.message.getMessage
 * 함수설명	: 메시지를 조회한다.
 * 파라미터	: msgCd : 메지지 코드 (프로퍼티 코드)
 *			  msgArgs : 메시지 치환값 (2개이상 치환할 경우 '^' 로 구분)
 * 리턴		: 메시지 값
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.message.getMessage
 */
com.message.getMessage = function(msgCd, msgArgs) {

	var result	= 'SYSTEM_ERROR';

	if (com.util.isEmpty(msgCd)) {
        return "";
    }

    if (com.util.isEmpty(msgArgs)) {
    	msgArgs = "";
    }

    gcm.data.getMessageValue(msgCd, msgArgs).done(function(resData) {
    	result	= resData.responseJSON.dataMap.nrs_message_value;
    });

    return result;
};


/**
 * 함수명 	: com.message.openMessage
 * 함수설명	: 메시지 팝업창을 오픈한다.
 * 파라미터	: options : 메시지 정보
 *			  options.messageType : 메시지 유형
 *			   -유형별 버튼
 *			     error : 확인
 *			     caution : 확인
 *			     complete : 확인
 *			     info : 확인
 *			     question_okcancel : 확인, 취소
 *			     question_yesnocancel : 예, 아니오, 취소
 *			     question_yesno : 예, 아니오
 *			  options.msgTitle : 메지지 제목 (프로퍼티 코드)
 *			  options.msgCode : 메지지 코드 (프로퍼티 코드)
 *			  options.msgArg : 메시지 치환값 (2개이상 치환할 경우 ',' 로 구분)
 *			  callbackFn : 메시지 팝업 창에서 확인, 취소, 예, 아니오, 취소 버튼 클릭 시 호출하는 콜백함수
 *			   - 콜백함수 전달 정보 
 *			      {
 *			  		btnType: "confirm",   	     // confirm (확인), cancel (취소), yes (예), no (아니오)
 *			        class: "class egov.nrs.message.vo.EgovNrsMessageBaseVo",
 *			  		nrsMessageArgs: "",
 *			  		nrsMessageCallBackFn: "",
 *			  		nrsMessageCd: "egov.message.error.web.com.error",
 *			  		nrsMessagePopupYn: "",
 *			  		nrsMessageRtnUri: "",
 *			  		nrsMessageTitle: "에러",
 *			  		nrsMessageType: "error",
 *			  		nrsMessageValue: "에러가 발생했습니다."
 *			     }
 *			  * 서버 메지가 없을 경우 btnType 만 파라미터로 전달
 *			   :
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.message.openMessage
 */
com.message.openMessage = function(options, callbackFn) {

	console.log({method : 'com.message.openMessage', options : options});
	// lastFocus 함수 실행 중지
	window.mMssageOpen		= true;
    window.mLastFocusStop	= true;

	var msgTitle = com.message.getMessage(options.msgTitle, options.msgTitleArg);
	var msgValue = com.message.getMessage(options.msgCode, options.msgArg);

	try {
		if (msgTitle != 'SYSTEM_ERROR' && msgValue != 'SYSTEM_ERROR') {
			var msgOption	= {
				messageType 	: options.msgType,
				messageTitle 	: msgTitle,
				message			: msgValue,
				messageAlign	: options.msgAlign || 'center',
				closeFocusID	: options.closeFocusID,
				callerId		: (options.callerId) ? options.callerId : (($p.getFrame()) ? $p.getFrame().id : '')
			};

			// 개인화 메시지 저장여부 체크
			if (gcm.SYS_ID == 'IM10' && options.msgCode && options.msgCode.indexOf('.user.') != -1) {
				var isSave	= gcm.data.checkMessageIndivid(options.msgCode);

				msgOption.individYn = true;
				msgOption.individMessageCd = options.msgCode;

				if (isSave) {
					window.mMssageOpen		= false;
				    window.mLastFocusStop	= false;

					callbackFn({btnType : 'comfirm'});
				} else {
					com.message._openMessage(msgOption, callbackFn);
				}
			} else {
				msgOption.individYn = false;
				com.message._openMessage(msgOption, callbackFn);
			}
		}
	} catch(ex) {
		window.mMssageOpen		= false;
	    window.mLastFocusStop	= false;

		console.log(ex);
	}
};


