/**
 * 함수명 	: com.message._openMessage
 * 함수설명	: 메시지 팝업창을 오픈한다.
 * 파라미터	: msgOption : 메시지 정보
 *			  msgOption.popId : 팝업아이디
 *			  msgOption.message : 메시지
 *			  msgOption.messageType : 메시지 유형
 *			  msgOption.messageData : 메시지 데이터
 *			  callbackFn : 콜백함수
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.message.openMessagePms
 */
com.message._openMessage = function(msgOption, callbackFn) {

	window.mMssageOpen		= true;
    window.mLastFocusStop	= true;

    try {

		// 시스템별 메세지 경로가 틀림.	
		var messagePath = {
			IM10 : '/ui/im10/com/message/Im10ComMessageIndi.xml',
			PM10 : '/ui/pm10/com/message/Pm10ComMessageIndi.xml',
			PM20 : '/ui/pm20/com/message/Pm20ComMessageIndi.xml',
			PM60 : '/ui/pm60/com/message/Pm60ComMessageIndi.xml',
			EM40 : '/ui/em40/com/message/Em40ComMessageIndi.xml',
			SM30 : '/ui/sm30/com/message/Sm30ComMessageIndi.xml',
			ZI01 : '/ui/zi01/com/message/zi10ComMessageIndi.xml',
		};

		if (com.util.isEmpty(msgOption.callerId)) {
			msgOption.callerId=  document.activeElement.id;
		}

		var focusInfo	= (com.util.isEmpty(window.name)) ? window.focusInfo.main : window.focusInfo.name;
		var url			= messagePath[gcm.SYS_ID];
		var popId 		= (msgOption.popId) ? msgOption.popId : 'message_popup' + com.num.random();
		var options 	= {};
		var lastFocus	= (focusInfo) ? focusInfo.last : '';

		var data 		= {
	    	id				: popId,
	        message			: msgOption.message || '',
	        messageType		: msgOption.messageType || 'info',
	        messageData		: msgOption.messageData || '',
	        messageAlign	: msgOption.messageAlign,
	        individYn 		: msgOption.individYn,
			individMessageCd: msgOption.individMessageCd,
			closeFocusID	: (msgOption.closeFocusID) ? msgOption.closeFocusID : lastFocus,
			callerId		: (msgOption.callerId) ? msgOption.callerId : '',
		};

		// 메시지 조사 처리
		data.message = com.str.replaceJosa(data.message);

		// 시스템별 메시지 options
		if (gcm.SYS_ID == 'IM10' || gcm.SYS_ID == 'ZI01') {
			options.className 	= 'no_header';
			options.width		= 500;
			options.height		= 266;

		} else if (gcm.SYS_ID == 'PM10') {
			options.className 	= 'no_header';
			options.width		= 400;
			options.height		= 230;

		} else if (gcm.SYS_ID == 'PM20') {
			options.className 	= 'confirm';
			options.width		= 450;
			options.height		= 266;

		} else if (gcm.SYS_ID == 'PM60') {
			options.className 	= 'no_header';
			options.width		= 400;
			options.height		= 230;

		} else if (gcm.SYS_ID == 'SM30') {
			options.className 	= 'no_header';
			options.width		= 450;
			options.height		= 266;

		} else if (gcm.SYS_ID == 'EM40') {
			options.className 	= 'no_header';
			options.width		= 450;
			options.height		= 266;

		}

	    options.left		= (document.body.offsetWidth - options.width) / 2 + $(document).scrollLeft();
	    options.top			= (window.innerHeight - options.height) / 2 + $(document).scrollTop();

	    if (com.util.isNotEmpty(callbackFn)) {
		    if (com.util.isFunction(callbackFn)) {
				var callbackId 		= $p.id +  "__close_callback_Func__" + new Date().getTime();

		        gcm.CB_FUNCTION_MANAGER["cbFuncSave"][callbackId] = callbackFn;
		        data.callbackId = callbackId;

		        delete callbackFn;
		    } else {
				console.log('콜백함수가 함수형이 아닙니다. 함수형으로 설정해 주세요.');
			}
	    }

	    // FloatingLayer가 오픈되어 있는 경우 Z-INDEX auto로
	    com.comp.setOpenFloating('Z-INDEX', 'BEFORE');

	    var options = {
	        id			: popId,
	        popupName	: msgOption.messageTitle || '메시지 알림',
	        type		: "wframePopup",
	        modal		: true,
	        top			: options.top + 'px',
	        left		: options.left + 'px',
	        width		: options.width + 'px',
	        height		: options.height + 'px',
	        className 	: options.className,
	        useMaximize	: false,
	        useModalStack 	: true,
	        dataObject	: com.win.frameParamOption(data).dataObject
	    };

	    $p.openPopup(url, options);
    } catch(ex) {
    	window.mMssageOpen		= false;
	    window.mLastFocusStop	= false;
    }
};


/**
 * 함수명 	: com.message.closeMessage
 * 함수설명	: 메시지 팝업창을 닫는다.
 * 				- 포커스 ID가 있는 경우 닫고 포커스 이동
 * 					: IM10 일 경우 메시지 창이 여러개 있는 경우 다음 메시지로 포커스 이동함.
 * 				- 콜백함수이 있는 경우 호출한다.
 * 파라미터	: resultData : 전송 데이터 (콜백함수에 파라미터로 전달)
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 */
com.message.closeMessage = function(resultData) {

	window.mMssageOpen		= false;
    window.mLastFocusStop	= false;

    console.log({method : 'closeMessage', result : resultData});

	var callbackId	= com.page.getParameter('callbackId');
	var callerId	= com.page.getParameter('callerId');
	var focusId		= com.page.getParameter('closeFocusID');
	var pid			= $p.getPopupId();
	var callbackFn	= null;

	$p.closePopup(pid);

	// FloatingLayer가 오픈되어 있는 경우 Z-INDEX 원복
    com.comp.setOpenFloating('Z-INDEX', 'AFTER');

	if (gcm.SYS_ID == 'IM10') {

		// blur 이벤트에서 메시지 창을 뜨우면 blur 컴포넌트로 포커스가 이동되어 메시지 창 닫고 다른 컴포넌트로 포커스 이동 시 또 blur 이벤트가 발생하게 됨 
		//  - closeFocusID 옵션을 NO로 하면 포커스를 이동 시키지 않음 (창 닫고 다른 컴포넌트 이동 시 blur 이벤트가 발생하지 않음)
		if (focusId == 'NO') {
			_callback();
			return;
		}

		// 마지막 창에 포커스 주기
		for (var i = w2popup_singleton.popupList.length -1 ; i > -1 ; i --) {
			if (w2popup_singleton.popupList[i].id != pid) {

				if (w2popup_singleton.popupList[i].id.indexOf('message_popup') != -1) {
					window[w2popup_singleton.popupList[i].popupWin.frame.scope.scwin.last_focus].focus();

					_callback();
					return;
    			} else {

    				im10.focus.setFocusFrame(w2popup_singleton.popupList[i].id);
    				_callback();
    				return;
    			}
			} 
		}

		if (com.util.isNotEmpty(focusId)) {

			try {
				var focusObj	= im10.util.getComponentHtmlId(focusId);

				if (focusObj) {
					im10.focus.setFocus(focusObj);
				}
			} catch(ex) {
				console.log(ex);
			}
		} else {
			if (com.util.isEmpty(window.name)) {
				im10.focus.setFocusFrame('main');
			} else {
				im10.focus.setFocusFrame($p.parent().com.win.getPopupOrgId());
			}
		}
	} else {
		var focusObj	= $p.getComponentById(focusId);

		if (focusObj) {
    		$(focusObj.render).attr('tabindex', '0');
    		focusObj.focus();
		}
	} 

	_callback();


	function _callback() {
		// Callback 함수 실행
		if (com.util.isNotEmpty(callbackId)) {
			callbackFn = gcm.CB_FUNCTION_MANAGER["cbFuncSave"][callbackId];

	        if (callbackFn) {
	        	// $p.closePopup 완료 전 콜백함수에서 페이지 이동 시 문제가 발생함.
	        	setTimeout(function() {
	        		callbackFn(resultData);
	        		delete gcm.CB_FUNCTION_MANAGER["cbFuncSave"][callbackId];
	        	}, 100);
	        }
		}
	}
};


