 */
com.message.isOpenMessage = function() {

	console.log({method : 'isOpenMessage', isOPen : window.mMssageOpen});

	if (com.util.isEmpty(window.mMssageOpen)) return false;

	if (window.mMssageOpen == false) {
		for (var i = 0 ; i < w2popup_singleton.popupList.length; i ++) {

			var popId	= w2popup_singleton.popupList[i].id;

			if (popId.indexOf('message_popup') != -1 || popId.indexOf('SYSTEM_ERROR_POPUP') != -1) {
