com.num = {};


/**
 * 함수명 	: com.num.round
 * 함수설명	: 숫자를 반올림 한다.
 * 파라미터	: value : 숫자 값
 *			  point : 반올림할 자리수 (없으면 정수 반환)
 * 리턴		: 반올림 숫자 값
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.num.round
 */
com.num.round = function(value, point) {
    var num = 1;
    if (typeof point !== "undefined") {
        num = Math.pow(10, point);
    }

    return Math.round(Number(value) * num) / num;
};


/**
 * 함수명 	: com.num.floor
 * 함수설명	: 숫자를 내림 한다.
 * 파라미터	: value : 숫자 값
 *			  point : 내림할 자리수 (없으면 정수 반환)
 * 리턴		: 내림 숫자 값
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.num.floor
 */
com.num.floor = function(value, point) {
    var num = 1;
    if (typeof point !== "undefined") {
        num = Math.pow(10, point);
    }

    return Math.floor(Number(value) * num) / num;
};


/**
 * 함수명 	: com.num.ceil
 * 함수설명	: 숫자를 올림 한다.
 * 파라미터	: value : 숫자 값
 *			  point : 내림할 자리수 (없으면 정수 반환)
 * 리턴		: 올림 숫자값
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.num.ceil
 */
com.num.ceil = function(value, point) {
    var num = 1;
    if (typeof point !== "undefined") {
        num = Math.pow(10, point);
