/**
 * 함수명 	: com.num.formatMoney
 * 함수설명	: 숫자를 통화 포맷으로 처리한다. (천단위 콤마 적용)
 * 파라미터	: value : 입력 숫자
 *			  tpye : 추가 문자
 *			   - plusZero : 0 마지막 추가
 *			   - dollar : $ 추가
 *			   - won : 원 마지막 추가
 * 리턴		: 천단위 표기한 문자
 *			   - type의 값이 있을 경우 type 문자 포함 시킴
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.num.formatMoney
 */
com.num.formatMoney = function (value, type) {
    var amount;

    if (type == "plusZero") {
        amount = new String(value) + "0";
    } else {
        amount = new String(value);
    }

    amount = amount.split(".");

    var amount1 = amount[0].split("").reverse();
    var amount2 = amount[1];

    var output = "";
    for (var i = 0; i <= amount1.length - 1; i++) {
        output = amount1[i] + output;
        if ((i + 1) % 3 == 0 && (amount1.length - 1) !== i)
            output = ',' + output;
    }

    if (type == "dollar") {
        if (!amount2) {
            output = "$ " + output;
        } else {
            output = "$ " + output + "." + amount2;
        }
    } else if (type == "won") {
        if (!amount2) {
            output = output + "원";
        } else {
            output = output + "." + amount2 + "원";
        }
    } else {
        if (!amount2) {
            output = output;
        } else {
            output = output + "." + amount2;
        }
    }

    return output;
};


