 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.num.random
 */
com.num.random	= function() {

	var t1 = new Date();

	// IE11에서는 msCrypto를 사용해야됨.
	var array 	= new Uint32Array(1);
	var random	= (window.crypto) ? window.crypto.getRandomValues(array) : window.msCrypto.getRandomValues(array);
	var retVal	= (t1.getTime() + random[0] + '').substr(0, 17);

	//return (Math.random() * 16).toString().replace(".","");

	return retVal;

};


/**
 * 함수명 	: com.num.sizeUnit
 * 함수설명	: 숫자를 단위를 설정한다. (KB, MB)
 * 파라미터	: size : 숫자
