 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.message.openMessagePms
 */
com.num.sizeUnit	= function(size) {

	size		 = parseInt(size);
	var sizeUnit = '';

    if (size / (1024 * 1024) > 1.0) {
    	sizeUnit    = com.num.formatNumber(com.num.round((size) / (1024 * 1024), 1)) + 'MB';
    } else if (size / (1024) > 1.0) {
    	sizeUnit    = com.num.formatNumber(com.num.round((size) / (1024), 1)) + 'KB';
    } else {
    	sizeUnit    = com.num.formatNumber(size);
    }

    return sizeUnit;
};



