com.str = {};


/**
 * 함수명 	: com.str.serialize
 * 함수설명	: XML, JSON 객체를 String 타입으로 반환한다.
 * 파라미터	: object : JSON, XML 객체
 *			  replacer : 치환할 문자열
 *			  space : 여백 수
 * 리턴		: 직열화 문자열
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.str.serialize
 */
com.str.serialize = function (object, replacer, space) {
    if (typeof object === 'string') {
        return object;
    } else if (com.util.isJSON(object)) {
        return JSON.stringify(object, replacer, space);
    } else if (com.util.isXmlDoc(object)) {
        return WebSquare.xml.serialize(object);
    } else {
        return object;
    }
};


/**
 * 함수명 	: com.str.lpad
 * 함수설명	: 문자열 좌측 길이만큼 문자를 채운다.
 * 파라미터	: str : 문자열
 *			  length : 총 문자열 길이 (채워을 때 최종 길이)
 *			  char : 채울 문자
 * 리턴		: 문자열 
 *			   - char의 길이가 length 보다 클 경우 '' 리턴
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.str.lpad
 */
com.str.lpad = function(str, length, char) {
    if (typeof str === "number") {
        str = str.toString();
    }

    if (char.length > length) {
        console.log("오류 : 채우고자 하는 문자열이 요청 길이보다 큽니다");
        return str + "";
    }

    while (str.length < length) {
        str = char + str;
    }

    str = str.length >= length ? str.substring(0, length) : str;
    return str;
};


/**
 * 함수명 	: com.str.rpad
 * 함수설명	: 문자열 우측 길이만큼 문자를 채운다.
 * 파라미터	: str : 문자열
 *			  length : 총 문자열 길이 (채워을 때 최종 길이)
 *			  char : 채울 문자
 * 리턴		: 문자열 
 *			   - char의 길이가 length 보다 클 경우 '' 리턴
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.str.rpad
 */
com.str.rpad = function(str, length, char) {
    if (char.length > length) {
        console.log("오류 : 채우고자 하는 문자열이 요청 길이보다 큽니다");
        return str + "";
    }
    while (str.length < length)
        str += char;
    str = str.length >= length ? str.substring(0, length) : str;
    return str;
};


