/**
 * 함수명 	: com.str.formatPhone
 * 함수설명	: 문자열에 전화번호 형식 Formatter를 적용하여 반환한다.
 *			   - xx-xxxx-xxxx, xxxx-xxx-xxxx, xxx-xxxx-xxxx, xxx-xxx-xxxx
 * 파라미터	: str : 전화번호, 휴대폰번호
 * 리턴		: 포맷팅된 전화번호 (전화번호, 휴대폰번호)
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.str.formatPhone
 */
com.str.formatPhone = function (str) {
      try {
          str = str.replace(/\s+/g,"");
          var commCdList = ["0505", "0502"]; // 4자리 국번 ,예외가 되는 국번 확인
          var commCdNum = str.substr(0,4); // 국번 4자리 확인
          if(commCdList.indexOf(commCdNum) >-1){ //국번이 0505 인경우
              return str.replace(/^(01[0136789]{1}|02|0[3-9]{1}[0-9]{1}[0-9]{1})-?([*0-9]{3,4})-?([0-9]{4})$/,"$1-$2-$3");
          }else if(str.length <=11){
              return str.replace(/^(01[0136789]{1}|02|0[3-9]{1}[0-9]{1})-?([*0-9]{3,4})-?([0-9]{4})$/,"$1-$2-$3");
          }else{
              return str;
          }
      } catch (ex) {
          return str;
      }
};


