/**
 * 함수명 	: com.str.isFinalConsonant
 * 함수설명	: 한글의 마직막 글자의 받침 존재 여부를 판단한다
 * 파라미터	: str : 문자열
 * 리턴		: 받침있음 : true, 받침없음 : false
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.str.isFinalConsonant
 */
com.str.isFinalConsonant = function (str) {
    var code = str.charCodeAt(str.length - 1);
    if ((code < 44032) || (code > 55197)) {
        return false;
    }
    if ((code - 16) % 28 == 0) {
        return false;
    }
    return true;
};


