};


/**
 * 함수명 	: com.str.replaceRegExp
 * 함수설명	: 표현식에 해당하는 문자를 치환한다. (표현식)
 *			   - multiSpace : 여러공백문자 (2 ~ 99)
 * 파라미터	: type : 표현식 유형
 *			   - multiSpace : 여러공백문자 (2 ~ 99)
 *			  str : 문자열
 *			  repStr : 치환 문자열
 * 리턴		: 치환 문자열
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.str.replaceRegExp
 */
com.str.replaceRegExp = function( type, str, repStr ){

	var regExp	= null;

	if (type == 'multiSpace') {
		// 연속된 공백문자 변경
		regExp	= / {2,99}/g;
		return str.replace(regExp, repStr);
	}
};


com.str.replaceJosa = function(input) {
    var josa 		= ["은(는)", "이(가)", "을(를)", "와(과)", "(으)로"];
    var iJosaExist 	= 0;
    var pos 		= 0;
    var lastCh 		= '';
    var jongSung 	= 0;

    while(true){
        iJosaExist = 0;
        for(var i = 0; i < josa.length; i++){
            pos = input.indexOf(josa[i]);
            if(pos > 0){
                iJosaExist = 1;
                jongSung = 0;
                lastCh = input.charAt(pos-1);
                //"]' )" 문자는 lastCh에서 skip 함
                var j = 0;
                //console.log("i = " + i + " " + input);
                while(true){
                    if(lastCh == ']' || lastCh == '\'' || lastCh == ' ' || lastCh == ')'){
                        lastCh = input.charAt(pos-1 - j++);
                    }else{
                        break;
                    }
                }
                //console.log("lastCh = " + lastCh);

                const unicode = lastCh.charCodeAt(0);
                //한글이고, 종성이 존재하면
                if(unicode >= 0xAC00 && unicode <= 0xD7A3 && (unicode - 0xAC00) % 28 != 0){
                    jongSung = 1;
                }
                //lastCh 가 숫자 '0', '1', '3', '6', '7', '8' 은 종성임
                if(lastCh == '0' || lastCh == '1' || lastCh == '3' || lastCh == '6' || lastCh == '7' || lastCh == '8'){
                    jongSung = 1;
                }

                if(jongSung == 1){
                    if(i == 0){
                        input = input.substring(0, pos) + "은" + input.substring(pos + 4);
                    }else if(i == 1){
                        input = input.substring(0, pos) + "이" + input.substring(pos + 4);
                    }else if(i == 2){
                        input = input.substring(0, pos) + "을" + input.substring(pos + 4);
                    }else if(i == 3){
                        input = input.substring(0, pos) + "과" + input.substring(pos + 4);
                    }else if(i == 4){
                        input = input.substring(0, pos) + "으로" + input.substring(pos + 4);
                    }
                }else{
                    if(i == 0){
                        input = input.substring(0, pos) + "는" + input.substring(pos + 4);
                    }else if(i == 1){
                        input = input.substring(0, pos) + "가" + input.substring(pos + 4);
                    }else if(i == 2){
                        input = input.substring(0, pos) + "를" + input.substring(pos + 4);
                    }else if(i == 3){
                        input = input.substring(0, pos) + "와" + input.substring(pos + 4);
                    }else if(i == 4){
                        input = input.substring(0, pos) + "로" + input.substring(pos + 4);
                    }
                }
            }
        }
        if(iJosaExist == 0){
            break;
        }
    }
    return input;
  };


/**
 * 함수명 	: com.str.trim
 * 함수설명	: 입력된 문자열의 좌우측 공백을 제거한 문자열을 구한다.
 * 파라미터	: str : 문자열
 * 리턴		: 양쪽 공백 제거 한 문자열
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.str.trim
 */
com.str.trim = function(str) {
    try {
        if (typeof str == "undefined" || str == null) {
            str ="";
        }
        if (typeof str !== "string") {
            str = str + "";
        }
        return str.trim();
    } catch (ex) {
        return str;
    }
};


/**
 * 함수명 	: com.str.getByteLength
 * 함수설명	: 문자열의 바이트 기준 문자열 길이를 반환한다.
 * 파라미터	: str : 문자열
 *			  ignoreChar : 제외 대상 문자
 * 리턴		: 문자열 길이
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.str.getByteLength
 */
com.str.getByteLength = function(str, ignoreChar, isEnter) {

	if (isEnter) {
		var expr		= /\n/g;
        var temp		= str.match(expr);
        var enterCnt	= (temp) ? temp.length : 0;
        var byteLength	= WebSquare.util.getByteLength(str);

        return enterCnt + byteLength;
	} else {
		return WebSquare.util.getByteLength(str, ignoreChar);
	}
};




