/**
 * 함수명 	: com.date.formatDate
 * 함수설명	: 문자열을 날짜 Formatter 적용하여 반환한다.
 * 파라미터	: str : 날짜 (yyyymmdd)
 *			  type : 날짜포맷유형
 *			   - slash :  '21/01/02'
 *			   - date :   '2021/01/02'
 *			   - colon :  '2012:03:19'
 *			   - 값이 없으면 :  2021년 01월 01일
 * 리턴		: 포맷팅된 날짜
 *			   -  type을 파라미터로 넘기지 않으면 : 2021년 01월 01일
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.date.formatDate
 */
com.date.formatDate = function (str, type) {
    var output = "";
    var date = new String(str);

    if (com.util.isEmpty(type)) {
    	 var year = date.substr(0, 4);
         var month = date.substr(4, 2);
         var day = date.substr(6, 2);
         var output = year + "년 " + month + "월 " + day + "일";

         return output;
    }


    // 포맷이 있는 경우
    if (type == "slash") {
        date = date.substring(2, date.length);
        for (var i = 0; i <= date.length - 1; i++) {
            output = output + date[i];
            if ((i + 1) % 2 == 0 && (date.length - 1) !== i)
                output = output + "/";
        }
    } else if (type == "date") {
        if (date.length == 8) {
            output = date.substr(0, 4) + "-" + date.substr(4, 2) + "-" + date.substr(6, 2);
        }
    } else if (type == "colon") {
        if (date.length == 8) {
            output = date.substr(0, 4) + ":" + date.substr(4, 2) + ":" + date.substr(6, 2);
        }
    } else {
    	var date = WebSquare.date.parseDate (str);
    	output =  WebSquare.date.getFormattedDate(date, type); 
    }

    return output;
};


