/**
 * 함수명 	: com.date.isDate
 * 함수설명	: 입력된 값이 날짜 유효성 여부를 판단한다.
 * 파라미터	: sDate : 날짜 문자열 (yyyyMMdd,  yyyyMMddHHmmss)
 *			  timeChk : 시간체크 여부
 * 리턴		: 성공 : true, 실패 : false
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.date.isDate
 */
com.date.isDate = function(sDate, timeChk) {
    var flag = true;
    try {
        if (sDate.length == 8) {
            sDate = sDate + "000000";
        }

        var y1 = parseInt(sDate.substring(0, 4), 10);
        var m1 = parseInt(sDate.substring(4, 6), 10);
        var d1 = parseInt(sDate.substring(6, 8), 10);
        var h1 = parseInt(sDate.substring(8, 10), 10);
        var t1 = parseInt(sDate.substring(10, 12), 10);
        var s1 = parseInt(sDate.substring(12), 10);
        if (isNaN(y1) || isNaN(m1) || isNaN(d1) || isNaN(h1) || isNaN(t1) || isNaN(s1))
            flag = false;

        if (m1 < 1 || m1 > 12)
            flag = false;

        var maxDay = 31;
        if (m1 == 2) {
            maxDay = ((y1 % 400 == 0) || ((y1 % 4 == 0) && (y1 % 100 != 0))) ? 29
                    : 28;
        } else if (m1 == 4 || m1 == 6 || m1 == 9 || m1 == 11) {
            maxDay = 30;
        }

        if (d1 < 1 || d1 > maxDay) {
            flag = false;
        }

        if (h1 + t1 + s1 != "") {
            if (h1 < 0 || h1 > 24) {
                flag = false;
            } else if (h1 == 24) {
                if(typeof timeChk == "boolean" && !timeChk)
                    flag = false;
                if (t1 > 0)
                    flag = false;
                if (s1 > 0)
                    flag = false;
            }
            if (t1 < 0 || t1 > 59)
                flag = false;
            if (s1 < 0 || s1 > 59)
                flag = false;
        }
    } catch (ex) {
        flag = false;
    }
    return flag;
};


/**
 * 함수명 	: com.date.diffDate
