 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.date.diffDate
 */
com.date.diffDate = function(fromDate, toDate) {
    try {
        if (!com.date.isDate(fromDate) || !com.date.isDate(toDate)) {
            return;
        }
        var diffDate = WebSquare.date.dateDiff(fromDate, toDate);
        return diffDate;
    } catch (ex) {
