    }
};


/**
 * 함수명 	: com.date.isLeafYear
 * 함수설명	: 입력된 양력의 날짜가 윤년인지 검사한다.
 * 파라미터	: pYmd : 날짜 (yyyyMMdd)
 * 리턴		: 성공 : true, 실패 : false
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.date.isLeafYear
 */
com.date.isLeafYear = function(pYmd) {
    try{
        var isLeafYear = false;
        if (!com.date.isDate(pYmd)) {
            return;
        } else {
            pYmd = pYmd.substr(0, 8);
            var y1 = parseInt( pYmd.substr(0, 4), 10);
            isLeafYear = ((y1 % 400 == 0 ) || ((y1 % 4 == 0) && (y1 % 100 != 0))) ? true : false;
        }
        return isLeafYear;
    } catch (ex) {
        console.error(ex);
    }
};


/**
 * 함수명 	: com.date.getDay
 * 함수설명	: 특정 날짜의 요일을 반환한다.
 *			   - type이 num 이면 숫자형 요일 (1(일요일) ~ 7(토요일))
 *			   - type이 없으면  월요일 ~ 일요일
 * 파라미터	: value : 날짜 문자열 (yyyyMMdd)
 *			  type : 반환 형식
 *			   - num : 숫자형 요일 (1(일요일) ~ 7(토요일))
 *			   - 없음 : 월요일 ~ 일요일
 * 리턴		: N/A
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.date.getDay
 */
com.date.getDay = function (value,type) {
    var dayVal;
    if (type == "num") {
        var dayVal = WebSquare.date._getDay(value);
        if (dayVal == 0 ) {
            return "7";
        }else{
            return String(dayVal);
        }
    } else {
        return WebSquare.date.getDay(value);
    }
};


