/**
 * 함수명 	: com.date.getLastDateOfMonth
 * 함수설명	: 월의 마지막 날짜를 반환한다.
 * 파라미터	: yearMonth : 년월 문자열 (yyyyMM)
 * 리턴		: 일짜 (28 ~ 31)
 * 작성일 	: 2022.05.16
 * 작성자 	: Inswave Systems
 * 예시	 	: API : com.date.getLastDateOfMonth
 */
com.date.getLastDateOfMonth = function(yearMonth) {
    try {
        if (typeof yearMonth !== "string") {
            yearMonth = com.str.serialize(yearMonth);
        }

        var year = yearMonth.substring(0, 4);
        var month = yearMonth.substring(4, 6);

        return (new Date(year, month, 0)).getDate();
    } catch(ex) {
        return null;
    }
};


