 * 함수설명	: URL 표시 제한한 팝업 open.
 * 파라미터	: url       - 표시 URL (예 : '/index.jsp')
 *            opt       - 팝업창 window option (예 : width, height,...)
 *            opt.id    - (필수) popup id 지정
 *            data      - 파라미터 데이터
 *            data.w2xp - (필수) 팝업에 보이는 메뉴ID or 화면xml(예 :'03010100' or '/ui/pm50/bpay/Pm50BpayPayWrtCs.xml') 
 *            nmbrLoginCls - 비회원여부 'Y' 비회원 로그인 지원
 * 리턴		: 없음
 * 작성일 	: 2025.01.02
 * 작성자 	: 장원호
 */
//==============================================================================
com.win.openFixPopup = function(url, opt, data, nmbrLoginCls) {

	if (com.util.isEmpty(data)) {
		data	= {};
	}

	var actForm = document.popPost;

	var optString = "";

	/*
	optString	= com.util.jsonToQueryString($.extend({
		width	: 600,
		height	: 700,
	}, opt), ',');
	*/
	optString	= com.util.jsonToQueryString(opt, ',');
	var paramStr	= com.util.jsonToQueryString(data, '&');

	console.log("optString ==> " + optString);
	console.log("paramStr ==> " + paramStr);

    if (data.w2xp != null && data.w2xp != "") {
    	actForm.w2xPath.value = data.w2xp;
        //document.w2xPath.value = data.w2xp;
    } else {
		var msgOption = {
	        msgType     : 'error',
	        msgCode     : 'pm10.message.error.biz.p0.0036', //메뉴정보가 없습니다.
	    };
		com.message.openMessage(msgOption);
		return false;
    }

    if (opt.id != null && opt.id != "") {
    	actForm.target = "postPopup" + opt.id;
    } else {
		var msgOption = {
		    msgType     : 'error',
		    msgCode     : 'pm10.message.error.biz.p0.0037', //popup id가 없습니다.
		};
		com.message.openMessage(msgOption);
	    actForm.w2xPath.value = "";
		return false;
    }

    var moveCls = "menu";    
    if (com.util.isNotEmpty(nmbrLoginCls)) { 
    	moveCls = "nmbr_menu"; //비회원처리가 필요한화면일 경우
    }

    var viewUri = "";
    if (data.w2xp.indexOf(".xml") > -1) {
    	viewUri = data.w2xp;
    } else {
    	viewUri = com.page.getTopPage().scwin.getIrosPageUrl(moveCls, data.w2xp);
    }
    console.log("viewUri ==> " + viewUri);

    //로그인 여부 확인
    if(com.util.isNotEmpty(viewUri)) {
    	if (viewUri == "/ui/pm10/p0/potalmain/Pm10P0IrosLogin.xml") {
	    	if (com.session.isLogin(viewUri) == false) {
	    	    actForm.w2xPath.value = "";
	    	    com.message.openMessage(Pm10ComUtil.gfn_getMesOption('info', 'pm10.message.info.web.p0.0018', '해당^로그인'), function() {
	                //메뉴페이지이동(로그인)
	        	    com.page.getTopPage().scwin.goToMenuPage("menu", "06010100");
	    	    });

	    	} else {
	    		// 정상적 상황으로 팝업 동작
	    	    if (paramStr != null && paramStr != "") {
	    	    	actForm.linkParam.value = encodeURI(encodeURIComponent(paramStr));
	    	    }

	    	    var postPopup 	= window.open("_blank", "postPopup" + opt.id, optString);
	    		actForm.action = url;
	    	    actForm.submit();

	    	    actForm.w2xPath.value = "";
	    	    actForm.linkParam.value = "";
	    	    actForm.action = "";
	    	}
    	} else {
    		// 정상적 상황으로 팝업 동작
    	    if (paramStr != null && paramStr != "") {
    	    	actForm.linkParam.value = encodeURI(encodeURIComponent(paramStr));
    	    }

    	    var postPopup 	= window.open("_blank", "postPopup" + opt.id, optString);
    		actForm.action = url;
    	    actForm.submit();

    	    actForm.w2xPath.value = "";
    	    actForm.linkParam.value = "";
    	    actForm.action = "";
    	}
    } else { //URL 값이 없는 경우 로그인 해야 함
	    actForm.w2xPath.value = "";
	    com.message.openMessage(Pm10ComUtil.gfn_getMesOption('info', 'pm10.message.info.web.p0.0018', '해당^로그인'), function() {
            //메뉴페이지이동(로그인)
    	    com.page.getTopPage().scwin.goToMenuPage("menu", "06010100");
	    });
//		com.message.logout();
    }

};

