/**
 * 함수명 	: com.win.getFixPopParam
 * 함수설명	: URL 표시 제한한 팝업 사용 시 파라메터 값 읽기.
 *            파라메터를 Json Object 형태로 반환함
 * 파라미터	: 없음 
 * 리턴		: Json Object
 * 작성일 	: 2025.01.02
 * 작성자 	: 장원호
 */
com.win.getFixPopParam = function() {
    var linkParam = new Object();
    console.log("WebSquareExternal.linkParam ===> " + WebSquareExternal.linkParam);
    if (WebSquareExternal.linkParam != null && WebSquareExternal.linkParam != "") {

        var tmpTotParam = WebSquareExternal.linkParam;
        tmpTotParam = tmpTotParam.replaceAll("%3D", "=");
        tmpTotParam = tmpTotParam.replaceAll("%26", "&");
        tmpTotParam = tmpTotParam.replaceAll("%2F", "/");
        console.log("tmpTotParam ===> " + tmpTotParam);
        var tmpArrParam = tmpTotParam.split("&");
        var tmpKey = "";

        for (var i = 0; i < tmpArrParam.length; i++) {
            var setParam = tmpArrParam[i].split(/=/);

            if (setParam.length > 1) {
                tmpKey = "";
                tmpKey = setParam[0];
                linkParam[tmpKey] = setParam[1];
            }
        }

    } else {
    	linkParam = null;
    }

    return linkParam;
};

