ext.multiBtnHandler = {
	init : function() {
		
		// 버튼 그룹 이벤트
		$(document).on('mouseenter', '.btn-multi-con', this.onMouseEnter);
		$(document).on('mouseleave', '.btn-multi-con', this.onMouseLeave);
		
		// 버튼 항목 클릭
		$(document).on('click', '.btn.multi', this.onClick);
		$(document).on('focus', '.btn.multi', this.onMouseEnter);
		$(document).on('blur', '.btn.multi', this.onMouseLeave);
	},
	onMouseEnter : function(e) {
		
		try{
		
			var btnCon		= $(e.target).hasClass('btn-multi-con') ? $(e.target) : $(e.target).parent();
			var btnList		= btnCon.find('.btn.multi');
			var activeIdx	= ext.multiBtnHandler.getActiveIndex(btnList);
			
	        btnCon[0].classList.add("hover");
	        btnCon[0].style.width = btnCon[0].getAttribute("data-max-width") + "px";
	        btnCon[0].style.top = activeIdx * btnList[0].offsetHeight * -1 + "px";
	        btnCon[0].style.left = 0;
		} catch (e) {
			console.log(e);
		}
	},
	onMouseLeave: function(e){
        
		var btnCon		= $(e.target).hasClass('btn-multi-con') ? $(e.target) : $(e.target).parent();
				
		btnCon[0].style.width = "auto";
        btnCon[0].style.top = 0;
        btnCon[0].classList.remove("hover");
        
        
    },
    getActiveIndex : function(btnList) {
    	for(var i = 0; i < btnList.length; i++){
            if(btnList[i].classList.contains("active")){
            	return i;
            }
        }
    }, 
    getMaxWidth: function(btnList){
        var w = 0;
        for(var i = 0; i < btnList.length; i++){
            if(btnList[i].offsetWidth > w){
                w = btnList[i].offsetWidth;
            }
        }
        return w+1;
    },
    onClick: function(e){
    	var btn			= $(e.target);
    	var btnList		= btn.parent().find('.btn.multi');

        for(let i=0; i<btnList.length; i++){
            btnList[i].classList.remove("active");

            if(!btnList[i].classList.contains("hide")){
                btnList[i].classList.add("hide");
            }
        }

        if(btn[0].classList.contains("hide")){
            btn[0].classList.remove("hide");
        }
        btn[0].classList.add("active");
        btn[0].blur();
    },
    defaultSetting: function(btnCon){
        var btnList = btnCon.find(".btn.multi");
        var activeCnt = 0;

        // button 컨테이너 hover 시 크기 지정
        btnCon.attr("data-max-width", ext.multiBtnHandler.getMaxWidth(btnCon.find(".btn.multi")));

        for(let i = 0; i < btnList.length; i++){
            if(!btnList[i].classList.contains("active")){
                btnList[i].classList.add("hide");
            }else{
                activeCnt += 1;
            }
        }

        if(activeCnt == 0){
            btnList[0].classList.remove("hide");
            btnList[0].classList.add("active");
        }
    }
    
};

