/**
 * 업로드 파일 검증
 *
 * @param vFormId 폼ID
 * @param vOpenFileExt 업로드 가능 확장자(예:"jpg, png, gif, bmp, pdf")
 * @param vMaxSize 제한사이즈(단위:MB)
 * @return true:업로드가능, false:업로드불가
 *
 * DATE : 2019.10.17
 * AUTH : 오성식
 */
EgovNrsFileBase.gfn_fileValid = function(vFormId, vOpenFileExt, vMaxSize) {

	var file_names = new Array(); //파일명목록

    var fileForm = $('#'+vFormId)[0];
    var fileInputCnt = $("input[type=file]").length;
    var openFileExt = vOpenFileExt; //업로드 가능 확장자
    var maxSize  = vMaxSize * 1024 * 1024  //제한사이즈(단위:MB)

    var selFileCnt = 0;
    var rtnValue = true;
    for(var i=0; i<fileInputCnt; i++) {
        // 파일 선택 체크1
        var targetFile = $("input[type=file]")[i].files[0];
        //console.log("targetFile null check="+EgovNrsStringBase.gfn_isEmpty(targetFile));
        if(EgovNrsStringBase.gfn_isEmpty(targetFile)){
            continue;
        }

        // 파일 선택 체크2
        var upload_file = targetFile.name;
        console.log("upload_file ="+upload_file);
        //console.log("upload_file null check="+EgovNrsStringBase.gfn_isEmpty(upload_file));
        if(EgovNrsStringBase.gfn_isEmpty(upload_file)){
            continue;
        } else {
            selFileCnt++;
        }

        //파일명저장
        file_names.push(upload_file);


        // 파일 확장자 체크
        var fileExt = upload_file.slice(upload_file.lastIndexOf(".") + 1).toLowerCase(); //파일 확장자를 잘라내고, 비교를 위해 소문자로 만듭니다.
        //console.log(">>fileExt="+fileExt);
        if(openFileExt.indexOf(fileExt)<0){ //확장자를 확인합니다.
            alert('파일첨부는 해당 확장자('+openFileExt+')만 등록 가능합니다.');
            rtnValue = false;
            break;
        }

        var fileSize = 0;

        fileSize = targetFile.size;
        console.log("file size="+fileSize);
        // 업로드한 파일 MB로 변환
        var fileSize2   = (fileSize / 1024) / 1024
        // 소수점 2자리에서 반올림
        var fileSize_mb = fileSize2.toFixed(2);
        //alert("파일사이즈 : "+ fileSize +", 최대파일사이즈 : 5MB");

        if(fileSize > maxSize){
            alert("첨부하신 파일 사이즈는 "+ fileSize_mb +"MB 입니다.\n첨부하실 파일 사이즈는 "+((maxSize/ 1024)/ 1024)+"MB 이내로 등록 가능합니다.");
            rtnValue = false;
            break;
        }
    } //end for

    // 파일 선택 체크
    if(selFileCnt == 0){
        alert("파일을 선택하여 주세요.");
        return false;
    }

    return rtnValue;
};


EgovNrsFileBase.isFileNameSpecial = function(strFileName){

    if(EgovNrsStringBase.gfn_isEmpty(strFileName) == true){
        
        return;
    }
    
    for(var i=0;i<strFileName.length;i++){
        cChar = strFileName.charAt(i);
        
        if( cChar == '/' || cChar == ':' || cChar == '*'|| cChar == '?' || cChar == '\"' || cChar == '<' || cChar == '>' || cChar == '|' || cChar == '\\') {
                return false;
        }
        
    }
    
    return true;
};

