 * @param selectFunctionNm  조회함수명
 *
 * DATE : 2019.06.17
 * AUTH : 오성식
 */
EgovNrsPagingBase.gfn_dispPageLine = function(divId, pageNo, totalDataCount, pagePerDataCount, pageSize, selectFunctionNm) {
    try {
        var currentPageNo = pageNo;
        var totalData    = totalDataCount;
        var pagePerCnt  = pagePerDataCount;
        var pageCnt    = new Number(pageSize);
        //console.log("-->pageSize="+pageSize+", pageCnt="+pageCnt);

        var totalPages = Math.ceil(totalData / pagePerCnt);
        if(totalPages == 0) totalPages = 1;
        totalPages = new Number(totalPages);

        //console.log("-->currentPageNo="+currentPageNo);
        var basePage = (currentPageNo <= pageCnt) ? 1 : (currentPageNo - (currentPageNo % pageCnt)) / pageCnt + 1;
        //console.log("-->basePage1="+basePage);
        basePage = (currentPageNo > pageCnt && (currentPageNo % pageCnt) == 0) ? (basePage - 1) * pageCnt + 1 : basePage * pageCnt + 1;
        //console.log("-->basePage2="+basePage);
        var prevPageBlock = (currentPageNo <= pageCnt) ? 0 : basePage - pageCnt - 1;
        //console.log("-->prevPageBlock="+prevPageBlock);
        var nextPageBlock = (basePage >= totalPages) ? 0 : new Number(basePage);
        //console.log("-->nextPageBlock="+nextPageBlock);
        var startPage = basePage - pageCnt;
        //console.log("-->startPage="+startPage+", basePage="+basePage+", pageCnt="+pageCnt);

        var pageHtml = "<ul>";
        //EgovNrsAbstractPaginationRenderer 기준으로 변경함(2021-10-27)
        //pageHtml += (currentPageNo == 1) ? "" : "<li><a href='javascript:"+selectFunctionNm+"(1);'><img src='/images/egov/nrs/com/btn_first.png' alt='처음으로'/></a></li>";
        //pageHtml += (prevPageBlock == 0) ? "" : "<li><a href='javascript:"+selectFunctionNm+"("+prevPageBlock+");'><img src='/images/egov/nrs/com/btn_prev.png' alt='이전'/></a></li>";
        pageHtml += "<li><a href='javascript:"+selectFunctionNm+"(1);'><img src='/images/egov/nrs/com/btn_first.png' alt='처음으로'/></a></li>";
        pageHtml += "<li><a href='javascript:"+selectFunctionNm+"("+prevPageBlock+");'><img src='/images/egov/nrs/com/btn_prev.png' alt='이전'/></a></li>";
        pageHtml += "";

        for(var i = startPage; i < (startPage + pageCnt); i++) {
            if(currentPageNo == i)
                pageHtml += "<li class='active'><a href='javascript:void(0);'>" + i + "</a></li>";
            else if(i <= totalPages)
                pageHtml += "<li><a href='javascript:void(0);' onclick='"+selectFunctionNm+"("+i+");'>" + i + "</a></li>";
        }

        //EgovNrsAbstractPaginationRenderer 기준으로 변경함(2021-10-27)
        //pageHtml += (nextPageBlock == 0)          ? "" : "<li><a href='javascript:"+selectFunctionNm+"("+nextPageBlock+");'><img src='/images/egov/nrs/com/btn_next.png' alt='다음'/></a></li>";
        //pageHtml += (currentPageNo == totalPages) ? "" : "<li><a href='javascript:"+selectFunctionNm+"("+totalPages+");'><img src='/images/egov/nrs/com/btn_last.png' alt='마지막으로'/></a></li>";
        pageHtml += "<li><a href='javascript:"+selectFunctionNm+"("+nextPageBlock+");'><img src='/images/egov/nrs/com/btn_next.png' alt='다음'/></a></li>";
        pageHtml += "<li><a href='javascript:"+selectFunctionNm+"("+totalPages+");'><img src='/images/egov/nrs/com/btn_last.png' alt='마지막으로'/></a></li>";

        pageHtml += "</ul>";

        $('#'+divId).html(pageHtml);
    } catch(e) {
        alert(e.message);
    }
};


