/**
 * 입력한 값이 몇바이트인지 계산하고 리턴함
 *    
 * @param id (strValue)
 * @return int
 *
 * DATE : 2021.12.10
 * AUTH : 최태석
 */
EgovNrsStringBase.gfn_byteLength = function(strValue){
    
    var returnBytes = 0;
    
    
    for (i = 0; i < strValue.length;i++) {
        var ch = strValue.charAt(i);
        if (escape(ch).length > 4) {
            returnBytes += 2;
        }else if (ch == "\n") {
            if (strValue.charAt(i - 1) != "\n") {
                returnBytes += 1;
            }
        }else if (ch == "<" || ch == ">") {
            returnBytes += 4;
        }else {
            returnBytes += 1;
        }
    }
    
    return returnBytes;
};

