 * AUTH : 최태석
 */
EgovNrsStringBase.gfn_chkMsgMaxLength = function(strValue,maxLength,textId){

    var length = EgovNrsStringBase.gfn_byteLength(strValue);
    
    if(length > maxLength){
    
        alert("최대 "+maxLength+"byte 이므로 초과된 글자수는 자동으로 삭제됩니다.");
        
        str = strValue.substr(0,maxLength);
        
        $('#'+textId).val(str);
    }
};



