/**
 * 주민등록번호가 유효한지 확인합니다
 * DATE : 2021.12.29
 * AUTH : 최태석
 */

EgovNrsStringBase.gfn_ChkJuminRegtNo = function(strJumin1 , strJumin2) {
    var isVal = false ;

    var strYY = strJumin1.substring(0,2) ;    // 생년
    var strMM = strJumin1.substring(2,4) ;    // 생월
    var strDD = strJumin1.substring(4,6) ;    // 생일
    var strGender = strJumin2.substring(0,1) ;  // 성별

    // 기본 체크
    //인터넷등기소 주민등록번호 유효성검증 기능 개선검토   
    if(strJumin1.length != 6 || strJumin2.length != 7 || strMM < 1 || strMM > 12 || strDD < 0 || strDD > 31 || strGender > 4 || strGender < 1) {
        //alert("잘못된 주민등록번호입니다") ;
        return isVal ;
    }

    // 주민등록번호 공식에 의한 체크
    var juminRegtNo = strJumin1 + strJumin2 ;

    var ck = 0 ;
    for(i = 0 ; i < 12 ; ++i) {
        var num = juminRegtNo.substring(i, i+1) ;
        ck += (i%8+2) * num ;
    }

    ck = (11-(ck%11))%10 ;

    if(parseInt(ck) != parseInt(juminRegtNo.substring(12,13))) {
        return isVal ;
    } else isVal = true ;

    return isVal ;
};

/**
 * 주민등록번호가 14세미만인지 체크한다.
 * DATE : 2021.12.29
 * AUTH : 최태석
 */
EgovNrsStringBase.gfn_CheckLess14 = function( strEnr1, strEnr2, strCurrent ) {

  if ( ( strEnr2.substring(0,1) == '3' )||( strEnr2.substring(0,1) == '4' ) ) {
    cal_enr = '20'+ strEnr1;
  } else if ( ( strEnr2.substring(0,1) == '5' )||( strEnr2.substring(0,1) == '6' ) ) {
    cal_enr = '21'+ strEnr1;
  } else if ( ( strEnr2.substring(0,1) == '7' )||( strEnr2.substring(0,1) == '8' ) ) {
    cal_enr = '22'+ strEnr1;
  } else if ( ( strEnr2.substring(0,1) == '9' )||( strEnr2.substring(0,1) == '0' ) ) {
    cal_enr = '23'+ strEnr1;
  } else {
    cal_enr = '19'+ strEnr1;
  }
  if ( strCurrent - cal_enr < 140000 ) {
    alert( '만 14세미만인 사용자는 회원등록을 할 수 없습니다.( 개인정보 보호방침 참조 )' );
    return false;
  }
};

/**
 * source에서 findText를 찾아 replaceText로 변환해 반환한다.
 *
 * @param source (원소스 문자)
 * @param findText (찾을 문자)
 * @param replaceText (바꿀 문자)
 * @return string 변환된 결과
 *
 * DATE : 2019.10.10
 * AUTH : 오성식
 */
EgovNrsStringBase.gfn_replaceText = function(source, findText, replaceText) {
	return source.replace(new RegExp('\\${findText}', 'g'), replaceText); 
};

