/**
 * 단말기가 모바일device인지 체크
 *
 * DATE : 2019.12.03
 * AUTH : 오성식
 */
EgovNrsComBase.gfn_isMobile = function(){
    //userAgent 기준임
    //OS(platform) 기준으로 변경 시, PC WEB에서 테스트 고려 필요)
    var ua = navigator.userAgent;

    if (ua.match(/iPhone|iPad|Android|Windows CE|BlackBerry|Symbian|Windows Phone|webOS|Opera Mini|Opera Mobi|POLARIS|IEMobile|lgtelecom|nokia|SonyEricsson/i) != null || ua.match(/LG|SAMSUNG|Samsung/) != null || document.body.clientWidth < 992){
        return true;
    }else{
        return false;
    }
};

/**
 * 브라우저 종류 체크
 *
 * DATE : 2019.12.09
 * AUTH : 오성식
 */
EgovNrsComBase.gfn_chkBrowser = function(){

    var ua = navigator.userAgent.toLowerCase();

    switch (true) {
        case ua.indexOf("edge") > -1: return "edge";
        case ua.indexOf("edg") > -1: return "chromium based edge (dev or canary)";
        case ua.indexOf("opr") > -1 && !!window.opr: return "opera";
        case ua.indexOf("chrome") > -1 && !!window.chrome: return "chrome";
        case ua.indexOf("trident") > -1: return "ie";
        case ua.indexOf("firefox") > -1: return "firefox";
        case ua.indexOf("safari") > -1: return "safari";
        default: return "other";
    }
};

