/**
 * 한글을 Encoding
 *    
 * @param strValue 
 * @return String
 *
 * DATE : 2021.12.13
 * AUTH : 최태석
 */
EgovNrsComBase.gfn_encode = function(strValue){

   var len = strValue.length;
   
   var returnVal = '';
   
   if ( len == 0 ) return ;
    
    for( i = 0 ; i < len ; i++ ){
        returnVal += strValue.charCodeAt(i);
        returnVal += ';' ;
    }
    
    return returnVal;
};

