/**
 * 함수명   : Pr10ComBase.gfn_isEmpty
 * 함수설명 : 빈값체크 함수
 * 파라메터 : 체크할 값
 * 리턴     : 체크결과(true/false)
 * 작성일   : 2022.05.17
 * 작성자   : 윤영국
 */
Pr10ComBase.gfn_isEmpty = function(value) {

	// Array
	if (com.util.isArray(value)) {
		if (value.length == 0) {
			return true;
		}

	// Object
	} else if (com.util.isPlainObject(value) && Object.keys(value).length === 0) {
		return true;
	}

	return com.util.isEmpty(value);
};

/**
 * 함수명   : Pr10ComBase.gfn_isEmpty
 * 함수설명 : 빈값체크 함수
 * 파라메터 : 체크할 값
 * 리턴     : 체크결과(true/false)
 * 작성일   : 2022.05.17
 * 작성자   : 윤영국
 */
Pr10ComBase.gfn_isNotEmpty = function(value) {
	return !Pr10ComBase.gfn_isEmpty(value);
};

