 * 함수설명 : 메시지팝업 Option 조회
 * 파라메터 : 메시지타입, 메시지코드
 * 리턴     : 메시지팝업 Option
 * 작성일   : 2022.05.17
 * 작성자   : 윤영국
 */
Pr10ComBase.gfn_getMessagePopupOption = function(msgType, msgCode, msgArg) {
	// 타이틀
	var msgTitle = "egov.message.title.web.com." + msgType;
	if (msgType.indexOf("question") > -1) {
		msgTitle = "egov.message.title.web.com.info";
	}

	// 메세지 옵션 정보 (
	var msgOption = { msgType : msgType
					, msgTitle : msgTitle
					, msgCode : msgCode
					, msgArg : msgArg
					};
	return msgOption;
};

/**
 * 함수명   : Pr10ComBase.gfn_getMessagePopupOption
 * 함수설명 : 오픈팝업 Option 조회
 * 파라메터 : N/A
 * 리턴     : 오픈팝업 Option
 * 작성일   : 2022.05.17
 * 작성자   : 윤영국
 */
Pr10ComBase.gfn_getOpenPopupOption = function() {

	// 팝업 옵션
	var popupOption = {
		type : "wframePopup",
		width : 1000,
		height : 800,
		modal : true,
		resizable : false,
		alwaysOnTop : true,
		posScreen : "WIN",
//		className : "no_header",
	};

	// 팝업명
	if (Pr10ComBase.gfn_isNotEmpty(arguments[0])) {
		popupOption.popupName = arguments[0];
	}
	// width
	if (Pr10ComBase.gfn_isNotEmpty(arguments[1])) {
		popupOption.width = arguments[1];
	}
	// height
	if (Pr10ComBase.gfn_isNotEmpty(arguments[2])) {
		popupOption.height = arguments[2];
	}
	// type
	if (Pr10ComBase.gfn_isNotEmpty(arguments[3])) {
		popupOption.type = arguments[3];
	}

	return popupOption;
};

