/**
 * 함수명   : Pr10ComBase.gfn_setPeriodDateBtn
 * 함수설명 : 조회기간 설정
 * 파라메터 : 조회기간설정 그룹 컴포넌트, 선택 인덱스
 * 리턴     : N/A
 * 작성일   : 2022.05.20
 * 작성자   : 윤영국
 */
Pr10ComBase.gfn_setPeriodDateBtn = function(compObj, selIdx, periodDef) {
	// 버튼 선택 class
	var addClassName = "color-main";

	// 버튼순서별 기간 정의
	if (Pr10ComBase.gfn_isEmpty(periodDef)) {
		periodDef = ["-7D", "-1M", "-3M"];
	}

	if (Pr10ComBase.gfn_isNotEmpty(compObj)) {

		var icaStComp, icaEdComp, btnFirstComp, btnSecondComp, btnThirdComp;

		var childGroup = compObj.getChildren();
		if (Pr10ComBase.gfn_isNotEmpty(childGroup)) {

			// 캘린더 그룹, 버튼 그룹
			if (childGroup.length == 2) {
				var childCalendar = childGroup[0].getChildren();
				var childButton = childGroup[1].getChildren();

				// 캘린더 2 + 하이픈 1
				if (childCalendar.length == 3) {

					// 캘린더 컴포넌트 그룹
					if (selIdx > -1) {
						var edDate = com.date.getServerDateTime();
						var stDate = getDateValue(periodDef[selIdx]);

						childCalendar[0].setValue(stDate);	// 시작일자
						childCalendar[2].setValue(edDate);	// 종료일자

						function getDateValue(period) {
							var len = period.length;
							var val = period.substring(0, len-1);
							switch (period.substring(len - 1, len)) {
								case "D" :
									return com.date.addDate(edDate, val);
									break;
								case "M" :
									return com.date.addMonth(edDate, val);
									break;
								default :
									return com.date.addDate(edDate, val);
							}
						}
					}

					// 버튼 콤포넌트 그룹
					var len = childButton.length;
					for (var i = 0; i < len; i++) {
						if (i == selIdx) {
							childButton[i].addClass(addClassName);
						} else {
							childButton[i].removeClass(addClassName);
						}
					}
				}
			}
		}
		// 기간설정 버튼 처리
		var scope = compObj.getScopeWindow();
		if (scope.dma_search_cond) {
			scope.dma_search_cond.set("period_date_btn", selIdx);
		}
	}
};

/**
 * 함수명   : Pr10ComBase.gfn_initPageList
 * 함수설명 : 페이징 설정
 * 파라메터 : 페이징 관련 설정
 * 리턴     : N/A
 * 작성일   : 2022.05.20
 * 작성자   : 윤영국
 */
Pr10ComBase.gfn_initPageList = function(pagingInfo) {

	// 페이지당 레코드 표시 건수
	if (Pr10ComBase.gfn_isEmpty(pagingInfo.pageUnit)) {
		// 페이지당 레코드 표시 건수 프로퍼티
		if (Pr10ComBase.gfn_isNotEmpty(pagingInfo.pageUnitProperty)) {
			var pageUnit = com.util.getPropertyStringValue(pagingInfo.pageUnitProperty);
			if (Pr10ComBase.gfn_isNotEmpty(pageUnit)) {
				pagingInfo.pageUnit = pageUnit;
			}
		}
	}
//	// 데이터셋 설정 (com모듈에서 처리)
//	if (Pr10ComBase.gfn_isNotEmpty(pagingInfo.pageUnit)) {
//		pagingInfo.dataMap.set("pageUnit", pagingInfo.pageUnit);
//	}

	// 페이지 표시 건수
	if (Pr10ComBase.gfn_isEmpty(pagingInfo.pageSize)) {
		// 페이지 표시 건수 프로퍼티
		if (Pr10ComBase.gfn_isNotEmpty(pagingInfo.pageSizeProperty)) {
			var pageSize = com.util.getPropertyStringValue(pagingInfo.pageSizeProperty);
			if (Pr10ComBase.gfn_isNotEmpty(pageSize)) {
				pagingInfo.pageSize = pageSize;
			}
		}
	}
	// 데이터셋 설정
	if (Pr10ComBase.gfn_isNotEmpty(pagingInfo.pageSize)) {
		pagingInfo.dataMap.set("pageSize", pagingInfo.pageSize);
	}

    // 페이징 관련 컴포넌트
	var compObjInfo = {
		sbm : pagingInfo.sbm,					// submission Comp
		dataMap : pagingInfo.dataMap,			// 전송 데이터 map
		page : pagingInfo.page,					// 페이징 comp
		totalPage	: pagingInfo.totalPage,		// 총 페이지 수 comp
		totalCnt : pagingInfo.totalCount		// 총 건수 comp
	};

	// 옵션 정보
	var options = {
		visibleRowNum : pagingInfo.visibleRowNum,
		pageUnit : pagingInfo.pageUnit
	};

	// 콜백 정보
	var callbackFnInfo = {
		submitDone : function(resData) {
			// 페이지정보
			var paginationInfo = resData.responseJSON.paginationInfo;

			// 전체건수표시
		    if (pagingInfo.totalCountIndi) {
			    Pr10ComBase.gfn_setTotalCountIndi(paginationInfo.totalRecordCount, pagingInfo.totalCountIndi);
		    }

		    // 콜백이 있을 경우 페이징 처리 후 콜백
			if (pagingInfo.callback) {
				pagingInfo.callback(resData);
			}
		}
	};

	// 페이지 처리 설정
	var scope = pagingInfo.sbm.getScopeWindow();
    var pluginName = pagingInfo.page.getPluginName();
    if (pluginName === "pageList") {
    	scope.com.grid.setPagingList(pagingInfo.grid, compObjInfo, options, callbackFnInfo);
    } else if (pluginName === "selectbox") {
    	scope.com.grid.setPagingCombo(pagingInfo.grid, compObjInfo, options, callbackFnInfo);
    }
};

/**
 * 함수명   : Pr10ComBase.gfn_executeSubmission
 * 함수설명 : submission 실행(콜백함수 지정)
 * 파라메터 : submission, callback
 * 리턴     : N/A
 * 작성일   : 2022.06.09
 * 작성자   : 윤영국
 */
Pr10ComBase.gfn_executeSubmission = function(sbmObj, callbackFn) {
	// submit-done 이벤트에 콜백함수 추가, 기 추가된 경우 추가하지 않음
	if (callbackFn && sbmObj.pushedUserEvent !== true) {
		sbmObj.pushedUserEvent = true;
		sbmObj.userEventList.push(new WebSquare.Events.XmlEvent('xforms-submit-done', 'script', {handler : callbackFn}));
	}
	var scope = sbmObj.getScopeWindow();
	scope.com.sbm.execute(sbmObj);
};

/**
 * 함수명   : Pr10ComBase.gfn_getBrowserName
 * 함수설명 : 브라우저명 조회
 * 파라메터 : 버전포함여부(default:false, ex:IE 11)
 * 리턴     : 브라우저명
 * 작성일   : 2022.06.30
 * 작성자   : 윤영국
 */
Pr10ComBase.gfn_getBrowserName = function(version) {

	// User-Agent
	var agent = window.navigator.userAgent.toLowerCase();

	var browserName = "Other";

	if (agent.indexOf("edge") > -1) {
		browserName = "Edge";
	} else if (WebSquare.util.isChromeEdge()) {
		browserName = "ChromeEdge";
	} else if (WebSquare.util.isChrome()) {
		browserName = "Chrome";
	} else if (WebSquare.util.isOpera()) {
		browserName = "Opera";
	} else if (WebSquare.util.isIEAllVersion()) {
		browserName = "IE";
	} else if (agent.indexOf("firefox") > -1) {
		browserName = "Firefox";
	} else if (WebSquare.util.isSafari()) {
		browserName = "Safari";
	}

	if (version === true) {
		var ver = WebSquare.util.browserVersion();
		if (Pr10ComBase.gfn_isNotEmpty(ver.trim())) {
			browserName += " " + ver;
		}
	}

	return browserName;
}

/**
 * 함수명   : Pr10ComBase.gfn_getUserClsYn
 * 함수설명 : 사용자구분여부 조회
 * 파라메터 : 사용자구분 (A:대리인, E:촉탁, N:일반인)
 * 리턴     : boolean
 * 작성일   : 2022.07.01
 * 작성자   : 윤영국
 */
Pr10ComBase.gfn_getUserClsYn = function(type, userClsCd) {

	if (Pr10ComBase.gfn_isEmpty(userClsCd)) {
		userClsCd = Pr10ComBase.gfn_getSession("userInfo.mbrUserClsCd");
	}

	var result = false;

	if (Pr10ComBase.gfn_isNotEmpty(userClsCd)) {
		if (type) {
			// 대리인 : 법무사, 변호사, 법무법인, 법무사법인
			if (type.indexOf("A") > -1) {
				if ("14300,14301,14307,14309".indexOf(userClsCd) > -1) {
					result = true;
				}
			}
			// 대리인 : 법무사, 변호사
			if (type.indexOf("P") > -1) {
				if ("14300,14301".indexOf(userClsCd) > -1) {
					result = true;
				}
			}
			// 촉탁 : 전자촉탁신청
			if (type.indexOf("E") > -1) {
				if (userClsCd == "14093") {
					result = true;
				}
			}
			// 일반인
			if (type.indexOf("N") > -1) {
				if (userClsCd == "14304") {
					result = true;
				}
			}
			// 신청인
			if (type.indexOf("S") > -1) {
				if (userClsCd == "14344") {
					result = true;
				}
			}
			// 법인대표
			if (type.indexOf("R") > -1) {
				if ("14306,14307,14309".indexOf(userClsCd) > -1) {
					result = true;
				}
			}
		}
	}

	return result;
}

/**
 * 함수명   : Pr10ComBase.gfn_getSession
 * 함수설명 : PR10 클라이언트 세션 조회
 * 파라메터 : Key
 * 리턴     : N/A
 * 작성일   : 2022.07.27
 * 작성자   : 윤영국
 */
Pr10ComBase.CONST_PR10_COM_SESSION = "PR10_COM_SESSION__";
Pr10ComBase.gfn_getSession = function(key) {
	var getServerSession = function(reqData) {

		var deferred = $.Deferred();
	    var options = {
	    	"id" 			: "sbm_EgovNrsSessionBaseCtrl_getSessionBaseVo",
	    	"action" 		: "/egov/EgovNrsSessionBaseCtrl/getSessionBaseVo.do",
	    	"method" 		: "post",
	    	"mediatype" 	: "application/json",
	    	"mode" 			: "synchronous",
	    	"processMsg" 	: '$blank',
	    	"submitDoneHandler" : function(e) {
	    		deferred.resolve(e);
	    	},
	    	"submitErrorHandler" : function(e) {
	    		deferred.reject(e);
	    	}
	    };
	    var sbmObj	= com.sbm.create(options);

	    $p.executeSubmission(sbmObj, reqData);

	    return deferred.promise();
	};

	// PR10 세션 데이터 조회
	var sessionData = com.storage.getLocalStorage(Pr10ComBase.CONST_PR10_COM_SESSION);
	if (!sessionData) {
		sessionData = {};
	}

	// 사용자 변경 시 세션 초기화
	var cryptedId = com.storage.getLocalStorage("CRYPTED_ID__");
	if (sessionData.__sessionId !== cryptedId) {
		var sessionBaseVo = {};
		// 서버세션 조회
		getServerSession().done(function(res) {
	    	// 응답 JSON객체가 없으면 함수 종료
	        var resJson = res.responseJSON || null;
	        if (com.util.isEmpty(resJson)) {
	        	return;
	        } else {
	        	sessionBaseVo = resJson.sessionBaseVo;
	        }

	    }).fail(function(res) {
	        // TODO 통신 오류일 때 예외처리
	    	console.error("getServerSession error!");
	    });

		sessionData = Object.assign({__sessionId: cryptedId}, {userInfo: sessionBaseVo});
		var loginCertYn = "N";
		var irosLoginCls = sessionData.userInfo.irosLoginCls;
		if (Pr10ComBase.gfn_isNotEmpty(irosLoginCls) && "DEFG".indexOf(irosLoginCls) > -1) {
			loginCertYn = "Y";
		}
		sessionData.loginCertYn = loginCertYn;
		// 암호화된 값을 복호화하여 로컬에 저장. 2025.06.27. 이기호(2025-W00303)
		var decKey = "AES_DEFAULT_KEY_AES_DEFAULT_KEY_";
		var cryptedIdResp = sessionData.userInfo.cryptedId;
		if(cryptedIdResp != null && cryptedIdResp.length >= 32)
			decKey = cryptedIdResp.substring(0, 32);

		var decrypted = CryptoJS.AES.decrypt(sessionData.userInfo.enrNo,
				CryptoJS.enc.Base64.parse(btoa(decKey)),
				 {iv : CryptoJS.enc.Base64.parse(btoa(decKey.substring(0, 16))), 
				  padding : CryptoJS.pad.Pkcs7});
		var decryptedEnrNo = decrypted.toString(CryptoJS.enc.Utf8);

		sessionData.userInfo.enrNo = decryptedEnrNo; 
		com.storage.setLocalStorage(Pr10ComBase.CONST_PR10_COM_SESSION, sessionData)
	}

	if (key) {
		// 사용자정보 : userInfo.userId
		if (key.indexOf(".") > -1) {
			var keyArr = key.split(".");
			// 사용자구분코드가 부동산(14308) 일경우 일반인으로 변경			
			if(key.indexOf("mbrUserClsCd") > -1 && sessionData[keyArr[0]][keyArr[1]] == "14308") {
				return "14304";
			}
			return sessionData[keyArr[0]][keyArr[1]];
		}
		return sessionData[key];
	} else {
		return sessionData;
	}
}

/**
 * 함수명   : Pr10ComBase.gfn_setSession
 * 함수설명 : PR10 클라이언트 세션 설정
 * 파라메터 : Object or Key, Value
 * 리턴     : N/A
 * 작성일   : 2022.07.27
 * 작성자   : 윤영국
 */
Pr10ComBase.gfn_setSession = function(key, value) {
	var sessionData = Pr10ComBase.gfn_getSession();
	// PR10 클라이언트 세션 확인
	if (sessionData) {
		if (com.util.isString(key) && key != "userInfo") {
			sessionData[key] = value;
		}
		com.storage.setLocalStorage(Pr10ComBase.CONST_PR10_COM_SESSION, sessionData)
	}
}

/**
 * 함수명   : Pr10ComBase.gfn_getContentPage
 * 함수설명 : 메인 메뉴화면 페이지
 * 파라메터 : N/A
 * 리턴     : N/A
 * 작성일   : 2022.08.17
 * 작성자   : 윤영국
 */
Pr10ComBase.gfn_getContentPage = function() {
	var contentFrame = null;
	var contentPage = null;

	// 1. 대민(PM10) 최상위 페이지
	var topPage = com.page.getTopPage();
	if (topPage) {
		// 2. 대민(PM10) 최상위 페이지의 작업영역 Main WFrame
		if (topPage.wfm_potal_main) {
			// 3. 대민(PM10) 최상위 페이지의 Main WFrame 내 메뉴화면 Main WFrame
			contentFrame = topPage.wfm_potal_main.getWindow().wfm_content;
		} else if (topPage.wfm_content) {	// 최상위 페이지 메인 프레임 가져오기가 실패했을 경우 - 개발 임시 등
			contentFrame = topPage.wfm_content;
		} else {	// 메뉴 메인화면 프레임 가져오기가 실패했을 경우 - 개발 임시 등
			return topPage;
		}
		contentPage = contentFrame.getWindow();
	}

	return contentPage;
}

