/**
 * 함수명   : Pr10ComBase.gfn_movePage
 * 함수설명 : 메인페이지를 이동한다.
 * 파라메터 : 화면URL, 파라미터
 * 리턴     : N/A
 * 작성일   : 2022.08.17
 * 작성자   : 윤영국
 */
Pr10ComBase.gfn_movePage = function(pageUrl, pageParam, chkLogin) {
	try {
		//Pm10ComMenu.gfn_movePage(pageUrl, pageParam);
		var isLogin = chkLogin === true ? com.session.isLogin(pageUrl) : true;
		if (isLogin) {
			if (pageUrl.indexOf('Pr10AwrtAnchorMenu') > -1 || pageUrl.indexOf('Pr10SmplRgsRgsCausSel') > -1 || pageUrl.indexOf('Pr10HndlWddocWrt') > -1) { //퀵도움말 적용 이후 팝업화면 종료 후 기본사항입력화면이 호출되는 경우(예:제출대기에서 수정작성, 처리내역에서 보정조치)에 에러가 발생하여 추가함.
				Pr10ComBase.gfn_getContentPage().com.page.movePage(pageUrl, pageParam);
			} else {
				Pm10ComMenu.gfn_movePage(pageUrl, pageParam);
			}
		} else {
			Pm10ComMenu.gfn_movePage(Pm10ComGlobal.LOGIN_PAGE_URL, pageParam);
		}
	} catch (e) {
		// 개발용(임시) - 외부포털 메인페이지로 정상접근하지 않은 경우
		Pr10ComBase.gfn_getContentPage().com.page.movePage(pageUrl, pageParam);
	}
	// 스크롤을 최상단으로
	window.scrollTo(0, 0);
}

