 * 작성자   : 윤영국
 */
Pr10ComBase.gfn_openWFrame = function(compObj, url, paramData) {
	var errorMSg = "";
	if (compObj && compObj.setSrc) {
		var scope = compObj.getScopeWindow();
		scope.com.win.openWFrame(compObj, url, paramData);
		return true;
	} else {
		if (compObj && compObj.getPluginName) {
			errorMSg += " [" + compObj.getPluginName() + "]";
		} else {
			errorMSg += " [" + typeof compObj + "]";
		}
	}
	console.log("컴포넌트 오류 !!!" + errorMSg);
	return false;
}

