 * 함수명   : Pr10ComBase.gfn_toggleAccordionGroup
 * 함수설명 : Accordion 그룹을 접거나 펼친다.
 * 파라메터 : Accordion Head 그룹, 스크롤 Body 그룹
 * 리턴     : N/A
 * 작성일   : 2022.08.26
 * 작성자   : 윤영국
 */
Pr10ComBase.gfn_toggleAccordionGroup = function(headObj, scrollBodyObj) {
	var scrollBody = null, scrollTop = null;

	// 스크롤 Body 그룹이 넘어온 경우 펼쳤을 때 자동으로 스크롤
	if (scrollBodyObj && scrollBodyObj.getPluginName && scrollBodyObj.getPluginName() == "group") {
		scrollBody = $("#" + scrollBodyObj.getID());
		scrollTop = $(scrollBody).scrollTop();
	}

	// 아코디언 Head 그룹 처리
	if (headObj && headObj.getPluginName && headObj.getPluginName() == "group") {
		headObj.toggleClass(Pr10ComBase.ACCORDION_ACTIVE_CLASS);
		if (headObj.hasClass(Pr10ComBase.ACCORDION_ACTIVE_CLASS)) {
			if (Pr10ComBase.gfn_isNotEmpty(scrollTop)) {
				// 아코디언 바디 영역이 확장된 만큼 스크롤
				var offsetHeight = $("#" + headObj.parentControl.getID()).children(".accodion-body").height();
				if (Pr10ComBase.gfn_isNotEmpty(offsetHeight)) {
					scrollTop += offsetHeight;
					// 자동 스크롤 시 아코디언 Head가 숨지 않도록 scrollTop의 최대값 지정
					scrollTop = headObj.getPosition("top") < scrollTop ? headObj.getPosition("top") : scrollTop;
					$(scrollBody).scrollTop(scrollTop);
				}
			}
		}
	}
}

/**
 * 함수명   : Pr10ComBase.gfn_setRowChecked
 * 함수설명 : 그리드뷰의 row 클릭 시 체크상태를 토글한다.
 * 파라메터 : 그리드뷰, 체크컬럼ID, row index, 컬럼ID, 클릭이벤트에서 제외할 컬럼ID
 * 리턴     : N/A
 * 작성일   : 2022.09.29
 * 작성자   : 윤영국
 */
Pr10ComBase.gfn_setRowChecked = function(gridObj, checkColId, rowIndex, colId, excldColIds) {

	// 그리드뷰인 경우에만 실행
	if (gridObj && gridObj.getPluginName() == "gridView") {

		// 파라미터 체크
		if (Pr10ComBase.gfn_isEmpty(checkColId) || Pr10ComBase.gfn_isEmpty(rowIndex) || Pr10ComBase.gfn_isEmpty(colId)) {
			return;
		}

		// 체크박스 컬럼 제외
		if (checkColId == colId) {
			return;
		}

		// 체크박스 수정 가능 상태 체크
		if (gridObj.getCellDisabled(rowIndex, checkColId) || gridObj.getCellReadOnly(rowIndex, checkColId)) {
			return;
		}

		// 제외컬럼
		if (Pr10ComBase.gfn_isNotEmpty(excldColIds) && excldColIds.indexOf(colId) > -1) {
			return;
		}

		// 라디오버튼인 경우 체크된 상태 유지
		if (gridObj.getColumnType(checkColId) == "radio") {
			if (gridObj.getCellChecked(rowIndex, checkColId)) {
				return;
			}
		}

		// 체크상태 토글
		gridObj.setCellChecked(rowIndex, checkColId, !gridObj.getCellChecked(rowIndex, checkColId));
	}
}

