/**
 * 함수명   : Pr10ComBase.gfn_executeSyncSubmission
 * 함수설명 : 동기방식의 submission을 실행한다.
 * 파라메터 : url, request parameter, exeption callback function
 * 리턴     : N/A
 * 작성일   : 2023.01.26
 * 작성자   : 윤영국
 */
Pr10ComBase.gfn_executeSyncSubmission = function(url, reqData, exceptionCallbackFn) {
	var deferred = $.Deferred();
	var options = {
			"id" : "sbm_pr10_executeSyncSubmission",
			"action" : url,
			"method" : "post",
			"mediatype" : "application/json",
			"mode" : "synchronous",
			"processMsg" : '$blank',
			"submitDoneHandler" : function(e) {
	    		deferred.resolve(e);
	    	},
	    	"submitErrorHandler" : function(e) {
	    		deferred.reject(e);
	    	}
	    };
	com.sbm.create(options, reqData, exceptionCallbackFn, null, true);
    return deferred.promise();
}

