/**
 * 함수명   : Pr10ComBase.gfn_executeSbmExt
 * 함수설명 : submission 실행
 * 파라미터 : N/A
 * 리턴     : N/A
 * 작성일   : 2023.04.12
 * 작성자   : 윤영국
 */
Pr10ComBase.gfn_executeSbmExt = function(sbmObj, paramData, callbackFn, expCallbackFn, compObj, isNoMessage) {
	// submitdone 이벤트 핸들러와 callback 연결
	sbmObj.pushedUserEvent = true;
	sbmObj.userEventList = [];
	sbmObj.userEventList.push(new WebSquare.Events.XmlEvent('xforms-submit-done', 'script', {handler : callbackFn}));

	// submission 실행
	var scope = sbmObj.getScopeWindow();
	scope.com.sbm.executeExt(
		sbmObj,
		paramData,
		function (e) {	// exception 메시지 팝업 후 콜백함수
			if (expCallbackFn) {
				// submission id 추가
				e.submission_id = sbmObj.org_id
				expCallbackFn(e);
			}
		},
		compObj,
		isNoMessage
	);
}

