/**
 * 함수명   : Pr10ComBase.gfn_checkCloseRegt
 * 함수설명 : 폐쇄등기소 체크
 * 파라메터 : N/A
 * 리턴     : N/A
 * 작성일   : 2022.07.04
 * 작성자   : 윤영국
 */
Pr10ComBase.gfn_checkCloseRegt = async function(closeRegtList, regtNo, keyType) {
	if (Pr10ComBase.gfn_isEmpty(closeRegtList)) {
		return false;
	}
	if (Pr10ComBase.gfn_isEmpty(regtNo)) {
		return false;
	}

	if(keyType == null || keyType == undefined){
		keyType = "Z";
	}

	var closedMsgCd = "pr10.message.info.web.awrt.0116";

	if(keyType == "R"){
		closedMsgCd = "pr10.message.info.web.sprt.0142";		
	}

	var today = com.date.getServerDateTime();
	var len = closeRegtList.length;
	for (var i = 0; i < len; i++) {
		var key = closeRegtList[i].key;
		var value = closeRegtList[i].value;
		var closeInfo = value.split("@");
		if (key == keyType + regtNo) {
			if (com.date.diffDate(today, closeInfo[0]) > 0) {
				closeInfo.shift();	// 유효일자 제거
				closeInfo.push("신청서");
				// 이미 사전안내 메세지를 출력했다면 메세지 출력은 건너뜀. 2025.09.18. 이기호(2025-W00606)
				if(Pr10ComBase.closeRegtMessageFlag === true){
					return true;
				}

				// 줄바꿈 추가, 안내메세지 출력 async로 변경. 2025.09.18. 이기호(2025-W00606)
				// {0}는<br/>{1}부터 {2}(으)로 통합되어 운영됩니다.<br/>등기업무처리를 위해서 {3}까지 등기소에 {4}를 제출하시기 바랍니다.
				await com.message.openMessagePms(Pr10ComBase.gfn_getMessagePopupOption("info", "pr10.message.info.web.awrt.0349", closeInfo.join("^")));
				Pr10ComBase.closeRegtMessageFlag = true;
				return true;
			}
		} else if (key == regtNo + keyType) {
			if (com.date.diffDate(today, closeInfo[0]) <= 0) {
				closeInfo.shift();	// 유효일자 제거
				// 줄바꿈 추가, 안내메세지 출력 async로 변경. 2025.09.18. 이기호(2025-W00606)
				// {0}는<BR/>{1}부터 {2}(으)로 통합되어 운영됩니다.<BR/>관할등기소를 {2}(으)로 변경하시기 바랍니다.
				await com.message.openMessagePms(Pr10ComBase.gfn_getMessagePopupOption("info", closedMsgCd, closeInfo.join("^")));
				return false;
			}
		}
	}

	return true;
}

