/**
 * 함수명   : Pr10ComBase.gfn_generateUuid
 * 함수설명 : UUID생성
 * 파라메터 : N/A
 * 리턴     : N/A
 * 작성일   : 2023.10.26
 * 작성자   : 윤영국
 */
Pr10ComBase.gfn_generateUuid = function() {
	var uuid = "";
	var cryptoEx = window.crypto ? window.crypto : (window.msCrypto ? window.msCrypto : null);

	if (cryptoEx != null) {
		try {
			uuid = "10000000-1000-4000-8000-100000000000".replace(
					/[018]/g,
					function(c) {
						return (c ^ cryptoEx.getRandomValues(new Uint8Array(1))[0] & 15 >> c / 4).toString(16);
					});
		} catch (e) {
			console.log(e);
		}
	}

	if (Pr10ComBase.gfn_isEmpty(uuid)) {
		uuid = Date.now() + "-" + Math.random().toString(36).substring(2);
	}

	return uuid;
}

/**
 * 함수명   : Pr10ComBase.gfn_checkApfrmLock
 * 함수설명 : 신청서락 체크
 * 파라미터 : N/A
 * 리턴     : N/A
 * 작성일   : 2024.03.11
 * 작성자   : 윤영국
 */
Pr10ComBase.gfn_checkApfrmLock = function(apfrmList, callbackFn) {
	var options = {
		"id" : "sbm_Pr10AwrtWrtCsCtrl_checkApfrmLock_Ext",
		"action" : "/biz/Pr10AwrtWrtCsCtrl/checkApfrmLock.do",
	};

	if (Pr10ComBase.gfn_isEmpty(Pr10ComBase._sbmApfrmLock)) {
		Pr10ComBase._sbmApfrmLock = com.sbm.create(options);
	}

	var checkApfrmLockList = com.util.isArray(apfrmList) ? apfrmList : [apfrmList];
	var reqData = {
		"checkApfrmLockList" : checkApfrmLockList
	};

	Pr10ComBase.gfn_executeSbmExt(
		Pr10ComBase._sbmApfrmLock,
		reqData,
		function(e) {	// submitdone
			var responseJSON = e && e.responseJSON ? e.responseJSON : {};
			var resultList = responseJSON.resultList ? responseJSON.resultList : [];
			var len = resultList.length;
			if (len < 1) {
				// {0}(을)를 수행하는 도중 오류가 발생했습니다.
				com.message.openMessage(Pr10ComBase.gfn_getMessagePopupOption("info", "pr10.message.create.web.com.0034", "신청서락 체크"));
				return;
			}
			for (var i = 0; i < len; i++) {
				// 신청서 Lock 여부
				var apfrmLockYn = resultList[i].lock_yn;
				// Lock 여부 체크
				if (apfrmLockYn == "Y") {
					var msgArgs = resultList[i].enr_recev_no;
					msgArgs = Pr10ComBase.gfn_isEmpty(msgArgs) ? "" : "작성번호[" + msgArgs + "]: ";				
