					com.message.openMessage(Pr10ComBase.gfn_getMessagePopupOption("info", "pr10.message.info.web.awrt.0103", msgArgs));
					return;
				}
			}

			if (callbackFn) {
				callbackFn(resultList);
			}
		}
	);
}

/**
 * 함수명   : Pr10ComBase.gfn_getPilotOpenInfo
 * 함수설명 : 시범운영단계 정보를 조회한다.
 * 파라메터 : 
 * 리턴     : 시범운영단계여부, 시범운영단계, 시범운영등기소목록
 * 작성일   : 2024.08.08
 * 작성자   : 이혜영
 */
Pr10ComBase.gfn_getPilotOpenInfo = function() {
	// 1. 시범운영 및 운영 단계에 해당하지 않는 경우 : ready
	// 2. 1-1단계 : demon1-1
	// 3. 1-2단계 : demon1-2
	// 4. 2단계 : demon2
	// 5. 최종오픈 : open
	var strOpenLevel = WebSquareExternal.systemOpenLevel;
	var boolPilot = false;

	//1단계:테스트등기소, 2단계:시범등기소
	if ("ready" == strOpenLevel) {
		boolPilot = false;
	} else if ("demon1-1" == strOpenLevel) {
		boolPilot = true;
	} else if ("demon1-2" == strOpenLevel) {
		boolPilot = true;
	} else if ("demon2" == strOpenLevel) {
		boolPilot = true;
	} else if ("open" == strOpenLevel) {
		boolPilot = false;
	} else {
		// 알수없음
		boolPilot = false;
	}

	var pilotRegtList = "";
	if (boolPilot) {
		Pr10ComBase.gfn_executeSyncSubmission("/biz/Pr10ComPropertyBaseCtrl/retrievePilotOpenInfo.do").done(function(e) {
			pilotRegtList = e.responseJSON.pilotRegtList;
		});
	}

	// 예시 [ready, "1101,1102,1188"]
	var result = {
		'pilot' : boolPilot,
		'openLevel' : strOpenLevel, 
		'pilotRegtList' : pilotRegtList
	}

	return result;
}

/**
 * 함수명   :  fn_refineSmplSrchSwrd
 * 함수설명 :  간편검색 시 검색어를 정제한다
 * 파라미터 :  swrd 검색어
 * 리턴    : 정제된검색어
 * 작성일   : 2025.04.18 (2025-W00113)
 * 작성자   : 천세영
 */
Pr10ComBase.fn_refineSmplSrchSwrd = function(swrd) {
	return swrd.split(' ').reduce(
			function(acc,val) { 
				return acc + ' ' + (val.match(/^산?(\d+-)?\d+번지$/)?val.replace('번지',''):val);
			}, '').trim();
}

/**
 * 함수명   : fn_removeSpecialChar
 * 함수설명 : 전달받은 파라미터 문자열의 특수문자와 스페이스를 제거한다.
