 * 작성일   : 2026.05.20 (2026-W00338)
 * 작성자   : 천세영
 */
Pr10ComBase.fn_removeSpecialChar = function(pStrValue) {
	var rStrValue = "";
	const regChar = /[\\`<>~'"_|+=/?!@#$%\^&*(){}\[\],\.\-\s]/g;

	if(pStrValue != null) {
	    rStrValue = pStrValue.replace(regChar, "");
	}

	return rStrValue;
}

