			vrfyType = ["alphabet", "chinese", "numeric", " &',-.·"];
			break;
		case "alphaChinaNumeric02":
			vrfyType = ["alphabet", "chinese", "numeric", " &'(),-.·"];
			break;
		case "noAlphabetic":
			vrfyType = ["noalphabet"];
			break;
		case "specialChar01":
			vrfyType = ["!@^"];
			break;
		break;
	}
	
	// 입력값제한 체크
	if (vrfyType != null) {
		var len = chkVal.length;
		for (var i = 0; i < len; i++) {
			if (!Pr10ComUtil.gfn_verifyInputChar(chkVal.charCodeAt(i), vrfyType)) {
				return false;
			}
		}
	}
	
	return true;
}

/**
 * 함수명   : Pr10ComUtil.gfn_changeNumToKor
 * 함수설명 : 숫자를 한글로 변환
 * 파라메터 : N/A
 * 리턴     : N/A
 * 작성일   : 2022.08.30
 * 작성자   : 강명진
 */
Pr10ComUtil.gfn_changeNumToKor = function(obj1, obj2) {
    var str = "";
    var num = Pr10ComUtil.gfn_delComma(obj1.getValue());
    var digit = new Array();
    var j = num.length - 1;

    // 숫자인지 확인
    var charpos = num.search("[^0-9]");

    if (num.length > 0) {
        var num_first = num.substring(0, 1);
        if (num_first == "0") {
            obj1.setValue("");
            obj2.setValue("");
            obj1.focus();
            return;
        }
    }

    var flag = true;
    
    for (var i = 0; i < num.length; i++) {
        digit[j] = num.charAt(i); // 숫자를 거꾸로 담는다.(배열에 reverse()라는 function이 이 역할을 한다.)

        str += Pr10ComUtil.gfn_changeNumToKor2(digit[j]);

        /*------------------------------------------------------------------*/
        /* 숫자가 0이 아닐 경우 단위 무조건 판별 */
        /* 숫자가 0인 경우 인덱스가 4로 나누어 떨어지는 경우(만, 억, 조) 중 */
        /* 하나만 선택할 수 있도록 flag를 둔다. */
        /*------------------------------------------------------------------*/
        if (digit[j] != "0" || (j % 4 == 0) && flag) {
	        if (j == 0) {
		        str += "";
		        continue;
	        }
	        
	        var namerji = j % 4;
            var han;
            
            switch (namerji) {
                case 0:
                    if (j / 4 == 1) {
                        han = "만";
                        flag = false;
                    } else if (j / 4 == 2) {
                        han = "억";
                        flag = false;
                    } else if (j / 4 == 3) {
                        han = "조";
                        flag = false;
                    }
                    break;
                case 1:
                    han = "십";
                    flag = true;
                    break;
                case 2:
                    han = "백";
                    flag = true;
                    break;
                case 3:
                    han = "천";
                    flag = true;
                    break;
            }
            
            str += han;
        }
        j--;
    }// end for

    if (str != "") {
        obj2.setValue(str);
    } else {
        obj2.setValue("");
    }
}

