/**
 * 함수명   : Pr10SolnCert.fn_checkDsFileExtn
 * 함수설명 : 전자서명파일확장자체크
 * 파라메터 : N/A
 * 리턴     : N/A
 * 작성일   : 2022.10.25
 * 작성자   : 윤영국
 */
Pr10SolnCert.fn_checkDsFileExtn = function(fileName) {
	// pdf파일인지 체크_마지막확장자가 sig이어야.첫sig확장자앞의 확장자는 pdf여야하고, sig확장자뒤의 확장자는 sig이어야한다.
	var firstIndex = -1;
	var tempArr = fileName.split(".");
	var len = tempArr.length;
	for (var i = 0; i < len; i++) {
		var item = tempArr[i];
		if (firstIndex == -1) {
			if (item == "sig") {
				firstIndex = i;
				// 첫 sig 확장자 앞의 확장자가 pdf가 아닌 경우
				if (i > 0 && tempArr[i - 1].toLowerCase() != "pdf") {
					return false;
				}
			}
		} else {
			// sig 확장자 뒤의 모든 확장자는 sig이어야한다.
			if (i > firstIndex && item != "sig") {
				return false;
			}
		}
	}

	// 파일명에 sig 확장자가 없거나 sig, pdf.sig 등 제외
	if (firstIndex == -1 || len < 3) {
		return false;
	}

	return true;
}

/**
 * 함수명   : Pr10SolnCert.fn_splitSignFile
 * 함수설명 : 분리서명파일생성
 * 파라메터 : N/A
 * 리턴     : N/A
 * 작성일   : 2023.05.18
 * 작성자   : 윤영국
 */
Pr10SolnCert.fn_splitSignFile = function(paramData, callbackFn) {
	var retData = Pr10SolnCert.fn_getSplitSignParam(paramData);

	//인증서팝업타입 적용
	if(retData && !EgovNrsComBase.gfn_isMobile()){
		Pr10SolnCert.fn_setSignPopupType(retData.signOptions.certGubun);
	}

	com.anySign.splitSignFile(retData.fileData, retData.signOptions, function(resData) {
		console.log("########## com.anySign.splitSignFile : callback", resData);
		if (resData && resData.signFileInfoMap) {
			var signedFileSubPath = resData.signFileInfoMap.nas_signed_file_sub_path;
			if (Pr10ComBase.gfn_isNotEmpty(signedFileSubPath)) {
				resData.signed_file_name = signedFileSubPath.split(/[/\\]/g).pop();	// 파일명 추출
				resData.signed_file_sub_path = signedFileSubPath;
			}
		} else {
			// {0}(을)를 수행하는 도중 오류가 발생했습니다.
			com.message.openMessage(Pr10ComBase.gfn_getMessagePopupOption("info", "pr10.message.create.web.com.0034", "전자서명"));
			return;
		}

		// 콜백함수 호출
		if (callbackFn) {
			callbackFn(resData);
		}
	});
}

