/**
 * 함수명   : Pr10SolnCert.fn_getSplitSignParam
 * 함수설명 : 분리서명을 위한 파라미터 조회
 * 파라메터 : N/A
 * 리턴     : N/A
 * 작성일   : 2023.05.30
 * 작성자   : 윤영국
 */
Pr10SolnCert.fn_getSplitSignParam = function(paramData) {
	var retData = {};

	var defFileData = {
			"nas_prop_key" : "pr10.system.edm.tempdir",
			"org_file_del_yn" : "Y",
		};

	var fileData = paramData.fileData;
	if (Pr10ComBase.gfn_isEmpty(fileData)) {
		var fileName = paramData.nas_target_file_sub_path;
		if (Pr10ComBase.gfn_isEmpty(fileName)) {
			var subPath = paramData.sub_path ? paramData.sub_path : "/FE00/";
			// 멀티파일
			if (paramData.type == "M") {
				fileName = subPath + paramData.fileList.join("&" + subPath);
			} else {
				fileName = subPath + paramData.file_name;
			}
		}
		fileData = Object.assign({"nas_target_file_sub_path" : fileName}, paramData);
	}
	retData.fileData = Object.assign(defFileData, fileData);

	var signOptions = paramData.signOptions;
	if (Pr10ComBase.gfn_isEmpty(signOptions)) {
		var certType = paramData.cert_type;
		if (Pr10ComBase.gfn_isEmpty(certType)) {
			if (Pr10ComBase.gfn_getUserClsYn("E")) {	// 촉탁사용자
				certType = "GPKI";
			} else if (Pr10ComBase.gfn_getUserClsYn("R")) {	// 법인대표
				certType = "RPKI";
			} else {
				certType = "NPKI";
			}
		}

		signOptions = {"certGubun" : certType};
	}

	retData.signOptions = signOptions;

	return retData;
}

/**
 * 함수명   : Pr10SolnCert.fn_setSignPopupType
 * 함수설명 : 인증서팝업 타입 적용
 * 파라메터 : N/A
 * 리턴     : N/A
 * 작성일   : 2024.05.02
 * 작성자   : 이혜영
 */
Pr10SolnCert.fn_setSignPopupType = function(certType) {	
	//인증서팝업옵션 적용
	if(certType == "RPKI"){
		AnySignProp.signType = "AnySign"; //공동인증서탭 활성화
	}else {
		AnySignProp.signType = "AnySignAll"; //공동인증서+금융인증서탭 활성화
	}	
}

/**
 * 함수명   : Pr10SolnCert.fn_getDsObjFileListForSbmt
 * 함수설명 : 멀티파일 분리서명을 위한 파일목록 조회
 * 파라메터 : N/A
 * 리턴     : N/A
 * 작성일   : 2023.05.30
 * 작성자   : 윤영국
 */
Pr10SolnCert.fn_getDsObjFileListForSbmt = function(paramList) {
	var fileList = [];
	if (paramList) {
		var len = paramList.length;
		for (var i = 0; i < len; i++) {
			var edmsEnrDir = paramList[i].edms_pk;
			edmsEnrDir = Pr10ComBase.gfn_isEmpty(edmsEnrDir) ? "" : edmsEnrDir + "/";
			// XML
			if (paramList[i].xmlInfo) {
				fileList.push(edmsEnrDir + paramList[i].xmlInfo.xml_name);
			}
			// 첨부문서
			if (paramList[i].attFileList) {
				var len2 = paramList[i].attFileList.length;
				for (var j = 0; j < len2; j++) {
					if (paramList[i].attFileList[j].edmsFileList) {
						var len3 = paramList[i].attFileList[j].edmsFileList.length;
						for (var k = 0; k < len3; k++) {
							fileList.push(edmsEnrDir + paramList[i].attFileList[j].edmsFileList[k].file_name);
						}
					}
				}
			}
		}
	}
	return fileList;
}

/**
 * 함수명   : Pr10SolnCert.fn_getSplitSignMultiFileName
 * 함수설명 : 멀티파일 분리서명을 위한 파일명 조회
 * 파라메터 : N/A
 * 리턴     : N/A
 * 작성일   : 2023.06.16
 * 작성자   : 윤영국
 */
Pr10SolnCert.fn_getSplitSignMultiFileName = function(paramList) {
	var splitSignMultiFileName = "";
	if (paramList && paramList.length > 0) {
		var fileList = [];
		var len = paramList.length;
		for (var i = 0; i < len; i++) {
			fileList.push(paramList[i].sub_path + paramList[i].file_name);
		}
		splitSignMultiFileName = fileList.join("&")
	}
	return splitSignMultiFileName;
}

/**
 * 함수명   : Pr10SolnCert.fn_verifyOtpAthnNo
 * 함수설명 : OTP인증번호검증
 * 파라메터 : N/A
 * 리턴     : N/A
 * 작성일   : 2023.12.19
 * 작성자   : 윤영국
 */
Pr10SolnCert.fn_verifyOtpAthnNo = function(paramData, callbackFn) {
	var options = {
		"id"     : "__sbm_Pr10StatDsCtrl_retrieveOtpIssueInfo",
		"action" : "/biz/Pr10StatDsCtrl/retrieveOtpIssueInfo.do",
		"mediatype" : "application/json",
	};
	var sbmObj = com.sbm.create(options);
	var reqData = paramData;
	Pr10ComBase.gfn_executeSbmExt(
		sbmObj,
		reqData,
		function(e) {
			var resJson = e.responseJSON;
			if (Pr10ComBase.gfn_isNotEmpty(resJson) && Pr10ComBase.gfn_isNotEmpty(resJson.nrsMessageCd)) {
				com.message.openMessage(Pr10ComBase.gfn_getMessagePopupOption("info", resJson.nrsMessageCd), function(result) {
					callbackFn("FAIL");
				});
			} else {
				var result = resJson.result ? resJson.result : {};
				if (Pr10ComBase.gfn_isEmpty(result.bcd_no)) {
//					// OTP 발급정보를 조회할 수 없습니다.
//					com.message.openMessage(Pr10ComBase.gfn_getMessagePopupOption("info", "pr10.message.info.biz.stat.0021"), function(result) {
//						callbackFn("FAIL");
//					});
					callbackFn("SUCC");
				} else if (Pr10ComBase.gfn_isEmpty(result.otp_bcd_no)) {
					// OTP 발급정보를 조회할 수 없습니다. 8월1일부로 OTP인증이 필수가 됨에따라 미발급 시 안내메세지 출력. 이기호.
					com.message.openMessage(Pr10ComBase.gfn_getMessagePopupOption("info", "pr10.message.info.biz.stat.0021"), function(result) {
						callbackFn("FAIL");
					});
				} else {
					var popupUrl = "/ui/pr10/stat/Pr10StatOtpAthn.xml";
					var popupOption = {
						popupName : "OTP 인증",
						width : 600,
						height : 400,
						modal : true,
					};
					var popupParam = result;
					popupParam.callbackFn = function(popupRslt) {
						callbackFn(popupRslt);
					}
					var passLoginCheck = true;
					Pr10ComBase.gfn_openPopup(popupUrl, popupOption, popupParam, passLoginCheck);
				}
			}
		},
		null,
		null,
		true
	);
}

