	/**
	 * 함수명   : Ps10ComBase.gfn_chkDate
	 * 함수설명 : 날자의 유효성을 체크한다.
	 * 파라메터 : 체크할 값
	 * 리턴     : 체크결과(true/false)
	 * 작성일   : 2022.06.27
	 * 작성자   : 한재준
	 */

	Ps10ComBase.gfn_chkdate = function(date) {

	    var iYear = date.substr(0,4);
	    var iMonth = date.substr(4,2);
	    var iDay = date.substr(6,2);    
	    var monthArr = new Array(31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31);

	    if( iMonth == 2 ) {
	        if ( ( (iYear % 4 == 0) && (iYear % 100 != 0) ) || (iYear % 400 == 0) ) {
	            monthArr[1] = "29";
	        }
	    }

	    if (date.length != 8) {    	
	        return false;
	    }

	    if( iYear < 9999 && iYear > 0 && iMonth <= 12 && iMonth > 0 && iDay <= monthArr[iMonth-1] && iDay > 0 ) {
	        return true;
	    }

	};

	/**
	 * 함수명   : Ps10ComBase.gfn_chkjonsokterm
	 * 함수설명 : 담보권 존속기간을 체크한다.
	 * 파라메터 : 담보권시작일, 담보권종료일
	 * 리턴     : 체크결과(true/false)
	 * 작성일   : 2022.12.07
	 * 작성자   : 장영동
	 */
	Ps10ComBase.gfn_chkjonsokterm = function(startDate, endDate) {
		var chkEndtYear = parseInt( startDate.substr(0,4) ) + 5; //기준종료년도(시작일자+5년)
		var chkEndDate = chkEndtYear + startDate.substr(4,2) + startDate.substr(6,2); // 기준종료일자

		if( chkEndDate - endDate < 0 ){ //기준종료일자 < 종료일자
			return false;
		}
		return true;
	}

	/**
	 * 함수명   : Ps10ComBase.gfn_make_jonsok
	 * 함수설명 : 입력받은 날짜정보로 담보권존속기간을 만들어 준다
	 * 파라메터 : 시작일, 종료일
	 * 리턴     : YYYY년 MM월 DD일부터 YYYY년 MM월 DD일까지
	 * 작성일   : 2022.12.07
	 * 작성자   : 장영동
	 */
	Ps10ComBase.gfn_make_jonsok = function(startDate,endDate) {
		var makeVal = "";
		var makeSpace = "";

		if (startDate != "" && startDate != null) {
			makeVal = Ps10ComBase.gfn_make_ymd(startDate,"YYYY");
			makeVal += " " + Ps10ComBase.gfn_make_ymd(startDate,"MM");
			makeVal += " " + Ps10ComBase.gfn_make_ymd(startDate,"DD");
			makeVal += "부터";
			makeSpace = " ";
		}
		if (endDate != "" && endDate != null) {
			makeVal += makeSpace + Ps10ComBase.gfn_make_ymd(endDate,"YYYY");
			makeVal += " " + Ps10ComBase.gfn_make_ymd(endDate,"MM");
			makeVal += " " + Ps10ComBase.gfn_make_ymd(endDate,"DD");
			makeVal += "까지";
		}
		return makeVal;
	};

	/**
	 * 함수명   : Ps10ComBase.gfn_make_ymd
	 * 함수설명 : 년월일을 만든다.
	 * 파라메터 : 대상일자, 연월일
	 * 리턴     : 년원일타입 text
	 * 작성일   : 2022.12.07
	 * 작성자   : 장영동
	 */
	Ps10ComBase.gfn_make_ymd = function(obj,ymd) {
		var returnVal = "";
		if (ymd == "YYYY" || ymd == "yyyy") {
			returnVal = Number(obj.substr(0,4))+"년";
		}
		if (ymd == "MM" || ymd == "mm") {
			returnVal = Number(obj.substr(4,2))+"월";
		}
		if (ymd == "DD" || ymd == "dd") {
			returnVal = Number(obj.substr(6,2))+"일";
		}
		return returnVal;
	};

	/**
	 * 함수명   : Ps10ComBase.fn_addHiddenFromJson
	 * 함수설명 : Json데이터의 Key에 hdn_ 을 붙여 추가한다.
	 * 파라메터 : 문자
	 * 리턴     : 문자
	 * 작성일   : 2022.06.28
	 * 작성자   : 한재준
	 */
	Ps10ComBase.fn_addHiddenFromJson = function(jsonData) {
		var keys = Object.keys(jsonData);
		var newJson = {};

		for (var i=0; i<keys.length; i++) {
			var key = keys[i];
			var addKey = "hdn_" + key;
			newJson[key] = jsonData[key];
			newJson[addKey] = jsonData[key];
		}

	   return newJson;
	};

	/**
	 * 함수명   : Ps10ComBase.fn_addHiddenFromJsonList
	 * 함수설명 : JsonList 데이터의 Key에 hdn_ 을 붙여 추가한다.
	 * 파라메터 : json 리스트
	 * 리턴     : json 리스트
	 * 작성일   : 2022.11.25
	 * 작성자   : 장영동
	 */
	Ps10ComBase.fn_addHiddenFromJsonList = function(jsonList) {
	    var resultJson = [];
		for (var i=0; i<jsonList.length; i++) {
		   resultJson[i] = Ps10ComBase.fn_addHiddenFromJson(jsonList[i]);
		}
	    return resultJson;
	};

	/**
	 * 함수명   : Ps10ComBase.fn_removeHiddenFromJson
	 * 함수설명 : Json데이터의 Key에 hdn_ 을 제거하여 추가한다.
	 * 파라메터 : 문자
	 * 리턴     : 문자
	 * 작성일   : 2022.06.28
	 * 작성자   : 한재준
	 */
	Ps10ComBase.fn_removeHiddenFromJson = function(jsonData) {
		var keys = Object.keys(jsonData);
