	/**
	 * 함수명   : Ps10ComBase.fn_addHiddenFromDataMap
	 * 함수설명 : Datamap에 Key에 hdn_ 을 추가한다.
	 * 파라메터 : 문자
	 * 리턴     : 문자
	 * 작성일   : 2022.06.28
	 * 작성자   : 한재준
	 */
	Ps10ComBase.fn_addHiddenFromDataMap = function(dataMap) {
		 var objInfo = dataMap.getInfo();	 

		 var keyCnt = dataMap.getCount();	 
		 for(var i = 0; i < keyCnt; i++) {
			 var keyName = dataMap.getKey(i);

			 if ( new RegExp("hdn_").test(keyName)) {
			     continue;		   
			 } 

			 var keyValue = dataMap.get(keyName);  
			 var hdnKeyName = "hdn_" + keyName;
			 dataMap.set(hdnKeyName, keyValue);		                   
		 }
	};

	/**
	 * 함수명   : Ps10ComBase.fn_convertToSnake
	 * 함수설명 : Json데이터의 Key를 스네이크로 변환한다.
	 * 파라메터 : 문자
	 * 리턴     : 문자
	 * 작성일   : 2023.01.18
	 * 작성자   : 장영동
	 */
	Ps10ComBase.fn_convertToSnake = function(jsonData) {
		var keys = Object.keys(jsonData);
		var newJson = {};

		for (var i=0; i<keys.length; i++) {
			var key = keys[i];
			var snakeKey = key.replace(/[A-Z]/g, (c) => { return '_' + c.toLowerCase() });
			newJson[key] = jsonData[key];
			newJson[snakeKey] = jsonData[key];
		}
		return newJson;
	};

