	 * 작성자   : 장영동
	 */
	Ps10ComBase.fn_convertToSnakeJsonList = function(jsonList) {
	    var resultJson = [];
		for (var i=0; i<jsonList.length; i++) {
		   resultJson[i] = Ps10ComBase.fn_convertToSnake(jsonList[i]);
