	/**
	 * 함수명   : fn_getEnrNoByEnrNoCls
	 * 함수설명 : 전달받은 파라미터 등록번호구분에 따라 파라미터 등록번호에 하이픈을 추가하여 반환한다.
	 *            하이픈 추가대상 : 내국인, 재외국민, 외국인, 법인 
	 * 파라미터 : {String} 변환대상 등록번호
	 *          : {String} 등록번호구분 
	 *                     내국인 : 12911, 재외국민 : 12912, 외국인 :12913, 법인 : 12921, 비법인 : 12931, 국가기관 : 12941
	 * 리턴     : {String} 변환결과 문자열
	 * 작성일   : 2022.08.08
	 * 작성자   : 
	 */
	Ps10ComBase.fn_getEnrNoByEnrNoCls = function(strEnrNo, strEnrNoCls) {
		var regExpNum = /[^0-9]/g;
		var strOnlyNum = strEnrNo.replace(regExpNum, '');
		var strTmp ='';

		var bHypoon = false;
		if (strEnrNoCls == '12913' 
			 || strEnrNoCls == '12911' 
		     || strEnrNoCls == '12912'
			 || strEnrNoCls == '12921') {
			bHypoon = true;
		}

		if (bHypoon) {
			//console.log("문자길이 : " + strOnlyNum.length);
			if (strOnlyNum.length < 6) {
				strTmp = strOnlyNum; 
			} else if (strOnlyNum.length >= 6 ) {
				strTmp += strOnlyNum.substr(0, 6);
				strTmp += '-';
				strTmp += strOnlyNum.substr(6);
			}
		} else {
			strTmp = strOnlyNum; 
		}

		return strTmp.substr(0,14);
	};

