	Ps10ComBase.fn_maxLenValid  = function(obj, maxLen) {
		if( obj.length <= 0 ) return true;

		//한글 2바이트로 계산
		var len = 0;
		for(var idx=0 ; idx < obj.length; idx++, len++) {
			if((obj.charCodeAt(idx)<0) || (obj.charCodeAt(idx)>127) ) len++; //add extra length
		}

		if( com.num.parseInt(len) > com.num.parseInt(maxLen)) {		
			//alert("최대 " + maxLen + "자까지만 입력가능합니다.\n(한글한자 2자, 그 외 1자로 적용됩니다.)");
			return false;
		}

		return true;
	}	

