	/**
	 * 함수명   : fn_regNoValid
	 * 함수설명 : 등록번호를 검증한다.    (구)ECOMValidations.js f_regNoValid()
	 * 파라메터 : 문자
	 * 리턴     : 검증결과
	 * 작성일   : 2023.03.08
	 * 작성자   : 장영동
	 */
	Ps10ComBase.fn_regNoValid = function(regNoTpCd, enrNo) {
		// 비법인 : 12931, 국가기관 : 12941, 미등기 외국법인 : 1D402
		if((regNoTpCd == "12931" && enrNo.length != 14) 
			|| regNoTpCd == "12941" 
			|| regNoTpCd == "1D402"
			|| regNoTpCd == "" 
			|| regNoTpCd.substring(0,4) == "1439"){
			return true;
		}

		//등록번호에 [-]이 없는 경우 붙여준다.
		if(enrNo.indexOf("-") != -1){
			enrNo = enrNo.substring(0,6) + enrNo.substring(7,enrNo.length);
		}

		if(enrNo.length != 13){ // 자리수체크
			return false;
		}

		if(regNoTpCd == "12911" || regNoTpCd == "12912" || regNoTpCd == "12913"){ // 내국인, 재외국민, 외국인
			var strBirthMonth = enrNo.substring(2,4);
			var strBirthDay = enrNo.substring(4,6);

			if(parseInt(strBirthMonth) > 12 || parseInt(strBirthDay) > 31){ // 생년월일 체크
				return false;
			}
		}

		var i = 0;
		var arr = new Array(13);
		while(i < 13){
			arr[i] = parseInt(enrNo.substring(i,i+1));
			i++;
		}

		if(regNoTpCd == "12913"){ // 외국인
			// Male Female check 9,0:1800년대 5,6:1900년대, 7,8:2000년대
			if(arr[6] == 1 || arr[6] == 2 || arr[6] == 3 || arr[6] == 4){
				return false;
			}

			// 등록기관 - 짝수이어야함
			var iOdd = arr[7]*10 + arr[8];
			//If SalNumberMod( nOdd, 2 ) != 0
			//Return FALSE

			// 분류 6,7,8,9
			if(arr[11] != 6 && arr[11] != 7 && arr[11] != 8 && arr[11] != 9){
				return false;
			}
		}

		if(regNoTpCd == "12911"){ // 내국인
			// Male Female check 9,0:1800 1,2:1900, 3,4:2000 5,6:2100 7,8:2200
			if(arr[6] == 5 || arr[6] == 6 || arr[6] == 7 || arr[6] == 8){
				return false;
			}
		}

		var iMultipliers = new Array(12);
		// 권리자의 각 구분에 따라 등록번호의 마지막 자릿수(CHECK DIGIT)체크하여
		// 등록번호가 제대로 입력되었는지 확인한다.
		if(regNoTpCd == "12911" || regNoTpCd == "12913" ){ // 내국인, 외국인
			var i=0;
			var iSum = 0;

			iMultipliers[0] = 2;
			iMultipliers[1] = 3;
			iMultipliers[2] = 4;
			iMultipliers[3] = 5;
			iMultipliers[4] = 6;
			iMultipliers[5] = 7;
			iMultipliers[6] = 8;
			iMultipliers[7] = 9;
			iMultipliers[8] = 2;
			iMultipliers[9] = 3;
			iMultipliers[10] = 4;
			iMultipliers[11] = 5;

			while(i<12){
				arr[i] = arr[i]*iMultipliers[i];
				iSum = iSum + arr[i];
				i++;
			}

			iSum = 11 - iSum%11;
			//Set nSum = 11 - ( SalNumberMod( nSum , 11 ) )

			if(iSum >= 10){
				iSum = iSum - 10;
			}

			if(regNoTpCd == "12913"){ // 외국인
				iSum = iSum + 2;
				if(iSum >= 10){
					iSum = iSum - 10;
				}
			}

			if(iSum != arr[12]){
				return false;
			}
		}

		// 등록번호가 제대로 입력되었는지 확인한다.
		if(regNoTpCd == "12912" || regNoTpCd == "12921" || ((regNoTpCd == "12931" || regNoTpCd == "1D401") && enrNo.length == 13)){ // 재외국민, 법인, 비법인(종중), 외국법인(등기)
			var i=0;
			var iSum = 0;

			iMultipliers[0] = 1;
			iMultipliers[1] = 2;
			iMultipliers[2] = 1;
			iMultipliers[3] = 2;
			iMultipliers[4] = 1;
			iMultipliers[5] = 2;
			iMultipliers[6] = 1;
			iMultipliers[7] = 2;
			iMultipliers[8] = 1;
			iMultipliers[9] = 2;
			iMultipliers[10] = 1;
			iMultipliers[11] = 2;

			while(i < 12){
				arr[i] = arr[i]*iMultipliers[i];
				iSum = iSum + arr[i];
				i++;
			}

			iSum = 10 - iSum%10;
			if(iSum == 10){
				iSum = 0;
			}
			if(iSum != arr[12]){
				return false;
			}
		}
		return true;	
	};

	/**
	 * 함수명   : fn_numToHan
	 * 함수설명 : 숫자로된 금액을 한글로 변환  (구)ECOMCommon.js f_numToHan()
	 * 파라메터 : 숫자
	 * 리턴     : 한글
	 * 작성일   : 2022.10.18
	 * 작성자   : 장영동
	 */
	var ps10ComBaseAmtFlag = true; // 단위 판별 플래그
	Ps10ComBase.fn_numToHan = function(amt) {

		var str   = "";
		var num   = amt;
		var digit = new Array();
		var j     = num.length - 1;

		//숫자인지 확인
		var charpos = num.search( "[^0-9]" );

		if( num.length > 0 &&  charpos >= 0 ) {
			return;
		}else if(num.length > 0 ){
			var num_first = num.substring(0,1);
			if(num_first == "0"){
				return;
			}
		}

		// 단위가 천조를 넘을 경우
		if (num.length > 16){
			return;
		}

		for (var i = 0; i < num.length; i ++){
			digit[j] = num.charAt(i); // 숫자를 거꾸로 담는다.(배열에 reverse()라는 function이 이 역할을 한다.)

			str += Ps10ComBase.fn_numToHan2(digit[j]);

			/*------------------------------------------------------------------*/
			/* 숫자가 0이 아닐 경우 단위 무조건 판별 */
			/* 숫자가 0인 경우 인덱스가 4로 나누어 떨어지는 경우(만, 억, 조) 중 */
			/* 하나만 선택할 수 있도록 ps10ComBaseAmtFlag를 둔다. */
			/* 잘 이해가 안되면 ps10ComBaseAmtFlag를 빼고 1억을 쳐보셈... ^^; */
			/*------------------------------------------------------------------*/
			if (digit[j] != "0" || (j % 4 == 0) && ps10ComBaseAmtFlag)
				str += Ps10ComBase.fn_danwiToHan(j);
				j --;
		}//end for

		if (str != ""){
			return str;
		}else{
			return;
		}

	};//end function

	/**
	 * 함수명   : fn_numToHan2
	 * 함수설명 : 숫자로 된 문자열을 입력받아 숫자에 해당하는 한글명을 리턴한다  (구)ECOMCommon.js f_numToHan2()
	 * 파라메터 : 숫자
	 * 리턴     : 한글
	 * 작성일   : 2022.10.18
	 * 작성자   : 장영동
	 */
	Ps10ComBase.fn_numToHan2 = function(val) {
		switch(Number(val)){
		case 1 : han = "일"; break;
		case 2 : han = "이"; break;
		case 3 : han = "삼"; break;
		case 4 : han = "사"; break;
		case 5 : han = "오"; break;
		case 6 : han = "육"; break;
		case 7 : han = "칠"; break;
		case 8 : han = "팔"; break;
		case 9 : han = "구"; break;
		case 0 : han = ""; break;
		}

		return han;
	};

	/**
	 * 함수명   : fn_danwiToHan
	 * 함수설명 : 숫자의 인덱스를 입력받아 단위에 해당하는 한글명을 리턴한다.    (구)ECOMCommon.js f_danwiToHan()
	 * 파라메터 : 숫자
	 * 리턴     : 한글
	 * 작성일   : 2022.10.18
	 * 작성자   : 장영동
	 */
	Ps10ComBase.fn_danwiToHan = function(val) {
		/* 일 단위는 Skip */
		if (val == 0)
		return "";

		var namerji = val % 4;

		switch(namerji){
		case 0: // 나머지가 '0'이면 만, 억, 조 중에 하나이다.
			if (val / 4 == 1) {
			han  = "만";
			ps10ComBaseAmtFlag = false;

			} else if (val / 4 == 2) {
			han  = "억";
			ps10ComBaseAmtFlag = false;

			} else if (val / 4 == 3) {
			han = "조";
			ps10ComBaseAmtFlag = false;
			}
			break;
			case 1: // 나머지가 '1'이면 십단위이다.
				han = "십"; ps10ComBaseAmtFlag = true; break;
			case 2: // 나머지가 '2'이면 백단위이다.
				han = "백"; ps10ComBaseAmtFlag = true; break;
			case 3: // 나머지가 '3'이면 천단위이다.
				han = "천"; ps10ComBaseAmtFlag = true; break;
		}//end switch

		return han;
	};


	/**
	 * 함수명   : Ps10ComBase.gfn_isEmpty
	 * 함수설명 : 빈값체크 함수
	 * 파라메터 : 체크할 값
	 * 리턴     : 체크결과(true/false)
	 * 작성일   : 2022.12.30
	 * 작성자   : 장영동
	 */
	Ps10ComBase.gfn_isEmpty = function(value) {
		// 기본 체크
		if (com.util.isEmpty(value) == true) {
			return true;
		}		

		// Array
		if (com.util.isArray(value)) {
			if (value.length == 0) {
				return true;
			}

		// Object
		} else if (com.util.isPlainObject(value) && Object.keys(value).length === 0) {
			return true;
		}

		return com.util.isEmpty(value);
	};


