	/**
	 * 함수명   : Ps10ComBase.gfn_stringAddComma
	 * 함수설명 : 문자열의 ','문자를 추가(화폐단위 및 실수에 자동으로 3자리 쉼표)한 문자를 반환한다.
	 * 파라메터 : {String} 변환대상 문자열
	 * 리턴     : {String} 변환결과 문자열
	 * 작성일   : 2022.05.01
	 * 작성자   : 한재준
	 */	
	Ps10ComBase.gfn_stringAddComma = function(strVal) {

		var str = Ps10ComBase.gfn_stringRemoveComma(strVal);

		if (str.length < 1) {
			return "";
		} else {
			var tm = "";
			var ck = "";
			var tm1 = "";
			var tm2 = "";

			if (str.substring(0, 1) == "-") {
				tm = str.substring(1, str.length);
				ck = "Y";
			} else {
				tm = str;
				ck = "N";
			}
			// 실수경우 . 을 기준으로 그 앞에만 comma 를 붙임
			var idx = 0;
			var isReal = false;// 실수여부
			for (i = 0; i < tm.length; i++) {
				if (tm.charAt(i) == '.') {
					idx = i;
					isReal = true;
					break;
				}
			}// end for
			if (isReal) {
				tm1 = tm.substring(0, idx);
				tm2 = tm.substring(idx + 1, tm.length);
				tm = tm1;
			}

			var st = "";
			var cm = ",";

			for (var i = tm.length, j = 0; i > 0; i--, j++) {

				if ((j % 3) == 2) {
					if (tm.length == j + 1) {
						st = tm.substring(i - 1, i) + st;
					} else {
						st = cm + tm.substring(i - 1, i) + st;
					}
				} else {
					st = tm.substring(i - 1, i) + st;
				}
			}

			if (ck == "Y") {
				st = "-" + st;
			}

			if (isReal) {// 실수경우
				st += "." + tm2;
			}

			return st;			
		}
	};

	/**
	 * 함수명   : Ps10ComBase.gfn_stringRemoveComma
	 * 함수설명 : 추가한 ','문자(화폐단위 및 실수에 자동으로 3자리 쉼표)를 삭제한다.
	 * 파라메터 : {String} 변환대상 문자열
