	Ps10ComBase.f_validatedata = function() {
		var epos = strValidateStr.search( "=" );
		var command  = "";
		var cmdvalue = "";
		var title = "";

		if(epos >= 0) {
		command  = strValidateStr.substring( 0, epos );
		cmdvalue = strValidateStr.substr( epos+1 );
		} else {
		command = strValidateStr;
		}

		if ( strTitle ) {
		title = "[" + strTitle + "] ";
		}

		switch(command) {

		case "req":
		case "required": {
		   objValue.value = right_trim(objValue.value);
		   objValue.value = left_trim(objValue.value);

			if( com.num.parseInt( objValue.value.length ) == 0 ) {
			if( !strError || strError.length ==0 ) {
				strError = SECOM002; // 필수입력입니다.
			}//if
			alert( title + strError );
			return false;
			}//if
			break;
		}//case required
		case "maxlen":
		case "maxlength": {
			if( com.num.parseInt( getByte(objValue.value) ) >  com.num.parseInt( cmdvalue ) ) {
			if( !strError || strError.length ==0 ) {
				strError = f_makemsg(SECOM004, com.num.parseInt(cmdvalue)); // 입력된 항목의 자릿수가 너무 큽니다.
			}//if
			alert( title + strError );
			return false;
			}//if
			break;
		}//case maxlen
		case "minlength":
		case "minlen": {
			if( com.num.parseInt( getByte(objValue.value) ) <  com.num.parseInt( cmdvalue ) ) {
			if( !strError || strError.length ==0 ) {
				strError = f_makemsg( SECOM005, cmdvalue ) ; // 입력된 항목의 자릿수가 너무 작습니다.
			}//if
			alert( title + strError );
			return false;
			}//if
			break;
		}//case minlen
		case "alnum":
		case "alphanumeric": {
			var charpos = objValue.value.search( "[^A-Za-z0-9]" );
			if( objValue.value.length > 0 &&  charpos >= 0 ) {
			if( !strError || strError.length ==0 ) {
				strError = SECOM009; // alphabetic 혹은 numeric 형식이 아닙니다.
			}//if
			alert( title + strError );
			return false;
			}//if
