	/**
	 * 함수명   : cmm_del_hyphen
	 * 함수설명 : 객체를 받아 하이픈('-')제거함수  (구)ECOMCommon.js f_cmm_del_hyphen(obj)
	 * 파라메터 : 문자
	 * 리턴     : 검증결과
	 * 작성일   : 2023.07.18
	 * 작성자   : 한재준
	 */
	Ps10ComBase.cmm_del_hyphen = function(obj) {	
		var str =  String(obj);
		if (str.length < 1) {
			return "";
		} else {
			var st = "";
			var sp = "-";
			for (var i = 0; i < str.length; i++) {
				if (sp.indexOf(str.substring(i, i + 1)) == -1) {
					st += str.substring(i, i + 1);
				}
			}		
			return st;
		}
	};	

	/**
	 * 함수명   : Ps10ComBase.gfn_movePage
	 * 함수설명 : 메인페이지를 이동한다.
	 * 파라메터 : 화면URL, 파라미터
	 * 리턴     : N/A
	 * 작성일   : 2023.08.17
	 * 작성자   : 장영동
	 */
	Ps10ComBase.gfn_movePage = function(pageUrl, pageParam) {
		try {
			Ps10ComBase.gfn_getContentPage().com.page.movePage(pageUrl, pageParam);
		} catch (e) {
			console.log(e);
			// 개발용(임시) - 외부포털 메인페이지로 정상접근하지 않은 경우
			Ps10ComBase.gfn_getContentPage().com.page.movePage(pageUrl, pageParam);
		}

		// 스크롤을 최상단으로
		window.scrollTo(0, 0);
	}	

	/**
	 * 함수명   : Ps10ComBase.gfn_getContentPage
	 * 함수설명 : 메인 메뉴화면 페이지
	 * 파라메터 : N/A
	 * 리턴     : N/A
	 * 작성일   : 2023.08.17
	 * 작성자   : 장영동
	 */
	Ps10ComBase.gfn_getContentPage = function() {
		var contentFrame = null;
		var contentPage = null;

		// 1. 대민(PM10) 최상위 페이지
		var topPage = com.page.getTopPage();
		if (topPage) {
			// 2. 대민(PM10) 최상위 페이지의 작업영역 Main WFrame
			if (topPage.wfm_potal_main) {
				// 3. 대민(PM10) 최상위 페이지의 Main WFrame 내 메뉴화면 Main WFrame
				contentFrame = topPage.wfm_potal_main.getWindow().wfm_content;
			} else if (topPage.wfm_content) {	// 최상위 페이지 메인 프레임 가져오기가 실패했을 경우 - 개발 임시 등
				contentFrame = topPage.wfm_content;
			} else {	// 메뉴 메인화면 프레임 가져오기가 실패했을 경우 - 개발 임시 등
				return topPage;
			}
			contentPage = contentFrame.getWindow();
		}

		return contentPage;
	}	

