	/**
	 * 함수명   : Ps10ComBase.gfn_setLpad
	 * 함수설명 : 입력항목에 Lpad를 설정한다.
	 * 파라미터 : str(문자), padLen(pad길이), padStr(pad문자)
	 * 리턴     : str
	 * 작성일   : 2023.11.22
	 * 작성자   : 장영동
	 */
	Ps10ComBase.gfn_setLpad = function(str, padLen, padStr) {
		if (padStr.length > padLen) {
	        return false;
	    }
	    str += ""; 
	    padStr += "";
	    while (str.length < padLen) {
	    	str = padStr + str;
	    }
	    str = str.length >= padLen ? str.substring(0, padLen) : str;
	    return str;
	};	

