/**
 * 함수명   : Pm50ComUtil.gfn_getByte
 * 함수설명 : 전달받은 파라미터 문자열의 byte 수(한글 2바이트 변환)를 계산한다.
 * 파라메터 : {String} 계산대상 문자열
 * 리턴     : {int} 문자열의 byte 수
 * 작성일   : 2022.05.01
 * 작성자   : 홍길동
 * @example : Pm50ComUtil.gfn_getByte(ibx_buld_stru_cont.getValue())
 */
Pm50ComUtil.gfn_getByte = function(objValue) {	
	var len = 0;
	for (var idx = 0; idx < objValue.length; idx++, len++) {
		if ((objValue.charCodeAt(idx) < 0) || (objValue.charCodeAt(idx) > 127)) {
			len++; // add extra length
		}
	}
	return len;
} 
	

/**
 * 함수명   : Pm50ComUtil.gfn_checkByte
 * 함수설명 : 전달받은 파라미터 문자열의 문자열의 byte를 반환한다.
 * 파라메터 : {String} 계산대상 문자열
 * 리턴     : {int} 문자열의 byte 수
 * 작성일   : 2022.05.01
 * 작성자   : 홍길동
 * @example : Pm50ComUtil.gfn_checkByte(ibx_buld_stru_cont.getValue())
 */	
Pm50ComUtil.gfn_checkByte = function(str) {
	var byteLength = 0;
	for (var inx = 0; inx < str.length; inx++) {
		var oneChar = escape(str.charAt(inx));
		if (oneChar.length == 1) {
			byteLength++;
		} else if (oneChar.indexOf("%u") != -1) {
			byteLength += 2;
		} else if (oneChar.indexOf("%") != -1) {
			byteLength += oneChar.length / 3;
		}
	}
	return byteLength;
}


