			} else {
				st = tm.substring(i - 1, i) + st;
			}
		}

		if (ck == "Y") {
			st = "-" + st;
		}

		if (isReal) {// 실수경우
			st += "." + tm2;
		}

		return st;

	}
}	


/**
 * 함수명   : Pm50ComUtil.gfn_delHyphen
 * 함수설명 : 전달받은 파라미터 문자열의 하이픈('-')문자를 제거한 문자를 반환한다.
 * 파라메터 : {String} 변환대상 문자열
 * 리턴     : {String} 변환결과 문자열
 * 작성일   : 2022.05.01
 * 작성자   : 홍길동
 * @example : Pm50ComUtil.gfn_delHyphen(ibx_buld_stru_cont.getValue())
 */	
Pm50ComUtil.gfn_delHyphen = function(str) {
	if (str.length < 1) {
		return "";
	} else {
		var st = "";
		var sp = "-";
		for (var i = 0; i < str.length; i++) {
			if (sp.indexOf(str.substring(i, i + 1)) == -1) {
				st += str.substring(i, i + 1);
			}
		}
		return st;
	}
}
	
	
/**
 * 함수명   : Pm50ComUtil.gfn_removeSpace
 * 함수설명 : 전달받은 파라미터 문자열의 공백을 제거하고 반환한다.
 * 파라메터 : {String} 변환(공백 제거)대상 문자열
 * 리턴     : {String} 변환(공백 제거)결과 문자열
 * 작성일   : 2022.05.01
 * 작성자   : 홍길동
 * @example : Pm50ComUtil.gfn_removeSpace(ibx_buld_stru_cont.getValue())
 */	
Pm50ComUtil.gfn_removeSpace = function(str) {		
	var len, index;
    while (true) {
         index = str.indexOf(" ");
         if (index == -1) break;
         len = str.length;
         str = str.substring(0, index) + str.substring((index+1),len);
    }
    return str;
};
			
	
