/**
 * 함수명   : Pm50ComUtil.gfn_isValidMonth
 * 함수설명 : 전달받은 파라미터의 월(month) 유효성을 검증한다.
 * 파라메터 : {String} 검증(월(month))대상 입력 문자열
 * 리턴     : {boolean} 검증결과(true/false)
 * 작성일   : 2022.05.01
 * 작성자   : 홍길동
 * @example : Pm50ComUtil.gfn_isValidMonth(ibx_rgs_caus_date.getValue())
 */	
Pm50ComUtil.gfn_isValidMonth = function(mm) {
    var m = parseInt(mm,10);
    return (m >= 1 && m <= 12);
}	


/**
 * 함수명   : Pm50ComUtil.gfn_isValidDay
 * 함수설명 : 전달받은 파라미터의 일(day) 유효성 확인한다.  
 * 파라메터 : {String} 검증대상 입력 문자열(년(year))
 * 		      {String} 검증대상 입력 문자열(월(month))
 * 		      {String} 검증대상 입력 문자열(일(day))
 * 리턴     : {boolean} 검증결과(true/false)
 * 작성일   : 2022.05.01
 * 작성자   : 홍길동
 * @example : Pm50ComUtil.gfn_isValidDay("2002","02", "30")
 */	
Pm50ComUtil.gfn_isValidDay = function(yyyy, mm, dd) {
    var m = parseInt(mm,10) - 1;
    var d = parseInt(dd,10);

    var end = new Array(31,28,31,30,31,30,31,31,30,31,30,31);
    if ((yyyy % 4 == 0 && yyyy % 100 != 0) || yyyy % 400 == 0) {
        end[1] = 29;
    }

    return (d >= 1 && d <= end[m]);
}


/**
 * 함수명   : Pm50ComUtil.gfn_isValidMonth
 * 함수설명 : 전달받은 파라미터의 일자의 유효성을 검증한다.
 * 파라메터 : {String} 검증대상 입력 문자열
 * 리턴     : {boolean} 검증결과(true/false)
 * 작성일   : 2022.05.01
 * 작성자   : 홍길동
 * @example : if( !Pm50ComUtil.gfn_validateTime(ibx_rgs_caus_date.getValue()) ){
 *            		com.win.openMessagePopup("error", "egov.message.title.web.Pm50ComUtil.error", "pm50.message.error.web.Pm50ComUtil.0004", "등기원인일자");
 *            		return false;
 *            }
 */	
Pm50ComUtil.gfn_validateTime = function(time) {
    if(time.length != 8) return false;
    var year  = time.substring(0,4);
    var month = time.substring(4,6);
    var day   = time.substring(6,8);
     
    if (parseInt(year,10) >= 1900 && Pm50ComUtil.gfn_isValidMonth(month) && Pm50ComUtil.gfn_isValidDay(year,month,day) ) {
        return true;
    }
    return false;
}	
	

/**
 * 함수명   : Pm50ComUtil.gfn_chkDate
 * 함수설명 : 전달받은 파라미터(날짜 문자열)의 형식을 검증한다.
 * 파라메터 : {String} 검증대상 입력 문자열(날짜)
 * 리턴     : {boolean} 검증결과(true/false)
 * 작성일   : 2022.05.01
 * 작성자   : 홍길동
 * @example : if(Pm50ComUtil.gfn_chkDate(ibx_rgs_caus_date.getValue())!=true){ 
 * 					com.win.openMessagePopup("error", "egov.message.title.web.com.error", "pm50.message.error.web.com.0001", "");
 *  				return false;
 *  		  }
 */	
Pm50ComUtil.gfn_chkDate = function(strDate) {	
	if (strDate.length != "10" || strDate.substr(4,1) != "-" || strDate.substr(7,1) != "-")
		return false;
		
	var iYear 		= strDate.substr(0,4);
	var iMonth		= strDate.substr(5,2);
	var iDay 		= strDate.substr(8,2);
	var monthArr 	= new Array(31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31);
	
	if( iMonth == 2 ) {
		if ( ( (iYear % 4 == 0) && (iYear % 100 != 0) ) || (iYear % 400 == 0) ) {
			monthArr[1] = "29";
		}
	}
	
	if( iYear >= 1900 && iMonth <= 12 && iMonth > 0 && iDay <= monthArr[iMonth-1] && iDay > 0 ) {
		return true;
	} else {
		return false;
	}
}
	
	
