				_CB_multiSignFile = function (aResult) {
					var aErrorObject = __SANDBOX.upInterface().setErrCodeAndMsg();
					if (aErrorObject.code != 0) {
						aErrCallback(aErrorObject);
						return;
					}

					aMultiSignTable.setSignedData(aMultiSignID, aSignedFilePath);

